      ) VALUES (
        'letter-frequency-analyzer',
        'es',
        'Letter Frequency Analyzer',
        'Letter Frequency Analyzer | AllWordTools',
        'See how often each letter appears, with counts and percentages.',
        'AllWordTools',
        'Letter Frequency Analyzer',
        'See how often each letter appears, with counts and percentages.',
