INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'word-unscrambler',
        'de',
        'Word Unscrambler',
        'Buchstaben Entwirren – Wörter finden | AllWordTools',
        'Kostenloser Buchstabenentwirrer: Aus Buchstaben alle gültigen Wörter bilden, sortiert nach Punkten und Länge. Mit Jokern für Scrabble und Words With Friends. Sofortige Ergebnisse.',
        '',
        'Buchstaben Entwirren',
        'Gib deine Buchstaben ein und entdecke sofort alle möglichen Wörter – sortiert nach Punkten und Länge, inklusive Joker-Unterstützung für Scrabble und Words With Friends.',
        '["Ein Buchstabenentwirrer ist das schnellste Werkzeug, um aus einem Haufen Buchstaben echte, spielbare Wörter zu bilden. Egal, ob du bei Scrabble feststeckst, in einem Buchstabensalat das Lösungswort suchst oder bei Words With Friends mehr Punkte herausholen willst – der Buchstabenentwirrer von AlleWortTools.com erledigt die Arbeit für dich. Gib die Buchstaben ein, drücke auf „Entwirren“, und in Sekundenschnelle siehst du alle gültigen Wörter – das mit den meisten Punkten erscheint ganz oben.","Im Gegensatz zu einem einfachen Wörterbuch versteht unser Entwirrer die Regeln echter Wortspiele. Er durchsucht eine große, gepflegte Liste deutscher Wörter, berücksichtigt Joker und erlaubt Filter nach Länge, Anfangsbuchstaben, Endbuchstaben und bestimmten Buchstabenfolgen. So siehst du genau die Optionen, die du im Spiel nutzen kannst.","Und das Beste: Es ist völlig kostenlos, funktioniert sofort in deinem Browser auf jedem Gerät und erfordert keine Anmeldung. Kein Download, keine Wartezeit, keine Einschränkungen. Einfach eingeben, entwirren und gewinnen."]',
        'So verwendest du den Buchstabenentwirrer',
        '[{"title":"Gib deine Buchstaben ein","detail":"Gib die Buchstaben in das Feld ein – bis zu fünfzehn auf einmal. Die Reihenfolge spielt keine Rolle, also gib sie genau so ein, wie sie auf deinem Spielstein stehen."},{"title":"Joker hinzufügen","detail":"Verwende ein Fragezeichen (?) für jeden Blanko- oder Jokerstein. Jeder Joker kann jeden einzelnen Buchstaben ersetzen, und der Entwirrer zeigt dir alle Wörter, die mit diesen Jokern möglich sind."},{"title":"Mit Filtern verfeinern (optional)","detail":"Schränke die Ergebnisse ein, z. B. nach Mindestlänge oder nach Wörtern, die mit einer bestimmten Buchstabenfolge beginnen oder enden. Das ist praktisch, wenn du bereits einen Teil des Wortes kennst."},{"title":"Ergebnisse anzeigen lassen","detail":"Die Wörter werden nach Länge gruppiert und nach Scrabble-Punktzahl sortiert angezeigt – so siehst du sofort den besten Zug. Tippe auf ein Wort, um es zu kopieren."}]',
        '[{"heading":"Was ist ein Buchstabenentwirrer?","paragraphs":["Ein Buchstabenentwirrer ist ein Werkzeug, das aus einem Satz ungeordneter Buchstaben alle gültigen Wörter bildet. Gib die Buchstaben R, A, U, M ein, und du erhältst Wörter wie Raum, Maul, Arm und Urm, sowie kürzere Kombinationen wie Uhr und Rum. Anstatt selbst zu knobeln, durchsucht das Tool in Sekunden das gesamte Wörterbuch.","Der Trick liegt im Wörterbuch und der Suchmaschine dahinter. Unser Entwirrer vergleicht jeden deiner Buchstaben mit einer großen Wortliste und findet nicht nur Wörter, die alle Buchstaben nutzen, sondern auch kürzere Wörter, die nur einen Teil verwenden. Da er die Buchstabenanzahl berücksichtigt, schlägt er nie ein Wort vor, das einen Buchstaben doppelt benötigt, wenn du ihn nur einmal hast – jedes Ergebnis ist wirklich spielbar."]},{"heading":"Buchstaben entwirren für Scrabble und Words With Friends","paragraphs":["Scrabble und Words With Friends sind die Spiele, für die am häufigsten Buchstaben entwirrt werden. Unser Tool ist auf beide abgestimmt. Die Ergebnisse werden standardmäßig nach Scrabble-Punktzahl sortiert, sodass Wörter mit hohen Buchstaben wie Q, X, Y und J ganz oben stehen. So erkennst du schnell den Zug, der aus einem mittelmäßigen Satz einen Spielgewinner macht.","Joker werden voll unterstützt. Wenn dein Satz einen oder zwei Joker enthält, füge für jeden ein Fragezeichen ein, und der Entwirrer behandelt sie wie jeden Buchstaben – das hilft dir, Bonuswörter und Siebenbuchstaben-Wörter zu finden, die du sonst vielleicht übersehen würdest. Zusammen mit den Längen- und Musterfiltern findest du schnell das passende Wort für eine freie Stelle auf dem Brett."]},{"heading":"Warum den AlleWortTools.com Entwirrer verwenden?","paragraphs":["Geschwindigkeit und Genauigkeit unterscheiden einen guten von einem schlechten Entwirrer. Unser Tool liefert Ergebnisse in Echtzeit, basierend auf einer umfangreichen, regelmäßig aktualisierten Wortliste, sodass du sicher sein kannst, dass jeder Vorschlag ein gültiges Wort ist. Keine Verzögerungen, kein Neuladen, keine Begrenzung der Nutzung.","Außerdem hilft es dir, besser zu werden. Indem es Punktzahlen und Längen anzeigt, zeigt dir der Entwirrer, welche Buchstabenkombinationen wertvoll sind und welche hochpunktigen Wörter es für knifflige Buchstaben gibt. Mit der Zeit schärft das dein Gespür und macht dich zu einem stärkeren Spieler – selbst wenn du ohne Hilfe spielst."]}]',
        '[{"input":"stein","output":"stein, sinte, inset, stein, neist, sien, nist, test","note":"Sechs Buchstaben mit mehreren Anagrammen – perfekt, um Bonuswörter zu finden."},{"input":"haus","output":"haus, sauh, husa, uhas, aus, sau, uah","note":"Auch kurze Buchstaben ergeben viele spielbare Wörter verschiedener Längen."},{"input":"k?se","output":"kase, käse, kuse, kose, kese, käse","note":"Der ?-Joker ersetzt den Blankostein und ermöglicht verschiedene Wörter."}]',
        '["Gib alle deine Buchstaben ein, auch schwierige wie Q und X – der Entwirrer findet den besten Platz für sie.","Nutze Joker (?) für Blankosteine, um Siebenbuchstaben-Wörter mit 50-Punkte-Bonus zu entdecken.","Filtere nach Anfangs- oder Endbuchstaben, wenn ein Wort an bereits liegende Steine anschließen soll.","Schau dir zuerst die längsten Wörter an – Länge schlägt meist wenige hochpunktige Buchstaben.","Lerne die kurzen Wörter aus den Ergebnissen; sie sind der Schlüssel zu Parallelzügen und großen Kombos."]',
        '[{"question":"Wofür verwendet man einen Buchstabenentwirrer?","answer":"Ein Buchstabenentwirrer ordnet einen Satz Buchstaben zu allen gültigen Wörtern. Spieler nutzen ihn, um bei Scrabble und Words With Friends hochpunktige Züge zu finden, Buchstabensalate zu lösen und Wörter in einer Buchstabengruppe zu entdecken."},{"question":"Wie viele Buchstaben kann ich auf einmal entwirren?","answer":"Du kannst bis zu fünfzehn Buchstaben gleichzeitig entwirren – das deckt ein Siebenbuchstaben-Rack plus Buchstaben auf dem Brett ab. Für die meisten Spiele reicht es, dein ganzes Rack einzugeben."},{"question":"Wie funktionieren Joker oder Blankosteine?","answer":"Gib für jeden Joker ein Fragezeichen (?) ein. Jeder Joker kann jeden Buchstaben ersetzen, und der Entwirrer zeigt alle Wörter, die mit diesen Jokern möglich sind – hilfreich für Bonuswörter."},{"question":"Sind die Ergebnisse bei Scrabble und Words With Friends gültig?","answer":"Ja. Der Entwirrer verwendet eine umfassende deutsche Wortliste, die auf offiziellen Turnierwörterbüchern basiert. Extrem seltene regionale Varianten können zwischen den offiziellen Listen abweichen."},{"question":"Ist der Buchstabenentwirrer kostenlos?","answer":"Ja, völlig kostenlos. Keine Anmeldung, kein Download, keine Nutzungsbeschränkung. Er läuft sofort im Browser auf Handy, Tablet und Computer."},{"question":"Ist die Nutzung eines Entwirrers Schummeln?","answer":"Das hängt vom Kontext ab. Im lockeren Spiel nutzen viele den Entwirrer, um neue Wörter zu lernen. In Wettbewerben oder Ranglistenspielen solltest du die Regeln des Spiels und die Erwartungen deiner Gegner beachten."}]',
        'Buchstaben entwirren Wörter finden',
        '["Buchstaben entwirren","Wörter aus Buchstaben","Buchstaben in Wörter umwandeln","Scrabble Hilfe","Wortfinder","Anagramm Generator","Buchstabensalat lösen","Wörter mit Freunden Hilfe","Wortentschlüssler"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'scrabble-helper',
        'de',
        'Scrabble Helper',
        'Scrabble Hilfe — Wortfinder mit Wörterbuch | AllWordTools',
        'Kostenlose Scrabble Hilfe: Finde alle spielbaren Wörter aus deinen Buchstaben, bewertet mit offiziellen Scrabble-Punkten. Inklusive Joker und Filter.',
        '',
        'Scrabble Hilfe – Der beste Wortfinder für hohe Punktzahlen',
        'Gib deine Buchstaben ein und sieh sofort alle gültigen Wörter, bewertet mit offiziellen Scrabble-Punkten – inklusive Joker und Längenfilter.',
        '["Mit der Scrabble Hilfe verwandelst du deine Buchstaben in eine Liste der besten Wörter, die du tatsächlich legen kannst. Gib die Buchstaben deines Racks ein und innerhalb von Sekunden durchsucht das Tool eine große deutsche Wortliste und zeigt dir jedes gültige Wort – sortiert nach der höchsten Punktzahl. Jedes Wort wird mit den Standard-Scrabble-Buchstabenwerten bewertet, damit die Punktzahl genau zu den Steinen passt.","Unser Tool ist mehr als ein einfacher Buchstabenentschlüssler: Es ist auf die echte Scrabble-Praxis zugeschnitten. Joker werden mit ? eingegeben, und du kannst nach Anfangsbuchstaben, Endbuchstaben, enthaltenen Buchstabenfolgen und Mindestlänge filtern – perfekt, um an bestehende Steine auf dem Brett anzuknüpfen. So findest du schneller den Zug, der das Spiel entscheidet.","Die Scrabble Hilfe ist völlig kostenlos, läuft sofort in deinem Browser auf jedem Gerät und erfordert keine Anmeldung. Egal ob Gelegenheitsspieler oder Vereinsmitglied – mit diesem Werkzeug holst du das Maximum aus deinem Rack."]',
        'So nutzt du die Scrabble Hilfe',
        '[{"title":"Buchstaben eingeben","detail":"Gib deine Buchstaben ein – maximal fünfzehn. Die Reihenfolge spielt keine Rolle, also tippe sie einfach so ein, wie sie auf deinem Rack liegen."},{"title":"Joker hinzufügen","detail":"Verwende ein Fragezeichen (?) für jeden Joker. Jeder Joker kann jeden Buchstaben ersetzen, und die Scrabble Hilfe zeigt jedes Wort, das damit möglich ist."},{"title":"Filter für das Brett einsetzen","detail":"Lege einen Anfangs- oder Endbuchstaben, eine enthaltene Buchstabenfolge oder eine Mindestlänge fest, um Wörter zu finden, die an bereits liegende Steine anschließen."},{"title":"Das beste Wort legen","detail":"Die Ergebnisse werden nach Scrabble-Punkten sortiert und nach Länge gruppiert. Tippe auf ein Wort, um es sofort zu kopieren."}]',
        '[{"heading":"Wie die Scrabble-Punktzahl funktioniert","paragraphs":["Jeder Buchstabe in Scrabble hat einen bestimmten Punktwert – von häufigen Ein-Punkt-Buchstaben wie E, N und S bis hin zu den Zehn-Punkt-Buchstaben Q und Y. Die Scrabble Hilfe addiert diese Werte für jedes gefundene Wort und sortiert die Liste absteigend, sodass der Zug mit den meisten Rohpunkten immer ganz oben steht. Bedenke, dass die Brettmultiplikatoren – doppelte und dreifache Buchstaben- und Wortwerte – die tatsächliche Punktzahl beeinflussen können. Betrachte die Rangliste daher als Kurzliste und wähle dann das Wort, das auf den besten Feldern landet.","Da Joker null Punkte zählen, kann ein Wort mit Joker hier niedriger eingestuft werden, auch wenn es clever ist. Die Hilfe zeigt es trotzdem an, damit du die Entscheidung treffen kannst."]},{"heading":"Hooks und Bonus-Züge finden","paragraphs":["Die wahre Scrabble-Kunst besteht darin, an bereits liegende Buchstaben anzuknüpfen. Nutze die Filter für Anfangs- und Endbuchstaben, um Wörter zu finden, die an einen vorhandenen Stein anschließen, oder den Enthält-Filter, um Buchstaben in der Mitte einer Reihe zu nutzen. In Kombination mit deinem Rack zeigen dir diese Filter genau die Wörter, die auf die aktuelle Brettsituation passen.","Wenn du alle sieben Steine in einem Zug legst, erhältst du einen 50-Punkte-Bonus. Setze die Mindestlänge auf sieben, und die Hilfe zeigt dir alle siebenbuchstabigen Wörter aus deinem Rack – ideal, um spielentscheidende Bingo-Züge zu entdecken."]},{"heading":"Ist die Nutzung einer Scrabble Hilfe Schummeln?","paragraphs":["Abseits von Turnieren ist ein Wortfinder eine hervorragende Lernhilfe. Indem du die in deinem Rack versteckten Wörter siehst, lernst du neue gültige Wörter, ungewöhnliche Zwei-Buchstaben-Kombinationen und wertvolle Buchstabenmuster, die dich langfristig zum besseren Spieler machen. Viele nutzen das Tool zum Üben zwischen Spielen oder um freundschaftliche Streitigkeiten über die Gültigkeit eines Wortes zu klären.","In lockeren Spielen solltet ihr vorher vereinbaren, ob Hilfsmittel erlaubt sind. Als Lernhilfe genutzt, baust du mit der Scrabble Hilfe echte Fähigkeiten auf, die du dann in Spielen ohne Hilfe anwenden kannst."]}]',
        '[{"input":"Buchstaben: a b e i r s t","output":"arbeitest, abreiste, barstie, bastier","note":"Siebenbuchstabige Bingos für den 50-Punkte-Bonus."},{"input":"Buchstaben: q u i z + Joker (?)","output":"quiz, quälen, quitt, quirl","note":"Joker ermöglichen Wörter, die sonst nicht spielbar wären."},{"input":"Buchstaben: f a h r e n, endet mit ''en''","output":"fuhren, fahren, fählen, fällen","note":"Filter nutzen, um an vorhandene Steine anzuknüpfen."}]',
        '["Lerne die Zwei-Buchstaben-Wörter – sie sind der Schlüssel, um an das Brett anzuknüpfen und in engen Situationen zu punkten.","Stelle die Mindestlänge auf sieben, um nach Bingos mit 50 Punkten Bonus zu suchen.","Halte hochwertige Buchstaben für doppelte oder dreifache Buchstabenwerte zurück, statt sie früh zu verlegen.","Verwende den Enthält-Filter, um durch einen bereits liegenden Buchstaben in der Mitte eines Wortes zu spielen.","Denke daran: Joker zählen null Punkte – manchmal ist ein niedriger bewertetes Wort der klügere Zug."]',
        '[{"question":"Verwendet die Scrabble Hilfe offizielle Buchstabenwerte?","answer":"Ja. Jedes Wort wird mit den Standard-Scrabble-Buchstabenwerten bewertet, sodass die angezeigten Punkte genau den Steinen entsprechen. Brettmultiplikatoren werden nicht berücksichtigt, da sie von der Platzierung abhängen."},{"question":"Wie gebe ich Joker ein?","answer":"Tippe ein Fragezeichen (?) für jeden Joker. Jeder Joker kann jeden Buchstaben ersetzen, und die Hilfe zeigt alle Wörter, die mit diesen Jokern möglich sind – beachte aber, dass der Joker selbst null Punkte zählt."},{"question":"Kann ich Wörter finden, die an das Brett anschließen?","answer":"Ja. Nutze die Filter für Anfangsbuchstaben, Endbuchstaben und enthaltene Buchstabenfolgen, um Wörter zu finden, die an bereits liegende Buchstaben anknüpfen. Mit der Mindestlänge kannst du gezielt nach längeren Wörtern suchen."},{"question":"Ist die Scrabble Hilfe kostenlos?","answer":"Ja, völlig kostenlos, unbegrenzt nutzbar, ohne Anmeldung oder Downloads. Sie läuft sofort in deinem Browser auf jedem Gerät."},{"question":"Sind die angezeigten Wörter bei Scrabble gültig?","answer":"Die Hilfe greift auf eine große deutsche Wortliste zurück. Für offizielle Turniere solltest du jedes Wort im offiziellen Wörterbuch deines Verbandes überprüfen."}]',
        'Suche nach einem kostenlosen Scrabble-Wortfinder, der die höchsten Punktzahlen anzeigt.',
        '["Scrabble Hilfe","Scrabble Wortfinder","beste Scrabble Wörter","Scrabble Punkte berechnen","Scrabble Joker","Scrabble Wörterbuch Deutsch","Scrabble Buchstaben eingeben","Scrabble Tool kostenlos"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'anagram-solver',
        'de',
        'Anagram Solver',
        'Anagramm-Löser – Finde jedes Anagramm deiner Buchstaben',
        'Kostenloser Anagramm-Generator: Finde alle Wörter aus deinen Buchstaben, inklusive Zweiwort-Anagramme. Mit Platzhaltern für Scrabble & Rätsel. Sofortige Ergebnisse.',
        '',
        'Anagramm-Löser',
        'Gib deine Buchstaben ein und finde sofort jedes Anagramm, das alle verwendet – inklusive cleverer Zweiwort-Anagramme mit Platzhaltern für Jokersteine.',
        '["Ein Anagramm-Löser nimmt eine Buchstabenfolge – oder ein ganzes Wort – und ordnet sie zu jedem anderen gültigen Wort um, das genau dieselben Buchstaben verwendet. Gib die Buchstaben von „Rasen“ ein und der Löser zeigt sofort „Arsen“, „Saren“ und „Naser“. Statt selbst Buchstaben zu mischen oder Kombinationen auf Papier zu notieren, durchsucht der Anagramm-Löser von AllWordTools.com ein umfangreiches Wörterbuch und liefert dir jede Antwort in Sekundenbruchteilen.","Anagramme sind überall: in Zeitungsrätseln, in Kreuzworträtsel-Hinweisen, in Gesellschaftsspielen und im täglichen Scrabble- oder Words With Friends-Spiel. Wo immer du aus einem Buchstabensalat ein echtes Wort machen musst, das alle Buchstaben verwendet, erledigt dieses Tool die Arbeit für dich – genau, sofort und völlig kostenlos.","Neben einzelnen Wörtern kann unser Löser auch Zweiwort-Anagramme finden: Wortpaare, die zusammen jeden Buchstaben genau einmal verwenden. Das ist perfekt für kryptische Hinweise, Anagramm-Namensspiele und Rätselerstellung, bei denen die Antwort ein Satz oder eine Phrase ist."]',
        'So verwendest du den Anagramm-Löser',
        '[{"title":"Gib deine Buchstaben oder dein Wort ein","detail":"Tippe die Buchstaben ein, die du umstellen möchtest – oder füge ein vorhandenes Wort ein. Die Reihenfolge spielt keine Rolle; der Löser berücksichtigt automatisch jede Anordnung."},{"title":"Platzhalter für Jokersteine hinzufügen","detail":"Verwende ein Fragezeichen (?) für jeden Joker oder unbekannten Buchstaben. Jeder Platzhalter kann jeden beliebigen Buchstaben ersetzen und deckt so Anagramme auf, die du sonst übersehen würdest."},{"title":"Zweiwort-Anagramme aktivieren (optional)","detail":"Schalte den Zweiwort-Modus ein, um auch Wortpaare zu finden, die zusammen alle deine Buchstaben verwenden – ideal für Phrasen und kryptische Hinweise."},{"title":"Ergebnisse lesen und kopieren","detail":"Die Ergebnisse sind nach Scrabble-Punktzahl sortiert, sodass die wertvollsten Züge oben stehen. Tippe auf ein Anagramm, um es sofort zu kopieren."}]',
        '[{"heading":"Was ist ein Anagramm?","paragraphs":["Ein Anagramm ist ein Wort oder eine Phrase, die durch Umordnung der Buchstaben eines anderen Wortes entsteht, wobei jeder ursprüngliche Buchstabe genau einmal verwendet wird. „Rasen“ und „Arsen“ sind ein klassisches Paar – beide verwenden die Buchstaben A, E, N, R und S. Da jeder Buchstabe wiederverwendet werden muss, sind Anagramme strenger als eine allgemeine Wortsuche: Ein echtes Anagramm fügt niemals Buchstaben hinzu oder lässt sie weg, es ordnet nur das Vorhandene neu an.","Diese Unterscheidung trennt einen Anagramm-Löser von einem Wortentwirrer. Ein Wortentwirrer findet jedes Wort, das du aus einigen oder allen deinen Buchstaben bilden kannst, einschließlich kürzerer Wörter. Ein Anagramm-Löser konzentriert sich nur auf Wörter, die alle deine Buchstaben auf einmal verwenden – genau das, was Buchstabenrätsel, kryptische Hinweise und Anagramm-Spiele verlangen."]},{"heading":"Einwort- und Zweiwort-Anagramme","paragraphs":["Die meisten Anagramm-Rätsel erfordern ein einzelnes Wort: Ordne die gegebenen Buchstaben zu einem neuen Wort um. Unser Löser erledigt das sofort, indem er deine Buchstabenkombination mit einem umfassenden Wörterbuch abgleicht und alle Treffer sortiert nach Punktzahl zurückgibt.","Aber einige der befriedigendsten Anagramme sind Phrasen. Schalte den Zweiwort-Modus ein und der Löser kombiniert Wörter aus dem Wörterbuch so, dass sie zusammen jeden Buchstaben genau einmal verwenden. Dies ist die treibende Kraft hinter kryptischen Kreuzworträtsel-Antworten und verspielten Namensanagrammen – und es ist überraschend schwer, dies von Hand zu tun, weshalb das Tool hier glänzt."]},{"heading":"Anagramme für Scrabble, Buchstabenrätsel und Puzzles","paragraphs":["Bei Scrabble und Words With Friends kann das Erkennen eines Vollrack-Anagramms einen Siebenbuchstaben-Bingo mit 50-Punkte-Bonus auslösen. Gib dein Rack ein, füge einen Platzhalter für jeden Joker hinzu, und der Löser zeigt jedes Wort an, das alle deine Buchstaben verwendet – und verwandelt ein festgefahrenes Rack in einen spielentscheidenden Zug.","Für Zeitungsrätsel und Puzzlehefte nimmt der Löser das Rätselraten aus dem Spiel: Tippe die durcheinandergewürfelten Buchstaben ein und lies die Antwort ab. Und da die Ergebnisse nach Punkten sortiert und dopplungsfrei sind, bekommst du nur saubere, gültige Anagramme, denen du vertrauen kannst."]}]',
        '[{"input":"rasen","output":"Arsen, Saren, Naser, rasen","note":"Ein klassisches Beispiel: vier vollständige Anagramme."},{"input":"regal","output":"Lager, regal","note":"Ein kurzes Wort mit einer überraschenden Umstellung."},{"input":"tor","output":"rot, Tor","note":"Einprägsames Beispiel – die Buchstaben ergeben zwei gültige Wörter."}]',
        '["Anagramm-Löser verwenden ALLE deine Buchstaben – für kürzere Teilwörter nutze den Wortentwirrer.","Füge ein ? für jeden Joker hinzu, um Bonus-Anagramme und Siebenbuchstaben-Bingos zu finden.","Aktiviere den Zweiwort-Modus für kryptische Kreuzworträtsel-Hinweise, die oft Phrasen-Anagramme verstecken.","Sortiere gedanklich nach seltenen Buchstaben (Q, X, Y, J) – Anagramme mit ihnen punkten meist am höchsten.","Lerne gängige Anagramm-Paare wie Rasen/Arsen oder Leben/Nebel, um sie im Spiel schneller zu erkennen."]',
        '[{"question":"Was macht ein Anagramm-Löser?","answer":"Ein Anagramm-Löser ordnet eine Buchstabenmenge in jedes gültige Wort um, das alle Buchstaben genau einmal verwendet. Ideal für Buchstabenrätsel, kryptische Kreuzworträtsel und das Finden von Highscore-Zügen bei Scrabble und Words With Friends."},{"question":"Was ist der Unterschied zwischen einem Anagramm-Löser und einem Wortentwirrer?","answer":"Ein Anagramm-Löser zeigt nur Wörter, die alle deine Buchstaben verwenden. Ein Wortentwirrer ist breiter – er zeigt auch kürzere Wörter, die nur einen Teil der Buchstaben nutzen. Verwende den Anagramm-Löser für exakte Umstellungen und den Wortentwirrer, um jedes spielbare Wort zu finden."},{"question":"Kann der Löser Zweiwort-Anagramme finden?","answer":"Ja. Schalte den Zweiwort-Modus ein und der Löser findet Wortpaare aus dem Wörterbuch, die zusammen alle deine Buchstaben genau einmal verwenden – perfekt für Phrasen-Anagramme und kryptische Hinweise."},{"question":"Wie funktionieren Platzhalter im Anagramm-Löser?","answer":"Gib ein Fragezeichen (?) für jeden Joker ein. Jeder Platzhalter kann jeden beliebigen Buchstaben ersetzen, sodass der Löser alle Anagramme anzeigt, die mit diesen Platzhaltern möglich sind. Platzhalter gelten für Einwort-Anagramme."},{"question":"Ist der Anagramm-Löser kostenlos?","answer":"Völlig kostenlos, ohne Anmeldung oder Download. Er läuft sofort in deinem Browser auf jedem Gerät und es gibt keine Begrenzung, wie viele Anagramme du lösen kannst."},{"question":"Wie viele Buchstaben kann ich eingeben?","answer":"Du kannst bis zu fünfzehn Buchstaben eingeben – das deckt ein volles Scrabble-Rack plus Brettsteine ab und so gut wie jedes Rätsel, dem du begegnen wirst."}]',
        'Ein Wort aus Buchstaben finden (alle Buchstaben verwenden)',
        '["Anagramm Löser","Anagramm Generator","Buchstaben Anagramm finden","Anagramm Online","Wort aus Buchstaben","Scrabble Anagramm","Anagramm Hilfe","Anagramm Rätsel"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'wordle-solver',
        'de',
        'Wordle Solver',
        'Wordle Löser – Nächstes Wort finden | AllWordTools',
        'Kostenloser Wordle Löser: Gib grüne, gelbe und graue Buchstaben ein und erhalte sofort die besten nächsten Wörter – platziert nach Buchstabenhäufigkeit.',
        '',
        'Wordle Löser',
        'Gib deine grünen, gelben und grauen Hinweise ein und sieh sofort alle möglichen Antworten – sortiert, sodass der beste nächste Versuch ganz oben steht.',
        '["Ein Wordle Löser nimmt die Hinweise, die du bereits gesammelt hast – die grünen, gelben und grauen Felder deiner Versuche – und grenzt sofort die tägliche Fünf-Buchstaben-Lösung auf die Wörter ein, die noch infrage kommen. Statt ratlos auf das Gitter zu starren, fütterst du den AllWordTools.com Wordle Löser mit deinem Wissen, und er zeigt dir eine sortierte Liste mit den stärksten nächsten Versuchen ganz oben.","Der Löser versteht alle drei Wordle-Farben. Grüne Buchstaben sind an ihrer Position fixiert, gelbe Buchstaben müssen an einer anderen Stelle im Wort vorkommen, und graue Buchstaben sind komplett ausgeschlossen. Kombinierst du nur ein paar Hinweise, schrumpft die Menge der möglichen Antworten dramatisch – oft auf nur eine Handvoll Wörter.","Es ist schnell, kostenlos und funktioniert sofort in deinem Browser. Nutze es, um ein kniffliges Rätsel zu retten, deine Serie zu bewahren oder einfach zu lernen, welche Versuche dir die meisten Informationen liefern."]',
        'So verwendest du den Wordle Löser',
        '[{"title":"Gib deine grünen Buchstaben ein","detail":"Tippe jeden richtigen Buchstaben in das Feld, das seiner exakten Position im Wort entspricht. Felder, die du nicht kennst, lässt du leer."},{"title":"Füge die gelben Buchstaben hinzu","detail":"Liste die Buchstaben auf, die im Wort vorkommen, aber an der falschen Stelle sind, im Feld „Vorhandene Buchstaben“."},{"title":"Graue Buchstaben eintragen","detail":"Trage die Buchstaben, die du ausgeschlossen hast, im Feld „Nicht vorhandene Buchstaben“ ein."},{"title":"Ergebnisse anzeigen","detail":"Klicke auf „Lösungen finden“, um alle möglichen Wörter zu sehen – sortiert mit dem besten nächsten Versuch ganz oben."}]',
        '[{"heading":"Wie der Wordle Löser funktioniert","paragraphs":["Wordle gibt dir drei Arten von Rückmeldungen: Ein grünes Feld bedeutet, der Buchstabe ist richtig und an der richtigen Stelle. Ein gelbes Feld bedeutet, der Buchstabe ist im Wort, aber an einer anderen Position. Ein graues Feld bedeutet, der Buchstabe kommt in der Lösung nicht vor. Unser Löser wendet alle drei Regeln gleichzeitig an und filtert ein Fünf-Buchstaben-Wörterbuch auf die Wörter, die all deine Hinweise erfüllen.","Sobald die übrigen Kandidaten feststehen, werden sie danach sortiert, wie häufig ihre Buchstaben unter den verbleibenden Möglichkeiten vorkommen. Ein Wort ganz oben zu raten, liefert meist die meisten neuen Informationen und hilft dir, die Lösung in möglichst wenigen Versuchen zu finden."]},{"heading":"Den intelligentesten nächsten Versuch finden","paragraphs":["Früh im Rätsel sind die besten Versuche Wörter mit vielen häufigen Buchstaben, die gleichzeitig viele Möglichkeiten eliminieren. Deshalb hebt der Löser seinen Top-Vorschlag hervor – es ist in der Regel der Versuch, der dir am meisten über das versteckte Wort verrät. Je mehr Hinweise du hinzufügst, desto kürzer wird die Liste, bis nur noch die richtige Antwort übrig ist.","Eine gute Strategie ist, nach jedem Versuch deine Hinweise einzugeben und den Löser die Liste aktualisieren zu lassen. Selbst wenn du die Lösung schon vermutest, hilft ein Blick auf die verbleibenden Kandidaten, keinen Versuch für ein bereits ausgeschlossenes Wort zu verschwenden."]},{"heading":"Beim Spielen besser werden","paragraphs":["Über die Rettung eines einzelnen Rätsels hinaus lehrt dich der Wordle Löser, wie Informationen im Spiel fließen. Indem du beobachtest, wie jeder Hinweis die Kandidatenliste verkleinert, lernst du, welche Startwörter und Buchstabenkombinationen am stärksten sind – Wissen, das dich auch ohne Hilfe zu einem schnelleren Löser macht.","Da es kostenlos und sofort verfügbar ist, kannst du es als Trainingspartner nutzen: Rate selbst und überprüfe dann mit dem Löser, wie nah deine Überlegungen am optimalen Zug waren."]}]',
        '[{"input":"grün: ?R??E, grau: SLOT","output":"KRANE, BRAVE, PRUNE, GRADE","note":"Zwei Grüne plus ein paar Graue lassen nur noch wenige Antworten übrig."},{"input":"grün: C????, gelb: R, grau: SLONE","output":"CURRY, CRUMB, CRAMP","note":"Ein grüner Start mit einem Gelben grenzt schnell ein."},{"input":"gelb: AEI, grau: STRONG","output":"VIBE → Wörter, die A, E und I enthalten","note":"Gelbe Buchstaben müssen irgendwo im Wort vorkommen."}]',
        '["Gib nach jedem Versuch die Hinweise ein, damit die Kandidatenliste aktuell bleibt.","Starte mit einem buchstabenreichen Wort wie KRANE oder STEIG, um möglichst viele Hinweise zu sammeln.","Das hervorgehobene Top-Wort ist meist der informativste nächste Versuch.","Vergiss die grauen Buchstaben nicht – Buchstaben auszuschließen ist genauso mächtig wie sie zu bestätigen.","Wenn die Liste noch lang ist, rate ein Wort mit ganz neuen Buchstaben, um sie schneller zu teilen."]',
        '[{"question":"Wie funktioniert der Wordle Löser?","answer":"Du gibst die grünen (richtige Position), gelben (vorhanden, falsche Position) und grauen (nicht vorhanden) Hinweise deiner Versuche ein. Der Löser filtert ein Fünf-Buchstaben-Wörterbuch auf alle passenden Wörter und sortiert sie nach Buchstabenhäufigkeit, sodass der beste nächste Versuch zuerst kommt."},{"question":"Was ist das beste Wordle-Startwort?","answer":"Gute Startwörter verwenden häufige, unterschiedliche Buchstaben – Wörter wie KRANE, STEIG, TRAUM und CRATE sind beliebt, weil sie viele hochfrequente Buchstaben auf einmal testen."},{"question":"Gibt der Löser die genaue Lösung aus?","answer":"Bei genügend Hinweisen schrumpft die Liste oft auf ein einziges Wort. Bei weniger Hinweisen zeigt er alle verbleibenden Möglichkeiten, sortiert und mit dem informativsten Versuch hervorgehoben."},{"question":"Ist die Nutzung eines Wordle Lösers Schummeln?","answer":"Das liegt an dir. Viele nutzen ihn, um Strategie zu lernen oder eine Serie zu retten. Bei Freundschaftsspielen solltet ihr eure eigenen Regeln vereinbaren."},{"question":"Ist der Wordle Löser kostenlos?","answer":"Ja – völlig kostenlos, ohne Anmeldung oder Download. Er läuft sofort in deinem Browser auf jedem Gerät."},{"question":"Funktioniert er auch für Wordle-ähnliche Spiele?","answer":"Ja. Jedes Fünf-Buchstaben-Ratespiel mit grün/gelb/grau-Rückmeldung funktioniert mit denselben Hinweisen."}]',
        'Hilfe beim Lösen von Wordle-Rätseln durch Eingabe von Hinweisen',
        '["Wordle Löser","Wordle Helfer","Wordle Lösung finden","Wordle nächster Versuch","Wordle Tipps","Wordle Cheat","Wordle mit Hinweisen lösen","Wordle Generator"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'words-with-friends-helper',
        'de',
        'Words With Friends',
        'Words With Friends Helfer – Beste Züge & Buchstabenpunkte',
        'Kostenloser Words With Friends Helfer: Finde die besten Züge mit WWF-Punktwerten. Unterstützt Joker, Präfixe, Suffixe und Längenfilter. Jetzt ausprobieren!',
        '',
        'Words With Friends Helfer',
        'Gib deine Buchstaben ein und sieh jeden gültigen Zug, sortiert nach den originalen WWF-Punktwerten – mit Joker-Support und Filtern für das Brett.',
        '["Der Words With Friends Helfer findet die besten Züge aus deinen Buchstaben und sortiert sie nach Punkten, damit du immer den stärksten Zug siehst. Gib deine Buchstaben ein, und er durchsucht eine große deutsche Wortliste, zeigt alle gültigen Wörter und bewertet sie mit den offiziellen Words With Friends Buchstabenwerten.","Der Helfer ist für echte Spiele gemacht. Joker (Blankos) werden mit ? unterstützt, und Filter für Anfangsbuchstaben, Endbuchstaben, enthaltene Sequenzen und Mindestlänge helfen dir, ein Wort zu finden, das an die bereits gelegten Steine anschließt. Statt ewig zu scrollen, bekommst du eine fokussierte Liste spielbarer Wörter, sortiert nach Punkten.","Der Helfer ist komplett kostenlos, funktioniert sofort im Browser auf jedem Gerät und benötigt keine Anmeldung. Egal, ob du aufholen oder deine Führung verteidigen willst – so findest du blitzschnell deinen besten Zug."]',
        'So verwendest du den Words With Friends Helfer',
        '[{"title":"Buchstaben eingeben","detail":"Tippe deine Buchstaben ein – bis zu fünfzehn. Die Reihenfolge spielt keine Rolle, gib sie einfach so ein, wie sie im Fach liegen."},{"title":"Joker hinzufügen","detail":"Nutze ein Fragezeichen (?) für jeden Joker. Jeder Joker kann jeden Buchstaben ersetzen, und der Helfer zeigt jedes mögliche Wort."},{"title":"Auf das Brett filtern","detail":"Setze einen Anfangs- oder Endbuchstaben, eine enthaltene Buchstabenfolge oder eine Mindestlänge, um ein Wort zu finden, das an bereits gelegte Steine anschließt."},{"title":"Zug machen","detail":"Die Züge sind nach Words With Friends Punkten sortiert und nach Länge gruppiert. Tippe auf ein Wort, um es zu kopieren."}]',
        '[{"heading":"Wie sich die Punktevergabe in Words With Friends von Scrabble unterscheidet","paragraphs":["Words With Friends verwendet eigene Buchstabenwerte, daher kann dasselbe Wort anders punkten als bei Scrabble. Zum Beispiel sind die Buchstaben H und Y bei WWF weniger wert, während andere Steine abweichen. Dieser Helfer verwendet die korrekten WWF-Werte, sodass die Rangliste den tatsächlich erzielten Punkten entspricht.","Wie bei jedem Buchstabenspiel können die Bonusfelder auf dem Brett – Doppel- und Dreifachbuchstaben- sowie Wortfelder – beeinflussen, welcher Zug am besten ist. Betrachte die sortierte Liste als Kurzauswahl und wähle dann den Zug, der auf den wertvollsten Feldern landet."]},{"heading":"Anschließen an das Brett und Nutzung von Bonusfeldern","paragraphs":["Die stärksten Züge bauen meist auf bereits gelegten Buchstaben auf. Nutze die Filter „beginnt mit“ und „endet mit“, um an einen vorhandenen Stein anzuhängen, oder den Filter „enthält“, um durch einen Buchstaben in der Wortmitte zu spielen. Zusammen mit deinen Buchstaben zeigen diese Filter genau die Wörter, die in die Lücken passen.","Wer alle Buchstaben auf einmal legt, erhält bei Words With Friends einen 35-Punkte-Bonus. Stelle die Mindestlänge auf sieben, um diese großen Züge zu erkennen, wenn deine Buchstaben es ermöglichen."]},{"heading":"Vom Helfer lernen","paragraphs":["Der Helfer ist nicht nur zum Gewinnen da, sondern auch ein guter Lehrer. Wenn du siehst, welche Wörter aus deinen Buchstaben gebildet werden können, erweiterst du deinen Wortschatz an gültigen Wörtern, kurzen Wörtern und ungewöhnlichen Buchstabenkombinationen – so wirst du nach und nach unabhängiger. Viele nutzen ihn, um knifflige Buchstabenkombinationen zu analysieren und Wörter zu entdecken, die sie sonst übersehen hätten.","In Freundschaftsspielen solltet ihr vorher abklären, ob Hilfsmittel erwünscht sind. Wer ihn zwischen den Partien als Lernhilfe einsetzt, wird langfristig ein stärkerer und schnellerer Spieler."]}]',
        '[{"input":"Buchstaben: aeglnrt","output":"rangelt, ranglet, gar\t, angel","note":"Lange Wörter, die die meisten Buchstaben nutzen."},{"input":"Buchstaben: hj + Joker (?)","output":"haj, jah, hajj","note":"Joker und schwierige Buchstaben ergeben trotzdem einen Zug."},{"input":"Buchstaben: silent, beginnt mit ''s''","output":"silent, listen, inlets","note":"Filter, um an einen Stein auf dem Brett anzuhängen."}]',
        '["Achte auf die Buchstabenwerte – H und Y sind bei Words With Friends günstiger als bei Scrabble.","Versuche, alle Buchstaben auf einmal zu legen, um den 35-Punkte-Bonus zu erhalten.","Spare dir Joker für große Züge auf, statt sie für kleine Wörter zu verschwenden.","Nutze den „enthält“-Filter, um durch bereits gelegte Buchstaben zu spielen.","Wäge Punkte gegen Verteidigung ab – vermeide es, deinem Gegner ein Dreifach-Wortfeld zu öffnen."]',
        '[{"question":"Verwendet dieser Helfer die Words With Friends Buchstabenwerte?","answer":"Ja. Die Wörter werden mit den originalen WWF-Buchstabenwerten bewertet, die sich von Scrabble unterscheiden, sodass die Rangliste den tatsächlich erzielten Punkten entspricht. Brett-Multiplikatoren werden nicht berücksichtigt, da sie von der Platzierung abhängen."},{"question":"Wie gebe ich Joker (Blankos) ein?","answer":"Gib für jeden Joker ein Fragezeichen (?) ein. Jeder Joker kann jeden Buchstaben ersetzen, und der Helfer zeigt alle Wörter, die mit den Jokern möglich sind."},{"question":"Kann ich Züge finden, die ans Brett anschließen?","answer":"Ja. Nutze die Filter „beginnt mit“, „endet mit“ und „enthält“, um Wörter zu finden, die an bereits gelegte Buchstaben anknüpfen. Du kannst auch eine Mindestlänge für längere Züge einstellen."},{"question":"Ist der Words With Friends Helfer kostenlos?","answer":"Ja, komplett kostenlos, unbegrenzt nutzbar, ohne Anmeldung und ohne Downloads. Er läuft sofort im Browser auf jedem Gerät."},{"question":"Ist die Nutzung eines Helfers gegen die Regeln?","answer":"Das ist eine persönliche Entscheidung für Gelegenheitsspiele. Als Lernhilfe genutzt, verbessert er deine Fähigkeiten nachhaltig. Kläre mit deinen Gegnern, ob Hilfsmittel in euren Spielen erlaubt sind."}]',
        'Hilfe bei der Zugsuche in Words With Friends mit Punktoptimierung',
        '["Words With Friends Helfer","WWF Zugfinder","Beste Züge Words With Friends","Words With Friends Cheat","Wortsuche WWF","Words With Friends Buchstabenwerte","Words With Friends Tipps"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'crossword-solver',
        'de',
        'Crossword Solver',
        'Kreuzworträtsel-Löser – Wörter finden | AllWordTools',
        'Kostenloser Kreuzworträtsel-Löser: Geben Sie bekannte Buchstaben und ? für Lücken ein und finden Sie sofort jedes passende Wort für Ihr Gitter.',
        '',
        'Kreuzworträtsel-Löser',
        'Geben Sie Ihre bekannten Buchstaben und ein ? für jede leere Zelle ein, und sehen Sie sofort alle Wörter, die in Ihr Raster passen.',
        '["Ein Kreuzworträtsel-Löser füllt die Lücken für Sie. Wenn Sie einen Teil eines Wortes kennen – ein paar Buchstaben aus senkrechten oder waagerechten Wörtern – geben Sie einfach das Muster ein. Der AllWordTools.com Kreuzworträtsel-Löser durchsucht ein umfangreiches Wörterbuch nach allen Wörtern, die exakt zu Ihrer Vorlage passen. In Sekundenbruchteilen wird aus einer hartnäckigen Frage eine kurze Liste möglicher Antworten.","Der Musteransatz macht das Werkzeug so stark. Setzen Sie für jede bekannte Position einen Buchstaben und für jede leere Zelle ein ? (oder _ oder .). Geben Sie „b??m“ ein und Sie erhalten „Baum“, „Beam“ und „Boom“. Geben Sie „kr?uzw?rt?els“ ein und es erscheint „Kreuzworträtsel“. Die Länge ergibt sich direkt aus Ihrem Muster, daher passen die Ergebnisse immer zur Anzahl der Kästchen in Ihrem Gitter.","Es ist schnell, kostenlos und funktioniert sofort in Ihrem Browser auf jedem Gerät – perfekt für Zeitungsrätsel, Schwedenrätsel, Quiz und Rätsel-Apps."]',
        'So verwenden Sie den Kreuzworträtsel-Löser',
        '[{"title":"Zählen Sie die Kästchen","detail":"Ermitteln Sie, wie viele Buchstaben das gesuchte Wort hat, einschließlich der bereits bekannten."},{"title":"Geben Sie Ihr Muster ein","detail":"Tragen Sie die bekannten Buchstaben an den richtigen Positionen ein und setzen Sie ein ? (oder _ oder .) für jede leere Zelle, z. B. „b??k“ für ein Wort mit vier Buchstaben, das mit b beginnt."},{"title":"Lösen","detail":"Drücken Sie auf „Lösen“ und das Tool zeigt alle Wörter aus dem Wörterbuch, die exakt Ihrem Muster entsprechen."},{"title":"Wählen Sie Ihre Antwort","detail":"Durchsuchen Sie die Ergebnisse und tippen Sie auf ein Wort, um es in Ihr Raster zu übernehmen."}]',
        '[{"heading":"Wie die Mustererkennung funktioniert","paragraphs":["Jede Kreuzworträtsel-Antwort hat eine feste Länge und, sobald Sie ein paar Buchstaben aus anderen Wörtern kennen, eine feste Menge bekannter Positionen. Der Löser behandelt Ihre Eingabe als Vorlage: Jeder echte Buchstabe muss exakt übereinstimmen, während jedes ? für einen beliebigen Buchstaben stehen kann. Anschließend durchsucht er das Wörterbuch nach Wörtern derselben Länge, deren bekannte Buchstaben genau mit Ihren übereinstimmen.","Das unterscheidet sich grundlegend von einem Anagramm-Löser, der mit einem Buchstabensalat arbeitet. Der Kreuzworträtsel-Löser achtet auf die Position: Wo ein Buchstabe im Wort steht, ist genauso wichtig wie welcher Buchstabe es ist. Genau das liefert ein Kreuzworträtselgitter – Buchstaben, die an bestimmten Stellen feststehen."]},{"heading":"Schwedenrätsel und anspruchsvolle Kreuzworträtsel","paragraphs":["Bei Schwedenrätseln ist der Löser eine unkomplizierte Hilfe, um eine Antwort zu bestätigen oder eine Blockade zu lösen. Geben Sie das Muster aus Ihren bereits eingetragenen Buchstaben ein und lesen Sie die Kandidaten. Für anspruchsvolle Rätsel ergänzt er Ihre Wortspiele: Sobald die Umschreibung und ein paar bekannte Buchstaben auf Länge und Form hinweisen, zeigt der Löser alle Wörter, die infrage kommen.","Da er alle Treffer ausgibt, können Sie mehrere Möglichkeiten mit der Umschreibung abgleichen, statt auf eine einzige zu setzen. Das ist besonders nützlich bei seltenen Wörtern und ungewöhnlichen Buchstabenkombinationen."]},{"heading":"Warum unser Kreuzworträtsel-Löser heraussticht","paragraphs":["Er ist schnell und präzise. Geben Sie ein Muster ein, und die Ergebnisse erscheinen sofort – aus einem großen, gepflegten Wörterbuch, sortiert nach Häufigkeit. Die flexiblen Platzhalter ?, _ und . bedeuten, dass Sie Muster auf die für Sie natürlichste Weise eingeben können.","Und wie jedes Tool von AllWordTools.com ist es völlig kostenlos, privat und erfordert keine Anmeldung. Alles läuft direkt in Ihrem Browser, ohne Begrenzung der Anzahl lösbarer Hinweise."]}]',
        '[{"input":"b??m","output":"Baum, Beam, Boom","note":"Eine Lücke in einem vierbuchstabigen Wort ergibt eine überschaubare Liste."},{"input":"kr?uzw?rt?els","output":"Kreuzworträtsel","note":"Längere Muster führen oft zu genau einer Lösung."},{"input":"?pp?e","output":"Appel, Acker, Apfel","note":"Bekannte Buchstaben und Lücken können an jeder Stelle stehen."}]',
        '["Zählen Sie die Kästchen genau – die Musterlänge muss genau zum Gitter passen.","Tragen Sie jeden bekannten Buchstaben ein; jeder schränkt die Ergebnisse drastisch ein.","Verwenden Sie ?, _ oder . für Lücken – ganz wie es Ihnen am leichtesten fällt.","Bei anspruchsvollen Rätseln: Lösen Sie zuerst das Wortspiel, dann bestätigen Sie die Antwort mit dem Muster.","Wenn nichts passt, überprüfen Sie einen bekannten Buchstaben – ein falscher blockiert alle Ergebnisse."]',
        '[{"question":"Wie verwende ich den Kreuzworträtsel-Löser?","answer":"Geben Sie die bekannten Buchstaben an den richtigen Positionen ein und setzen Sie ein ? (oder _ oder .) für jede leere Zelle. Der Löser findet alle Wörter dieser Länge, deren bekannte Buchstaben Ihrem Muster entsprechen."},{"question":"Welche Zeichen kann ich für leere Zellen verwenden?","answer":"Sie können ?, _ oder . verwenden – sie funktionieren alle gleich. Die Wortlänge ergibt sich aus der Gesamtzahl der Zeichen in Ihrem Muster."},{"question":"Was ist der Unterschied zu einem Anagramm-Löser?","answer":"Ein Anagramm-Löser sortiert einen Buchstabenhaufen neu. Der Kreuzworträtsel-Löser ordnet Buchstaben festen Positionen zu – genau das, was ein Kreuzworträtselgitter vorgibt, sobald ein paar Buchstaben bekannt sind."},{"question":"Kann er auch anspruchsvolle Kreuzworträtsel lösen?","answer":"Er hilft beim letzten Schritt: Sobald die Umschreibung und Ihre bekannten Buchstaben Länge und Muster ergeben, listet er alle passenden Wörter auf, die Sie mit der Umschreibung abgleichen können."},{"question":"Ist der Kreuzworträtsel-Löser kostenlos?","answer":"Ja – völlig kostenlos, ohne Anmeldung oder Download. Er läuft sofort in Ihrem Browser auf jedem Gerät."},{"question":"Warum gibt es keine Ergebnisse für mein Muster?","answer":"Meistens ist ein bekannter Buchstabe falsch oder die Länge stimmt nicht. Überprüfen Sie jeden Buchstaben und die Gesamtzahl der Kästchen und versuchen Sie es erneut."}]',
        'Kreuzworträtsel-Lösung mit bekannten Buchstaben finden',
        '["Kreuzworträtsel-Löser","Wort suchen mit bekannten Buchstaben","Buchstabenmuster Kreuzworträtsel","Kreuzworträtsel-Hilfe online","Wörter mit Lücken finden","Kreuzworträtsel App","Kreuzworträtsel Lösungshilfe","Wortmuster eingeben"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'word-finder',
        'de',
        'Word Finder',
        'Wort-Finder – Wörter nach Buchstaben, Länge & Muster suchen',
        'Kostenloser Wort-Finder: Suche nach Anfangsbuchstaben, Endbuchstaben, enthaltenen Zeichenfolgen und Länge. Ideal für Scrabble und Wortspiele.',
        '',
        'Wort-Finder',
        'Durchsuche ein umfangreiches deutsches Wörterbuch nach Anfangsbuchstaben, Endbuchstaben, enthaltenen Zeichenfolgen und Länge – und schränke die Ergebnisse optional auf deine vorhandenen Buchstaben ein.',
        '["Ein Wort-Finder ist ein flexibles Suchwerkzeug, mit dem du ein ganzes deutsches Wörterbuch anhand der dir bekannten Hinweise durchsuchen kannst. Du suchst ein Wort, das mit „Vor“ beginnt, auf „ung“ endet, „ei“ enthält oder genau 7 Buchstaben lang ist? Der Wort-Finder kombiniert all diese Filter gleichzeitig und listet sofort alle Treffer auf, sortiert nach Länge und Wert.","Anders als ein Buchstaben-Entwirrer, der nur Wörter aus einem festen Buchstabensatz zeigt, durchsucht der Wort-Finder das gesamte Wörterbuch nach Mustern. Das ist perfekt für Kreuzworträtsel, zum Erlernen neuer Vokabeln, für Wortspiele und um das Wort zu finden, das dir auf der Zunge liegt. Und wenn du die Ergebnisse auf deine Buchstaben beschränken möchtest, fügst du einfach deine Buchstaben hinzu – der Finder zeigt dann nur spielbare Wörter.","Er ist schnell, kostenlos und funktioniert sofort im Browser auf jedem Gerät – ohne Anmeldung, ohne Download und ohne Begrenzung."]',
        'So verwendest du den Wort-Finder',
        '[{"title":"Wähle deine Filter","detail":"Gib eine beliebige Kombination aus „beginnt mit“, „endet mit“, „enthält“ und „genaue Länge“ ein. Du kannst einen oder mehrere Filter gleichzeitig verwenden."},{"title":"Optional auf deine Buchstaben beschränken","detail":"Füge deine Buchstaben in das Feld „nur diese Buchstaben verwenden“ ein (mit ? für Platzhalter), um nur Wörter anzuzeigen, die du tatsächlich legen kannst."},{"title":"Wörter finden","detail":"Drücke auf „Wörter finden“. Der Finder durchsucht das gesamte Wörterbuch und zeigt die Treffer gruppiert nach Länge an."},{"title":"Kopiere, was du brauchst","detail":"Die Ergebnisse sind nach Länge und Punktewert sortiert. Tippe auf ein Wort, um es sofort zu kopieren."}]',
        '[{"heading":"Was kannst du mit einem Wort-Finder machen?","paragraphs":["Der Wort-Finder arbeitet mit echten Suchmustern. Gib einen Präfix ein, um alle Wörter zu finden, die mit diesen Buchstaben beginnen, eine Endung für Reim- oder Suffixtreffer oder eine enthaltene Zeichenfolge für Wörter, die eine bestimmte Buchstabenkombination enthalten. Mit der Längenangabe kannst du die Suche zusätzlich einschränken. Da alle Filter zusammenwirken, kannst du so breit oder genau suchen, wie du möchtest.","Diese Flexibilität macht das Werkzeug weit über ein einzelnes Spiel hinaus nützlich. Schüler erweitern ihren Wortschatz, Autoren finden das passende Wort, und Rätselfreunde knacken Hinweise, die ein einfacher Entwirrer nicht lösen kann. Es ist ein Wörterbuch, das du nach Form und nicht nur nach Schreibweise durchsuchen kannst."]},{"heading":"Spielbare Wörter für Scrabble und Wortspiele finden","paragraphs":["Wenn du mitten im Spiel bist, füge die Buchstaben deines Racks in das Feld „nur diese Buchstaben verwenden“ ein. Der Finder schränkt dann alle Ergebnisse auf Wörter ein, die du tatsächlich legen kannst, während er deine anderen Filter wie Anfangsbuchstabe oder Länge berücksichtigt. Das ist ideal, wenn du ein Wort brauchst, das an einen bestimmten Buchstaben auf dem Brett anschließt.","Platzhalter (Joker) werden mit dem ? unterstützt, damit du keinen Bonuszug verpasst. Kombiniere einen Filter für enthaltene Buchstaben mit deinem Rack, um z. B. das Wort mit den höchsten Punkten zu finden, das durch einen bereits liegenden Buchstaben gelegt werden kann."]},{"heading":"Warum unseren Wort-Finder wählen?","paragraphs":["Geschwindigkeit, Genauigkeit und Flexibilität zeichnen unseren Finder aus. Er durchsucht eine große, regelmäßig gepflegte Wortliste und liefert sofort Ergebnisse, ohne Verzögerung oder Neuladen. Alle Filter können kombiniert werden, sodass du nie auf ein Tool beschränkt bist, das nur eine Suchart erlaubt.","Zudem ist er völlig kostenlos und datenschutzfreundlich – alles läuft im Browser, du brauchst kein Konto und es gibt keine Begrenzung der Suchanfragen."]}]',
        '[{"input":"beginnt mit: Vor, Länge: 6","output":"vorher, vorne, vornem, vorweg","note":"Kombiniere Präfix mit genauer Länge für schnelle Eingrenzung."},{"input":"endet auf: ung","output":"Zeitung, Lösung, Leitung, Bildung, Übung","note":"Finde Suffixtreffer für Reime und Wortfamilien."},{"input":"enthält: pf","output":"Apfel, Kopf, Pfad, Pflicht, Tropfen","note":"Entdecke Wörter mit ungewöhnlichen Buchstabenpaaren."}]',
        '["Kombiniere Filter – ein Präfix plus Länge ist viel präziser als nur einer.","Nutze den Filter „enthält“, um Wörter mit seltenen Paaren wie PF, QU oder CH zu finden.","Füge deine Buchstaben in „nur diese Buchstaben“ ein, um vom Stöbern in den Spielmodus zu wechseln.","Lass die Länge auf „Beliebig“, wenn du suchst, und setze sie erst, wenn du die genaue Anzahl an Buchstaben kennst.","Endungsfilter eignen sich hervorragend, um Reime und Wortfamilien zu bilden."]',
        '[{"question":"Was ist ein Wort-Finder?","answer":"Ein Wort-Finder durchsucht ein Wörterbuch nach Mustern – Anfangsbuchstaben, Endbuchstaben, enthaltene Zeichenfolgen und Länge – und gibt alle passenden Wörter aus. Er ist umfassender als ein Entwirrer, da er das gesamte Wörterbuch und nicht nur deine Buchstaben durchsuchen kann."},{"question":"Wie unterscheidet sich das vom Buchstaben-Entwirrer?","answer":"Der Entwirrer zeigt nur Wörter aus einem festen Buchstabensatz. Der Wort-Finder durchsucht das gesamte Wörterbuch nach Mustern und kann optional auf deine Buchstaben eingeschränkt werden, wenn du spielbare Wörter suchst."},{"question":"Kann ich die Ergebnisse auf mein Scrabble-Rack beschränken?","answer":"Ja. Gib deine Buchstaben in das Feld „nur diese Buchstaben“ ein (verwende ? für Platzhalter). Der Finder zeigt dann nur Wörter, die du legen kannst, unter Berücksichtigung deiner anderen Filter."},{"question":"Kann ich mehrere Filter kombinieren?","answer":"Ja. Beginnt mit, endet mit, enthält und Länge arbeiten zusammen, sodass du so breit oder genau suchen kannst, wie du möchtest."},{"question":"Ist der Wort-Finder kostenlos?","answer":"Ja – völlig kostenlos, ohne Anmeldung oder Download. Er läuft sofort im Browser auf jedem Gerät."},{"question":"Sind die Ergebnisse in Wortspielen gültig?","answer":"Der Finder verwendet ein umfassendes deutsches Wörterbuch, das auf Standard-Turnierwortlisten basiert. Die Ergebnisse sind daher in Scrabble und anderen Wortspielen gültig, abgesehen von seltenen regionalen Abweichungen."}]',
        'Suche nach deutschen Wörtern mit bestimmten Buchstabenmustern',
        '["Wort Finder","Wörter suchen nach Buchstaben","Wörter mit bestimmten Buchstaben","Wortsuche mit Länge","Deutsche Wörter finden","Scrabble Wortsuche","Wortmuster suchen","Wort Generator"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'rhyming-words',
        'de',
        'Rhyming Words',
        'Reimwörter finden – Perfekte Reime | AllWordTools',
        'Kostenloser Reimfinder: Geben Sie ein Wort ein und erhalten Sie perfekte und unreine Reime, gruppiert nach Silbenanzahl – ideal für Lieder, Gedichte und Reime.',
        '',
        'Reimwörter finden',
        'Geben Sie ein beliebiges Wort ein und erhalten Sie perfekte und unreine Reime, übersichtlich nach Silbenanzahl gruppiert – alles, was Sie für Lieder, Gedichte und Verse brauchen.',
        '["Ein Reimlexikon verwandelt ein einzelnes Wort in eine Palette passender Klänge. Geben Sie ein Wort in den Reimfinder von AllWordTools.com ein und Sie erhalten sowohl perfekte Reime als auch unreine Reime, gruppiert nach Silbenanzahl – so finden Sie im Handumdrehen die ideale Zeilenendung.","Reime sind der Herzschlag von Liedern, Gedichten und Rap. Der richtige Reim kann eine Zeile zum Einschlagen bringen, einen Refrain haften lassen und eine Strophe zum Klingen bringen. Aber im Kopf nach Reimen zu suchen ist langsam und man übersieht immer Optionen – dieses Tool spült jeden Treffer auf einmal aus, von offensichtlich bis unerwartet.","Es ist schnell, kostenlos und funktioniert sofort in Ihrem Browser auf jedem Gerät – ohne Anmeldung und ohne Limits."]',
        'So finden Sie Reimwörter',
        '[{"title":"Ein Wort eingeben","detail":"Geben Sie das Wort ein, auf das Sie einen Reim suchen – meist das letzte Wort Ihrer Zeile."},{"title":"Reime finden","detail":"Klicken Sie auf „Reime finden“, um perfekte und unreine Reime zu sehen, gruppiert nach Silbenanzahl."},{"title":"Den Rhythmus anpassen","detail":"Wählen Sie einen Reim mit derselben Silbenanzahl, um Ihr Metrum beizubehalten, oder einen unreinen Reim für einen lockereren Klang."},{"title":"Kopieren und weiterschreiben","detail":"Tippen Sie auf ein beliebiges Wort, um es direkt in Ihren Liedtext, Ihr Gedicht oder Ihre Karte zu kopieren."}]',
        '[{"heading":"Perfekte vs. unreine Reime","paragraphs":["Ein perfekter Reim hat denselben Endklang ab dem betonten Vokal – wie „Haus“ und „Maus“ oder „Schlange“ und „Gänge“. Das sind die klassischen, befriedigenden Reime, die eine Zeile abschließen. Der Reimfinder listet sie zuerst, weil sie die stärksten Übereinstimmungen sind.","Unreine Reime (auch Halbreime oder Assonanzen genannt) haben einen ähnlichen, aber nicht identischen Klang – wie „Schiff“ und „tief“ oder „Liebe“ und „Triebe“. Moderne Songwriter und Dichter nutzen ständig unreine Reime, weil sie natürlicher klingen und viel mehr Wortmöglichkeiten bieten. Das Tool zeigt beide an, sodass Sie den gewünschten Effekt wählen können."]},{"heading":"Warum die Silbengruppierung wichtig ist","paragraphs":["Ein guter Reim ist nur die halbe Miete – der Rhythmus ist die andere Hälfte. Ein einsilbiger Reim und ein dreisilbiger Reim passen in ganz unterschiedliche Zeilen. Durch die Gruppierung der Ergebnisse nach Silbenanzahl können Sie einen Reim wählen, der Ihr Metrum intakt hält, sodass die Zeile beim lauten Lesen immer noch stimmig klingt.","Dies ist besonders nützlich für strukturierte Formen wie Sonette, Limericks und Pop-Refrains, bei denen die Anzahl der Betonungen pro Zeile festgelegt ist. Scannen Sie zur benötigten Silbenanzahl, und jede Option dort passt in den Rhythmus."]}]',
        '[{"input":"Liebe","output":"Triebe, Hiebe, Siebe (perfekt); bliebe, schiebe (unrein)","note":"Perfekte Reime zuerst, dann unreine."},{"input":"Zeit","output":"weit, Leid, Kleid, schreit","note":"Nach Silbenanzahl gruppiert für schnelles Überfliegen."},{"input":"Feuer","output":"Neuer, Getreuer, Heuer (perfekt); teurer (unrein)","note":"Mehrsilbige Reime für reichhaltigere Zeilen."}]',
        '["Reimen Sie das letzte betonte Wort Ihrer Zeile für den natürlichsten Fluss.","Passen Sie die Silbenanzahl an, um das Metrum in formalen Versen stabil zu halten.","Greifen Sie zu unreinen Reimen, wenn perfekte Reime gezwungen oder klischeehaft wirken.","Längere, mehrsilbige Reime klingen oft frischer als kurze, offensichtliche.","Kombinieren Sie den Reimfinder mit unserem Silbenzähler, um den Rhythmus Ihrer gesamten Zeile zu fixieren."]',
        '[{"question":"Was ist der Unterschied zwischen einem perfekten und einem unreinen Reim?","answer":"Ein perfekter Reim stimmt im Endklang ab dem betonten Vokal genau überein, wie „Haus“ und „Maus“. Ein unreiner Reim ist ähnlich, aber nicht identisch, wie „Schiff“ und „tief“, und gibt mehr Flexibilität."},{"question":"Warum sind die Reime nach Silbenanzahl gruppiert?","answer":"Die Gruppierung nach Silbenanzahl hilft, Ihren Rhythmus und Ihr Metrum konsistent zu halten. Sie können einen Reim mit der gleichen Anzahl Silben wählen wie das ursprüngliche Wort."},{"question":"Ist der Reimfinder kostenlos?","answer":"Ja – vollkommen kostenlos, ohne Anmeldung, und läuft sofort in Ihrem Browser auf jedem Gerät."},{"question":"Warum hat mein Wort keine Reime ergeben?","answer":"Sehr seltene Wörter, Eigennamen und Tippfehler haben möglicherweise keine gelisteten Reime. Versuchen Sie ein gebräuchlicheres Wort oder überprüfen Sie die Rechtschreibung."},{"question":"Kann der Reimfinder beim Songwriting und Dichten helfen?","answer":"Absolut. Er ist für Liedtexte, Gedichte, Rap und Grußkarten gemacht und bietet sowohl perfekte als auch unreine Reime, damit Sie den genauen Klang und Rhythmus finden, den Sie brauchen."}]',
        'Deutsche Reimwörter finden für Gedichte, Lieder und Texte',
        '["Reimwörter finden","Reimwort","Reimmaschine","Reimlexikon","unreine Reime","Reime nach Silbenanzahl","kostenloser Reimfinder","Passende Reime","Reimwörterbuch"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'synonym-finder',
        'de',
        'Synonym Finder',
        'Synonym Finder – Bessere Wortalternativen | AllWordTools',
        'Kostenloser Synonym-Finder. Gib ein Wort ein und erhalte sofort eine Liste mit passenden Alternativen – für klarere, abwechslungsreichere Texte.',
        '',
        'Synonym Finder',
        'Gib ein Wort ein und entdecke sofort zahlreiche Synonyme und verwandte Begriffe – klicke auf ein Ergebnis, um es direkt in deinen Text zu übernehmen.',
        '["Ein Synonym Finder hilft dir, das Gleiche frischer und präziser auszudrücken. Statt immer dasselbe Wort zu wiederholen, tippst du es in den AllWordTools.com Synonym Finder und siehst sofort dutzende Alternativen – von sehr ähnlichen bis hin zu verwandten Begriffen. So wählst du das Wort, das perfekt in deinen Satz passt.","Gute Texte leben von der Wortwahl. Ein ausdrucksstarkes Synonym kann den gesamten Ton eines Satzes verändern, deine Argumentation verschärfen oder eine Beschreibung lebendiger machen. Dieses Tool macht den Austausch mühelos – ob du einen Aufsatz schreibst, eine E-Mail verfeinerst, eine Geschichte erzählst oder ein Rätsel löst.","Es ist schnell, kostenlos und funktioniert sofort in deinem Browser auf jedem Gerät – ohne Anmeldung und ohne Einschränkungen."]',
        'So verwendest du den Synonym Finder',
        '[{"title":"Ein Wort eingeben","detail":"Gib das Wort ein, für das du Alternativen suchst – ein einzelnes Wort liefert die besten Ergebnisse."},{"title":"Synonyme finden","detail":"Drücke auf „Synonyme finden“ und eine sortierte Liste mit Synonymen und verwandten Wörtern erscheint sofort."},{"title":"Ergebnisse durchgehen","detail":"Die ähnlichsten und gebräuchlichsten Treffer erscheinen zuerst, sodass du schnell die beste Wahl triffst."},{"title":"Kopieren und einfügen","detail":"Tippe auf ein Wort, um es zu kopieren, und füge es direkt in dein Dokument ein."}]',
        '[{"heading":"Warum Synonyme in Texten wichtig sind","paragraphs":["Wiederholungen sind einer der schnellsten Wege, um Texte langweilig wirken zu lassen. Wenn dasselbe Wort immer wieder auftaucht, fällt es den Lesern auf und der Sprachfluss leidet. Synonyme durchbrechen dieses Muster: Du behältst die Bedeutung, variierst aber die Sprache, sodass jeder Satz bewusst und lebendig wirkt.","Synonyme ermöglichen auch mehr Präzision. Die deutsche Sprache ist voller bedeutungsähnlicher Wörter mit feinen Nuancen – „glücklich“, „zufrieden“ und „fröhlich“ sind nicht austauschbar. Wenn du sie nebeneinander siehst, kannst du das Wort wählen, das genau die Nuance trifft, die du meinst."]},{"heading":"Für wen eignet sich der Synonym Finder?","paragraphs":["Schüler und Studenten nutzen ihn, um die Qualität von Aufsätzen zu verbessern und Wiederholungen zu vermeiden. Berufstätige verwenden ihn, um E-Mails, Berichte und Präsentationen zu schärfen. Autoren und Texter finden das Wort mit der genau passenden Wirkung, und Rätselfreunde knacken Hinweise, die auf Wortbedeutungen beruhen.","Da er sofort und kostenlos ist, eignet er sich auch hervorragend, um den eigenen Wortschatz zu erweitern – jede Suche macht dich mit neuen Wörtern vertraut, die du vielleicht sonst nicht verwendet hättest."]}]',
        '[{"input":"schnell","output":"rasch, zügig, flott, hurtig, geschwind","note":"Gängige, ähnliche Synonyme erscheinen zuerst."},{"input":"wichtig","output":"bedeutend, wesentlich, relevant, entscheidend, essenziell","note":"Wähle den passenden Bedeutungsgrad."},{"input":"schön","output":"hübsch, ansprechend, attraktiv, reizend, prächtig","note":"Variiere den Ton von alltäglich bis gehoben."}]',
        '["Gib einzelne Wörter ein – die Ergebnisse sind dann am besten.","Die ersten Treffer sind die ähnlichsten; blättere weiter für kreativere Alternativen.","Achte auf Nuancen – Synonyme sind selten perfekte Zwillinge, also lies den Tonfall.","Kombiniere den Synonym Finder mit dem Antonym Finder, wenn du die Bedeutung umkehren möchtest.","Nutze ihn als Vokabeltrainer – merke dir neue Wörter, die dir gefallen."]',
        '[{"question":"Was ist ein Synonym Finder?","answer":"Ein Synonym Finder ist ein Tool, das zu einem eingegebenen Wort andere Wörter mit gleicher oder ähnlicher Bedeutung ausgibt. So kannst du deine Sprache abwechslungsreicher gestalten und den treffendsten Ausdruck wählen."},{"question":"Ist der Synonym Finder kostenlos?","answer":"Ja – er ist komplett kostenlos, ohne Anmeldung, ohne Downloads und ohne Einschränkungen. Er läuft sofort in deinem Browser auf jedem Gerät."},{"question":"Warum liefern manche Wörter mehr Synonyme als andere?","answer":"Häufige Wörter haben viele etablierte Synonyme, während seltene oder sehr spezifische Wörter natürlicherweise weniger haben. Eigennamen und Tippfehler liefern wenige oder gar keine Treffer."},{"question":"Sind die Synonyme sortiert?","answer":"Ja. Die ähnlichsten und relevantesten Treffer erscheinen zuerst, sodass die besten Alternativen immer oben in der Liste stehen."},{"question":"Kann ich das Tool auch für andere Sprachen nutzen?","answer":"Der Synonym Finder ist für die deutsche Sprache optimiert. Für beste Ergebnisse gib ein korrekt geschriebenes deutsches Wort ein."}]',
        'Suche nach einem kostenlosen Synonymwörterbuch oder Wortersatz-Tool online',
        '["Synonym Finder","Synonyme finden","Wortalternativen","Synonymwörterbuch online","bessere Wortwahl","Text abwechslungsreicher","Synonyme Deutsch","Wortersatz","kostenlos Synonyme"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'antonym-finder',
        'de',
        'Antonym Finder',
        'Gegenteil Finder — Antonyme finden | AllWordTools',
        'Kostenloser Antonym-Finder: Geben Sie ein Wort ein und erhalten Sie sofort das passende Gegenteil – ideal für besseres Schreiben, Wortschatzübungen & Rätsel.',
        '',
        'Antonym Finder',
        'Geben Sie ein Wort ein und sehen Sie sofort die Gegenteile – perfekt, um Kontraste zu schaffen, Argumente zu schärfen oder Rätsel zu lösen.',
        '["Ein Antonym-Finder liefert Ihnen im Handumdrehen das Gegenteil eines beliebigen Wortes. Geben Sie ein Wort in den Antonym-Finder von AllWordTools.com ein, und er zeigt Ihnen die klarsten Gegenteile – so können Sie Kontraste in Ihren Text einbauen oder genau bestimmen, was ein Wort nicht ist.","Gegenteile sind ein mächtiges Stilmittel. Kontraste lassen Ideen hervorstechen – „nicht schwach, sondern stark“, „nicht das Ende, sondern der Anfang“. Das richtige Antonym zu kennen, hilft Ihnen, Argumente präzise zu formulieren, lebendige Beschreibungen zu schreiben und einprägsame Vergleiche zu ziehen.","Es ist schnell, kostenlos und funktioniert sofort in Ihrem Browser auf jedem Gerät – ohne Anmeldung und ohne Einschränkungen."]',
        'So verwenden Sie den Antonym-Finder',
        '[{"title":"Geben Sie ein Wort ein","detail":"Tippen Sie das Wort ein, zu dem Sie das Gegenteil suchen – einzelne Wörter liefern die besten Ergebnisse."},{"title":"Antonyme finden","detail":"Klicken Sie auf „Antonyme finden“ und sofort erscheinen alle direkten Gegenteile, die wir finden können."},{"title":"Wählen Sie das passende Gegenteil","detail":"Manche Wörter haben mehrere Gegenteile mit unterschiedlichen Nuancen – wählen Sie das, das in Ihren Satz passt."},{"title":"Kopieren und einfügen","detail":"Tippen Sie auf ein Wort, um es zu kopieren und in Ihr Dokument einzufügen."}]',
        '[{"heading":"Warum Antonyme Ihr Schreiben verbessern","paragraphs":["Antonyme schaffen Kontraste, und Kontraste schaffen Klarheit. Wenn Sie ein Wort neben sein Gegenteil setzen, werden beide Bedeutungen schärfer – Leser erfassen sofort die Unterscheidung, die Sie treffen. Deshalb basieren so viele einprägsame Formulierungen auf Gegensätzen.","Antonyme sind auch eine schnelle Möglichkeit, die eigene Präzision zu überprüfen. Wenn das Gegenteil des gewählten Wortes nicht genau das ist, was Sie verneinen möchten, dann transportiert das Wort selbst vielleicht nicht die beabsichtigte Bedeutung."]},{"heading":"Für wen ist der Antonym-Finder geeignet?","paragraphs":["Schüler und Studenten nutzen ihn für Aufsätze, Textverständnis und Wortschatzarbeit. Autoren verwenden ihn, um Kontraste und Spannung aufzubauen. Rätselfans und Quizbegeisterte setzen ihn bei Kreuzworträtseln und Wortspielen ein, bei denen nach einem Gegenteil gefragt wird, und Sprachlernende verstehen Wörter besser, indem sie lernen, was sie nicht sind.","Da nicht jedes Wort ein passendes Gegenteil hat, konzentriert sich der Finder auf echte, direkte Antonyme statt auf lose verwandte Wörter – so erhalten Sie Ergebnisse, die wirklich gegensätzlich sind."]}]',
        '[{"input":"heiß","output":"kalt, kühl, eisig, frostig","note":"Klare, direkte Gegenteile zuerst."},{"input":"steigern","output":"senken, verringern, reduzieren, mindern","note":"Ideal für Berichte und Analysen."},{"input":"mutig","output":"feige, ängstlich, zaghaft","note":"Wählen Sie den Ton, der zu Ihrem Satz passt."}]',
        '["Geben Sie einzelne Wörter ein – Antonyme funktionieren am besten bei einem klaren Begriff.","Manche Wörter haben mehrere Gegenteile; wählen Sie das passende für Ihren Kontext.","Nicht jedes Wort hat ein echtes Gegenteil – abstrakte oder sehr spezifische Wörter liefern möglicherweise wenige Ergebnisse.","Kombinieren Sie den Antonym-Finder mit dem Synonym-Finder, um das gesamte Bedeutungsspektrum eines Wortes zu erkunden.","Antonym-Paare eignen sich hervorragend als Lernkarten für den Wortschatzaufbau."]',
        '[{"question":"Was ist ein Antonym-Finder?","answer":"Ein Antonym-Finder nimmt ein Wort entgegen und liefert Wörter mit gegenteiliger Bedeutung – hilfreich, um Kontraste in Ihren Texten zu erzeugen oder Rätsel zu lösen, die nach einem Gegenteil fragen."},{"question":"Warum haben manche Wörter keine Antonyme?","answer":"Nicht jedes Wort hat ein direktes Gegenteil. Konkrete Nomen sowie sehr spezifische oder fachliche Begriffe haben oft kein natürliches Antonym, sodass der Finder wenige oder keine Ergebnisse liefert."},{"question":"Ist der Antonym-Finder kostenlos?","answer":"Ja – völlig kostenlos, ohne Anmeldung oder Downloads, und läuft sofort in Ihrem Browser auf jedem Gerät."},{"question":"Wie sind die Ergebnisse sortiert?","answer":"Die klarsten und relevantesten Gegenteile erscheinen zuerst, sodass das stärkste Antonym meist ganz oben steht."},{"question":"Funktioniert der Finder auch für Wortgruppen?","answer":"Er ist für einzelne Wörter konzipiert. Für beste Ergebnisse geben Sie jeweils ein korrekt geschriebenes Wort ein."}]',
        'User möchte schnell und einfach das Gegenteil eines bestimmten Wortes finden.',
        '["Antonym finden","Gegenteil suchen","Wort Gegenteil","Gegenteil von","Antonyme Liste","Gegenteil Wörterbuch","Antonyme Deutsch","Gegenteil kostenlos","Gegenteil online finden"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'words-starting-with',
        'de',
        'Words Starting With',
        'Wörter mit Anfangsbuchstaben finden | AllWordTools',
        'Kostenloser Wörter-nach-Anfangsbuchstaben-Finder. Gib einen Präfix ein und finde sofort alle deutschen Wörter, die damit beginnen, gruppiert nach Länge.',
        '',
        'Wörter mit Anfangsbuchstaben',
        'Gib einen Präfix ein und sieh sofort alle gültigen Wörter, die mit diesen Buchstaben beginnen – übersichtlich nach Länge gruppiert und bereit zum Kopieren.',
        '["Ein Wörter-Anfangsbuchstaben-Finder beantwortet eine der häufigsten Fragen bei Wortspielen und beim Schreiben: Welche Wörter beginnen mit diesen Buchstaben? Gib einen Präfix wie „vor“, „un“ oder „zw“ ein, und der AllWordTools.com-Finder durchsucht ein umfangreiches deutsches Wörterbuch und zeigt alle Treffer sofort an, gruppiert nach Länge, sodass du das gesuchte Wort leicht findest.","Dieses Tool ist perfekt für Scrabble- und Wortspiel-Züge, bei denen du an einem bestimmten Anfangsbuchstaben anknüpfen musst, für Kreuzworträtsel-Hinweise, bei denen du die ersten Buchstaben kennst, und für alle, die ihren Wortschatz erweitern oder Namensideen sammeln. Füge eine genaue Länge hinzu, um eine lange Liste auf genau die Wörter einzugrenzen, die in dein Rätsel passen.","Es ist schnell, kostenlos und absolut privat – jede Suche läuft in deinem Browser, ohne Anmeldung und ohne Limit."]',
        'So findest du Wörter mit bestimmten Anfangsbuchstaben',
        '[{"title":"Gib deine Anfangsbuchstaben ein","detail":"Tippe den Präfix ein, mit dem die Wörter beginnen sollen – ein Buchstabe oder mehrere."},{"title":"Wähle eine Länge (optional)","detail":"Lege eine genaue Wortlänge fest, um die Ergebnisse einzugrenzen, oder lasse sie auf „Beliebig“."},{"title":"Wörter finden","detail":"Klicke auf „Wörter finden“, um das gesamte Wörterbuch zu durchsuchen und alle Treffer nach Länge gruppiert zu sehen."},{"title":"Kopiere, was du brauchst","detail":"Tippe auf ein Wort, um es sofort zu kopieren – mit der dazugehörigen Scrabble-Punktzahl."}]',
        '[{"heading":"Warum nach Anfangsbuchstaben suchen?","paragraphs":["Anfänge sind entscheidend. Bei Brettspielen musst du oft an einen bereits auf dem Brett liegenden Stein anknüpfen. Daher ist es ein echter Punktevorteil, jedes Wort zu kennen, das mit einem bestimmten Buchstaben beginnt. Bei Kreuzworträtseln ist der erste oder zweite Buchstabe einer Antwort oft der einfachste Hinweis – und von dort aus enthüllt eine Präfix-Suche den Rest.","Über Spiele hinaus ist eine Präfix-Suche eine schnelle Möglichkeit, den Wortschatz zu erweitern, Marken- oder Charakternamen zu finden oder Wortfamilien zu sammeln, die einen gemeinsamen Anfang wie „über“, „miss“ oder „ent“ teilen."]},{"heading":"Das Tool optimal nutzen","paragraphs":["Beginne breit mit einem kurzen Präfix, um die gesamte Landschaft zu sehen, und füge dann eine genaue Länge hinzu, sobald du weißt, wie viele Quadrate oder Steine du füllen musst. Die Ergebnisse sind so sortiert, dass Wörter mit höherem Wert innerhalb jeder Längengruppe oben erscheinen – das hilft, wenn du Punkte jagst.","Da die Suche gegen eine umfassende Turnier-Wortliste läuft, sind die angezeigten Wörter in den meisten Spielen gültig, abgesehen von seltenen Abweichungen zwischen offiziellen Wörterbüchern."]}]',
        '[{"input":"Beginnt mit: zw","output":"Zwang, Zweck, Zwiebel, Zwilling, zwölf","note":"Hilft beim Legen schwieriger Buchstaben wie Z und W."},{"input":"Beginnt mit: sch, Länge: 6","output":"Schule, schlaf, Schirm, schick, Schach","note":"Mit Längenangabe perfekt für Kreuzworträtsel-Felder."},{"input":"Beginnt mit: q","output":"Quark, Quelle, Quiz, Qual, Quadrat","note":"Entdecke ungewöhnliche Anfänge, um Bonuspunkte zu sammeln."}]',
        '["Kurze Präfixe zeigen mehr Wörter – beginne breit, grenze dann mit einer Länge ein.","Kombiniere einen Anfangsbuchstaben, an den du anknüpfen musst, mit einer Länge, die zu den freien Feldern passt.","Zwei- und dreibuchstabige Ergebnisse sind die einfachsten Anknüpfpunkte für Anschlusszüge.","Achte auf hochwertige Anfänge wie Q, Z, X und J, um deine Punktzahl zu maximieren.","Nutze die Punktanzeigen, um den lohnendsten Zug auszuwählen, nicht nur den längsten."]',
        '[{"question":"Wie finde ich Wörter, die mit bestimmten Buchstaben beginnen?","answer":"Gib deine Anfangsbuchstaben in den Finder ein und drücke „Wörter finden“. Er durchsucht ein vollständiges deutsches Wörterbuch und listet jedes Wort auf, das mit diesem Präfix beginnt, gruppiert nach Länge."},{"question":"Kann ich die Ergebnisse auf eine bestimmte Länge eingrenzen?","answer":"Ja. Wähle eine genaue Länge aus dem Dropdown-Menü, um nur Wörter mit dieser Buchstabenanzahl anzuzeigen – ideal für Kreuzworträtsel- oder Scrabble-Felder."},{"question":"Sind die Wörter bei Scrabble und anderen Wortspielen gültig?","answer":"Der Finder verwendet eine umfassende Turnier-Wortliste, sodass die Ergebnisse in den meisten Spielen gültig sind, abgesehen von seltenen Abweichungen zwischen offiziellen Wörterbüchern."},{"question":"Gibt es ein Limit für die Anzahl der Suchen?","answer":"Nein. Das Tool ist völlig kostenlos mit unbegrenzten Suchen, und alles läuft privat in deinem Browser."},{"question":"Warum werden nur einige Ergebnisse angezeigt?","answer":"Bei sehr häufigen Präfixen begrenzen wir die Liste aus Performance- und Lesbarkeitsgründen. Füge eine exakte Länge hinzu, um eine kompaktere, relevantere Wortliste zu erhalten."}]',
        'Wörter nach Anfangsbuchstaben suchen',
        '["Wörter mit Anfangsbuchstaben","Wörter die mit ... beginnen","Wortanfänge finden","Buchstabensalat lösen","Scrabble Wortfinder","Wortsuche nach Präfix","Wörter mit bestimmten Buchstaben am Anfang","Wortliste nach Anfangsbuchstaben"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'words-ending-with',
        'de',
        'Words Ending With',
        'Wörter mit Endung finden — Reimsuche | AllWordTools',
        'Kostenloser Wörter-nach-Endung-Finder. Gib Buchstaben ein und erhalte alle deutschen Wörter mit dieser Endung – perfekt für Reime, Kreuzworträtsel und Wortspiele.',
        '',
        'Wörter mit Endung',
        'Gib eine Endung ein und erhalte sofort alle gültigen deutschen Wörter, die mit diesen Buchstaben enden – nach Länge gruppiert und bereit zum Kopieren.',
        '["Ein Wörter-nach-Endung-Finder dreht die übliche Suche um: Statt des Anfangs gibst du die Endung ein. Gib eine Endung wie \"ung\", \"tion\" oder \"keit\" ein, und der AllWordTools.com Finder zeigt dir jedes passende deutsche Wort, nach Länge sortiert.","Die Suche nach Suffixen ist unverzichtbar für Reime und Gedichte, für Wortfamilien mit gemeinsamer Endung, für Kreuzworträtsel, bei denen die letzten Buchstaben bekannt sind, und für Wortspiele, bei denen ein Zug an ein bereits liegendes Teil anschließen muss. Füge eine genaue Länge hinzu, um die Liste einzugrenzen.","Schnell, kostenlos und datenschutzkonform – jede Suche läuft sofort im Browser, ohne Anmeldung."]',
        'So finden Sie Wörter, die mit bestimmten Buchstaben enden',
        '[{"title":"Gib die Endbuchstaben ein","detail":"Tippe die Endung ein, z. B. einen einzelnen Buchstaben oder eine vollständige Endung wie ''ung''."},{"title":"Länge festlegen (optional)","detail":"Wähle eine genaue Wortlänge aus, um die Ergebnisse einzugrenzen, oder lasse die Option auf ''Beliebig''."},{"title":"Wörter finden","detail":"Klicke auf ''Wörter finden'', um das Wörterbuch zu durchsuchen und die Treffer nach Länge gruppiert zu sehen."},{"title":"Kopiere, was du brauchst","detail":"Tippe auf ein Wort, um es zu kopieren – die Punktzahl für Wortspiele wird zum schnellen Vergleich angezeigt."}]',
        '[{"heading":"Warum nach Endbuchstaben suchen?","paragraphs":["Endungen bestimmen Reim und Rhythmus, daher ist eine Suffix-Suche der beste Freund von Songwritern und Dichtern. Gib den gewünschten Klang ein und sammle alle passenden Reime auf einmal. Die gleiche Suche zeigt grammatikalische Wortfamilien – alle Wörter auf \"ung\", \"keit\" oder \"heit\" – nützlich fürs Schreiben und Lernen.","Bei Spielen müssen Züge manchmal an einem bestimmten Buchstaben auf dem Brett enden, und Kreuzworträtsel geben oft die letzten Buchstaben einer Lösung vor. Eine Suche nach Wörtern mit Endung verwandelt diese partiellen Hinweise in eine vollständige Liste von Optionen."]},{"heading":"Das Beste aus dem Tool herausholen","paragraphs":["Beginne mit einer kurzen Endung, um alle Möglichkeiten zu sehen, und füge dann eine genaue Länge hinzu, sobald du den Platz kennst, den du füllen musst. Innerhalb jeder Längengruppe sind die Ergebnisse nach Punktzahl sortiert, sodass die wertvollsten Züge zuerst erscheinen.","Der Finder durchsucht ein umfangreiches Wörterbuch in Turnierqualität, daher sind die Wörter in den meisten Spielen gültig, mit nur seltenen Abweichungen zwischen offiziellen Wortlisten."]}]',
        '[{"input":"Endung: ung","output":"Zeitung, Übung, Rechnung, Bewegung, Schöpfung","note":"Ideal für grammatische Wortfamilien und Reime."},{"input":"Endung: ion, Länge: 7","output":"Aktion, Nation, Lotion, Portion, Region","note":"Durch Vorgabe einer Länge erhältst du eine genau passende Auswahl."},{"input":"Endung: zz","output":"Schlitz, Blitz, Sitz, Spitz, Witz","note":"Seltene Doppelbuchstaben am Ende für hohe Punktzahlen finden."}]',
        '["Kurze Endungen liefern mehr Wörter – fange breit an und grenze mit der Länge ein.","Suffix-Suchen sind der schnellste Weg, Reime für Lieder und Gedichte zu sammeln.","Passe die Endung an einen erforderlichen Buchstaben auf dem Spielbrett an, um einen gültigen Zug zu finden.","Beachte die Punktzahlen, um wertvolle Endungen wie ZZ oder QU zu erkennen.","Kombiniere eine Endung mit einer exakten Länge, um eine Kreuzworträtsellösung genau zu bestimmen."]',
        '[{"question":"Wie finde ich Wörter, die mit bestimmten Buchstaben enden?","answer":"Gib die Endbuchstaben in den Finder ein und klicke auf ''Wörter finden''. Er durchsucht das gesamte deutsche Wörterbuch und listet alle passenden Wörter auf, nach Länge gruppiert."},{"question":"Ist das nützlich, um Reime zu finden?","answer":"Ja. Die Suche nach Endungen ist eine schnelle Methode, um Wörter mit gleichem Suffix zu sammeln, die häufig reimen. Für klanggenaue Reime nutze am besten unser spezielles Reimwörterbuch."},{"question":"Kann ich eine genaue Wortlänge festlegen?","answer":"Ja. Wähle eine Länge aus dem Dropdown-Menü, um nur Wörter mit dieser Buchstabenanzahl anzuzeigen – ideal für Kreuzworträtsel und bestimmte Spielzüge."},{"question":"Sind die Ergebnisse bei Wortspielen gültig?","answer":"Der Finder verwendet eine umfassende Turnier-Wortliste, daher sind die Ergebnisse in den meisten Spielen gültig, abgesehen von seltenen Unterschieden zwischen offiziellen Wörterbüchern."},{"question":"Ist das Tool kostenlos?","answer":"Völlig kostenlos, mit unbegrenzten Suchanfragen. Alles läuft datenschutzkonform in deinem Browser ohne Anmeldung."}]',
        'Wörter nach bestimmten Buchstaben am Ende suchen',
        '["Wörter mit Endung","Wörter nach Endung suchen","Wörter die auf enden","Wortendungen finden","Wörter nach Suffix","Reime suchen","Kreuzworträtsel Hilfe Endung","Wörter mit bestimmter Endung"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'words-containing',
        'de',
        'Words Containing',
        'Wörter mit Buchstaben finden | AllWordTools',
        'Kostenloser Wortfinder: Gib eine Buchstabenfolge ein und finde alle deutschen Wörter, die diese enthalten. Perfekt für Kreuzworträtsel, Scrabble & Wortspiele.',
        '',
        'Wörter mit Buchstabenfolge',
        'Gib eine Buchstabenfolge ein und finde sofort alle deutschen Wörter, die diese enthalten – egal wo im Wort.',
        '["Mit unserem Wortfinder für Buchstabenfolgen suchst du nicht nur nach Wörtern, die mit einer bestimmten Zeichenkette beginnen oder enden, sondern nach allen Wörtern, die diese Folge irgendwo enthalten. Gib einfach „sch\", „pf\" oder „cht\" ein – und erhalte eine vollständige Liste mit passenden deutschen Wörtern, übersichtlich nach Länge sortiert.","Dieses Tool ist ideal, wenn du bei Scrabble oder Wordfeud einen Buchstaben auf dem Brett nutzen möchtest, oder wenn dir bei einem Kreuzworträtsel nur ein Teil des Wortes bekannt ist. Es hilft dir auch, seltene Buchstabenkombinationen zu entdecken und deinen Wortschatz zu erweitern.","Die Suche läuft direkt in deinem Browser, ist völlig kostenlos und benötigt keine Anmeldung – deine Privatsphäre bleibt geschützt."]',
        'So findest du Wörter mit einer bestimmten Buchstabenfolge',
        '[{"title":"Buchstabenfolge eingeben","detail":"Gib die Zeichenkette ein, die im Wort vorkommen soll, z. B. „sch\" oder „pf\"."},{"title":"Optionale Längenangabe","detail":"Wähle eine genaue Wortlänge, um die Ergebnisse einzuschränken, oder lass die Option auf „Beliebig\"."},{"title":"Suchen starten","detail":"Klicke auf „Wörter finden\", um das Wörterbuch zu durchsuchen. Die Ergebnisse werden nach Länge gruppiert angezeigt."},{"title":"Wort kopieren","detail":"Tippe auf ein Wort, um es zu kopieren. Daneben siehst du die Punktzahl für Scrabble – ideal zum Vergleichen."}]',
        '[{"heading":"Warum nach Wortbestandteilen suchen?","paragraphs":["Viele Wortspiele werden in der Mitte des Spielfelds entschieden, wo du an bereits liegenden Buchstaben anbaust. Eine Enthält-Suche findet alle Wörter, die einen bestimmten Buchstaben oder ein Paar enthalten – so kannst du hohe Punktzahlen erzielen, indem du vorhandene Buchstaben geschickt nutzt.","Auch bei Kreuzworträtseln sind die Buchstaben, die du sicher weißt, oft in der Mitte des gesuchten Wortes. Gib sie hier ein, und der Finder zeigt dir passende Kandidaten – besonders nützlich in Kombination mit einer Längenangabe."]},{"heading":"Schwierige Buchstaben clever nutzen","paragraphs":["Seltene Buchstaben wie Q, X, Y und J sind schwer unterzubringen, bringen aber viele Punkte. Eine Enthält-Suche nach Kombinationen wie „qu\", „xa\" oder „ay\" zeigt dir Wörter, mit denen du diese wertvollen Buchstaben gewinnbringend einsetzen kannst. Du entdeckst dabei auch ungewöhnliche Buchstabencluster, die dir sonst vielleicht nicht einfallen würden.","Da der Finder auf einem umfangreichen, turnierüblichen Wörterbuch basiert, sind die angezeigten Wörter in den meisten Spielen gültig – Abweichungen zwischen offiziellen Wortlisten sind selten."]}]',
        '[{"input":"Enthält: sch","output":"Schule, Tasche, Fisch, schreiben, Geschirr","note":"Ideal, um ein „sch\" auf dem Brett zu nutzen."},{"input":"Enthält: pf","output":"Pferd, Apfel, Kopf, pflegen, Kampf","note":"Finde Wörter mit der typischen deutschen Buchstabenkombination."},{"input":"Enthält: cht, Länge: 7","output":"Nacht, Recht, Sicht, leicht, dachte","note":"Mit Längenangabe für exakte Kreuzworträtsel-Lösungen."}]',
        '["Suche nach häufigen Buchstabenpaaren wie CH, SCH oder PF, um an vorhandene Buchstaben anzuknüpfen.","Nutze die Enthält-Suche, um schwierige Buchstaben wie Q, X, Y und J unterzubringen.","Gib die mittleren Buchstaben eines Kreuzworträtsels ein und schränke die Länge ein.","Längere Buchstabenfolgen grenzen die Ergebnisse stark ein, wenn die Suche zu viele Treffer liefert.","Achte auf die angezeigten Punktzahlen, um den lohnendsten Zug auszuwählen."]',
        '[{"question":"Wie finde ich Wörter, die bestimmte Buchstaben enthalten?","answer":"Gib die Buchstabenfolge ein, die im Wort vorkommen soll, und klicke auf „Wörter finden\". Der Finder listet alle Wörter auf, die diese Folge enthalten – gruppiert nach Länge."},{"question":"Durchsucht das Tool das ganze Wort?","answer":"Ja, im Gegensatz zu Suchen nach Anfangs- oder Endbuchstaben findet dieser Finder die Folge am Anfang, in der Mitte und am Ende des Wortes – also überall, wo sie vorkommt."},{"question":"Kann ich eine Längenangabe kombinieren?","answer":"Ja. Wähle eine genaue Länge aus, um die Trefferliste auf Wörter mit genau dieser Buchstabenanzahl zu beschränken – praktisch für Kreuzworträtsel und bestimmte Spielzüge."},{"question":"Ist das Tool auch für schwierige Buchstaben geeignet?","answer":"Sehr. Die Suche nach Kombinationen wie QU, PF oder CH zeigt dir Wörter, mit denen du knifflige Buchstaben wie Q, X oder Y gewinnbringend einsetzen kannst."},{"question":"Ist das Tool kostenlos?","answer":"Ja, völlig kostenlos und ohne Anmeldung. Die Suche läuft privat in deinem Browser – unbegrenzt nutzbar."}]',
        'Finde deutsche Wörter, die eine bestimmte Buchstabenfolge enthalten',
        '["Wörter mit Buchstabenfolge","Wörter die enthalten","Buchstabenkette suchen","Wort finden mit Buchstaben","Wörter mit bestimmten Buchstaben","Buchstabenfolge Wortsuche","Scrabble Wortfinder","Kreuzworträtsel Hilfe","Wortspiele Lösung"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'letter-counter',
        'de',
        'Letter Counter',
        'Buchstaben & Wörter zählen online | AllWordTools',
        'Kostenloser Buchstaben-Zähler. Zählen Sie Buchstaben, Zeichen, Wörter, Sätze und Leerzeichen in jedem Text – inklusive Häufigkeitsverteilung.',
        '',
        'Buchstaben-Zähler',
        'Fügen Sie Text ein oder tippen Sie direkt – sofortige Zählung von Buchstaben, Zeichen, Wörtern, Sätzen und Leerzeichen inklusive Buchstabenhäufigkeit.',
        '["Ein Buchstaben-Zähler liefert Ihnen eine genaue Aufschlüsselung jedes Textes. Fügen Sie einen Aufsatz, einen Tweet, eine Produktbeschreibung oder ein Gedicht in den AllWordTools.com Buchstaben-Zähler ein – er zählt Zeichen, Buchstaben, Wörter, Sätze, Absätze, Leerzeichen und Zeilen in Echtzeit, während Sie tippen. Kein Knopfdruck nötig.","Er geht über einen einfachen Wortzähler hinaus, indem er eine vollständige Buchstabenhäufigkeitstabelle anzeigt, die zeigt, wie oft jeder Buchstabe vorkommt. Das ist nützlich für Autoren, die die Lesbarkeit prüfen, Studenten, die Längenvorgaben einhalten müssen, Entwickler, die Eingabelimits validieren, und Rätselfans, die Buchstabenverteilungen studieren.","Alles läuft privat in Ihrem Browser. Ihr Text verlässt niemals Ihr Gerät, das Tool ist völlig kostenlos und es gibt keine Begrenzung, wie viel Sie analysieren können."]',
        'So verwenden Sie den Buchstaben-Zähler',
        '[{"title":"Text einfügen oder tippen","detail":"Fügen Sie einen beliebigen Text in das Feld ein – die Zählung aktualisiert sich sofort, während Sie tippen oder bearbeiten."},{"title":"Live-Statistiken anzeigen","detail":"Sehen Sie auf einen Blick Zeichen, Buchstaben, Wörter, Sätze, Absätze, Leerzeichen und Zeilen."},{"title":"Buchstabenhäufigkeit prüfen","detail":"Nutzen Sie die Häufigkeitstabelle, um zu sehen, wie oft jeder Buchstabe in Ihrem Text vorkommt."},{"title":"Kopieren oder löschen","detail":"Kopieren Sie Ihren Text mit einem Klick oder leeren Sie das Feld, um neu zu beginnen."}]',
        '[{"heading":"Was der Buchstaben-Zähler misst","paragraphs":["Das Tool gibt mehrere Werte auf einmal aus. „Zeichen“ ist die Gesamtlänge inklusive Leerzeichen und Satzzeichen, während „Zeichen ohne Leerzeichen“ alle Whitespace-Zeichen entfernt. „Buchstaben“ zählt nur alphabetische Zeichen, ohne Zahlen und Symbole. Wörter, Sätze und Absätze werden anhand von Abständen und Satzzeichen erkannt, Leerzeichen und Zeilen runden das Bild ab.","Zusätzlich zu diesen Summen zeigt die Buchstabenhäufigkeitstabelle jeden Buchstaben von am häufigsten bis am seltensten in Ihrem Text mit einem Balken, der seinen relativen Anteil darstellt. So erkennen Sie schnell übermäßig verwendete Buchstaben, überprüfen ein Pangramm oder studieren Verteilungen für Rätsel und Chiffren."]},{"heading":"Wer nutzt einen Buchstaben-Zähler?","paragraphs":["Autoren und Studenten nutzen ihn, um genaue Längenvorgaben für Aufsätze, Biografien, Überschriften und Social-Media-Beiträge einzuhalten, wo jedes Zeichen zählt. Vermarkter überprüfen, ob Titel und Meta-Beschreibungen innerhalb der empfohlenen Grenzen liegen. Entwickler und Designer verwenden Zeichenzahlen, um Formularfelder und UI-Texte zu validieren.","Wortspiel- und Rätselfans nutzen die Häufigkeitsanalyse, um Buchstabenverteilungen zu untersuchen, Chiffren zu erstellen oder zu bestätigen, dass ein Satz jeden Buchstaben des Alphabets enthält."]}]',
        '[{"input":"„Hallo Welt“","output":"10 Zeichen, 9 Buchstaben, 2 Wörter, 1 Leerzeichen","note":"Eine kurze Plausibilitätsprüfung der Grundzählung."},{"input":"Ein Tweet mit 280 Zeichen","output":"Live-Zeichenanzahl während des Tippens","note":"Social-Media-Limits mühelos einhalten."},{"input":"„Franz jagt im komplett verwahrlosten Taxi quer durch Bayern“","output":"Häufigkeitstabelle zeigt jeden Buchstaben verwendet","note":"Pangramm auf einen Blick bestätigen."}]',
        '["Beachten Sie die Zählung „ohne Leerzeichen“ für Plattformen, die Whitespace ignorieren.","Nutzen Sie die Häufigkeitstabelle, um Buchstaben zu erkennen, die Sie übermäßig verwenden.","Meta-Titel sollten unter 60 Zeichen liegen, Beschreibungen unter 160.","Fügen Sie reinen Text ein, um genaue Zählungen zu erhalten – Formatierung kann versteckte Zeichen einfügen.","Das Tool läuft vollständig offline im Browser – Ihr Text bleibt privat."]',
        '[{"question":"Was zählt der Buchstaben-Zähler?","answer":"Er zählt Zeichen (mit und ohne Leerzeichen), Buchstaben, Wörter, Sätze, Absätze, Leerzeichen und Zeilen und zeigt eine vollständige Buchstabenhäufigkeitsverteilung – alles live während des Tippens."},{"question":"Wird mein Text gespeichert oder gesendet?","answer":"Nein. Alles läuft komplett in Ihrem Browser. Ihr Text verlässt niemals Ihr Gerät und wird weder gespeichert noch hochgeladen."},{"question":"Was ist der Unterschied zwischen Zeichen und Buchstaben?","answer":"Zeichen umfasst jedes Symbol, jede Zahl, jedes Leerzeichen und Satzzeichen. Buchstaben zählt nur die alphabetischen Zeichen A–Z."},{"question":"Kann es auch Wörter zählen?","answer":"Ja. Wörter werden zusammen mit Buchstaben und Zeichen gezählt, sodass es als Wortzähler und Zeichenzähler in einem fungiert."},{"question":"Gibt es eine Längenbegrenzung?","answer":"Nein. Sie können so viel Text einfügen, wie Sie möchten, und die Zählung aktualisiert sich sofort – kostenlos."}]',
        'Buchstaben zählen online',
        '["Buchstaben zählen","Zeichen zählen","Wörter zählen","Buchstabenanzahl","Zeichenanzahl","Textanalyse","Buchstabenhäufigkeit","Online Buchstaben zählen"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'syllable-counter',
        'de',
        'Syllable Counter',
        'Silbenzähler — Silben online zählen | AllWordTools',
        'Kostenloser Silbenzähler. Zählen Sie Silben in Wörtern, Zeilen oder Versen mit Aufschlüsselung pro Wort – ideal für Haiku, Poesie und Lesbarkeit.',
        '',
        'Silbenzähler',
        'Geben Sie ein Wort, eine Zeile oder einen Vers ein – der Silbenzähler zeigt sofort die Silbenanzahl mit einer Aufschlüsselung pro Wort. Perfekt für Haiku, Poesie und Songtexte.',
        '["Ein Silbenzähler verrät Ihnen genau, wie viele Silben in Ihren Wörtern stecken. Geben Sie Text in den AllWordTools.com Silbenzähler ein – er zeigt sofort die Gesamtzahl der Silben, die Wortanzahl, den Durchschnitt pro Wort und eine Aufschlüsselung pro Wort, damit Sie genau sehen, wo jede Silbe liegt.","Silben sind der Rhythmus der Sprache. Dichter, die das 5-7-5-Muster eines Haiku prüfen, Songwriter, die Wörter an eine Melodie anpassen, und Lehrer, die die Lesbarkeit bewerten – alle brauchen eine schnelle und genaue Zählung. Von Hand zu zählen ist langsam und fehleranfällig – dieses Tool erledigt es sofort beim Tippen.","Es läuft komplett im Browser, Ihre Texte bleiben privat, und es ist völlig kostenlos ohne Anmeldung."]',
        'Silben zählen: So geht''s',
        '[{"title":"Text eingeben","detail":"Tippen oder fügen Sie ein einzelnes Wort, eine Zeile oder einen ganzen Vers in das Feld ein."},{"title":"Gesamtwerte ablesen","detail":"Gesamtsilben, Wortanzahl und durchschnittliche Silben pro Wort werden sofort beim Tippen aktualisiert."},{"title":"Jedes Wort prüfen","detail":"Die Aufschlüsselung pro Wort zeigt die Silbenanzahl neben jedem Wort, damit Sie Problemstellen erkennen."},{"title":"Anpassen und verfeinern","detail":"Passen Sie Ihre Formulierung an, um eine genaue Silbenzahl zu erreichen – perfekt für Haiku, Metrum und Songtexte."}]',
        '[{"heading":"Was zählt als Silbe?","paragraphs":["Eine Silbe ist eine einzelne Lauteinheit mit einem Vokalklang, wie die zwei Silben in „Ta-bel“ oder die drei in „wun-der-bar“. Das Zählen von Silben misst den Rhythmus einer Zeile und ist die Grundlage poetischer Formen vom Haiku bis zum Jambus.","Die deutsche Rechtschreibung stimmt nicht immer mit der Aussprache überein – stumme Buchstaben oder Endungen können täuschen. Dieser Zähler verwendet linguistische Regeln, um häufige Muster wie stummes ''e'', Diphthonge und typische Suffixe zu erkennen und liefert eine genaue Zählung für die allermeisten Wörter."]},{"heading":"Wo ein Silbenzähler hilft","paragraphs":["Dichter nutzen ihn für formgebundene Gedichte: das 5-7-5 eines Haiku, die zehn Silben eines Jambus oder das strenge Metrum eines Limericks. Songwriter passen Texte an eine Melodie an, damit jede Zeile gut zum Rhythmus passt. Lehrer und Redakteure messen die Lesbarkeit – kürzere Wörter mit weniger Silben sind in der Regel leichter lesbar.","Auch für Namen, Markenideen und Slogans ist ein Silbenzähler praktisch: Eine bestimmte Silbenzahl kann einen Satz einprägsamer machen."]}]',
        '[{"input":"Abend","output":"2 Silben (A-bend)","note":"Einzelne Wörter werden sofort gezählt."},{"input":"Ein alter Teich","output":"4 Silben insgesamt","note":"Ideal zum Prüfen der ersten Haiku-Zeile."},{"input":"wunderschöner Sonnenaufgang","output":"4 + 4 = 8 Silben","note":"In der Aufschlüsselung sehen Sie die Silben jedes Wortes."}]',
        '["Für ein Haiku: Zielen Sie auf 5, 7 und 5 Silben in den drei Zeilen.","Lesen Sie knifflige Wörter laut vor, um die Zählung zu überprüfen.","Beachten Sie den Durchschnitt pro Wort – niedriger bedeutet leichter lesbar.","Nutzen Sie die Einzelaufschlüsselung, um das Wort zu finden, das den Rhythmus stört.","Kombinieren Sie es mit dem Reimwörter-Tool für passende Klänge und Rhythmus."]',
        '[{"question":"Wie funktioniert der Silbenzähler?","answer":"Er wendet eine Reihe von Ausspracheregeln auf jedes Wort an – zählt Vokalgruppen und berücksichtigt stumme Buchstaben und häufige Endungen – und schätzt so die Silbenzahl. Die Summe wird für den gesamten Text ausgegeben."},{"question":"Ist der Zähler immer 100 % genau?","answer":"Für die allermeisten deutschen Wörter ist er genau, aber bei einigen unregelmäßigen Wörtern oder seltenen Namen kann es um eine Silbe abweichen. Der sicherste Check ist lautes Vorlesen."},{"question":"Ist mein Text privat?","answer":"Ja, vollkommen. Der Zähler läuft komplett in Ihrem Browser – Ihr Text wird nie hochgeladen oder gespeichert und verlässt Ihr Gerät nicht."},{"question":"Kann ich ein ganzes Gedicht oder einen Absatz zählen lassen?","answer":"Ja. Fügen Sie Text jeder Länge ein – der Zähler zeigt Gesamtsilben, Wortanzahl, Durchschnitt pro Wort und eine Aufschlüsselung pro Wort."},{"question":"Ist der Silbenzähler kostenlos?","answer":"Ja – kostenlos und unbegrenzt nutzbar, ohne Anmeldung oder Download, auf jedem Gerät."}]',
        'Kostenlos online Silben zählen für Haiku, Gedichte und Texte',
        '["Silbenzähler","Silben zählen","Silben zählen online","Silbenanzahl ermitteln","Silben in Wörtern zählen","Haiku Silbenzähler","Silbenzähler kostenlos","Silben pro Wort","Silben zählen Tool"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'random-word-generator',
        'de',
        'Random Word Generator',
        'Zufallswort Generator – Ideen sofort | AllWordTools',
        'Kostenloser Zufallswort Generator. Erzeugen Sie zufällige deutsche Wörter mit Filtern nach Länge und Anfangsbuchstabe – perfekt für Brainstorming, Spiele und Schreibübungen.',
        '',
        'Zufallswort Generator',
        'Erzeugen Sie zufällige deutsche Wörter auf Knopfdruck – mit Filtern für Anzahl, Länge und Anfangsbuchstabe. Ideal für Brainstorming, Spiele und Schreibimpulse.',
        '["Ein Zufallswort Generator gibt Ihrem Gehirn einen Funken aus dem Nichts. Drücken Sie einen Knopf und der AllWordTools.com Zufallswort Generator zieht frische Wörter aus einem großen deutschen Wortschatz – Sie entscheiden, wie viele Sie sehen möchten, wie lang sie sein sollen und mit welchem Buchstaben sie beginnen.","Zufälligkeit ist ein überraschend mächtiges kreatives Werkzeug. Ein Wort, das Sie selbst nie gewählt hätten, kann Schreibblockaden lösen, eine Geschichte anregen, ein Projekt benennen oder ein Partyspiel starten. Dank der Filter nach Länge und Anfangsbuchstabe bleiben die Wörter zufällig, aber dennoch nützlich für Ihre Aufgabe.","Das Tool läuft komplett im Browser, ist völlig kostenlos und hat keine Grenzen – generieren Sie so viele Wörter, wie Sie möchten."]',
        'So nutzen Sie den Zufallswort Generator',
        '[{"title":"Anzahl der Wörter wählen","detail":"Stellen Sie ein, wie viele Wörter generiert werden sollen – von einem einzelnen Wort bis zu fünfzig auf einmal."},{"title":"Optionale Filter hinzufügen","detail":"Legen Sie einen Anfangsbuchstaben sowie eine Mindest- und Maximallänge fest, um die Art der Wörter zu beeinflussen."},{"title":"Wörter generieren","detail":"Klicken Sie auf „Wörter generieren“ und eine frische, zufällige Auswahl erscheint sofort."},{"title":"Kopieren, was Sie brauchen","detail":"Tippen Sie auf ein Wort, um es zu kopieren, oder nutzen Sie „Alle kopieren“, um die gesamte Liste auf einmal zu übernehmen."}]',
        '[{"heading":"Kreative Einsatzmöglichkeiten für Zufallswörter","paragraphs":["Autoren nutzen Zufallswörter, um die Schreibblockade zu überwinden – ein unerwartetes Wort kann eine Figur, einen Schauplatz oder eine Wendung vorschlagen. Brainstormer verwenden sie als laterale Denkanstöße, die neue Verbindungen erzwingen, wenn ein Projektname oder eine Idee nicht kommen will. Lehrer setzen sie für Rechtschreibübungen, Wortschatztraining und Improvisationsspiele ein.","Zufallswörter treiben auch eine Vielzahl von Spielen an: Pantomime und Scharaden, Geschichtenrunden, Aufwärmübungen und Partychallenges. Die Längen- und Anfangsbuchstabenfilter erlauben es, den Schwierigkeitsgrad an die Gruppe anzupassen."]},{"heading":"Filter, die Zufall nützlich machen","paragraphs":["Reiner Zufall kann Wörter hervorbringen, die zu lang, zu obskur oder von der falschen Form für Ihre Zwecke sind. Die Filter des Generators lösen das: Sie legen eine Mindest- und Maximallänge fest, um Wörter in einem angenehmen Bereich zu halten, und fügen einen Anfangsbuchstaben hinzu, wenn Wörter benötigt werden, die auf eine bestimmte Weise beginnen – praktisch für Buchstabenspiele oder thematische Listen.","Jeder Durchlauf wird frisch aus einem umfassenden deutschen Wortschatz gezogen, sodass Sie jedes Mal echte Abwechslung erhalten, nicht dieselbe Handvoll Wörter wiederholt."]}]',
        '[{"input":"5 Wörter, beliebige Länge","output":"Hafen, Feder, Wiese, Klang, Zug","note":"Ein schneller Kreativfunke."},{"input":"beginnt mit S, Länge 4-6","output":"Sonne, Sturm, Schatten, Schnee","note":"Filter nach Buchstabe und Länge kombiniert."},{"input":"10 Wörter, Länge 3","output":"Hut, See, Tag, Wal, Eis, Ohr, Bus, Maus, Rad, Ufo","note":"Ideal für Rechtschreibspiele mit Kindern."}]',
        '["Generieren Sie zuerst eine kleine Auswahl und wiederholen Sie, bis ein Wort eine Idee auslöst.","Nutzen Sie den Anfangsbuchstaben-Filter für Buchstabenspiele und thematische Brainstormings.","Stellen Sie eine Längenspanne ein, um altersgerechte Wörter für den Unterricht zu erhalten.","Kopieren Sie alle Wörter, um die ganze Liste in ein Dokument oder eine Spielvorlage zu exportieren.","Kombinieren Sie mehrere Zufallswörter und erzwingen Sie eine Verbindung zwischen ihnen für kreatives Schreiben."]',
        '[{"question":"Wofür wird ein Zufallswort Generator verwendet?","answer":"Er dient zum Brainstorming, zur Überwindung von Schreibblockaden, für Rechtschreib- und Wortschatzübungen sowie für Spiele wie Pantomime, Scharaden und Geschichten erfinden. Er produziert auf Abruf frische deutsche Wörter."},{"question":"Kann ich die Länge der Wörter steuern?","answer":"Ja. Sie können eine Mindest- und Maximallänge sowie einen Anfangsbuchstaben festlegen, sodass die Zufallswörter dennoch zu Ihrer Aufgabe passen."},{"question":"Woher stammen die Wörter?","answer":"Sie werden aus einem großen, standardisierten deutschen Wortschatz gezogen, sodass echte, gültige Wörter mit viel Abwechslung bei jedem Durchlauf erscheinen."},{"question":"Ist der Zufallswort Generator kostenlos?","answer":"Ja – völlig kostenlos und unbegrenzt nutzbar, ohne Anmeldung oder Downloads. Er läuft sofort im Browser auf jedem Gerät."},{"question":"Sind die Wörter jedes Mal anders?","answer":"Ja. Jeder Durchlauf zieht eine frische zufällige Auswahl, sodass Sie jedes Mal neue Wörter sehen."}]',
        'Kostenloses Tool zur Generierung zufälliger Wörter mit Filtermöglichkeiten für kreative Zwecke',
        '["Zufallswort Generator","zufällige Wörter generieren","Wortgenerator kostenlos","Zufallswort Deutsch","Brainstorming Wörter","Kreativitätstool Wörter","Wortspiel Generator","Inspiration Wort Generator"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'boggle-solver',
        'de',
        'Boggle Solver',
        'Boggle-Löser — Finde jedes Wort im Raster | AllWordTools.com',
        'Kostenloser Boggle-Löser: Finde jedes Wort in 3×3-, 4×4- oder 5×5-Gittern, durch benachbarte Buchstaben verbunden und nach Länge sortiert. Inklusive Qu-Sonderfeld.',
        '',
        'Boggle-Löser',
        'Gib die Buchstaben deines Spielbretts ein und lass dir sofort alle Wörter anzeigen, die du durch benachbarte Felder legen kannst – gruppiert nach Länge und bewertet nach Boggle-Regeln.',
        '["Der Boggle-Löser findet jedes gültige Wort, das in deinem Raster versteckt ist. Gib die Buchstaben genau so ein, wie sie auf dem Brett stehen – in einem 3×3-, 4×4- oder 5×5-Layout – und er durchläuft jeden Pfad durch benachbarte Felder, um alle Wörter zu enthüllen, die du hättest finden können. Die längsten Wörter mit den meisten Punkten erscheinen zuerst.","Boggle-Wörter müssen aus Buchstaben bestehen, die horizontal, vertikal oder diagonal aneinandergrenzen, und kein Feld darf in einem Wort zweimal verwendet werden. Unser Löser befolgt genau diese Regeln und überprüft jeden möglichen Pfad, damit nichts übersehen wird. Er unterstützt sogar das spezielle Qu-Feld – gib einfach qu in eine Zelle ein.","Das Tool ist völlig kostenlos, funktioniert sofort im Browser auf jedem Gerät und erfordert keine Anmeldung. Nutze es, um deine Punktzahl zu überprüfen, Streitigkeiten zu schlichten oder dein Auge für längere Wörter zu trainieren."]',
        'So verwendest du den Boggle-Löser',
        '[{"title":"Wähle die Brettgröße","detail":"Wähle 3×3, 4×4 oder 5×5, passend zu deinem Spiel. Das Raster wird sofort aktualisiert."},{"title":"Gib die Buchstaben ein","detail":"Trage jeden Buchstaben genau so in die Zelle ein, wie er auf dem Brett steht. Für das Qu-Feld gib qu in eine Zelle ein."},{"title":"Mindestlänge festlegen","detail":"Wähle die kürzeste Wortlänge, die angezeigt werden soll – in den meisten Boggle-Spielen zählen Wörter ab drei Buchstaben."},{"title":"Das Brett lösen","detail":"Drücke auf Lösen, um alle möglichen Wörter zu sehen, gruppiert nach Länge und bewertet nach Boggle-Regeln. Tippe auf ein Wort, um es zu kopieren."}]',
        '[{"heading":"Wie die Boggle-Punktzahl funktioniert","paragraphs":["Im klassischen Boggle bringen längere Wörter mehr Punkte. Drei- und Vier-Buchstaben-Wörter zählen einen Punkt, Fünf-Buchstaben-Wörter zwei, Sechs-Buchstaben-Wörter drei, Sieben-Buchstaben-Wörter fünf und Wörter mit acht oder mehr Buchstaben elf Punkte. Der Löser markiert jedes Wort mit seiner Punktzahl und listet die längsten zuerst, damit du siehst, wo die großen Punkte warten.","Verschiedene Editionen und Hausregeln variieren die Mindestwortlänge und gelegentlich die Punktevergabe. Passe daher die Einstellung zur Mindestlänge an deine Spielweise an. Die Pfadregeln – benachbarte Felder, keine Wiederholung – bleiben in allen Versionen gleich."]},{"heading":"Die Nachbarschafts- und Qu-Regeln","paragraphs":["Ein Boggle-Wort entsteht, indem man von Feld zu benachbartem Feld geht. Jeder Schritt kann nach oben, unten, links, rechts oder diagonal erfolgen, und du darfst in einem Wort nie zweimal auf demselben Feld landen. Unser Löser durchläuft jeden möglichen Pfad von jedem Startfeld aus, sodass er Wörter findet, die sich auf Wegen durch das Brett schlängeln, die man leicht übersieht.","Das Qu-Feld zählt als zwei Buchstaben in einer Zelle. Gib qu in ein einzelnes Feld ein, und der Löser behandelt es als Paar, sodass Wörter wie Quiz oder Quilt korrekt über das Brett verfolgt werden."]},{"heading":"Besser werden bei Boggle","paragraphs":["Den Löser nach einer Runde zu nutzen, ist eine schnelle Methode, um sich zu verbessern. Das Durchgehen der langen Wörter, die du übersehen hast, trainiert dein Gehirn, häufige Endungen wie -en, -er und -te zu erkennen und diagonalen Pfaden zu folgen, die du sonst auslassen würdest. Mit der Zeit wirst du mehr Wörter ohne Hilfe finden und höhere Punktzahlen erzielen.","Da die Punkte mit der Länge stark ansteigen, ist die Jagd nach Sechs- und Sieben-Buchstaben-Wörtern oft lohnender, als viele kurze zu sammeln. Die Längengruppierung des Lösers macht es leicht, dein Training auf diese hochwertigen Wörter zu konzentrieren."]}]',
        '[{"input":"4×4-Raster mit t,i,e,r...","output":"Tier, Reit, Riet, Eiter","note":"Wörter, die über benachbarte Felder verbunden werden."},{"input":"Zelle als ''qu'' eingegeben","output":"Quiz, Quit, Quilt","note":"Das Qu-Feld zählt als zwei Buchstaben in einer Zelle."},{"input":"Mindestlänge 5","output":"Steal, Least, Slate, Tales","note":"Kurze Wörter ausblenden, um sich auf große Punkte zu konzentrieren."}]',
        '["Achte auf häufige Endungen wie -en, -er und -te, um kurze Wörter zu verlängern.","Folge diagonalen Pfaden – sie werden am leichtesten übersehen.","Längere Wörter bringen viel mehr Punkte – priorisiere Sechs- und Sieben-Buchstaben-Funde.","Gib qu in eine Zelle ein, damit Wörter mit Qu korrekt erfasst werden.","Überprüfe nach jeder Runde die übersehenen Wörter, um dein Auge zu trainieren."]',
        '[{"question":"Welche Brettgrößen unterstützt der Löser?","answer":"Er unterstützt 3×3-, 4×4- und 5×5-Gitter und deckt damit klassisches Boggle, Boggle und Big Boggle ab. Wähle die Größe, die zu deinem Spiel passt, und gib die Buchstaben ein."},{"question":"Wie gebe ich das Qu-Feld ein?","answer":"Gib qu in eine einzelne Zelle ein. Der Löser behandelt es als zwei Buchstaben, sodass Wörter wie Quiz und Quilt korrekt verfolgt werden."},{"question":"Folgt er den echten Boggle-Regeln?","answer":"Ja. Wörter werden aus benachbarten Feldern horizontal, vertikal oder diagonal gebildet, und kein Feld wird in einem Wort zweimal verwendet. Jeder gültige Pfad wird überprüft."},{"question":"Wie werden die Wörter bewertet?","answer":"Nach klassischer Boggle-Wertung: 3–4 Buchstaben = 1 Punkt, 5 Buchstaben = 2, 6 Buchstaben = 3, 7 Buchstaben = 5, 8 oder mehr = 11. Die längsten Wörter werden zuerst angezeigt."},{"question":"Ist der Boggle-Löser kostenlos?","answer":"Ja, völlig kostenlos und unbegrenzt nutzbar, ohne Anmeldung oder Download. Er läuft sofort im Browser auf jedem Gerät."}]',
        'Boggle-Wörter finden und Lösung überprüfen',
        '["Boggle Löser","Boggle Wörter finden","Boggle Lösung online","Boggle Wortsuche","Boggle Generator","Boggle 4x4 lösen","Boggle Punkte berechnen","Boggle Hilfe"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'hangman-solver',
        'de',
        'Hangman Solver',
        'Galgenmännchen Löser – Buchstaben raten | AllWordTools',
        'Kostenloser Galgenmännchen Löser: Alle möglichen Wörter aus bekannten Buchstaben und Fehlversuchen anzeigen und den klügsten nächsten Buchstaben vorschlagen.',
        '',
        'Galgenmännchen Löser',
        'Geben Sie die bekannten Buchstaben und die Fehlversuche ein – wir zeigen alle möglichen Wörter und den intelligentesten nächsten Buchstaben, sortiert nach Häufigkeit.',
        '["Der Galgenmännchen Löser nutzt Ihre vorhandenen Hinweise, um das Wort zu ermitteln – und vor allem den besten nächsten Buchstaben. Geben Sie das Muster der bekannten Buchstaben mit Unterstrichen für die Unbekannten ein, fügen Sie alle bereits falsch geratenen Buchstaben hinzu, und sofort wird eine Liste aller passenden Wörter sowie die vielversprechendsten Buchstaben angezeigt.","Die Magie liegt in den Buchstabenvorschlägen. Statt zufällig zu raten, zählt der Löser, wie viele der verbleibenden möglichen Wörter jeden ungeratenen Buchstaben enthalten, und zeigt die Prozentwerte. Der Buchstabe mit der höchsten Prozentzahl gibt die beste Trefferchance und liefert die meisten Informationen, sodass Sie mit weniger Fehlern ans Ziel kommen.","Der Dienst ist völlig kostenlos, funktioniert sofort im Browser auf jedem Gerät und erfordert keine Anmeldung. Nutzen Sie ihn, um eine knifflige Runde zu gewinnen, oder um eine klügere Guess-Strategie zu lernen, die Sie auch alleine anwenden können."]',
        'So verwenden Sie den Galgenmännchen Löser',
        '[{"title":"Bekannte Buchstaben eingeben","detail":"Geben Sie das Wort mit Unterstrichen für unbekannte Positionen ein, z.B. _pp_e. Achten Sie auf die exakte Länge – ein Unterstrich pro Lücke."},{"title":"Fehlversuche hinzufügen","detail":"Listen Sie die Buchstaben auf, die Sie bereits falsch geraten haben und die nicht im Wort vorkommen. Diese schließen unmögliche Wörter aus."},{"title":"Lösen","detail":"Klicken Sie auf „Lösen“, um alle passenden Wörter sowie die besten nächsten Buchstaben zu sehen, sortiert danach, in wie vielen möglichen Wörtern sie vorkommen."},{"title":"Klug raten","detail":"Raten Sie den Buchstaben mit der höchsten Prozentzahl, aktualisieren Sie das Muster mit dem Ergebnis und lösen Sie erneut, um die Auswahl einzugrenzen."}]',
        '[{"heading":"Wie die Vorschläge für den besten Zug funktionieren","paragraphs":["Wenn noch mehrere Wörter zu Ihrem Muster passen, ist der klügste Zug, einen Buchstaben zu raten, der in möglichst vielen dieser Wörter vorkommt. Der Löser zählt über alle verbleibenden Kandidaten hinweg, wie viele jeden ungeratenen Buchstaben enthalten, und sortiert die Buchstaben dann mit dem Prozentsatz. Ein Buchstabe in 90% der Kandidaten ist ein nahezu sicherer Treffer, einer in 20% ist ein Glücksspiel.","Dieser Häufigkeitsansatz erfüllt zwei Ziele gleichzeitig: Er maximiert Ihre Chance, einen Buchstaben aufzudecken, und wenn der Buchstabe vorhanden ist, teilt er die verbleibenden Wörter meist in eine viel kleinere Menge auf. Deshalb ist der Top-Vorschlag fast immer Ihr bester Zug, besonders zu Beginn einer Runde, wenn noch viele Wörter möglich sind."]},{"heading":"Das Muster richtig eingeben","paragraphs":["Das Muster ist das Rückgrat des Lösers, daher ist die korrekte Länge entscheidend. Verwenden Sie einen Unterstrich für jeden unbekannten Buchstaben und platzieren Sie Ihre bekannten Buchstaben an den exakten Positionen. Wenn Sie wissen, dass das Wort _ a _ _ e ist, geben Sie es genau so ein – der Löser berücksichtigt nur Wörter dieser Länge mit diesen festen Buchstaben.","Der Löser geht außerdem davon aus, dass bekannte Buchstaben überall dort vorkommen, wo sie hingehören. Eine Lücke wird nie durch einen Buchstaben gefüllt, den Sie bereits an anderer Stelle aufgedeckt haben. Zusammen mit der Liste der Fehlversuche bleibt die Kandidatenmenge präzise."]},{"heading":"Gewinnen und Lernen","paragraphs":["Mitten im Spiel eingesetzt, ist der Löser ein zuverlässiger Weg, um aus einem schwierigen Wort herauszukommen, bevor Ihnen die Versuche ausgehen. Danach verwendet, lehrt er eine Strategie, die Sie in jedes zukünftige Spiel mitnehmen können: Beginnen Sie mit häufigen Buchstaben, bevorzugen Sie Vokale und häufige Konsonanten, und lassen Sie jedes Ergebnis Ihren nächsten Zug beeinflussen.","Wie bei jedem Hilfsmittel: Stimmen Sie mit Ihren Mitspielern ab, ob Helfer willkommen sind. Als Lernhilfe verwandelt er glückliches Raten in eine wiederholbare Methode."]}]',
        '[{"input":"Muster _pp_e, Fehlversuche: keine","output":"Apfel, Äppel, Appel","note":"Alle Wörter, die zu den bekannten Buchstaben passen."},{"input":"Muster B_a_h, Fehlversuche: tz","output":"Brach, Brawl, Branch","note":"Fehlversuche schließen unmögliche Wörter aus."},{"input":"Vorschläge für _____","output":"E (72%), A (61%), R (55%)","note":"Raten Sie den Buchstaben mit der höchsten Prozentzahl zuerst."}]',
        '["Beginnen Sie mit häufigen Buchstaben – E, A, R, I, O und T kommen in den meisten Wörtern vor.","Raten Sie immer den Buchstaben mit der höchsten Prozentzahl, den der Löser vorschlägt, für die besten Gewinnchancen.","Lösen Sie nach jedem Rateversuch erneut, damit die Kandidatenliste und die Vorschläge aktuell bleiben.","Führen Sie Ihre Fehlversuche vollständig – jeder falsche Buchstabe grenzt die Ergebnisse ein.","Überprüfen Sie die Länge des Musters; ein falscher Unterstrich ändert jedes Ergebnis."]',
        '[{"question":"Wie gebe ich das Wortmuster ein?","answer":"Geben Sie das Wort mit einem Unterstrich für jeden unbekannten Buchstaben ein und setzen Sie Ihre bekannten Buchstaben an die richtigen Positionen, z.B. _pp_e. Achten Sie auf die exakte Länge."},{"question":"Was gehört in das Feld für Fehlversuche?","answer":"Listen Sie jeden Buchstaben auf, den Sie bereits geraten haben und der nicht im Wort vorkommt. Der Löser verwendet diese, um Wörter auszuschließen, die nicht die Lösung sein können."},{"question":"Wie wählt der Löser den besten Buchstaben aus?","answer":"Er zählt, wie viele der verbleibenden möglichen Wörter jeden ungeratenen Buchstaben enthalten, sortiert sie und zeigt die Prozentwerte. Den mit der höchsten Prozentzahl zu raten, gibt die beste Trefferchance."},{"question":"Ist der Galgenmännchen Löser kostenlos?","answer":"Völlig kostenlos, unbegrenzt nutzbar, ohne Anmeldung oder Download. Er läuft sofort im Browser auf jedem Gerät."},{"question":"Findet der Löser immer das Wort?","answer":"Er findet jedes gültige Wort, das zu Ihren Hinweisen passt, aus einer großen deutschen Wortliste. Sehr seltene Namen oder Slang sind möglicherweise nicht enthalten, aber gebräuchliche Wörter werden immer angezeigt."}]',
        'Hilfe beim Lösen von Galgenmännchen-Rätseln durch intelligente Buchstabenauswahl',
        '["Galgenmännchen Löser","Galgenmännchen Hilfe","Galgenmännchen Buchstaben finden","Galgenmännchen Lösung","besten Buchstaben Galgenmännchen","Galgenmännchen Wort finden","Galgenmännchen Tipps","Galgenmännchen Strategie"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'text-twist-solver',
        'de',
        'Text Twist Solver',
        'Text Twist Löser – Buchstaben entwirren & Bonuswort finden',
        'Kostenloser Text Twist Löser: Entwirre Buchstaben, finde alle gültigen Wörter nach Länge gruppiert und das Bonuswort für den nächsten Level.',
        '',
        'Text Twist Löser',
        'Gib deine Buchstaben ein und erhalte alle gültigen Wörter – gruppiert nach Länge – mit hervorgehobenem Bonuswort.',
        '["Der Text Twist Löser hilft dir, eine festgefahrene Runde im Handumdrehen zu knacken. Gib die verdrehten Buchstaben ein, die du hast, und er findet jedes gültige Wort von drei Buchstaben bis zur vollen Länge – übersichtlich nach Wortlänge sortiert, genau wie das Spielfeld. Besonders praktisch: Die Bonuswörter, die alle Buchstaben nutzen, werden farblich hervorgehoben, damit du sie auf einen Blick erkennst und die Runde erfolgreich abschließt.","In Text Twist und ähnlichen Spielen werden längere Wörter belohnt, vor allem das Wort, das alle Buchstaben enthält. Statt die Buchstaben immer neu zu mischen, bekommst du eine geordnete Liste, die sich am Spielfeld orientiert. So siehst du sofort, welche Längen noch fehlen und welche Wörter du zuerst eingeben solltest.","Der Löser ist völlig kostenlos, funktioniert sofort im Browser auf jedem Gerät und erfordert keine Anmeldung. Nutze ihn, um eine zeitgesteuerte Runde zu gewinnen, das nächste Level freizuschalten oder einfach die Wörter zu lernen, die du ständig übersiehst."]',
        'So verwendest du den Text Twist Löser',
        '[{"title":"Buchstaben eingeben","detail":"Tippe die Buchstaben der Runde ein – meist sechs oder sieben. Die Reihenfolge spielt keine Rolle."},{"title":"Runde lösen","detail":"Drücke auf Lösen und das Tool findet alle gültigen Wörter von drei Buchstaben bis zur vollen Länge."},{"title":"Jede Länge ausfüllen","detail":"Die Wörter sind nach Länge gruppiert wie das Spielfeld, sodass du Reihe für Reihe ausfüllen kannst."},{"title":"Bonuswort spielen","detail":"Die Bonuswörter werden hervorgehoben und mit einem Stern markiert – gib eines ein, um die Runde zu beenden."}]',
        '[{"heading":"Warum das Bonuswort wichtig ist","paragraphs":["In den meisten Text Twist Runden kommst du nur weiter, wenn du mindestens ein Wort findest, das alle Buchstaben verwendet. Diese Bonuswörter unter Zeitdruck zu erkennen, ist oft am schwierigsten. Der Löser hebt sie mit einem Stern hervor und platziert sie in einer eigenen Gruppe an oberster Stelle – so entgeht dir das entscheidende Wort nicht.","Manche Runden haben mehrere Wörter in voller Länge. Der Löser listet alle auf, gibt dir eine Auswahl und eine Sicherheit für den Fall, dass eines nicht erkannt wird. Hast du das Bonuswort gefunden, kannst du die kürzeren Wörter nachtragen, um deine Punktzahl zu steigern."]},{"heading":"Jede Länge auf dem Spielfeld ausfüllen","paragraphs":["Text Twist Boards haben für jede Wortlänge ein Feld, und deine Punktzahl steigt, je mehr du ausfüllst. Da der Löser die Ergebnisse nach Länge sortiert, kannst du systematisch vorgehen: Dreibuchstabige Wörter, dann vierbuchstabige und so weiter bis zum Bonus. Das entspricht dem Spielfeld und zeigt dir genau, welche Längen du noch brauchst.","Jedes Wort wird bewertet. Falls deine Version höhere Punktzahlen für bestimmte Buchstaben vergibt, kannst du die wertvollsten Wörter priorisieren. Tippe auf ein Wort, um es zu kopieren und direkt im Spiel einzugeben."]},{"heading":"Eigene Fähigkeiten verbessern","paragraphs":["Der Löser ist nicht nur zum Lösen da, sondern auch ein toller Lehrmeister. Indem du die Wörter, die du verpasst hast, ansiehst – vor allem das Bonuswort – trainierst du dein Auge für häufige Buchstabenmuster und Endungen. So findest du Vollwortlängen immer schneller selbst. Anagrammspiele leben von Mustererkennung, und ein wenig Übung macht sich bezahlt.","Versuche die Runde zuerst selbst zu lösen und nutze dann das Tool, um zu prüfen, was dir entgangen ist. Mit der Zeit wirst du immer seltener auf den Löser angewiesen sein."]}]',
        '[{"input":"Buchstaben: reostn","output":"tensor, tenors (Bonus) · store, tones · ore, ten","note":"Vollständige Wörter werden als Bonus mit Stern markiert."},{"input":"Buchstaben: aeprs","output":"spare, pears, parse, reaps","note":"Jede Länge wird passend zum Spielfeld gruppiert."},{"input":"Buchstaben: glinst","output":"tingles (Bonus) · sling, glint · tin, gin","note":"Bonuswort zuerst, dann die kürzeren Zeilen füllen."}]',
        '["Finde zuerst das Bonuswort – es ist meist der einzige Weg, um die Runde abzuschließen.","Gehe systematisch vor: erst alle Dreier, dann Vierer usw., damit kein Feld leer bleibt.","Achte auf häufige Endungen wie -en, -er, -ung, um schnell längere Wörter zu bauen.","Verwandle Wörter in die Pluralform – das bringt oft ein weiteres Wort.","Löse die Runde zuerst selbst, dann prüfe mit dem Tool, was du verpasst hast – das bringt dich weiter."]',
        '[{"question":"Was ist das Bonuswort bei Text Twist?","answer":"Ein Wort, das alle Buchstaben einer Runde verwendet. Meist musst du es finden, um weiterzukommen. Der Löser hebt alle Vollwortlängen mit einem Stern hervor."},{"question":"Wie viele Buchstaben kann ich eingeben?","answer":"Bis zu zwölf, obwohl die meisten Runden sechs oder sieben Buchstaben haben. Der Löser findet alle gültigen Wörter von drei Buchstaben bis zur maximalen Länge."},{"question":"Sind die Ergebnisse wie das Spielfeld gruppiert?","answer":"Ja. Die Wörter werden nach Länge sortiert, passend zum Spielfeld, sodass du Reihe für Reihe ausfüllen und Lücken sofort erkennen kannst."},{"question":"Ist der Text Twist Löser kostenlos?","answer":"Völlig kostenlos – unbegrenzt nutzbar, ohne Anmeldung oder Download. Läuft sofort im Browser auf jedem Gerät."},{"question":"Funktioniert er auch für andere Anagrammspiele?","answer":"Ja. Er ist ideal für Text Twist, TwistedWords, Word Twist und ähnliche Spiele, bei denen aus Buchstaben Wörter gebildet werden müssen."}]',
        'Benutzer suchen einen schnellen, kostenlosen Wortentschlüssler für das Spiel Text Twist, um rückständige Level zu lösen, insbesondere das Bonuswort zu finden.',
        '["Text Twist Löser","Buchstaben entwirren","Bonuswort finden","Text Twist Hilfe","Wortspiel Löser","Anagramm Löser kostenlos","Text Twist Cheat","Wörter aus Buchstaben"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'vowel-counter',
        'de',
        'Vowel Counter',
        'Vokalzähler – Vokale im Text zählen | AllWordTools',
        'Kostenloser Vokalzähler: Zählt Vokale (a, e, i, o, u) in Texten mit detaillierter Aufschlüsselung, Gesamtzahlen und Prozentanteil. Sofort, genau und kostenlos.',
        '',
        'Vokalzähler',
        'Fügen Sie Text ein, um die Vokale a, e, i, o und u zu zählen – mit Aufschlüsselung pro Vokal, Gesamtzahlen, Prozentangaben und Hinweis zum Buchstaben y.',
        '["Ein Vokalzähler erfasst alle Vokale in Ihrem Text und zeigt deren Verteilung pro Buchstabe an. Vokale – a, e, i, o und u – sind die Laute, die jede Silbe tragen. Daher ist das Zählen von Vokalen nützlich für Rechtschreibübungen, Lyrik, Sprachunterricht und Worträtsel.","Der Vokalzähler von AllWordTools.com aktualisiert sich live während der Eingabe und zeigt die Gesamtzahl der Vokale, das Verhältnis zu Konsonanten, den Vokalanteil im Text sowie eine detaillierte Aufschlüsselung jedes Vokals. Der Buchstabe y wird gesondert ausgewiesen, da er manchmal als Vokal fungiert.","Das Tool ist kostenlos, arbeitet sofort und läuft komplett im Browser auf jedem Gerät – ohne Anmeldung oder Download."]',
        'So verwenden Sie den Vokalzähler',
        '[{"title":"Text eingeben","detail":"Tippen oder fügen Sie ein Wort, einen Satz oder ein ganzes Dokument in das Textfeld ein."},{"title":"Gesamtzahlen ablesen","detail":"Sehen Sie die Anzahl der Vokale, Konsonanten, Gesamtbuchstaben und den Vokalanteil in Prozent."},{"title":"Aufschlüsselung prüfen","detail":"Ein Balkendiagramm zeigt, wie oft jeder der Vokale a, e, i, o und u vorkommt."},{"title":"Ergebnis kopieren","detail":"Kopieren Sie die Vokalanzahl mit einem Klick für Aufsätze, Projekte oder Rätsel."}]',
        '[{"heading":"Welche Buchstaben als Vokale zählen","paragraphs":["Im Deutschen sind die fünf Hauptvokale a, e, i, o und u. Dieses Tool zählt genau diese fünf Buchstaben und liefert eine saubere, eindeutige Gesamtzahl. Der Buchstabe y ist ein Sonderfall: In Wörtern wie ''typisch'' oder ''System'' klingt er wie ein Vokal, in ''Yacht'' wie ein Konsonant. Daher wird y separat aufgeführt, nicht zusammen mit den Vokalen.","Die Analyse ist case-insensitiv, Groß- und Kleinbuchstaben werden zusammengezählt. Zahlen, Leerzeichen und Satzzeichen werden ignoriert, sodass Sie eine reine Buchstabenanzahl erhalten."]},{"heading":"Wo ein Vokalzähler hilft","paragraphs":["Vokalzahlen sind für überraschend viele Aufgaben nützlich. Dichter und Songwriter nutzen sie, um den Klangfluss einer Zeile zu untersuchen, da Vokale den Klang eines Wortes tragen. Sprachlernende verstehen Silbenstrukturen besser, und Lehrer verwenden sie im Rechtschreib- und Phonetikunterricht.","Auch Rätselfans profitieren: Viele Wortspiele belohnen ein ausgewogenes Verhältnis von Vokalen und Konsonanten. Mit diesem Tool haben Sie alle Daten auf einen Blick."]}]',
        '[{"input":"Elefant","output":"3 Vokale (e, e, a)","note":"Ein Wort mit mehreren verschiedenen Vokalen."},{"input":"Rhythmus","output":"0 Vokale, y enthalten","note":"Kein a, e, i, o oder u – y übernimmt die Vokalrolle."},{"input":"Europäische Union","output":"9 Vokale (e, u, o, ä, i, e, U, i, o)","note":"Ein Satz mit vielen Vokalen, inklusive Umlaut."}]',
        '["Beachten Sie: y wird separat gezählt, da es mal Vokal, mal Konsonant sein kann.","Nutzen Sie den Vokalanteil in Prozent, um zu beurteilen, wie klangvoll ein Text ist.","Der Zähler ist case-insensitiv: Groß- und Kleinbuchstaben werden zusammengezählt.","Kombinieren Sie ihn mit dem Konsonantenzähler für ein vollständiges Buchstabenbild.","Probieren Sie vokalreiche Wörter wie ''Eisenbahn'' oder ''Ameise'' aus, um die Aufschlüsselung zu sehen."]',
        '[{"question":"Welche Buchstaben zählt der Vokalzähler?","answer":"Er zählt die fünf Hauptvokale a, e, i, o und u. Der Buchstabe y wird separat ausgewiesen, da er je nach Wort als Vokal oder Konsonant fungiert."},{"question":"Ist der Buchstabe y ein Vokal?","answer":"Manchmal. Y klingt in Wörtern wie ''typisch'' oder ''System'' wie ein Vokal, in ''Yacht'' wie ein Konsonant. Der Zähler zeigt y separat an, sodass Sie selbst entscheiden können, wie Sie ihn behandeln."},{"question":"Zählt das Tool Großbuchstaben?","answer":"Ja. Der Zähler ist case-insensitiv, Groß- und Kleinbuchstaben werden zusammengezählt. Zahlen, Leerzeichen und Satzzeichen werden ignoriert."},{"question":"Was ist der Vokalanteil in Prozent?","answer":"Das ist der Anteil der Vokale an allen Buchstaben im Text – ein schnelles Maß dafür, wie vokalreich der Text ist."},{"question":"Ist der Vokalzähler kostenlos?","answer":"Ja, völlig kostenlos und ohne Einschränkung nutzbar. Keine Anmeldung, kein Download. Das Tool läuft sofort im Browser auf jedem Gerät."}]',
        'Kostenloses Tool zum Zählen von Vokalen in deutschen Texten',
        '["Vokalzähler","Vokale zählen","Vokale in Text zählen","Selbstlaute zählen","Vokalanalyse online","Buchstaben zählen mit Vokalen","Vokalverteilung","Online Vokalzähler kostenlos","Textanalyse Vokale"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'consonant-counter',
        'de',
        'Consonant Counter',
        'Konsonantenzähler – Konsonanten in jedem Text zählen',
        'Kostenloser Konsonantenzähler: Zählt Konsonanten in jedem Text mit Aufschlüsselung pro Buchstabe, Gesamtzahl und Prozentanteil. Sofort, genau und ohne Anmeldung.',
        '',
        'Konsonantenzähler',
        'Fügen Sie einen Text ein, um die Konsonanten zu zählen – alle Buchstaben außer A, E, I, O und U – mit Gesamtzahl, Prozentanteil und einer detaillierten Aufschlüsselung pro Buchstabe.',
        '["Ein Konsonantenzähler erfasst alle Konsonanten in Ihrem Text – jeden Buchstaben, der kein Vokal ist. Konsonanten prägen die Struktur und den Rhythmus von Wörtern. Daher ist das Zählen hilfreich für Rechtschreibübungen, Gedichte, Zungenbrecher, Sprachenlernen und Wortspiele.","Der Konsonantenzähler von AllWordTools.com aktualisiert sich live während der Eingabe und zeigt die Gesamtzahl der Konsonanten, den Vergleich zu den Vokalen, den Konsonantenanteil am Text und eine vollständige Aufschlüsselung der Häufigkeit jedes Konsonanten.","Das Tool ist kostenlos, sofort einsatzbereit und läuft direkt im Browser auf jedem Gerät – ohne Anmeldung und ohne Download."]',
        'So verwenden Sie den Konsonantenzähler',
        '[{"title":"Text eingeben","detail":"Geben Sie ein Wort, einen Satz oder ein ganzes Dokument in das Feld ein."},{"title":"Gesamtzahlen ablesen","detail":"Sie sehen die Anzahl der Konsonanten, der Vokale, die Gesamtbuchstaben und den Konsonantenanteil in Prozent."},{"title":"Aufschlüsselung prüfen","detail":"Ein Balkendiagramm zeigt, wie oft jeder Konsonant vorkommt, sortiert nach Häufigkeit."},{"title":"Ergebnis kopieren","detail":"Kopieren Sie die Konsonantenzahl mit einem Klick für Aufsätze, Projekte oder Rätsel."}]',
        '[{"heading":"Welche Buchstaben als Konsonanten zählen","paragraphs":["Ein Konsonant ist jeder Buchstabe, der nicht zu den fünf Vokalen A, E, I, O und U gehört – also B, C, D, F, G, H, J, K, L, M, N, P, Q, R, S, T, V, W, X, Y und Z. In diesem Tool wird Y als Konsonant gewertet, was der gängigsten Konvention entspricht. So bleiben Ihre Ergebnisse konsistent und vorhersagbar.","Die Analyse erfolgt ohne Berücksichtigung der Groß-/Kleinschreibung, sodass Groß- und Kleinbuchstaben zusammengezählt werden. Zahlen, Leerzeichen und Satzzeichen werden ignoriert, um eine saubere Buchstabenanzahl zu erhalten."]},{"heading":"Wobei ein Konsonantenzähler hilft","paragraphs":["Die Anzahl der Konsonanten zeigt die Textur und den Schwierigkeitsgrad der Sprache. Konsonantenreiche Wörter und Phrasen sind oft schwerer auszusprechen – die Grundlage vieler Zungenbrecher –, während ein ausgewogenes Verhältnis von Konsonanten und Vokalen den Text fließender macht. Autoren, Dichter und Sprachtrainer nutzen Konsonantenzahlen, um Rhythmus und Klarheit zu verfeinern.","Bei Wortspielen hilft die Kenntnis des Konsonantenanteils, die Buchstaben auf dem Brett zu beurteilen und Züge zu planen. Sprachlernende nutzen sie, um Silbenstruktur und Aussprache zu verstehen. Dieses Tool macht all das sofort sichtbar."]}]',
        '[{"input":"Streichholzschächtelchen","output":"18 Konsonanten, 6 Vokale","note":"Ein bekannt langes deutsches Wort mit vielen Konsonanten."},{"input":"Rhythmus","output":"7 Konsonanten","note":"Fast nur Konsonanten, Y übernimmt die Vokalrolle."},{"input":"Banane","output":"3 Konsonanten, 3 Vokale","note":"Ein perfekt ausgewogenes kurzes Wort."}]',
        '["Dieses Tool zählt Y als Konsonanten, der gängigsten Konvention.","Nutzen Sie den Konsonantenanteil, um zu bewerten, wie dicht oder prägnant ein Satz klingt.","Konsonantenhäufungen ergeben tolle Zungenbrecher – probieren Sie ''Schlittschuh'' oder ''Angstschweiß''.","Der Zähler ignoriert Groß-/Kleinschreibung und fasst automatisch zusammen.","Kombinieren Sie ihn mit dem Vokalzähler für eine vollständige Buchstabenbilanz."]',
        '[{"question":"Welche Buchstaben zählt der Konsonantenzähler?","answer":"Er zählt jeden Buchstaben, der kein Vokal ist – B, C, D, F, G, H, J, K, L, M, N, P, Q, R, S, T, V, W, X, Y und Z. Der Buchstabe Y wird hier als Konsonant gewertet."},{"question":"Ist Y ein Konsonant oder ein Vokal?","answer":"Das hängt vom Wort ab, aber dieses Tool zählt Y standardmäßig als Konsonanten, was der gängigsten Konvention entspricht und die Ergebnisse konsistent hält."},{"question":"Zählt es Großbuchstaben und Satzzeichen?","answer":"Es zählt Groß- und Kleinbuchstaben zusammen und ignoriert Zahlen, Leerzeichen und Satzzeichen, sodass Sie eine saubere Buchstabenanzahl erhalten."},{"question":"Was bedeutet der Konsonantenanteil in Prozent?","answer":"Er gibt den Anteil der Konsonanten an allen Buchstaben im Text an – ein schnelles Maß dafür, wie konsonantenreich der Text ist."},{"question":"Ist der Konsonantenzähler kostenlos?","answer":"Ja, völlig kostenlos und ohne Einschränkungen. Keine Anmeldung, kein Download. Das Tool läuft sofort im Browser auf jedem Gerät."}]',
        'Konsonanten zählen online',
        '["Konsonanten zählen","Konsonantenzähler","Konsonanten in Text zählen","Konsonanten pro Buchstabe","Konsonantenanteil","Konsonanten und Vokale zählen","Buchstaben zählen online","Konsonanten in Wörtern zählen"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'word-meaning',
        'de',
        'Word Meaning',
        'Wortbedeutung – Was bedeutet ein Wort? | AllWordTools.com',
        'Kostenloses Tool, um die Bedeutung jedes deutschen Wortes in einfacher Sprache zu finden – mit Beispielsätzen und Wortarten. Sofort und präzise von AllWordTools.com.',
        '',
        'Wortbedeutung',
        'Finden Sie die Bedeutung jedes deutschen Wortes in klarer, verständlicher Sprache – gruppiert nach Wortart und mit echten Beispielsätzen.',
        '["Manchmal brauchen Sie nicht den gesamten Wörterbucheintrag – Sie wollen einfach nur wissen, was ein Wort bedeutet. Das Wortbedeutung-Tool von AllWordTools.com liefert Ihnen genau das: klare, leicht verständliche Definitionen für jedes deutsche Wort, sortiert nach Wortart und ergänzt durch passende Beispielsätze.","Jede Bedeutung ist nummeriert, sodass Sie schnell diejenige finden, die zu dem Kontext passt, in dem Ihnen das Wort begegnet ist. Die Beispielsätze zeigen das Wort in Aktion – so wird eine abstrakte Definition viel greifbarer und einprägsamer.","Das Tool ist kostenlos, schnell und funktioniert sofort in Ihrem Browser auf jedem Gerät – perfekt für einen schnellen Bedeutungscheck beim Lesen oder Schreiben."]',
        'So finden Sie die Bedeutung eines Wortes',
        '[{"title":"Geben Sie ein Wort ein","detail":"Tippen Sie das einzelne Wort ein, dessen Bedeutung Sie wissen möchten."},{"title":"Holen Sie sich die Bedeutung","detail":"Klicken Sie auf „Bedeutung abrufen“, um sofort klare Definitionen zu erhalten."},{"title":"Wählen Sie die passende Bedeutung","detail":"Die Definitionen sind nummeriert und nach Wortarten gruppiert – wählen Sie die, die zu Ihrem Kontext passt."},{"title":"Lesen Sie die Beispiele","detail":"Nutzen Sie die Beispielsätze, um zu sehen, wie das Wort tatsächlich verwendet wird."}]',
        '[{"heading":"Klare Bedeutungen, sinnvoll gruppiert","paragraphs":["Wörter haben selten nur eine einzige Bedeutung. Das Wortbedeutung-Tool gruppiert die verschiedenen Bedeutungen nach Wortarten – so sehen Sie alle Nominalbedeutungen zusammen, dann die verbalen usw. – das erleichtert es, die passende Bedeutung schnell zu finden.","Jede Definition ist in einfachem Deutsch verfasst und, wo verfügbar, mit einem Beispielsatz versehen. Ein Wort in einem natürlichen Satz zu lesen, ist oft der schnellste Weg, seine Bedeutung wirklich zu erfassen – die Beispiele übernehmen daher einen großen Teil der Lehre."]},{"heading":"Wann Sie das Tool nutzen sollten","paragraphs":["Greifen Sie zum Wortbedeutung-Tool, wann immer Ihnen beim Lesen, Lernen oder Surfen ein unbekanntes Wort begegnet. Es ist auch hilfreich beim Schreiben, wenn Sie noch einmal überprüfen möchten, ob ein Wort genau das bedeutet, was Sie denken, bevor Sie es verwenden.","Für Deutschlernende ist es eine schnelle, freundliche Möglichkeit, den Wortschatz zu erweitern – die Kombination aus einer klaren Definition und einem echten Beispiel hilft, neue Wörter im Gedächtnis zu verankern."]}]',
        '[{"input":"ehrlich","output":"Adjektiv – aufrichtig und wahrheitsgemäß; ohne Lüge","note":"Klare Bedeutung mit Wortart."},{"input":"Hafen","output":"Nomen – geschützter Ort an der Küste für Schiffe; Verb – (selten) einen Gedanken oder ein Gefühl hegen","note":"Mehrere Bedeutungen nach Wortart gruppiert."},{"input":"widerstandsfähig","output":"Adjektiv – fähig, sich schnell von Schwierigkeiten zu erholen","note":"Kurze, verständliche Definition plus Beispiel."}]',
        '["Schlagen Sie immer nur ein Wort auf einmal nach, um die klarste Antwort zu erhalten.","Achten Sie auf die Wortart, um die richtige Bedeutung auszuwählen.","Lesen Sie den Beispielsatz, um die Bedeutung zu verinnerlichen.","Für Synonyme und Aussprache nutzen Sie das vollständige Wörterbuch-Tool.","Wenn ein Wort viele Bedeutungen hat, überfliegen Sie die nummerierte Liste und wählen Sie die passende für Ihren Kontext."]',
        '[{"question":"Wie unterscheidet sich dieses Tool vom Wörterbuch?","answer":"Das Wortbedeutung-Tool konzentriert sich nur auf Definitionen und Beispiele für einen schnellen Bedeutungscheck, während das vollständige Wörterbuch auch Aussprache, Synonyme und Antonyme anzeigt."},{"question":"Werden Beispielsätze angezeigt?","answer":"Ja, sofern die Wörterbuchquelle sie bereitstellt. Die Beispielsätze erscheinen unter jeder Definition und zeigen das Wort im Gebrauch."},{"question":"Warum hat ein Wort mehrere Bedeutungen?","answer":"Viele Wörter haben mehrere Bedeutungen in verschiedenen Wortarten. Sie sind gruppiert und nummeriert, damit Sie die richtige finden."},{"question":"Ist es kostenlos?","answer":"Vollständig kostenlos und unbegrenzt nutzbar, ohne Anmeldung oder Downloads, auf jedem Gerät."},{"question":"Was passiert, wenn das Wort nicht gefunden wird?","answer":"Überprüfen Sie die Schreibweise. Sehr seltene oder fachspezifische Begriffe sind möglicherweise nicht in der Wörterbuchquelle enthalten."}]',
        'Bedeutung eines Wortes schnell nachschlagen',
        '["Wortbedeutung","Bedeutung nachschlagen","Wörterbuch online","Was bedeutet","Wortdefinition","Bedeutung mit Beispielen","kostenloses Wörterbuch","deutsche Wortbedeutung"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'spell-checker',
        'de',
        'Spell Checker',
        'Rechtschreibprüfung online kostenlos | AllWordTools.com',
        'Kostenlose Rechtschreibprüfung: Finden Sie Rechtschreibfehler und erhalten Sie sofort die korrekte Schreibweise. Einfach Text einfügen und korrigieren lassen.',
        '',
        'Rechtschreibprüfung',
        'Finden Sie alle Tipp- und Rechtschreibfehler in Ihrem Text und erhalten Sie sofort die korrekte Schreibweise – ohne Änderung von Grammatik oder Stil.',
        '["Die Rechtschreibprüfung von AllWordTools.com konzentriert sich auf eine Aufgabe und erledigt sie zuverlässig: falsch geschriebene Wörter erkennen und die richtige Schreibweise vorschlagen. Fügen Sie einfach Ihren Text ein, und Sie erhalten eine korrigierte Version sowie eine Liste aller korrigierten Wörter, sodass Sie jede Änderung nachvollziehen können.","Ideal für den letzten Check vor dem Versenden einer E-Mail, dem Abgeben einer Hausarbeit oder dem Veröffentlichen eines Beitrags. Da nur die Rechtschreibung korrigiert wird, bleiben Ihr Wortlaut und Tonfall exakt erhalten.","Das Tool ist kostenlos, läuft direkt im Browser und prüft auch längere Texte in einem Durchgang."]',
        'So verwenden Sie die Rechtschreibprüfung',
        '[{"title":"Text einfügen","detail":"Fügen Sie den zu prüfenden Text ein."},{"title":"Prüfung starten","detail":"Klicken Sie auf „Rechtschreibung prüfen“, und alle Fehler werden erkannt."},{"title":"Korrekturen prüfen","detail":"Sehen Sie jedes falsch geschriebene Wort neben der korrekten Schreibweise."},{"title":"Korrigierten Text kopieren","detail":"Kopieren Sie die bereinigte Version mit allen behobenen Fehlern."}]',
        '[{"heading":"Die häufigsten Rechtschreibfehler im Deutschen erkennen","paragraphs":["Typische Fehler wie „wiederspiegeln“ statt „widerspiegeln“, „das selbe“ statt „dasselbe“ oder „Ende diesen Jahres“ statt „Ende dieses Jahres“ werden oft übersehen. Die Rechtschreibprüfung zeigt sie zuverlässig an und schlägt die richtige Schreibweise vor.","Auch einfache Tippfehler wie vertauschte Buchstaben, doppelte Buchstaben oder fehlende Buchstaben werden erfasst – selbst solche, die die Autokorrektur manchmal übersieht."]},{"heading":"Nur Rechtschreibung – sonst nichts","paragraphs":["Anders als umfassende Grammatiktools ändert die Rechtschreibprüfung bewusst keine Grammatik, Zeichensetzung oder Ihren Schreibstil. Dadurch bleibt sie ein sicherer, berechenbarer letzter Schritt: Sie sehen ausschließlich Änderungen an der Rechtschreibung.","Wenn Sie auch Grammatik und Ausdruck verbessern möchten, nutzen Sie anschließend die KI-Grammatikprüfung für ein komplettes Lektorat."]}]',
        '[{"input":"Ich habe das Paket erhalten.","output":"Ich habe das Paket erhalten.","note":"Kein Fehler – korrekt geschrieben."},{"input":"Das ist ein intresantes Buch.","output":"Das ist ein interessantes Buch.","note":"Häufiger Rechtschreibfehler korrigiert: ‚intresant‘ → ‚interessant‘."},{"input":"Er hat sich die Suppe schmecken lassen.","output":"Er hat sich die Suppe schmecken lassen.","note":"Falsche Getrennt- und Zusammenschreibung verbessert: ‚schmecken lassen‘ bleibt korrekt, aber ‚Suppe‘ (groß) wurde nicht geändert. Hinweis: Die Rechtschreibprüfung korrigiert nur offensichtliche Rechtschreibfehler, nicht zwingend die Groß-/Kleinschreibung."}]',
        '["Führen Sie die Rechtschreibprüfung immer als letzten Schritt durch, nachdem Sie den Inhalt bearbeitet haben.","Achten Sie auf korrekt geschriebene, aber falsch verwendete Wörter (z. B. „seid“ vs. „seit“) – nutzen Sie zur Erkennung die Grammatikprüfung.","Erstellen Sie eine persönliche Liste häufig falsch geschriebener Wörter, um sie langfristig zu lernen."]',
        '[{"question":"Ändert die Rechtschreibprüfung auch die Grammatik?","answer":"Nein. Sie korrigiert nur die Rechtschreibung. Grammatik, Zeichensetzung und Wortlaut bleiben unverändert."},{"question":"Erkennt die Prüfung österreichisches und Schweizer Deutsch?","answer":"Sie basiert auf dem deutschen Standard-Deutsch, erkennt aber die meisten regionalen Varianten und korrigiert eindeutige Fehler dennoch zuverlässig."},{"question":"Ist die Rechtschreibprüfung kostenlos?","answer":"Ja, die Rechtschreibprüfung ist vollkommen kostenlos nutzbar."}]',
        'Rechtschreibfehler korrigieren lassen',
        '["Rechtschreibprüfung","Rechtschreibprüfung online","kostenlose Rechtschreibprüfung","Rechtschreibfehler finden","korrekte Schreibweise","Rechtschreibprüfung Deutsch","Text auf Rechtschreibung prüfen","Schreibfehler korrigieren","Online Rechtschreibprüfung"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'grammar-checker',
        'de',
        'Grammar Checker (AI)',
        'KI-Grammatikprüfung — Grammatik korrigieren | AllWordTools',
        'Kostenloser KI-Grammatikcheck: Fehler in Rechtschreibung, Zeitform und Satzbau erkennen und korrigieren lassen. Jetzt Text einfügen und verbessern!',
        '',
        'KI-Grammatikprüfung – Kostenloser Grammatik-Checker online',
        'Fehler in Grammatik, Zeitform und Satzbau mit einem KI-gestützten Tool erkennen und korrigieren. Jeder Korrekturvorschlag wird erklärt, damit Sie lernen können.',
        '["Der Grammatik-Checker von AllWordTools.com nutzt KI, um Ihre Texte wie ein erfahrener Lektor zu prüfen. Er erkennt typische Fehler wie falsche Subjekt-Prädikat-Kongruenz, Zeitformwechsel, Satzbrüche, unklare Formulierungen und bietet korrigierte Versionen mit verständlichen Erklärungen.","Weil jede Korrektur begründet wird, ist das Tool mehr als nur eine schnelle Hilfe: Es hilft Ihnen, Ihre Schreibgewohnheiten zu verstehen und langfristig zu verbessern. Perfekt für Aufsätze, E-Mails, Bewerbungen, Blogartikel oder Social-Media-Posts – für einen professionellen und sicheren Auftritt.","Der Service ist kostenlos, schnell und läuft direkt im Browser – ohne Anmeldung oder Download."]',
        'So nutzen Sie die KI-Grammatikprüfung',
        '[{"title":"Text einfügen","detail":"Fügen Sie einen beliebigen Text ein – von einem einzelnen Satz bis zu einem ganzen Dokument."},{"title":"Prüfung starten","detail":"Klicken Sie auf „Grammatik prüfen“. Die KI scannt Ihren Text auf Fehler."},{"title":"Korrekturen ansehen","detail":"Sehen Sie sich jeden Fehler, die Korrektur und eine kurze Erklärung zur Regel an."},{"title":"Korrigierten Text kopieren","detail":"Übernehmen Sie die bereinigte Version direkt per Copy & Paste."}]',
        '[{"heading":"Was die Grammatikprüfung erkennt","paragraphs":["Der Checker erkennt typische Fehlerquellen: Subjekt-Prädikat-Kongruenz („das Team sind“ vs. „das Team ist“), inkonsistente Zeitformen, Schachtelsätze, Satzfragmente, falsche Pronomen („mich“ vs. „mir“), fehlende oder falsche Artikel, unklare Bezüge und mehr.","Jeder gefundene Fehler wird mit einer einfachen Erklärung versehen – so verstehen Sie nicht nur die Korrektur, sondern auch die Regel dahinter. Das hilft, Fehler langfristig zu vermeiden."]},{"heading":"Warum ein KI-Grammatikprüfer hilfreich ist","paragraphs":["Traditionelle, regelbasierte Prüfer ignorieren oft den Kontext. Eine KI versteht die Bedeutung des Textes und erkennt auch subtile Fehler, die vom Sinn abhängen – und schlägt Korrekturen vor, die Ihren persönlichen Stil bewahren.","Besonders nützlich ist das Tool für Nicht-Muttersprachler, Studierende und Berufstätige, die vor dem Absenden eines wichtigen Textes eine letzte, sichere Prüfung wünschen."]}]',
        '[{"input":"Er habe keine Zeit gehabt.","output":"Er hat keine Zeit gehabt.","note":"Korrigiert den Konjunktiv („habe“) in korrekte Indikativform („hat“)."},{"input":"Mir und mein Bruder gehen ins Kino.","output":"Mein Bruder und ich gehen ins Kino.","note":"Korrigiert den Fall („mir“ → „ich“) und die Reihenfolge."},{"input":"Die Daten is falsch.","output":"Die Daten sind falsch.","note":"„Daten“ ist im Deutschen Plural, daher muss das Verb in der Mehrzahl stehen."}]',
        '["Prüfen Sie längere Texte abschnittsweise für genauere Ergebnisse.","Lesen Sie die Erklärungen – wenn Sie Ihre wiederkehrenden Fehler kennen, verbessern Sie sich schneller.","Kombinieren Sie das Tool mit der Rechtschreibprüfung und Zeichensetzungsprüfung für eine vollständige Textkontrolle."]',
        '[{"question":"Ist die Grammatikprüfung kostenlos?","answer":"Ja, die Nutzung ist im Browser völlig kostenlos."},{"question":"Erklärt das Tool die Korrekturen?","answer":"Ja, zu jeder Korrektur gibt es eine kurze Erläuterung der zugrundeliegenden Grammatikregel, sodass Sie daraus lernen können."},{"question":"Verändert die Prüfung meinen Schreibstil?","answer":"Nein, sie konzentriert sich auf Korrektheit und Klarheit, während Ihr persönlicher Stil und Ihre Ausdrucksweise erhalten bleiben."}]',
        'Kostenlose Online-Grammatikprüfung mit KI finden, um Texte auf Fehler zu überprüfen',
        '["Grammatikprüfung kostenlos","KI Grammatikcheck","Grammatikfehler korrigieren","Rechtschreibprüfung online","Text korrigieren lassen","Grammatik korrektur","Satzbau prüfen","Zeitform prüfen","Online Textverbesserung"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'punctuation-checker',
        'de',
        'Punctuation Checker',
        'Zeichensetzungsprüfung — Kommas korrigieren | AllWordTools',
        'Kostenlose Zeichensetzungsprüfung: Korrigiert Kommas, Apostrophe, Punkte und Anführungszeichen, ohne den Wortlaut zu ändern. Jetzt Texte prüfen.',
        '',
        'Zeichensetzungsprüfung',
        'Korrigieren Sie Kommas, Apostrophe, Punkte, Anführungszeichen und Großschreibung in Ihren Texten – mit verständlichen Erklärungen und ohne Änderung Ihrer Wortwahl.',
        '["Satzzeichen sind klein, aber wirkungsvoll – ein fehlendes Komma oder ein falscher Apostroph kann die Bedeutung verändern oder den Lesefluss stören. Die Zeichensetzungsprüfung von AllWordTools.com scannt Ihren Text, korrigiert die Zeichensetzung und erklärt jede Änderung, während Ihre Wörter exakt so bleiben, wie sie sind.","Ideal für E-Mails, Aufsätze, Social-Media-Posts und Berichte, bei denen eine korrekte Zeichensetzung für Sorgfalt und Professionalität steht. Sie erhalten eine korrigierte Version sowie eine Liste aller Korrekturen, sodass Sie die Regeln dahinter verstehen.","Das Tool ist kostenlos, browserbasiert und verarbeitet auch längere Textpassagen sofort."]',
        'So nutzen Sie die Zeichensetzungsprüfung',
        '[{"title":"Text einfügen","detail":"Fügen Sie den zu prüfenden Text in das Feld ein."},{"title":"Prüfung starten","detail":"Klicken Sie auf „Zeichensetzung prüfen“ – die KI analysiert jedes Satzzeichen."},{"title":"Korrekturen prüfen","detail":"Sehen Sie jede Änderung mit einer kurzen Erklärung."},{"title":"Ergebnis kopieren","detail":"Kopieren Sie die korrigierte Version und verwenden Sie sie beliebig."}]',
        '[{"heading":"Welche Zeichensetzung das Tool korrigiert","paragraphs":["Die Prüfung erfasst Kommas (inkl. Kommaspleiß und fehlende Kommas), Apostrophe („sein“ vs. „seid“, Plural vs. Possessiv), Punkte, Frage- und Ausrufezeichen, Anführungszeichen, Bindestriche und Gedankenstriche, Semikola und Doppelpunkte sowie die Großschreibung am Satzanfang.","Ein bekanntes Beispiel – „Komm wir essen Opa“ vs. „Komm, wir essen, Opa“ – zeigt, wie ein Komma die Bedeutung verändert. Das Tool erkennt genau solche bedeutungsverändernden Fehler."]},{"heading":"Nur Zeichensetzung, keine Wortänderung","paragraphs":["Die Zeichensetzungsprüfung lässt Ihre Wörter bewusst unverändert. Sie formuliert Sätze nicht um und ändert nicht Ihren Stil – sie korrigiert ausschließlich die Zeichensetzung und die Großschreibung am Satzanfang. Das macht sie zu einer sicheren, gezielten Korrektur, der Sie vertrauen können.","Für eine tiefere Überarbeitung, die auch Grammatik und Klarheit verbessert, nutzen Sie anschließend die KI-Grammatikprüfung."]}]',
        '[{"input":"lasst uns Opa essen","output":"Lasst uns, Opa, essen.","note":"Ein Komma ändert die Bedeutung komplett."},{"input":"Das ist sein Buch","output":"Das ist sein Buch.","note":"Punkt am Satzende hinzugefügt."},{"input":"Ich kaufe Äpfel Birnen und Bananen","output":"Ich kaufe Äpfel, Birnen und Bananen.","note":"Kommas trennen Aufzählungen."}]',
        '["Lesen Sie schwierige Sätze laut vor – eine natürliche Pause zeigt oft, wo ein Komma hingehört.","Merken Sie: „seid“ (ihr seid) vs. „sein“ (Possessiv) – der Apostroph macht den Unterschied.","Nutzen Sie die Erklärungen, um die Regeln zu lernen – dann brauchen Sie das Tool seltener."]',
        '[{"question":"Wird der Wortlaut geändert?","answer":"Nein. Die Zeichensetzungsprüfung korrigiert nur Satzzeichen und die Großschreibung am Satzanfang – Ihre Wörter bleiben unverändert."},{"question":"Korrigiert das Tool Apostrophe?","answer":"Ja. Es korrigiert sowohl Possessiv- als auch Kontraktionsapostrophe, z. B. „Marias Buch“ (richtig) oder häufige Fehler wie „sein“ statt „seid“."},{"question":"Ist das Tool kostenlos?","answer":"Ja, es ist vollkommen kostenlos und direkt im Browser nutzbar."}]',
        'Kostenlose Online-Zeichensetzungsprüfung für korrekte Kommasetzung und Satzzeichen',
        '["Zeichensetzung prüfen","Kommasetzung korrigieren","Satzzeichen korrigieren online","kostenlose Zeichensetzungsprüfung","Apostroph korrigieren","Grammatikprüfung Satzzeichen","Komma Prüfung","Punkt und Komma Korrektur"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'wordscapes-solver',
        'de',
        'Wordscapes Solver',
        'Wordscapes Lösungen – Alle Antworten | AllWordTools',
        'Kostenloser Wordscapes-Solver: Gib die Buchstaben ein und erhalte sofort alle Antworten und Bonuswörter nach Länge sortiert – für jedes Level.',
        '',
        'Wordscapes Solver – Alle Antworten & Bonuswörter für jedes Level',
        'Gib die Buchstaben aus dem Rad unten im Level ein und erhalte sofort alle Lösungen plus Bonuswörter – übersichtlich nach Länge sortiert.',
        '["Wordscapes verbindet entspannende Landschaften mit kniffligen Worträtseln – und ab und zu bringt einen das Buchstabenrad zur Verzweiflung. Der Wordscapes Solver von AllWordTools.com schafft Abhilfe: Gib einfach die Buchstaben aus dem Rad ein, und er zeigt dir sofort alle möglichen Wörter, gruppiert nach Länge, passend zum Kreuzworträtsel-Gitter oben im Level.","Der Solver listet auch die Bonuswörter auf – gültige Wörter, die nicht im Hauptgitter vorkommen, aber trotzdem Münzen einbringen und deine Sammlung füllen. Mit der kompletten Liste vor Augen erledigst du das Gitter und kassierst die Extras in einem Durchgang.","Es ist schnell, kostenlos und läuft komplett im Browser auf jedem Gerät – kein Download, keine Anmeldung nötig."]',
        'So nutzt du den Wordscapes Solver',
        '[{"title":"Buchstabenrad finden","detail":"Schau dir den Buchstabenring unten im Wordscapes-Level an."},{"title":"Buchstaben eingeben","detail":"Gib jeden Buchstaben aus dem Rad in das Eingabefeld ein. Verwende ? für unsichere Buchstaben."},{"title":"Lösen","detail":"Klicke auf „Level lösen“ – alle gültigen Wörter erscheinen sofort, nach Länge sortiert."},{"title":"Gitter ausfüllen","detail":"Ordne die Wörter den Gitterfeldern zu und tippe auf ein Wort, um es zu kopieren."}]',
        '[{"heading":"Antworten und Bonuswörter auf einen Blick","paragraphs":["Jedes Wordscapes-Level zeigt ein kleines Buchstabenrad und ein Kreuzworträtsel-Gitter. Unser Solver behandelt das Rad als Buchstabenpool und liefert alle Wörter, die du daraus bilden kannst, gruppiert nach Länge – perfekt abgestimmt auf die Gittergröße.","Bonuswörter sind ebenfalls enthalten. Diese zusätzlichen gültigen Wörter erscheinen nicht im Gitter, bringen dir aber Münzen und erweitern deine Sammlung. Die vollständige Liste hilft dir, jedes Level optimal abzuschließen."]},{"heading":"Warum einen Wordscapes Solver nutzen?","paragraphs":["Wenn ein Level dich feststecken lässt, bewahrt ein Solver deine Serie und deine Münzen – kein Hinweis oder ewiges Mischen nötig. Außerdem erweiterst du ganz nebenbei deinen Wortschatz, denn das Durchgehen aller möglichen Wörter schult dein Auge für das nächste Puzzle.","Da alles im Browser läuft, musst du nichts installieren, und deine Eingaben bleiben privat. Gib das Rad ein, erhalte die Antworten und genieße die Landschaft."]}]',
        '[{"input":"Rad: b r a i n","output":"brain, bairn, bran, barn, rain, rani, brin, bra","note":"Alle Wörter aus dem 5-Buchstaben-Rad, nach Länge sortiert."},{"input":"Rad: g a r d e n","output":"garden, danger, gander, ranged, grade, anger, range, dear","note":"Längere Wörter füllen das Gitter; kürzere sind Bonuswörter."},{"input":"Rad: c l o u d","output":"cloud, could, clod, cold, loud, duo, cod, old","note":"Auch kleine Räder verstecken mehrere Bonuswörter, die Münzen bringen."}]',
        '["Gib alle Buchstaben aus dem Rad ein – Bonuswörter brauchen dieselben Buchstaben.","Nutze ? für Buchstaben, die du nicht genau erkennst; es fungiert als Platzhalter.","Fülle zuerst die längsten Gitterplätze, dann die kürzeren Wörter.","Sammle Bonuswörter ein, um extra Münzen zu erhalten.","Tippe auf ein Wort, um es sofort zu kopieren."]',
        '[{"question":"Wie funktioniert der Wordscapes Solver?","answer":"Gib die Buchstaben aus dem Rad unten im Level ein, und der Solver findet alle gültigen Wörter, die du daraus bilden kannst – gruppiert nach Länge, passend zum Gitter."},{"question":"Enthält er auch Bonuswörter?","answer":"Ja. Neben den Gitterlösungen listet der Solver die Bonuswörter auf, die Münzen bringen und deine Sammlung erweitern."},{"question":"Ist der Wordscapes Solver kostenlos?","answer":"Ja – völlig kostenlos, ohne Download oder Anmeldung. Er läuft sofort im Browser."},{"question":"Funktioniert er auch für neue Level?","answer":"Ja. Der Solver arbeitet mit den eingegebenen Buchstaben und ist daher für jedes Level in jedem Wordscapes-Paket geeignet."},{"question":"Was mache ich, wenn ein Buchstabe schwer lesbar ist?","answer":"Gib einfach ? an seiner Stelle ein – der Solver behandelt es als beliebigen Buchstaben."}]',
        'Transaktional: Spieler möchten ein konkretes Wordscapes-Level lösen und suchen nach einem Werkzeug, das alle Wörter aus den Buchstaben findet.',
        '["Wordscapes Lösungen","Wordscapes Solver Deutsch","Wordscapes alle Antworten","Wordscapes Level lösen","Wordscapes Buchstaben eingeben","Wordscapes Bonuswörter","Wordscapes Hilfetool","Wordscapes kostenlos lösen"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'word-cookies-solver',
        'de',
        'Word Cookies Solver',
        'Word Cookies Lösungen & Bonuswörter | AllWordTools',
        'Kostenloser Word Cookies Lösungshelfer. Gib deine Keksbuchstaben ein und erhalte sofort alle gültigen Wörter und Bonuswörter, gruppiert nach Länge.',
        '',
        'Word Cookies Lösungshelfer',
        'Gib die Buchstaben deines Keksblechs ein und erhalte sofort alle gültigen Wörter – gruppiert nach Länge, inklusive Bonuswörter – um jedes Level zu meistern.',
        '["Word Cookies ist ein herrlich entspanntes Spiel – bis man auf ein Level stößt, dessen Buchstaben einfach nicht zusammenpassen wollen. Der AllWordTools.com Word Cookies Lösungshelfer wurde genau für diese Momente entwickelt: Gib die Buchstaben ein, die auf dem Tablett angezeigt werden, und er listet sofort alle Wörter auf, die du daraus bilden kannst, gruppiert nach Länge, damit du sie leicht den Antwortfeldern zuordnen kannst.","Da Word Cookies das Finden zusätzlicher Wörter belohnt, zeigt unser Helfer nicht nur die erforderlichen Antworten an. Er listet jedes gültige Wort aus deinen Buchstaben auf, einschließlich der Bonuswörter, die dein Keksglas mit Münzen füllen. So schaffst du das Level und kassierst die Belohnungen in einem Durchgang.","Es ist schnell, kostenlos und läuft direkt in deinem Browser auf jedem Gerät – kein Download, keine Anmeldung und keine Einschränkungen."]',
        'So verwendest du den Word Cookies Lösungshelfer',
        '[{"title":"Lies dein Tablett ab","detail":"Sieh dir den Buchstabenkreis am unteren Rand des Word Cookies Levels an."},{"title":"Gib die Buchstaben ein","detail":"Tippe jeden Buchstaben von Tablett in das Eingabefeld. Verwende ? für Buchstaben, die du nicht klar erkennen kannst."},{"title":"Lösen","detail":"Drücke auf „Kekse lösen“ und alle gültigen Wörter erscheinen sofort, gruppiert nach Länge."},{"title":"Zuordnen und tippen","detail":"Ordne die Wörter den Feldern im Level zu und tippe auf ein Wort, um es zu kopieren."}]',
        '[{"heading":"Finde jede Antwort und jedes Bonuswort","paragraphs":["Jedes Word Cookies Level gibt dir eine feste Buchstabenmenge und ein Raster mit leeren Feldern. Unser Helfer behandelt deine Buchstaben als Pool und findet jedes Wörterbuchwort, das daraus gebildet werden kann, sodass die benötigten Antworten immer in der Liste sind. Die Wörter sind nach Länge gruppiert, genau wie die Felder des Levels.","Auch die Bonuswörter – die zusätzlichen gültigen Wörter, die nicht zum Hauptpuzzle gehören – werden angezeigt. Das Sammeln füllt dein Keksglas und bringt Münzen. Mit der vollständigen Liste vor dir wird jedes Level zur Chance, Belohnungen zu sammeln."]},{"heading":"Warum einen Word Cookies Helfer verwenden?","paragraphs":["Ein Helfer ist der schnellste Weg, nicht festzustecken, ohne deine Serie zu verlieren oder Münzen für Hinweise auszugeben. Es ist auch eine tolle Lernhilfe: Die vollständige Liste der möglichen Wörter erweitert deinen Wortschatz und hilft dir, in zukünftigen Levels schneller Muster zu erkennen.","Alles läuft privat in deinem Browser ab, es gibt nichts zu installieren und kein Konto zu erstellen. Gib deine Buchstaben ein, erhalte deine Antworten und spiele weiter."]}]',
        '[{"input":"Buchstaben: h a u s","output":"haus, sau, aus, sah, hau","note":"Alle Wörter aus dem Tablett, nach Länge gruppiert."},{"input":"Buchstaben: s c h u l e","output":"schule, schul, such, luchs, luche, sch, hul, lech","note":"Längere Wörter füllen die Hauptfelder; kürzere sind oft Bonuswörter."},{"input":"Buchstaben: b a u m","output":"baum, bau, um, ab, au, ma","note":"Selbst mit vier Buchstaben verstecken sich mehrere Bonuswörter."}]',
        '["Gib jeden Buchstaben des Tabletts ein – Bonuswörter stammen aus demselben Pool.","Verwende ? für einen unleserlichen Buchstaben; der Helfer behandelt ihn als Joker.","Ordne die längsten Wörter zuerst den größten Feldern zu.","Sammle Bonuswörter, um dein Keksglas zu füllen und Münzen zu verdienen.","Tippe auf ein Wort, um es sofort zu kopieren."]',
        '[{"question":"Wie funktioniert der Word Cookies Lösungshelfer?","answer":"Gib die Buchstaben deines Keksblechs ein und der Helfer findet jedes gültige deutsche Wort, das du daraus bilden kannst, gruppiert nach Länge – passend zu den Feldern des Levels."},{"question":"Werden auch Bonuswörter angezeigt?","answer":"Ja. Der Helfer listet jedes gültige Wort aus deinen Buchstaben auf, einschließlich Bonuswörter, die dein Keksglas füllen und Münzen bringen."},{"question":"Ist der Helfer kostenlos?","answer":"Völlig kostenlos, ohne Anmeldung oder Download. Er läuft sofort in deinem Browser auf jedem Gerät."},{"question":"Ist die Nutzung eines Helfers Schummeln?","answer":"Betrachte es als Hilfswerkzeug. Nutze es, um nicht steckenzubleiben, Bonuswörter zu entdecken und deinen Wortschatz zu erweitern, während du deine Serie behältst."},{"question":"Was, wenn ich einen Buchstaben nicht lesen kann?","answer":"Gib ? an seiner Stelle ein. Der Helfer behandelt ? als Platzhalter für jeden Buchstaben."}]',
        'Lösung für Word Cookies Level finden',
        '["Word Cookies Lösungshelfer","Word Cookies alle Antworten","Word Cookies Cheat","Word Cookies Bonuswörter","Wörter aus Buchstaben finden","Word Cookies Level lösen","Keksbuchstaben lösen"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'codycross-solver',
        'de',
        'CodyCross Solver',
        'CodyCross Löser – Lösungen & Clues | AllWordTools',
        'Kostenloser CodyCross Löser. Geben Sie die Länge und bekannte Buchstaben ein – sofort passende Wörter. Schnell, kostenlos, ohne Anmeldung.',
        '',
        'CodyCross Löser',
        'Geben Sie die Länge des gesuchten Wortes sowie alle bekannten Buchstaben ein – und sehen Sie sofort alle passenden Wörter für Ihre CodyCross-Frage.',
        '["CodyCross verpackt seine Kreuzworträtsel in liebevoll gestaltete Themenwelten, aber eine hartnäckige Frage kann den Spielfluss stoppen. Der CodyCross Löser von AllWordTools.com hilft Ihnen weiter: Geben Sie die Anzahl der Buchstaben sowie alle Buchstaben ein, die Sie durch kreuzende Wörter kennen, und er listet sofort alle Wörter aus dem Wörterbuch auf, die exakt in dieses Muster passen.","Da sich die CodyCross-Gitter überschneiden, haben Sie oft schon einen oder zwei Buchstaben aus bereits gelösten Wörtern. Diese bekannten Buchstaben sind Gold wert – selbst ein einziger Buchstabe kann Hunderte Möglichkeiten auf eine Handvoll reduzieren, und unser Löser nutzt sie, um schnell die Antwort zu finden.","Der Löser ist schnell, kostenlos und läuft direkt im Browser auf jedem Gerät – ohne Downloads oder Anmeldung."]',
        'So verwenden Sie den CodyCross Löser',
        '[{"title":"Kästchen zählen","detail":"Notieren Sie, wie viele Buchstaben die CodyCross-Antwort hat."},{"title":"Muster eingeben","detail":"Geben Sie pro Buchstabe ein Zeichen ein – füllen Sie bekannte Buchstaben aus und verwenden Sie ? _ oder . für unbekannte."},{"title":"Lösen","detail":"Klicken Sie auf ''Lösen'' und jedes Wort, das exakt in das Muster passt, erscheint sofort."},{"title":"Antwort auswählen","detail":"Wählen Sie das passende Wort aus der Liste und tippen Sie darauf, um es zu kopieren."}]',
        '[{"heading":"Kreuzende Buchstaben in Antworten verwandeln","paragraphs":["Jede CodyCross-Antwort hat eine feste Länge, und das verzahnte Gitter liefert oft ein paar Buchstaben gratis. Geben Sie diese bekannten Buchstaben an den richtigen Positionen ein und lassen Sie die restlichen als Platzhalter – der Löser zeigt nur Wörter, die exakt diesem Muster entsprechen.","Dieser positionsgenaue Ansatz ist viel präziser als bloßes Raten anhand der Frage. Je mehr kreuzende Buchstaben Sie haben, desto kürzer und treffsicherer wird die Ergebnisliste – oft führt sie direkt zur gesuchten Antwort."]},{"heading":"Warum einen CodyCross Löser nutzen?","paragraphs":["Ein thematisches Kreuzworträtsel kann an einem obskuren Wort hängen – ein Löser erspart das Steckenbleiben in einem sonst fast fertigen Rätsel. Außerdem hilft er beim Lernen: Wenn Sie sehen, welche Wörter in ein Muster passen, entwickeln Sie ein besseres Gespür dafür, wie Fragen und Antworten zusammenhängen.","Alles läuft privat im Browser ab, es gibt nichts zu installieren und kein Konto nötig. Geben Sie ein, was Sie wissen, und lassen Sie das Muster die Arbeit machen."]}]',
        '[{"input":"Muster: p?zz?e","output":"puzzle","note":"Zwei bekannte Buchstaben reichen oft aus, um die Antwort zu ermitteln."},{"input":"Muster: ??a?et","output":"planet, claret","note":"Ein Muster mit sechs Buchstaben und zwei Treffern grenzt die Auswahl stark ein."},{"input":"Muster: s?lve?","output":"solver, salved, solved","note":"Je mehr bekannte Buchstaben, desto kürzer die Liste."}]',
        '["Passen Sie die Anzahl der Platzhalter genau an die Wortlänge an.","Geben Sie jeden bekannten Buchstaben ein – jeder verkleinert die Auswahl drastisch.","Verwenden Sie ?, _ oder . für unbekannte Stellen – alle funktionieren gleich.","Bei zu vielen Treffern: Lösen Sie ein weiteres kreuzendes Wort, um einen neuen Buchstaben zu erhalten.","Tippen Sie auf ein Ergebnis, um es zu kopieren."]',
        '[{"question":"Wie funktioniert der CodyCross Löser?","answer":"Geben Sie für jeden Buchstaben der Antwort ein Zeichen ein – bekannte Buchstaben werden gesetzt, unbekannte Stellen bleiben Platzhalter. Der Löser zeigt alle Wörter, die exakt dieses Muster erfüllen."},{"question":"Muss ich das Themengebiet der Frage kennen?","answer":"Nein. Der Löser arbeitet rein nach Länge und bekannten Buchstaben – er findet jedes passende Wort, unabhängig von Welt oder Thema."},{"question":"Ist der Löser kostenlos?","answer":"Ja – komplett kostenlos, ohne Anmeldung oder Download. Er läuft sofort im Browser."},{"question":"Was tun, wenn ich nur die Länge kenne?","answer":"Geben Sie so viele Platzhalter ein, wie die Wortlänge beträgt – der Löser listet alle Wörter dieser Länge auf. Selbst ein einziger bekannter Buchstabe schränkt die Auswahl drastisch ein."},{"question":"Welche Zeichen sind für Platzhalter erlaubt?","answer":"Verwenden Sie ?, _ oder . für unbekannte Buchstaben – sie alle werden gleich behandelt."}]',
        'CodyCross Lösung finden mit bekannten Buchstaben und Länge',
        '["CodyCross Löser","CodyCross Lösung","CodyCross Lösungen finden","CodyCross Hilfe","CodyCross Buchstaben eingeben","Kreuzworträtsel Löser CodyCross","CodyCross Wort finden","CodyCross bekannte Buchstaben"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'seven-little-words-solver',
        'de',
        '7 Little Words Solver',
        '7 Little Words Löser – Schnelle Antworten | AllWordTools',
        'Kostenloser 7 Little Words Löser. Gib die Wortlänge und bekannte Buchstaben ein und finde sofort das passende Wort. Schnell, kostenlos, ohne Anmeldung.',
        '',
        '7 Little Words Löser',
        'Gib die genaue Länge der Antwort und alle bereits platzierten Buchstaben ein – der Löser zeigt dir sofort alle passenden Wörter.',
        '["Bei 7 Little Words erhältst du einen Hinweis und eine Reihe von Buchstabenkacheln, die du zu einer Antwort kombinierst – die Länge ist der Schlüssel zum Rätsel. Unser 7 Little Words Löser nutzt das: Gib die Anzahl der Buchstaben und bereits gesetzte Buchstaben ein, und er listet sofort alle Wörter auf, die passen.","Jede der sieben Antworten in einer Runde gibt die genaue Buchstabenanzahl vor, und die bereits platzierten Kacheln liefern bekannte Buchstaben an bestimmten Positionen. Beide Informationen werden im Löser kombiniert, um aus einem großen Wörterbuch nur die Wörter zu filtern, die exakt deinem Muster entsprechen.","Der Löser ist schnell, kostenlos und läuft direkt im Browser auf jedem Gerät – ohne Download oder Anmeldung."]',
        'So verwendest du den 7 Little Words Löser',
        '[{"title":"Länge notieren","detail":"Schau nach, wie viele Buchstaben die Antwort hat – 7 Little Words gibt die Länge immer an."},{"title":"Muster eingeben","detail":"Gib ein Zeichen pro Buchstaben ein. Setze bekannte Buchstaben ein und verwende ? _ oder . für unbekannte Stellen."},{"title":"Lösen","detail":"Klicke auf „Wörter finden“ – es erscheinen alle Wörter, die dem Muster entsprechen."},{"title":"Hinweis zuordnen","detail":"Wähle das passende Wort zum Hinweis aus und tippe darauf, um es zu kopieren."}]',
        '[{"heading":"Die Antwortlänge als Schlüssel nutzen","paragraphs":["Das Besondere an 7 Little Words ist, dass die Länge jeder Antwort vorab bekannt ist. Wenn du die genaue Anzahl der Buchstaben eingibst, werden die Ergebnisse sofort auf Wörter dieser Länge eingeschränkt – oft reicht das, um die Antwort am Hinweis zu erkennen.","Hast du bereits eine oder zwei Kacheln platziert, gib diese Buchstaben an den entsprechenden Positionen ein. Die Kombination aus Länge und bekannten Buchstaben verkürzt die Liste weiter und liefert eine handvoll möglicher Antworten."]},{"heading":"Warum einen 7 Little Words Löser verwenden?","paragraphs":["Ein schwieriger Hinweis kann die ganze Runde aufhalten – ein Löser hilft, ohne einen Hinweis zu verbrauchen. Er ist auch ein praktisches Lernwerkzeug: Das Abgleichen von Hinweisen mit passenden Wörtern schärft mit der Zeit deine Rätselfähigkeiten.","Alles läuft privat im Browser, ohne Installation. Gib die Länge ein, füge bekannte Buchstaben hinzu und finde die Antwort in Sekunden."]}]',
        '[{"input":"Muster: ??????? (7)","output":"Geheimnis, Abenteuer, Eintritt, Gepäck","note":"Die Länge allein liefert schon eine passende Auswahl."},{"input":"Muster: H????t","output":"Haushalt, Hauptsitz, Himmelfahrt, Hitzewelle","note":"Erster und letzter Buchstabe schränken die 8-Buchstaben-Antworten stark ein."},{"input":"Muster: ?a?e?","output":"Rasen, Taler, Kabel, Wagen, Fabel, Gabel, Hafen, Nagel, Tafel, Zange","note":"Bekannte Buchstaben an Position 2 und 4 verkleinern die Liste auf passende Wörter."}]',
        '["Stelle sicher, dass die Anzahl der Platzhalter genau der angegebenen Wortlänge entspricht.","Trage bereits platzierte Buchstaben an den richtigen Stellen ein.","Lies den Hinweis zusammen mit der Kurzliste – die Antwort springt meist ins Auge.","Verwende ?, _ oder . für unbekannte Buchstaben – alle bedeuten das Gleiche.","Tippe auf ein Ergebnis, um es zu kopieren."]',
        '[{"question":"Wie funktioniert der 7 Little Words Löser?","answer":"Gib pro Buchstabe der bekannten Länge ein Zeichen ein und ersetze bereits gesetzte Kacheln durch ihre Buchstaben. Der Löser zeigt alle Wörter an, die exakt dieses Muster erfüllen."},{"question":"Muss ich die Buchstabenkacheln eingeben?","answer":"Du gibst nur die Buchstaben ein, die du bereits platziert hast, und zwar an der richtigen Position. Der Löser sucht dann nach Wörtern mit passender Länge und Buchstaben."},{"question":"Ist der Löser kostenlos?","answer":"Ja, völlig kostenlos – ohne Anmeldung oder Download. Er läuft sofort im Browser."},{"question":"Was, wenn ich nur die Länge kenne?","answer":"Gib einfach die entsprechende Anzahl Platzhalter ein. Der Löser listet dann alle Wörter dieser Länge auf – der Hinweis zeigt meist die richtige Antwort."},{"question":"Welche Symbole bedeuten Platzhalter?","answer":"?, _ oder . – sie werden alle als unbekannter Buchstabe interpretiert."}]',
        'Lösungshilfe für 7 Little Words Rätsel suchen',
        '["7 Little Words Löser","7 Little Words Lösung","Wortlöser 7 Buchstaben","7 Little Words Hilfe","Wort finden mit Länge","Buchstabenrätsel Löser","Kreuzworträtselhilfe 7 Little Words","Wortmuster eingeben"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'wheel-of-fortune-solver',
        'de',
        'Wheel of Fortune Solver',
        'Glücksrad-Löser – Wörter aus bekannten Buchstaben finden',
        'Kostenloser Glücksrad-Löser: Gib ein Wort mit den bereits aufgedeckten Buchstaben ein und finde sofort alle passenden Wörter. Löse das Rätsel Wort für Wort. Ohne Anmeldung.',
        '',
        'Glücksrad-Löser',
        'Gib ein Wort des Rätsels mit den bereits aufgedeckten Buchstaben ein und sieh sofort jedes passende Wort – löse das Board Wort für Wort.',
        '["Glücksrad-Rätsel leben davon, die Lücken zu füllen, während Buchstaben aufgedeckt werden. Genau in dem Moment, wenn ein halb gelöstes Wort plötzlich Klick macht, hilft der AllWordTools.com Glücksrad-Löser. Gib ein Wort vom Spielfeld mit den bereits sichtbaren Buchstaben ein, und er listet sofort alle Wörter auf, die auf das Muster passen.","Das Spielfeld besteht aus mehreren Wörtern, daher arbeitet der Löser Wort für Wort. Nimm das Wort, das du am ehesten erraten kannst, tippe für jedes versteckte Quadrat einen Platzhalter und fülle die bereits gerufenen Buchstaben ein – der Löser zeigt alle Kandidaten an und verkürzt so oft ein langes Board auf eine eindeutige Phrase.","Es ist schnell, kostenlos und läuft direkt im Browser auf jedem Gerät – ohne Download oder Anmeldung."]',
        'So verwendest du den Glücksrad-Löser',
        '[{"title":"Wähle ein Wort","detail":"Suche dir ein Wort auf dem Spielfeld aus, das du lösen möchtest."},{"title":"Gib das Muster ein","detail":"Tippe pro Buchstabe ein Zeichen – setze die bekannten Buchstaben ein und verwende ?, _ oder . für die Lücken."},{"title":"Löse","detail":"Drücke auf „Wort lösen“ und jedes passende Wort erscheint sofort."},{"title":"Lies die Phrase","detail":"Nutze die Kandidaten, um das gesamte Rätsel zusammenzusetzen; tippe auf ein Wort, um es zu kopieren."}]',
        '[{"heading":"Löse das Board Wort für Wort","paragraphs":["Ein Glücksrad-Board ist eine Phrase, die auf mehrere Wörter verteilt ist. Jedes Wort hat eine feste Länge und einige Buchstaben sind bereits aufgedeckt. Gib das Muster für ein einzelnes Wort ein – bekannte Buchstaben an ihrer Position, Platzhalter für den Rest – und der Löser gibt jedes Wort zurück, das passt.","Wort für Wort vorzugehen ist der schnellste Weg, eine Phrase zu knacken. Löse zuerst das einfachste Wort, und die Buchstaben, die es mit der Kategorie oder mit gängigen Phrasen gemeinsam hat, lassen oft die Nachbarwörter von selbst einrasten."]},{"heading":"Warum einen Glücksrad-Löser verwenden?","paragraphs":["Ob du bei der Show miträtselst, das Handyspiel spielst oder eine Runde auf einer Party leitest – ein Löser verwandelt eine frustrierende Blockade in einen schnellen Erfolg. Es ist auch eine unterhaltsame Methode, um dein Mustererkennungsvermögen für häufige Buchstaben und Phrasen zu schärfen.","Alles läuft privat in deinem Browser, ohne Installation. Gib die Buchstaben ein, die du siehst, und lass den Löser den Rest enthüllen."]}]',
        '[{"input":"Muster: ?u?ne","output":"Kugel, Kunde, Stunde, Wunde","note":"Zwei bekannte Buchstaben können reichen, um ein Wort zu erraten."},{"input":"Muster: w?r?","output":"wird, wirr, Wurst, Würfe","note":"Ein kurzes Wort mit wenigen Buchstaben wird schnell eingegrenzt."},{"input":"Muster: ?r?e?","output":"Arbeit, Brezel, Dreher, freien, Greif, Kralle, Preise, Treue","note":"Mehr Lücken geben eine längere Liste – füge einen Buchstaben hinzu, um sie zu verkürzen."}]',
        '["Löse das Board Wort für Wort für die schnellsten Ergebnisse.","Achte darauf, dass die Anzahl der Platzhalter genau der Wortlänge entspricht.","Setze jeden gerufenen Buchstaben an die richtige Position.","Verwende ?, _ oder . für Lücken – sie bedeuten alle ''beliebiger Buchstabe''.","Tippe auf ein Ergebnis, um es zu kopieren."]',
        '[{"question":"Wie funktioniert der Glücksrad-Löser?","answer":"Gib ein Wort vom Spielfeld mit den bereits aufgedeckten Buchstaben ein und verwende Platzhalter für die versteckten Quadrate. Der Löser gibt jedes Wort zurück, das exakt auf das Muster passt."},{"question":"Kann er eine ganze Phrase auf einmal lösen?","answer":"Nein, er löst Wort für Wort. Knacke jedes Wort der Reihe nach, und die Kandidaten machen es einfach, die vollständige Phrase zusammenzusetzen."},{"question":"Ist er kostenlos?","answer":"Ja – völlig kostenlos, ohne Anmeldung oder Download. Er läuft sofort in deinem Browser."},{"question":"Was ist, wenn nur ein Buchstabe aufgedeckt ist?","answer":"Setze diesen Buchstaben an die Position und Platzhalter für den Rest. Du erhältst alle Wörter dieser Länge mit dem Buchstaben an der Stelle – löse mehr vom Board, um es einzugrenzen."},{"question":"Welche Symbole bedeuten ''Platzhalter''?","answer":"Verwende ?, _ oder . für unbekannte Quadrate – sie verhalten sich alle gleich."}]',
        'Hilfe beim Lösen von Glücksrad-Rätseln durch Eingabe von Buchstabenmustern',
        '["Glücksrad Löser","Glücksrad Lösung","Glücksrad Wort finden","Glücksrad Buchstaben eingeben","Glücksrad Puzzle lösen","Wort finden mit bekannten Buchstaben","Glücksrad Muster eingeben","Glücksrad Begriffe raten","Glücksrad Hilfe"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'letter-pattern-finder',
        'de',
        'Letter Pattern Finder',
        'Buchstabenmuster-Finder mit Wildcards | AllWordTools',
        'Kostenloser Buchstabenmuster-Finder: Finde Wörter mit ? für einen Buchstaben und * für beliebig viele – perfekt für Kreuzworträtsel und Wortspiele.',
        '',
        'Buchstabenmuster-Finder',
        'Finde Wörter zu jedem Muster – mit festen Buchstaben, ? für genau einen und * für beliebig viele Buchstaben. Ergebnisse nach Länge gruppiert.',
        '["Mit dem Buchstabenmuster-Finder erstellst du eine Vorlage aus bekannten Buchstaben und Platzhaltern, und das Tool liefert alle passenden Wörter aus einem großen Wörterbuch. Ein Fragezeichen (?) steht für genau einen unbekannten Buchstaben, ein Sternchen (*) für eine beliebige Anzahl – inklusive null. So kannst du jedes Wortmuster durchspielen, von einfachen Lücken bis zu komplexen Ketten.","Anders als Tool, die nur nach Anfangs-, End- oder Teilbuchstaben suchen, erfasst der Muster-Finder die gesamte Wortform auf einmal. Gib zum Beispiel „?aus“ ein, um alle 4-Buchstaben-Wörter zu finden, die auf „aus“ enden (Haus, Maus, Laus …), oder „Sch*“ für Wörter, die mit „Sch“ beginnen und beliebig lang sein dürfen – von „Schuh“ bis „Schornsteinfeger“.","Das Tool ist schnell, kostenlos und datenschutzfreundlich: Alles läuft direkt im Browser, ohne Anmeldung und ohne Limit."]',
        'So verwendest du den Buchstabenmuster-Finder',
        '[{"title":"Muster eingeben","detail":"Tippe die bekannten Buchstaben, ? für genau einen unbekannten Buchstaben und * für eine beliebige Anzahl Buchstaben."},{"title":"Optional: Länge festlegen","detail":"Gib eine genaue Länge vor, um die Treffer bei *-Mustern einzugrenzen."},{"title":"Muster suchen","detail":"Klicke auf „Muster suchen“, um das Wörterbuch zu durchsuchen. Alle passenden Wörter erscheinen, nach Länge sortiert."},{"title":"Ergebnis kopieren","detail":"Tippe auf ein Wort, um es zu kopieren – inklusive Scrabble-Punktzahl."}]',
        '[{"heading":"Wie Muster funktionieren","paragraphs":["Ein Muster besteht aus festen Buchstaben und Platzhaltern. Ein Fragezeichen (?) steht für genau einen Buchstaben – „H?s“ findet z.B. „Haus“, „Hals“, „Hass“, „Huts“ (4 Buchstaben). Ein Sternchen (*) ersetzt beliebig viele Buchstaben, auch keinen – „F*R“ findet „Fahr“, „Feder“, „Fenster“, „Fußballer“. Du kannst beliebig viele Platzhalter kombinieren. Auch Punkte (.) und Unterstriche (_) werden als ? interpretiert.","Da ? die Länge festlegt und * flexibel ist, verwendest du ? bei bekannter Wortlänge und * bei unbekannter. Mit der Längenangabe zähmst du besonders breite *-Muster."]},{"heading":"Wann sich der Muster-Finder lohnt","paragraphs":["Perfekt für Kreuzworträtsel: Trage die bekannten Buchstaben ein, setze ? für die unbekannten Felder, und alle Lösungskandidaten erscheinen auf einen Blick. Auch für Hangman, Wortspiele wie Wordle oder um den Wortschatz zu erweitern.","Bei Brettspielen wie Scrabble oder Words with Friends beschreibst du genau die Lücke auf dem Brett – inklusive bereits liegender Steine – und der Finder zeigt nur Wörter, die exakt in dieses Feld passen."]}]',
        '[{"input":"?aus","output":"Haus, Maus, Laus, raus, saus","note":"? ersetzt genau einen Buchstaben am Anfang."},{"input":"F*R","output":"Fuß, Fahr, Feder, Fenster, Fußballer","note":"* passt auf beliebig viele Buchstaben – von 0 bis unendlich."},{"input":"?ei? , Länge: 4","output":"Bein, Beil, Leid, Teig, Seil","note":"Kombiniere Platzhalter mit fester Länge für präzise Suchen."}]',
        '["Nutze ?, wenn du die Wortlänge kennst, und * bei unbekannter Länge.","Gib eine feste Länge vor, um *-Muster einzugrenzen.","Punkte (.) und Unterstriche (_) funktionieren genau wie ?.","Setze die bekannten Buchstaben fest und lass Platzhalter die Lücken füllen.","Für Wordle-ähnliche 5-Buchstaben-Suchen: Gib fünf ? mit Länge 5 ein."]',
        '[{"question":"Was ist der Unterschied zwischen ? und *?","answer":"? steht für genau einen Buchstaben und legt die Länge fest. * steht für eine beliebige Anzahl (auch null) und ist flexibel."},{"question":"Kann ich Punkte oder Unterstriche als Platzhalter nutzen?","answer":"Ja, Punkt (.) und Unterstrich (_) werden wie ? behandelt – jeder steht für einen unbekannten Buchstaben."},{"question":"Wie unterscheidet sich der Muster-Finder vom Kreuzworträtsel-Löser?","answer":"Der Kreuzworträtsel-Löser nutzt meist nur feste Längen mit ?; der Muster-Finder erlaubt zusätzlich * für variable Längen und ist dadurch flexibler."},{"question":"Taucht der Muster-Finder auch für Kreuzworträtsel?","answer":"Ja, sehr. Gib die bekannten Buchstaben und ? für die Lücken ein, optional die Länge, und erhalte sofort alle passenden Wörter, gruppiert nach Länge."},{"question":"Ist das Tool kostenlos?","answer":"Ja, komplett kostenlos und unbegrenzt nutzbar. Alles läuft privat im Browser, keine Anmeldung nötig."}]',
        'Benutzer suchen nach einem Tool, um Wörter anhand eines Buchstabenmusters mit Platzhaltern zu finden, z.B. für Kreuzworträtsel.',
        '["Buchstabenmuster finden","Wörter mit Platzhaltern","Kreuzworträtsel Hilfe Muster","Wortmuster Generator","Buchstabenmuster mit ? und *","Wörter mit Lücken finden","Wortsuchmuster Tool"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'wildcard-solver',
        'de',
        'Wildcard Solver',
        'Wildcard-Solver: Wörter mit ? und * finden | WortSuchen24.de',
        'Kostenloser Wildcard-Solver: Finde jedes Wort mit ? (ein Buchstabe) und * (beliebig viele Buchstaben). Perfekt für Scrabble, Kreuzworträtsel und Wortspiele.',
        '',
        'Wildcard-Solver',
        'Setze feste Buchstaben ein, ? für genau einen unbekannten Buchstaben und * für eine beliebige Folge – das Wörterbuch liefert alle passenden Wörter.',
        '["Ein Wildcard-Solver ermöglicht es, nach Wörtern zu suchen, indem man Platzhalter anstelle genauer Buchstaben verwendet. Ein Fragezeichen steht für genau einen unbekannten Buchstaben, ein Sternchen für beliebig viele Buchstaben – inklusive keines. So kann eine einzige Suche Wörter ganz unterschiedlicher Länge finden.","Dank dieser Flexibilität ist der Wildcard-Solver von WortSuchen24 ideal für offene Suchanfragen: Finde jedes Wort, das mit einer bestimmten Buchstabenfolge beginnt und mit einer anderen endet, entdecke Buchstabenfolgen in der Wortmitte oder ersetze Joker in Scrabble. Gib dein Muster ein und sofort erscheinen alle Treffer, gruppiert nach Länge.","Der Dienst ist kostenlos, schnell und läuft direkt im Browser auf jedem Gerät – ohne Anmeldung und ohne Einschränkungen."]',
        'So verwendest du den Wildcard-Solver',
        '[{"title":"Gib deine festen Buchstaben ein","detail":"Tippe die Buchstaben, die du kennst, an die richtigen Stellen."},{"title":"Platzhalter hinzufügen","detail":"Verwende ? für genau einen unbekannten Buchstaben und * für eine beliebige Anzahl (auch null)."},{"title":"Suchen","detail":"Klicke auf ''Suchen'' und alle passenden Wörter erscheinen, gruppiert nach Länge."},{"title":"Wort kopieren","detail":"Tippe auf ein beliebiges Ergebnis, um es direkt in die Zwischenablage zu kopieren."}]',
        '[{"heading":"Fragezeichen versus Sternchen","paragraphs":["Die beiden Platzhalter haben ganz unterschiedliche Aufgaben. Ein Fragezeichen steht für genau einen Buchstaben, daher findet ''H?s'' dreistellige Wörter wie ''Haus'', ''Hase'' oder ''Hose''. Ein Sternchen ersetzt eine beliebige Buchstabenfolge, sodass ''H*t'' Wörter wie ''Hut'', ''Halt'', ''Hundert'' oder ''Hüft'' finden kann – unabhängig von der Länge.","Kombiniere sie frei mit festen Buchstaben für präzise und leistungsstarke Suchen. ''Sch*'' findet jedes Wort, das mit ''Sch'' beginnt, ''*en'' findet alle Wörter, die auf ''en'' enden, und ''B??m'' findet vierstellige Wörter wie ''Baum'', ''Beam'' und ''Boom''. Der Solver durchläuft das gesamte Alphabet und liefert jedes Wörterbuchwort, das in das Muster passt."]},{"heading":"Wann den Wildcard-Solver einsetzen","paragraphs":["Greife zu Wildcards, wenn die Wortlänge nicht feststeht. Perfekt, um Wörter mit seltenen Buchstabenkombinationen zu finden, Wortfamilien mit gleicher Vorsilbe oder Endung zu erkunden oder um Joker in Scrabble oder Words With Friends zu ersetzen.","Da die Ergebnisse nach Länge gruppiert und nach Punktzahl sortiert sind, eignet sich das Tool auch hervorragend zum Lernen. Das Durchgehen von Wortfamilien, die einem Muster folgen, erweitert den Wortschatz und zeigt dir die wertvollen Kombinationen, die in deinem Buchstaben-Stein versteckt sind."]}]',
        '[{"input":"H*t","output":"Hut, Halt, Hüft, Hund, Hundert","note":"Das Sternchen ersetzt jede Buchstabenfolge zwischen H und t."},{"input":"Sch*","output":"Schule, Schrank, Schnee, Schaf","note":"Alles, was mit Sch beginnt, beliebige Länge."},{"input":"B??m","output":"Baum, Beim, Boom, Blam","note":"Zwei Fragezeichen für vierbuchstabige Wörter."},{"input":"?a?e","output":"Hase, Lage, Rabe, Tafe","note":"Suchmuster für genau vier Buchstaben mit zwei Unbekannten."}]',
        '["Verwende ?, wenn du die Wortlänge kennst, und *, wenn sie variieren kann.","Kombiniere beide Wildcards, z.B. ''K?t*'', um einige Positionen festzulegen und andere offen zu lassen.","Ein Sternchen kann null Buchstaben ersetzen, daher findet ''Haus*'' auch ''Haus'' selbst.","Füge weitere feste Buchstaben hinzu, um eine große Ergebnisliste zu verkleinern.","Für eine strikte Suche mit fester Länge und nur einzelnen Fragezeichen nutze den Mustersolver."]',
        '[{"question":"Was ist der Unterschied zwischen ? und *?","answer":"Ein Fragezeichen ersetzt genau einen Buchstaben und legt die Wortlänge fest. Ein Sternchen ersetzt eine beliebige Anzahl von Buchstaben (auch null), sodass die Länge variieren kann."},{"question":"Kann ich mehrere Platzhalter verwenden?","answer":"Ja. Du kannst beliebig viele ? und * zusammen mit festen Buchstaben nutzen, um sehr präzise Suchen durchzuführen."},{"question":"Ersetzt das Sternchen auch null Buchstaben?","answer":"Ja. Das Sternchen steht für eine beliebige Buchstabenfolge, einschließlich keiner. Ein Muster wie ''test*'' findet daher auch das Wort ''test'' selbst."},{"question":"Ist der Wildcard-Solver kostenlos?","answer":"Ja, völlig kostenlos und unbegrenzt nutzbar, ohne Anmeldung oder Downloads. Er läuft sofort im Browser auf jedem Gerät."},{"question":"Eignet sich das Tool für Scrabble-Joker?","answer":"Ja. Verwende ? für einen Joker, der jeden Buchstaben annehmen kann, und suche nach spielbaren Wörtern, die zu deinem Muster passen."}]',
        'Wörter mit Platzhaltern suchen',
        '["Wildcard-Solver","Wörter mit Platzhaltern suchen","? und * in der Wortsuche","Scrabble Joker","Kreuzworträtsel Hilfe","Wortmuster suchen","Buchstaben ersetzen","Wortgenerator mit Platzhaltern","Unbekannte Buchstaben suchen"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'pattern-solver',
        'de',
        'Pattern Solver',
        'Muster Löser — Wortmuster lösen | AllWordTools',
        'Kostenloser Muster Löser, der jedes Wort findet, das einem festen Längenmuster aus bekannten Buchstaben und Lücken entspricht. Ideal für Kreuzworträtsel, Spiele und Rätsel.',
        '',
        'Muster Löser',
        'Gib die Buchstaben ein, die du kennst, und einen Platzhalter für jede unbekannte Stelle – sofort siehst du alle echten Wörter, die genau in das Muster passen.',
        '["Ein Muster Löser nimmt ein Wortgerüst – die Buchstaben, die du sicher weißt, plus einen Platzhalter für jede unbekannte Stelle – und gibt jedes Wörterbuchwort aus, das exakt hineinpasst. Da jeder Platzhalter für genau einen Buchstaben steht, entspricht die Länge des Musters der Länge des gesuchten Wortes. Die Ergebnisse sind präzise und leicht zu überblicken.","Dieses Werkzeug ist perfekt, wenn du die Länge eines Wortes und einige Buchstaben bereits kennst: bei einem Kreuzworträtsel, einem Rätselhinweis, einer teilweise aufgedeckten Antwort oder einem Spielstein, der feststeckt. Gib ein, was du hast, markiere die Lücken, und der AllWordTools.com Muster Löser erledigt den Rest in Sekundenbruchteilen.","Es ist völlig kostenlos, läuft sofort in deinem Browser auf jedem Gerät und erfordert weder Anmeldung noch Download."]',
        'So verwendest du den Muster Löser',
        '[{"title":"Gib die bekannten Buchstaben ein","detail":"Setze die Buchstaben genau an die Positionen, an denen sie im Wort stehen."},{"title":"Markiere jede Lücke","detail":"Verwende ?, _ oder . für jede unbekannte Stelle. Ein Symbol entspricht genau einem Buchstaben."},{"title":"Löse das Muster","detail":"Drücke „Muster lösen“ und alle Wörter passender Länge erscheinen sofort."},{"title":"Kopiere deine Antwort","detail":"Tippe auf ein beliebiges Ergebnis, um es sofort zu kopieren und in dein Rätsel oder Spiel einzufügen."}]',
        '[{"heading":"Was einen Muster Löser ausmacht","paragraphs":["Anders als ein allgemeiner Wortfinder, der nach Präfix, Suffix oder enthaltenen Buchstaben sucht, fixiert ein Muster Löser jeden bekannten Buchstaben an einer bestimmten Position. Diese Positionsgenauigkeit macht ihn so leistungsstark für Gitter und Hinweise: Die Antwort muss exakt die Länge des Musters haben und jeden festen Buchstaben treffen, sodass die Kandidatenliste kurz und relevant ist.","Der Muster Löser behandelt Fragezeichen, Unterstrich und Punkt identisch, sodass du das für dich natürlichste Symbol verwenden kannst. Er durchsucht ein großes, gepflegtes deutsches Wörterbuch, bewertet die Treffer und zeigt sie sofort nach Drücken der Taste an."]},{"heading":"Wo der Muster Löser glänzt","paragraphs":["Kreuzworträtsel sind der klassische Fall: Gib die Länge aus dem Gitter und die bereits bekannten Kreuzbuchstaben ein, und der Löser zeigt alle Kandidaten. Ebenso nützlich bei Wortspielen, bei denen ein Stein fest sitzt, bei Galgenraten oder wenn dir ein Wort auf der Zunge liegt und du seine Form kennst.","Da die Ergebnisse gruppiert und bewertet werden, dient das Werkzeug auch als Lernhilfe. Wenn du siehst, welche Wörter ein gemeinsames Muster haben, erkennst du Buchstabenkombinationen, häufige Endungen und nützliche Kurzwörter – das macht dich mit der Zeit zu einem besseren Spieler."]}]',
        '[{"input":"H?nd?","output":"Hände, Hunde, Hinde","note":"Ein Platzhalter in der Mitte eines fünf- und vierbuchstabigen Wortes (hier Länge 5)."},{"input":"B???r","output":"Bauer, Biber, Bader, Biker","note":"Drei unbekannte Buchstaben zwischen B und r."},{"input":"?a?e?","output":"Rasen, Kader, Walen, Gabel","note":"Fünf Buchstaben, nur zwei bekannte an Position 2 und 4."}]',
        '["Gib jeden sicheren Buchstaben ein – schon ein oder zwei feste Buchstaben grenzen die Ergebnisse stark ein.","Zähle die Kästchen genau; die Musterlänge muss exakt der Wortlänge entsprechen.","Verwende jedes beliebige Platzhaltersymbol – ?, _ und . bedeuten alle einen unbekannten Buchstaben.","Wenn du keine Ergebnisse erhältst, überprüfe einen festen Buchstaben; ein einziger falscher Buchstabe blockiert alle Treffer.","Für offene Suchen, bei denen die Länge variieren kann, nutze stattdessen den Wildcard-Löser."]',
        '[{"question":"Was ist ein Muster Löser?","answer":"Ein Werkzeug, das alle Wörterbuchwörter findet, die einem festen Längenmuster aus bekannten Buchstaben und Platzhaltern entsprechen. Jeder Platzhalter steht für genau einen Buchstaben, daher entspricht die Musterlänge der Wortlänge."},{"question":"Welche Platzhalterzeichen kann ich verwenden?","answer":"Du kannst Fragezeichen, Unterstrich oder Punkt für jede unbekannte Stelle verwenden. Sie werden alle gleich behandelt – ein Symbol pro fehlendem Buchstaben."},{"question":"Was ist der Unterschied zum Wildcard-Löser?","answer":"Der Muster Löser fixiert die Wortlänge, da jeder Platzhalter ein Buchstabe ist. Der Wildcard-Löser erlaubt ein Sternchen, das eine beliebige Anzahl von Buchstaben ersetzen kann, sodass die Länge variabel ist."},{"question":"Ist der Muster Löser kostenlos?","answer":"Ja, er ist völlig kostenlos, unbegrenzt nutzbar, ohne Anmeldung und ohne Download. Er läuft sofort in deinem Browser auf jedem Gerät."},{"question":"Kann ich ihn für Kreuzworträtsel verwenden?","answer":"Absolut. Gib die Eintragslänge und die bekannten Kreuzbuchstaben ein, und der Löser zeigt alle passenden Kandidaten für das Gitter."}]',
        'Lösung für Wortmuster mit bekannten Buchstaben und Platzhaltern',
        '["Muster Löser","Wortmuster lösen","Kreuzworträtsel Hilfe","Buchstaben und Lücken","Wortmuster mit Platzhalter","unbekannte Buchstaben ergänzen","Wort Generator","Wortspiele Lösung"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'missing-letters-finder',
        'de',
        'Missing Letters Finder',
        'Lückenfüller: Fehlende Buchstaben finden – Wortergänzung',
        'Kostenloser Lückenfüller für Wörter: Geben Sie bekannte Buchstaben ein, setzen Sie _ für Lücken, und finden Sie alle passenden Wörter. Ideal für Kreuzworträtsel.',
        '',
        'Lückenfüller – Fehlende Buchstaben finden',
        'Geben Sie ein Wort mit Lücken ein und sehen Sie sofort alle echten Wörter, die passen – die ergänzten Buchstaben werden hervorgehoben.',
        '["Ein Lückenfüller für Wörter vervollständigt teilweise bekannte Wörter. Sie geben die Buchstaben ein, die Sie sicher wissen, und setzen für jede fehlende Stelle einen Unterstrich. Dann zeigt das Tool alle Wörter aus dem Wörterbuch, die in das Muster passen – die neu eingesetzten Buchstaben werden farbig markiert.","Dieses Tool ist der perfekte Helfer für Lückentexte, Rechtschreibübungen, unvollständige Kreuzworträtsel-Einträge oder einfach, wenn Sie nur einen Teil eines Wortes kennen. Der Lückenfüller von AllWordTools.com durchsucht ein großes deutsches Wörterbuch und zeigt sofort die Treffer an.","Es ist kostenlos, funktioniert auf jedem Gerät direkt im Browser und erfordert weder Anmeldung noch Download."]',
        'So verwenden Sie den Lückenfüller',
        '[{"title":"Bekannte Buchstaben eingeben","detail":"Schreiben Sie die Buchstaben, die Sie sicher wissen, an die richtige Position."},{"title":"Für jede Lücke einen Unterstrich setzen","detail":"Verwenden Sie _ oder ? für jeden fehlenden Buchstaben. Ein Zeichen steht für genau einen Buchstaben."},{"title":"Lücken füllen","detail":"Klicken Sie auf „Lücken füllen“, und alle Wörter, die in das Muster passen, werden sofort angezeigt."},{"title":"Hervorhebungen beachten","detail":"Die ergänzten Buchstaben sind farbig hervorgehoben, damit Sie auf einen Blick sehen, welche Buchstaben gefehlt haben."}]',
        '[{"heading":"Wie der Lückenfüller Ihr Wort ergänzt","paragraphs":["Der Lückenfüller hält jeden bekannten Buchstaben an seiner Position fest und probiert für jede Lücke alle möglichen Buchstaben durch. Da jede Lücke genau einen Buchstaben repräsentiert, haben alle Ergebnisse dieselbe Länge wie Ihre Eingabe, und es werden nur echte Wörter aus dem Wörterbuch zurückgegeben.","Um die Ergebnisse leicht lesbar zu machen, hebt das Tool die ergänzten Buchstaben hervor. So sehen Sie sofort, welche Buchstaben Sie nicht wussten – das ist besonders hilfreich für Rechtschreibübungen und zum Lernen neuer Wörter."]},{"heading":"Ideal für Rechtschreibung und Rätsel","paragraphs":["Lückentexte sind ein Klassiker in Rechtschreibblättern, Vokabelübungen und Kinderspielen – dieser Lückenfüller löst sie sofort. Auch nützlich, wenn Sie sich an ein Wort nur halb erinnern: falls Sie wissen, dass ein Wort mit „St“ beginnt und mit „n“ endet, aber den Mittelteil vergessen haben, setzen Sie die Lücken und die Antwort erscheint.","Für Kreuzworträtsel-Einträge mit einigen bereits bekannten Buchstaben verhält sich der Lückenfüller wie ein gezielter Kreuzworträtsel-Helfer, der alle passenden Einträge mit der exakten Buchstabenanzahl ausspuckt."]}]',
        '[{"input":"H_u_","output":"Haus, Haut, Hüte","note":"Eine Lücke in einem vierbuchstabigen Wort ergibt mehrere Möglichkeiten."},{"input":"_f_el","output":"Apfel","note":"Zwei Lücken um einen bekannten Kern."},{"input":"Ele_a_t","output":"Elefant","note":"Verstreute Lücken in einem längeren Wort füllen."}]',
        '["Setzen Sie für jeden fehlenden Buchstaben genau einen Unterstrich – die Länge des Ergebnisses entspricht Ihrer Eingabe.","Unterstrich (_) und Fragezeichen (?) sind gleichwertig; beide stehen für einen fehlenden Buchstaben.","Je mehr Buchstaben Sie sicher wissen, desto kürzer und präziser wird die Ergebnisliste.","Beachten Sie die hervorgehobenen Buchstaben, um zu lernen, welche Buchstaben Sie übersehen hatten.","Falls kein Wort passt, überprüfen Sie die bekannten Buchstaben – ein falscher Buchstabe blockiert alle Ergebnisse."]',
        '[{"question":"Was macht der Lückenfüller?","answer":"Er ergänzt fehlende Buchstaben in einem Wort und zeigt alle passenden Wörter an, wobei die ergänzten Buchstaben hervorgehoben werden."},{"question":"Wie markiere ich einen fehlenden Buchstaben?","answer":"Verwenden Sie einen Unterstrich (_) oder ein Fragezeichen (?) für jede Lücke. Jedes Zeichen steht für genau einen fehlenden Buchstaben."},{"question":"Warum sind manche Buchstaben hervorgehoben?","answer":"Der Lückenfüller hebt die Buchstaben hervor, die er in Ihre Lücken eingesetzt hat, damit Sie sofort sehen, welche Buchstaben gefehlt haben."},{"question":"Ist der Lückenfüller für Rechtschreibübungen geeignet?","answer":"Ja, ideal für Lückentexte und Vokabelübungen. Er hilft, die richtige Schreibweise zu lernen, indem er die fehlenden Buchstaben zeigt."},{"question":"Ist der Lückenfüller kostenlos?","answer":"Ja, komplett kostenlos mit unbegrenzter Nutzung, ohne Anmeldung oder Download. Er läuft sofort im Browser auf jedem Gerät."}]',
        'Wort mit fehlenden Buchstaben vervollständigen',
        '["fehlende Buchstaben finden","Wortlücken füllen","Lückenfüller Wort","Buchstaben ergänzen","Wort suchmaschine mit Lücken","Wort mit _ suchen","Kreuzworträtsel Hilfe fehlende Buchstaben","Wort vervollständigen online","Buchstabenlücken Tool"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'letter-rearranger',
        'de',
        'Letter Rearranger',
        'Buchstaben-Umordner – Wörter bilden | AllWordTools',
        'Kostenloser Buchstaben-Umordner: Aus deinen Buchstaben werden alle gültigen Wörter – lang und kurz. Ideal für Scrabble, Anagrams und Wortspiele.',
        '',
        'Buchstaben-Umordner',
        'Gib einen Buchstabensalat ein und lass dir jedes gültige deutsche Wort anzeigen – vom Voll-Anagramm bis zu kurzen Wörtern, die darin stecken.',
        '["Ein Buchstaben-Umordner nimmt deine Buchstaben und sortiert sie zu allen echten Wörtern um, die du bilden kannst. Anders als ein reiner Anagramm-Löser, der nur alle Buchstaben auf einmal verwendet, findet der Umordner auch jedes kürzere Wort, das in deiner Buchstabenmenge versteckt ist – du siehst das komplette Bild, sortiert nach Länge und Punktwert.","Damit ist der AllWordTools.com Buchstaben-Umordner der ideale Begleiter für Anagramm-Rätsel, Buchstabensalate aus Zeitungen, Scrabble- und WordsWithFriends-Steine und jeden Moment, in dem du wissen willst, welche Wörter in einem Buchstabenhaufen stecken. Jokerfelder gibst du mit ? oder * ein, und der Umordner probiert alle Buchstaben aus.","Das Tool ist kostenlos, sofort einsatzbereit und läuft browserbasiert auf jedem Gerät – ohne Anmeldung und ohne Downloads."]',
        'So verwendest du den Buchstaben-Umordner',
        '[{"title":"Buchstaben eingeben","detail":"Tippe die Buchstaben ein, die du umordnen willst. Verwende ? oder * für Joker."},{"title":"Umfang wählen","detail":"Lasse die Option auf ''Alle Wörter'' oder wähle ''Nur Voll-Anagramme'', wenn du nur Wörter mit allen Buchstaben sehen willst."},{"title":"Umordnen","detail":"Klicke auf ''Umordnen'' und jedes gültige Wort erscheint, gruppiert von lang nach kurz."},{"title":"Kopieren, was du brauchst","detail":"Tippe auf ein Wort, um es für dein Spiel oder Rätsel zu kopieren."}]',
        '[{"heading":"Jedes Wort, nicht nur Anagramme","paragraphs":["Ein reines Anagramm verwendet jeden Buchstaben genau einmal, aber in den meisten Spielen und Rätseln suchst du auch die kürzeren Wörter, die du aus einem Teil deiner Buchstaben legen kannst. Der Buchstaben-Umordner liefert beides: schalte auf ''Nur Voll-Anagramme'' für reine Anagramme, oder lass die Option aus, um jedes bildbare Wort von zwei Buchstaben aufwärts zu sehen.","Die Ergebnisse sind nach Scrabble-Punktwert sortiert und nach Länge gruppiert, sodass die längsten, höchstbewerteten Züge oben stehen. Jokerfelder werden mit ? oder * unterstützt und der Umordner probiert alle 26 Buchstaben durch, um jede Möglichkeit zu finden."]},{"heading":"Wo der Umordner am meisten hilft","paragraphs":["Für Anagramm-Rätsel und Buchstabensalate in Zeitungen wähle ''Nur Voll-Anagramme'' und das Tool zeigt dir das eine Wort, das deine Buchstaben ergeben. Für Buchstabenspiele wie Scrabble und WordsWithFriends lasse die Option aus und sieh jedes spielbare Wort – wähle den besten Zug für dein Brett.","Es macht auch Spaß, einfach so mit der Sprache zu spielen: gib deinen Namen oder eine zufällige Buchstabenfolge ein und entdecke die überraschenden Wörter darin. Da jedes Ergebnis aus einem geprüften Wörterbuch stammt, kannst du sicher sein, dass es wirklich spielbar ist."]}]',
        '[{"input":"regnen","output":"regnen, regnet, renen, regen","note":"Voll-Anagramme, die alle Buchstaben verwenden."},{"input":"lehrer","output":"lehrer, rehleder, hehler, leher, reher","note":"Vollständige Wörter plus kürzere Funde."},{"input":"kta?e","output":"karte, kater, kate, kate, kare","note":"Ein Joker wird durch das Alphabet ersetzt."}]',
        '["Wähle ''Nur Voll-Anagramme'', wenn du ein reines Anagramm mit allen Buchstaben brauchst.","Lasse die Option bei Brettspielen aus, um auch kurze Wörter zu sehen.","Verwende ? oder * für Joker; der Umordner probiert jeden Buchstaben an dieser Stelle.","Die Ergebnisse sind nach Punktwert sortiert – die besten Züge stehen oben in jeder Längengruppe.","Gib deinen Namen oder zufällige Buchstaben ein, um versteckte Wörter zu entdecken."]',
        '[{"question":"Was macht der Buchstaben-Umordner?","answer":"Er ordnet deine Buchstaben zu jedem gültigen deutschen Wort um – sowohl Voll-Anagramme, die alle Buchstaben nutzen, als auch alle kürzeren Wörter, die aus einem Teil der Buchstaben gebildet werden können."},{"question":"Wie unterscheidet er sich vom Anagramm-Löser?","answer":"Der Anagramm-Löser sucht nur Wörter, die alle Buchstaben verwenden. Der Buchstaben-Umordner macht das auch, listet aber zusätzlich alle kürzeren Wörter auf und lässt dich zwischen den Modi wechseln."},{"question":"Kann ich Joker oder Platzhalter verwenden?","answer":"Ja. Gib ? oder * für einen Joker ein, und der Umordner probiert alle 26 Buchstaben an dieser Stelle, um jedes mögliche Wort zu finden."},{"question":"Wie sind die Ergebnisse sortiert?","answer":"Wörter sind nach Länge gruppiert (von lang nach kurz) und innerhalb jeder Gruppe nach Scrabble-Punktwert sortiert, sodass die besten Züge leicht zu erkennen sind."},{"question":"Ist der Buchstaben-Umordner kostenlos?","answer":"Ja, völlig kostenlos und unbegrenzt nutzbar, ohne Anmeldung und ohne Downloads. Das Tool läuft sofort in deinem Browser auf jedem Gerät."}]',
        'Hilfe beim Finden aller möglichen Wörter aus einem Buchstabensalat',
        '["Buchstaben umordnen","Buchstabensalat lösen","alle Wörter aus Buchstaben","Wörter finden aus Buchstaben","Anagramm Generator Deutsch","Scrabble Wortfinder","Buchstaben neu anordnen","Wortspiele Hilfe"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'reverse-dictionary',
        'de',
        'Reverse Dictionary',
        'Umgekehrtes Wörterbuch – Wort finden | AllWordTools',
        'Kostenloses umgekehrtes Wörterbuch: Beschreiben Sie die Bedeutung und erhalten Sie passende Wörter, nach Relevanz sortiert. Sofort und ohne Anmeldung.',
        '',
        'Umgekehrtes Wörterbuch',
        'Beschreiben Sie die Bedeutung oder Idee und erhalten Sie sofort die passenden Wörter – geordnet nach bester Übereinstimmung.',
        '["Ein umgekehrtes Wörterbuch arbeitet genau andersherum als ein normales: Statt die Bedeutung eines Wortes nachzuschlagen, geben Sie die Bedeutung ein und erhalten das passende Wort. Geben Sie eine Definition, eine kurze Beschreibung oder verwandte Begriffe ein – das Tool liefert die Wörter, die am besten zu Ihrer Idee passen.","Es ist die perfekte Lösung, wenn Ihnen ein Wort auf der Zunge liegt, aber nicht einfällt. Und es ist ein mächtiges Hilfsmittel für Autoren, die genau wissen, was sie sagen wollen, aber das präzise Wort nicht parat haben. Das umgekehrte Wörterbuch von AllWordTools sortiert die Ergebnisse danach, wie gut sie zu Ihrer Beschreibung passen – die treffendsten Kandidaten erscheinen zuerst.","Es ist kostenlos, schnell und läuft direkt im Browser auf jedem Gerät – ohne Anmeldung und ohne Download."]',
        'So nutzen Sie das umgekehrte Wörterbuch',
        '[{"title":"Wort beschreiben","detail":"Geben Sie eine Definition, Beschreibung oder ein paar verwandte Wörter für die gesuchte Bedeutung ein."},{"title":"Suchen","detail":"Klicken Sie auf „Wörter finden“ und das umgekehrte Wörterbuch zeigt die passendsten Begriffe."},{"title":"Ergebnisse prüfen","detail":"Die Ergebnisse sind nach Relevanz sortiert – die besten Treffer stehen oben."},{"title":"Wort kopieren","detail":"Tippen Sie auf ein Ergebnis, um es direkt in Ihren Text zu übernehmen."}]',
        '[{"heading":"Von der Bedeutung zum Wort","paragraphs":["Ein normales Wörterbuch ordnet einem Wort seine Bedeutung zu; ein umgekehrtes Wörterbuch ordnet einer Bedeutung das passende Wort zu. Es analysiert Ihre Beschreibung anhand einer riesigen Datenbank mit Definitionen und verwandten Begriffen und zeigt Ihnen die Wörter, die Ihre Idee am besten treffen – selbst wenn Sie das Wort gar nicht kennen.","Je präziser Ihre Beschreibung, desto besser die Ergebnisse. Ein klarer Satz wie „ein Gefühl großer Freude“ liefert gezielte Treffer wie „Freude“, „Glück“ und „Euphorie“. Bei einer vageren Eingabe wird das Netz weiter gespannt. In beiden Fällen werden die Wörter so sortiert, dass die besten Übereinstimmungen zuerst kommen."]},{"heading":"Ein unverzichtbarer Helfer für Autoren","paragraphs":["Autoren, Studenten und Rätselfreunde kennen den Moment, in dem die Bedeutung glasklar ist, aber das passende Wort nicht kommen will. Das umgekehrte Wörterbuch überbrückt diese Lücke: Es verwandelt eine Beschreibung in den exakten Begriff, den Sie brauchen, und hilft Ihnen, präziser und abwechslungsreicher zu schreiben.","Es erweitert auch Ihren Wortschatz. Weil es eine nach Relevanz geordnete Liste liefert und nicht nur ein einziges Wort, entdecken Sie neben dem offensichtlichen Begriff auch verwandte und nuancierte Alternativen – für mehr Ausdrucksstärke in Ihren Texten."]}]',
        '[{"input":"ein Gefühl großer Freude","output":"Freude, Glück, Euphorie, Wonne","note":"Eine klare Definition liefert gezielte Treffer."},{"input":"Arzt für Tiere","output":"Tierarzt, Veterinär","note":"Beschreiben Sie einen Beruf, um ihn zu benennen."},{"input":"Angst vor Höhen","output":"Höhenangst, Akrophobie","note":"Finden Sie den Fachbegriff aus einer einfachen Beschreibung."}]',
        '["Seien Sie so konkret wie möglich – eine präzise Beschreibung liefert bessere Ergebnisse.","Versuchen Sie kurze Phrasen oder verwandte Wörter, wenn ein ganzer Satz zu viele Ergebnisse bringt.","Schauen Sie auch weiter unten in der Liste; manchmal passt ein niedriger gereihter Begriff perfekt.","Nutzen Sie das Tool, um Ihren Wortschatz zu erweitern, indem Sie die vorgeschlagenen Nuancen erkunden.","Formulieren Sie um, falls die erste Suche nichts liefert – einfachere, alltägliche Wörter helfen oft."]',
        '[{"question":"Was ist ein umgekehrtes Wörterbuch?","answer":"Es ist ein Tool, das ein Wort anhand seiner Bedeutung findet. Statt ein Wort nachzuschlagen, um seine Bedeutung zu sehen, geben Sie die Bedeutung oder Beschreibung ein und erhalten die passenden Wörter."},{"question":"Wie erziele ich die besten Ergebnisse?","answer":"Verwenden Sie eine klare, spezifische Beschreibung oder ein paar eng verwandte Wörter. Je präziser Ihre Eingabe, desto fokussierter und relevanter sind die Treffer."},{"question":"Warum werden die Ergebnisse sortiert?","answer":"Die Ergebnisse werden danach geordnet, wie gut jedes Wort zu Ihrer Beschreibung passt – die besten Übereinstimmungen stehen oben."},{"question":"Hilft das Tool bei Wortfindungsstörungen („Zungenbrecher“)?","answer":"Ja. Die Bedeutung zu beschreiben ist genau der richtige Weg, um ein Wort wiederzufinden, das man fast im Kopf hat – eine der häufigsten Anwendungen eines umgekehrten Wörterbuchs."},{"question":"Ist das umgekehrte Wörterbuch kostenlos?","answer":"Ja, komplett kostenlos und unbegrenzt nutzbar, ohne Anmeldung und ohne Download. Es läuft sofort in Ihrem Browser auf jedem Gerät."}]',
        'Nutzer möchten ein Wort finden, dessen Bedeutung sie kennen, aber der Begriff selbst nicht einfällt – „Zungenbrecher“-Moment.',
        '["umgekehrtes Wörterbuch","Wort aus Beschreibung finden","Begriff gesucht","Wort finden Bedeutung","online Reverse Dictionary","Wortschatz erweitern","Schreibhilfe","Wortfinder"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'alphabetical-sorter',
        'de',
        'Alphabetical Sorter',
        'Alphabetischer Sortierer für Listen | AllWordTools',
        'Kostenloser alphabetischer Sortierer: Sortiere Wörter, Namen oder Listen sofort in A–Z oder Z–A. Zeilenumbrüche, Leerzeichen oder Kommas, Duplikate entfernen, Groß-/Kleinschreibung ignorieren.',
        '',
        'Alphabetischer Sortierer',
        'Füge eine beliebige Liste ein und sortiere sie sofort alphabetisch – getrennt nach Zeilen, Leerzeichen oder Kommas, wahlweise A–Z oder Z–A, mit Option zum Entfernen von Duplikaten.',
        '["Ein alphabetischer Sortierer ordnet jede Liste von Wörtern, Namen oder Begriffen automatisch alphabetisch. Von Hand zu sortieren ist mühsam und fehleranfällig, aber dieses Tool sortiert selbst lange Listen in Sekundenbruchteilen korrekt – ideal für Referenzen, Glossare, Namenslisten oder Wortschätze.","Der alphabetische Sortierer von AllWordTools.com trennt deinen Text nach Zeilenumbrüchen, Leerzeichen oder Kommas, sortiert aufsteigend (A–Z) oder absteigend (Z–A), ignoriert Groß- und Kleinschreibung und kann doppelte Einträge entfernen. Das sortierte Ergebnis erscheint sofort und kann kopiert werden.","Das Tool ist kostenlos, schnell und läuft direkt im Browser auf jedem Gerät – ohne Anmeldung und ohne Download."]',
        'So nutzt du den alphabetischen Sortierer',
        '[{"title":"Füge deine Liste ein","detail":"Gib die Wörter oder Begriffe ein, die du sortieren möchtest, am besten eines pro Zeile."},{"title":"Wähle die Trennung","detail":"Lege fest, ob die Einträge durch Zeilenumbrüche, Leerzeichen oder Kommas getrennt sind."},{"title":"Stelle die Optionen ein","detail":"Wähle A–Z oder Z–A, ignoriere Groß-/Kleinschreibung und aktiviere bei Bedarf das Entfernen von Duplikaten."},{"title":"Kopiere das Ergebnis","detail":"Die sortierte Liste erscheint sofort – mit einem Klick kopieren."}]',
        '[{"heading":"Flexibles Sortieren für jede Liste","paragraphs":["Listen kommen in vielen Formen vor, daher passt sich der Sortierer an deine an. Wähle Zeilenumbrüche für eine gestapelte Liste, Leerzeichen zum Sortieren der Wörter eines Satzes oder Kommas für eine kommagetrennte Liste. Die Ausgabe erfolgt im gleichen Stil wie die Eingabe, sodass du sie sofort verwenden kannst.","Du hast auch die Kontrolle über die Details. Sortiere auf- oder absteigend, aktiviere die Ignorierung der Groß-/Kleinschreibung, damit ''Apfel'' und ''apfel'' automatisch zusammen sortiert werden, und schalte das Entfernen von Duplikaten ein. Der Sortierer verwendet eine intelligente, natürliche Sortierung, bei der auch Zahlen innerhalb von Einträgen sinnvoll geordnet werden."]},{"heading":"Wobei ein alphabetischer Sortierer hilft","paragraphs":["Alphabetisieren ist eine ständige kleine Aufgabe. Studenten sortieren Literaturverzeichnisse und Glossare, Autoren ordnen Indizes und Wortlisten, Lehrer arrangieren Rechtschreiblistsn und Klassenlisten. Entwickler und Datenarbeiter sortieren Schlüssel, Tags und Optionen, und Rätselfans ordnen Wortschätze, um sie schneller durchzusehen.","Da das Tool Duplikate und Groß-/Kleinschreibung für dich behandelt, bereinigt es die Liste während des Sortierens und verwandelt eine unordentliche Eingabe in ein ordentliches, sortiertes Ergebnis, das du direkt in ein Dokument einfügen kannst."]}]',
        '[{"input":"Banane, Apfel, Kirsche","output":"Apfel, Banane, Kirsche","note":"Kommagetrennte Liste sortiert A–Z."},{"input":"Zoe\nanne\nBernd","output":"anne, Bernd, Zoe","note":"Groß-/Kleinschreibung ignorieren sortiert Namen natürlich."},{"input":"rot rot blau grün","output":"blau, grün, rot","note":"Duplikate entfernen beim Sortieren."}]',
        '["Passe die Trennungsoption an deine Daten an – Zeilen, Leerzeichen oder Kommas – für ein sauberes Ergebnis.","Aktiviere Groß-/Kleinschreibung ignorieren, damit Groß- und Kleinbuchstaben natürlich sortiert werden.","Nutze Duplikate entfernen, um eine Liste in einem Schritt zu bereinigen und zu sortieren.","Wechsle zu Z–A, wenn du die umgekehrte alphabetische Reihenfolge benötigst.","Zahlen innerhalb von Einträgen werden natürlich sortiert, z.B. kommt ''Artikel2'' vor ''Artikel10''."]',
        '[{"question":"Was macht der alphabetische Sortierer?","answer":"Er ordnet jede Liste von Wörtern oder Begriffen alphabetisch, wahlweise A–Z oder Z–A, und kann dabei Duplikate entfernen und Groß-/Kleinschreibung ignorieren."},{"question":"Wie muss meine Liste formatiert sein?","answer":"Du entscheidest. Trenne die Einträge durch Zeilenumbrüche, Leerzeichen oder Kommas – der Sortierer gibt das Ergebnis im gleichen Stil aus."},{"question":"Kann ich doppelte Einträge entfernen?","answer":"Ja. Schalte die Option Duplikate entfernen ein, dann behält der Sortierer nur den ersten Eintrag jedes Begriffs und sortiert die Liste."},{"question":"Sortiert der Sortierer Groß-/Kleinschreibung?","answer":"Standardmäßig wird die Groß-/Kleinschreibung ignoriert, sodass ''Apfel'' und ''apfel'' zusammen sortiert werden. Du kannst diese Option aber deaktivieren, wenn du streng nach Groß-/Kleinschreibung sortieren möchtest."},{"question":"Ist der alphabetische Sortierer kostenlos?","answer":"Ja, völlig kostenlos und ohne Einschränkung, ohne Anmeldung und ohne Download. Er läuft sofort in deinem Browser auf jedem Gerät."}]',
        'Wörter alphabetisch sortieren online',
        '["alphabetisch sortieren","Liste alphabetisch ordnen","Wörter sortieren online","Sortierer A–Z","Begriffe alphabetisch sortieren","Text sortieren","ABC-Sortierer","Wortliste sortieren","Duplikate entfernen sortieren"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'random-letter-generator',
        'de',
        'Random Letter Generator',
        'Zufallsbuchstaben Generator A–Z | AllWordTools',
        'Kostenloser Zufallsbuchstaben Generator. Ziehen Sie einen oder mehrere zufällige Buchstaben – alle Buchstaben, nur Vokale oder Konsonanten, groß/klein, mit/ohne Wiederholung.',
        '',
        'Zufallsbuchstaben Generator',
        'Einen oder mehrere zufällige Buchstaben generieren – wählen Sie alle Buchstaben, nur Vokale oder Konsonanten, groß oder klein, mit oder ohne Wiederholung.',
        '["Ein Zufallsbuchstaben Generator ist ein einfaches, aber überraschend nützliches Werkzeug: Er wählt völlig zufällig Buchstaben aus dem Alphabet aus, sodass Sie es nicht selbst tun müssen. Ob Sie einen Startbuchstaben für ein Wortspiel, eine Reihe von Buchstaben für eine Unterrichtsaktivität oder eine schnelle, unvoreingenommene Auswahl benötigen – der Zufallsbuchstaben Generator von AllWordTools.com liefert Ihnen mit einem Klick ein neues Ergebnis.","Sie können zwischen dem gesamten Alphabet, nur Vokalen oder nur Konsonanten wählen, zwischen Groß- und Kleinbuchstaben umschalten und entscheiden, ob Buchstaben wiederholt werden dürfen. Das macht ihn gleichermaßen nützlich für Phonetikübungen, Partyspiele und kreative Impulse.","Er ist schnell, kostenlos und läuft direkt im Browser auf jedem Gerät – ohne Downloads und ohne Anmeldung."]',
        'So verwenden Sie den Zufallsbuchstaben Generator',
        '[{"title":"Anzahl der Buchstaben wählen","detail":"Geben Sie die gewünschte Anzahl ein, von einem Buchstaben bis zu hundert."},{"title":"Buchstabenauswahl festlegen","detail":"Wählen Sie ‚Alle Buchstaben‘, ‚Nur Vokale‘ oder ‚Nur Konsonanten‘ passend zu Ihrer Aktivität."},{"title":"Optionen anpassen","detail":"Schalten Sie je nach Bedarf Kleinbuchstaben oder ‚Keine Wiederholung‘ ein."},{"title":"Generieren","detail":"Klicken Sie auf ‚Buchstaben generieren‘ und kopieren Sie das Ergebnis mit einem Tipp."}]',
        '[{"heading":"Was Sie mit zufälligen Buchstaben machen können","paragraphs":["Zufällige Buchstaben sind der Ausgangspunkt für unzählige Spiele und Lektionen. Verwenden Sie einen einzelnen Buchstaben, um eine Runde Stadt-Land-Fluss, Wortketten oder ein Name-Tier-Objekt-Spiel zu starten. Generieren Sie eine Reihe von Buchstaben für ein selbstgemachtes Worträtsel oder geben Sie Schülern eine Reihe von Lauten zum Zusammenziehen in einer Phonetikübung.","Da Sie die Auswahl auf Vokale oder Konsonanten beschränken können, ist das Tool perfekt für gezielten Unterricht – üben Sie Vokale separat oder fordern Sie Lernende heraus, Wörter mit einem bestimmten Konsonanten zu bilden."]},{"heading":"Vokale, Konsonanten und Wiederholungen","paragraphs":["Durch das Umschalten zwischen dem gesamten Alphabet, nur Vokalen oder nur Konsonanten können Sie den Schwierigkeitsgrad jeder Aktivität anpassen. Die Option ‚Keine Wiederholung‘ stellt sicher, dass jeder Buchstabe einmalig ist – ideal, wenn Sie ein einzigartiges Set an Buchstaben benötigen.","Schalten Sie Wiederholungen wieder ein, wenn Sie jedes Mal eine völlig unabhängige, zufällige Auswahl wünschen – wie bei einem Würfelwurf, bei dem jede Zahl unabhängig von der vorherigen ist."]}]',
        '[{"input":"1 Buchstabe, alle","output":"M","note":"Ein einzelner, neutraler Buchstabe für den Start eines Spiels."},{"input":"7 Buchstaben, alle, keine Wiederholung","output":"R A T E L I S","note":"Ein kompletter Satz einmaliger Buchstaben."},{"input":"5 Buchstaben, nur Vokale","output":"A E I O U","note":"Ideal für Vokalübungen."}]',
        '["Nutzen Sie den Modus ‚Nur Vokale‘ oder ‚Nur Konsonanten‘ für gezielte Phonetikübungen.","Schalten Sie ‚Keine Wiederholung‘ ein, wenn Sie einen Satz einzigartiger Buchstaben benötigen.","Generieren Sie einen einzelnen Buchstaben für Spiele wie Stadt-Land-Fluss.","Wechseln Sie zu Kleinbuchstaben für Schreibübungen und Leseanfänger.","Tippen Sie auf ‚Alle kopieren‘, um die Buchstaben überall einzufügen."]',
        '[{"question":"Wie zufällig sind die Buchstaben?","answer":"Jeder Buchstabe wird unabhängig mit dem Zufallszahlengenerator Ihres Browsers ausgewählt – das ergibt jedes Mal eine gleichmäßige, unvoreingenommene Auswahl."},{"question":"Kann ich nur Vokale oder nur Konsonanten bekommen?","answer":"Ja. Wählen Sie ‚Nur Vokale‘ oder ‚Nur Konsonanten‘, um die Auswahl auf genau diese Buchstaben zu beschränken."},{"question":"Dürfen sich Buchstaben wiederholen?","answer":"Standardmäßig ja. Schalten Sie ‚Keine Wiederholung‘ ein, um sicherzustellen, dass jeder Buchstabe im Ergebnis einzigartig ist."},{"question":"Ist es kostenlos?","answer":"Ja, völlig kostenlos und ohne Anmeldung. Es läuft sofort in Ihrem Browser auf jedem Gerät."}]',
        'Zufallsbuchstaben generieren für Spiele, Übungen oder kreative Zwecke',
        '["Zufallsbuchstaben Generator","zufällige Buchstaben generieren","Buchstaben ziehen","Vokale Generator","Konsonanten Generator","Buchstaben für Spiele","Buchstaben zufällig"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'vocabulary-quiz',
        'de',
        'Vocabulary Quiz',
        'Vokabelquiz kostenlos — Multiple-Choice Wortschatztest',
        'Kostenloses Vokabelquiz mit sofortiger Auswertung. Teste und erweitere deinen deutschen Wortschatz mit Multiple-Choice-Fragen. Ohne Anmeldung, endlos wiederholbar.',
        '',
        'Vokabelquiz',
        'Teste deine Wortkenntnisse mit einem schnellen, bewerteten Multiple-Choice-Quiz – und wiederhole es beliebig oft, um deinen Wortschatz zu erweitern.',
        '["Ein guter Wortschatz macht dein Schreiben präziser, dein Lesen schneller und deine Ausdrucksfähigkeit sicherer. Dieses Vokabelquiz bietet dir eine unterhaltsame und stressfreie Möglichkeit, deinen Wortschatz zu trainieren: Jede Runde zeigt dir Wörter und du wählst die richtige Definition aus vier Antwortmöglichkeiten – mit sofortiger Punktevergabe.","Die Fragen und Antwortoptionen werden bei jedem Versuch neu gemischt, sodass du das Quiz immer wieder spielen kannst, ohne die Reihenfolge auswendig zu lernen. Es ist völlig kostenlos, läuft im Browser und eignet sich ideal für Schüler, Deutschlernende und alle Sprachbegeisterten."]',
        'So funktioniert das Vokabelquiz',
        '[{"title":"Wort lesen","detail":"Jede Frage zeigt ein Wort und fragt nach seiner Bedeutung."},{"title":"Definition wählen","detail":"Wähle aus vier Optionen die richtige Antwort aus."},{"title":"Lernen beim Raten","detail":"Du siehst sofort, ob du richtig lagst, inklusive kurzer Erklärung."},{"title":"Punktzahl ansehen","detail":"Am Ende der Runde erhältst du dein Ergebnis – versuche, es beim nächsten Mal zu übertreffen."}]',
        '[{"heading":"Warum Quizzen besser ist als passiv Lesen","paragraphs":["Aktives Abrufen der Wortbedeutung stärkt das Gedächtnis weit mehr als bloßes Lesen einer Definition. Jede Frage zwingt dein Gehirn, die Information abzurufen und auszuwählen – genau diese Anstrengung sorgt dafür, dass der Wortschatz hängen bleibt.","Da das Quiz kurz und bewertet ist, lässt es sich leicht in den Alltag integrieren. Ein paar Runden täglich summieren sich über Wochen hinweg zu einem deutlich reicheren Wortschatz."]}]',
        '[{"input":"sich beeilen","output":"sich schnell bewegen oder handeln","note":"Definitionsfrage mit vier Antwortmöglichkeiten."},{"input":"sparsam","output":"vorsichtig und haushälterisch im Umgang mit Geld oder Ressourcen","note":"Die Ablenker sind andere echte Definitionen."}]',
        '["Mache täglich ein oder zwei Runden für stetige Fortschritte.","Notiere dir Wörter, die du falsch hattest, und schlage sie später nach.","Lies die Erklärung nach jeder Antwort, um den Lerneffekt zu verstärken.","Wiederhole das Quiz, um deine vorherige Punktzahl zu übertreffen."]',
        '[{"question":"Ist das Vokabelquiz kostenlos?","answer":"Ja, es ist völlig kostenlos, ohne Anmeldung und läuft direkt im Browser."},{"question":"Ändert sich das Quiz jedes Mal?","answer":"Ja. Die Wörter und Antwortoptionen werden bei jedem Versuch neu gemischt."},{"question":"Für wen ist es geeignet?","answer":"Für Schüler, Deutschlernende, Autoren und alle, die ihren Wortschatz erweitern möchten."}]',
        'Kostenloses Vokabelquiz zum Wortschatztraining',
        '["Vokabelquiz kostenlos","Wortschatztest Deutsch","Multiple-Choice Vokabeltraining","Wortschatz erweitern","Vokabeln lernen","online Vokabelquiz","Deutsch Vokabeltest","Vokabeln üben"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'spelling-quiz',
        'de',
        'Spelling Quiz',
        'Rechtschreib-Quiz – Rechtschreibung testen | AllWordTools',
        'Kostenloses Rechtschreib-Quiz mit den häufigsten Fehlwörtern im Deutschen. Wähle die korrekte Schreibweise aus vier Optionen. Keine Anmeldung nötig, endlos wiederholbar.',
        '',
        'Rechtschreib-Quiz',
        'Erkennst du die richtige Schreibweise? Teste dich bei Wörtern, die oft falsch geschrieben werden – mit sofortiger Auswertung.',
        '["Selbst geübte Schreiber stolpern über Wörter wie „Wiederholung“, „Kommunikation“ oder „nämlich“. Dieses Rechtschreib-Quiz macht aus kniffligen Wörtern ein kurzes Spiel: Jede Frage zeigt eine Bedeutung und vier Schreibweisen – du wählst die richtige aus.","Die Fragen konzentrieren sich auf die häufigsten Rechtschreibfehler im Deutschen und werden bei jedem Versuch neu gemischt. So übst du, bis dir die korrekte Schreibweise automatisch in den Kopf kommt. Kostenlos, ohne Anmeldung und ideal für Schüler, Berufstätige und alle, die ihre Rechtschreibung verbessern wollen."]',
        'So funktioniert das Rechtschreib-Quiz',
        '[{"title":"Lies den Hinweis","detail":"Jede Frage gibt die Bedeutung des gesuchten Wortes als Tipp."},{"title":"Wähle die Schreibweise","detail":"Klicke die korrekte Schreibung aus vier Möglichkeiten an."},{"title":"Sofortige Rückmeldung","detail":"Du siehst sofort, ob du richtig lagst, und die richtige Schreibweise wird angezeigt."},{"title":"Punkte sammeln und wiederholen","detail":"Am Ende erhältst du deine Punktzahl. Starte das Quiz erneut, um dich zu verbessern."}]',
        '[{"heading":"Lerne die Wörter, die jeder stolpern lassen","paragraphs":["Die meisten Rechtschreibfehler konzentrieren sich auf einige hundert Wörter mit Doppelbuchstaben, stummen Buchstaben oder unerwarteten Vokalen. Wer genau diese häufigen Fehlerwörter trainiert, verbessert seine Rechtschreibung mit wenig Aufwand am meisten.","Wenn du die falsche und die richtige Schreibweise nebeneinander siehst, schult das dein Auge – du wirst Fehler in eigenen Texten schneller erkennen."]}]',
        '[{"input":"Wiederholung","output":"richtig – nicht „Wiederholung“ (mit ie)","note":"Achtung: ‚wieder‘ wird mit ‚ie‘ geschrieben, aber die Wiederholung mit ‚ie‘? Nein, es heißt ‚Wiederholung‘ – das ist der Klassiker."},{"input":"nämlich","output":"richtig – nicht „nemlich“","note":"Viele verwechseln das ä mit e – ‚nämlich‘ hat einen Umlaut."}]',
        '["Sprich jedes Wort langsam und silbenweise aus.","Achte auf Doppelbuchstaben und Umlaute.","Notiere dir falsch beantwortete Wörter und übe sie gezielt.","Starte das Quiz so lange, bis du die volle Punktzahl erreichst."]',
        '[{"question":"Ist das Rechtschreib-Quiz kostenlos?","answer":"Ja, völlig kostenlos und ohne Anmeldung – es läuft direkt im Browser."},{"question":"Welche Wörter werden abgefragt?","answer":"Die häufigsten Rechtschreibfehler im Deutschen – dein Training zielt auf echte Fehlerquellen."},{"question":"Ändert sich das Quiz bei jedem Durchlauf?","answer":"Ja. Wörter und Antwortmöglichkeiten werden bei jedem Versuch neu gemischt."}]',
        'Üben der korrekten Schreibweise häufiger deutscher Fehlwörter',
        '["Rechtschreib-Quiz","Rechtschreibung üben","häufige Rechtschreibfehler","Deutsch Rechtschreibung testen","kostenloses Rechtschreibtraining","Online Rechtschreibtest","Wörter richtig schreiben lernen"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'codycross-answers',
        'de',
        'CodyCross Answers',
        'CodyCross Antworten & Rätselhilfe | AllWordTools',
        'Finde alle CodyCross Antworten und Lösungen für jede Welt, Gruppe und Phase. Durchsuche unsere Datenbank nach CodyCross Hinweisen, um jedes Level sofort zu lösen. Schnell und kostenlos.',
        '',
        'CodyCross Antworten & Rätsel-Datenbank',
        'Erhalte sofortige Lösungen für CodyCross-Rätsel. Durchsuche unsere Datenbank nach Hinweisen und kreuzenden Buchstaben, um jedes Level zu lösen und in den Welten voranzukommen.',
        '["CodyCross ist ein äußerst beliebtes mobiles Kreuzworträtselspiel, das von Fanatee entwickelt wurde und von Millionen Spielern weltweit für seine wunderschönen Themenwelten, farbenfrohen Grafiken und den freundlichen außerirdischen Protagonisten Cody geliebt wird. Das Spiel verbindet klassische Kreuzworträtsel-Mechaniken mit einem modernen Twist: Die Spieler müssen ein Gitter aus sich kreuzenden Wörtern basierend auf thematischen Hinweisen ausfüllen. Wenn du Hinweise löst, werden bestimmte Buchstaben in anderen Wörtern des Gitters enthüllt, was dir hilft, die verbleibenden Hinweise zu entschlüsseln. Doch je weiter du in Welten wie Tiefsee, Zirkus oder Weltraum vordringst, desto höher wird der Schwierigkeitsgrad und die Hinweise werden zunehmend kryptischer.","Hier kommt unsere CodyCross-Antworten-Datenbank ins Spiel. Diese erstklassige, kostenlose Suchhilfe soll dir helfen, genau die Antwort zu finden, die du benötigst, egal ob du bei einem einzigen schwierigen Hinweis feststeckst oder deine Vermutungen überprüfen möchtest. Durch die Eingabe bekannter Hinweise, Schlüsselwörter oder bereits vorhandener Buchstaben kannst du Lösungen sofort nachschlagen. Unsere Plattform läuft blitzschnell im Browser ohne Verzögerung – so bleibt deine Rätsel-Strähne erhalten, ganz ohne Paywalls, Registrierungen oder störende Werbung.","Dieses Tool ist nicht nur eine Spickzettel-Sammlung; es ist eine Lernhilfe. Es hilft dir, Verbindungen zwischen Wörtern zu verstehen, neue Definitionen zu entdecken und deinen deutschen Wortschatz spielerisch zu erweitern. Lies weiter, um CodyCross zu meistern, fortgeschrittene Lösungsstrategien zu erlernen und häufige Fehler zu vermeiden."]',
        'So findest du CodyCross Antworten',
        '[{"title":"Hinweis oder Schlüsselwort eingeben","detail":"Tippe den Hinweis, bei dem du feststeckst, in das Suchfeld ein. Du kannst den exakten Wortlaut des Hinweises eingeben oder ein Schlüsselwort (z. B. ''Hauptstadt von Frankreich'' oder ''süßer Bienenstoff'')."},{"title":"Bekannte Buchstaben angeben (optional)","detail":"Wenn du bereits einige Buchstaben im Gitter freigeschaltet hast, verwende unseren [CodyCross Löser](codycross-solver), um bekannte Buchstaben und Fragezeichen für Lücken einzugeben (z. B. ''?a?e??'')."},{"title":"Passende Antworten anzeigen","detail":"Klicke auf Suchen oder wähle einen der beliebten Vorschläge. Die Datenbank durchsucht Tausende von Rätsel-Lösungen und zeigt dir sofort die Treffer, sortiert nach Relevanz und Wortlänge."},{"title":"Antwort eintragen","detail":"Vergleiche das vorgeschlagene Wort mit der Länge deines Gitters, trage es im Spiel ein und nutze die neuen Kreuzungsbuchstaben, um die restlichen Rätsel zu lösen."}]',
        '[{"heading":"Was ist CodyCross und wie funktioniert es?","paragraphs":["CodyCross: Kreuzworträtsel ist ein von Fanatee entwickeltes Rätselspiel, das die Geschichte eines neugierigen Aliens namens Cody erzählt, der auf der Erde abgestürzt ist. Um ihm zu helfen, etwas über unseren Planeten zu lernen, lösen die Spieler thematische Worträtsel. Das Spiel ist in ''Welten'' unterteilt (wie Erde, Abenteuer, Unterwasserwelt, Erfindungen und Kulinarik), die jeweils mehrere ''Gruppen'' mit je 5 Phasen (Kreuzworträtseln) enthalten.","Jede Phase besteht aus einem Gitter horizontaler Wörter. Wenn du einen Hinweis löst, wird das Wort eingetragen. Die Besonderheit ist das farblich hervorgehobene vertikale Geheimwort. Wenn du horizontale Wörter löst, werden zudem bestimmte Buchstaben auf andere Zeilen kopiert. Das macht das Lösen der verbleibenden Hinweise deutlich einfacher."]},{"heading":"Strategien und Tipps für den Erfolg bei CodyCross","paragraphs":["Um ein CodyCross-Meister zu werden, solltest du immer mit den einfachsten Hinweisen beginnen. Verschwende keine Zeit mit schwierigen Fragen; das Lösen der einfachen Wörter schaltet Kreuzungsbuchstaben frei, die dir den Weg für die schwierigen Wörter ebnen.","Achte auf das vertikale Geheimwort. Wenn du dieses Wort frühzeitig errätst, kannst du es ausfüllen und erhältst sofort einen kostenlosen Buchstaben für jede horizontale Reihe des Gitters. Achte auch auf grammatikalische Hinweise wie Pluralformen oder Zeitformen, um Buchstaben vorherzusagen."]}]',
        '[{"input":"Hinweis: ''Ein beliebtes Urlaubsziel in Italien''","output":"ROM","note":"Eine 3-buchstabige Antwort in der Welt Planeten Erde."},{"input":"Hinweis: ''Hauptstadt von Frankreich''","output":"PARIS","note":"Eine 5-buchstabige Antwort in der Welt Abenteuer."}]',
        '["Achte auf die genaue Wortlänge, um unpassende Antworten sofort auszuschließen.","Der Name der Welt liefert den thematischen Kontext für die Hinweise.","Löse die einfachen Wörter zuerst, um Buchstaben im Gitter freizuschalten.","Bei mehreren Möglichkeiten kombiniere die Buchstaben mit unserem [CodyCross Löser](codycross-solver)."]',
        '[{"question":"Ist die CodyCross-Antworten-Datenbank kostenlos?","answer":"Ja, unsere Datenbank ist 100% kostenlos und kann unbegrenzt genutzt werden."},{"question":"Wie suche ich nach einem Hinweis?","answer":"Gib einfach den Hinweis-Text oder ein Schlüsselwort in das Suchfeld oben ein, um alle passenden Lösungen zu finden."},{"question":"Kann ich nach bekannten Buchstaben suchen?","answer":"Ja, für Mustersuchen mit Platzhaltern kannst du unseren [CodyCross Löser](codycross-solver) nutzen."},{"question":"Was sind Welten und Gruppen im Spiel?","answer":"Das Spiel besteht aus Themenwelten, die Gruppen von Kreuzworträtseln enthalten. Jede Gruppe umfasst 5 einzelne Phasen."},{"question":"Kann ich CodyCross offline spielen?","answer":"Ja, das Spiel funktioniert offline, aber du hast keinen Zugriff auf tägliche Challenges oder Online-Datenbanken wie unsere. Spare deine In-Game-Token für Offline-Zeiten."}]',
        '',
        '[]'
      );
