INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'word-unscrambler',
        'ar',
        'Word Unscrambler',
        'حل حروف مبعثرة: فك ترتيب الحروف والكلمات | AllWordTools',
        'اكتشف أسرع طريقة لتحويل الحروف المبعثرة إلى كلمات صالحة للعب في سكرابل، كلمات مع الأصدقاء، وألغاز الكلمات. أدخل حروفك وشاهد النتائج مرتبة حسب القيمة.',
        '',
        'حل الحروف المبعثرة: اكتشف الكلمات الخفية فورًا!',
        'حول أي مجموعة حروف إلى كلمات قابلة للعب وذات قيمة عالية في ثوانٍ.',
        '["هل تجد صعوبة في ترتيب الحروف المبعثرة لتكوين كلمات صالحة؟ سواء كنت عالقًا في جولة صعبة من لعبة سكرابل (Scrabble)، تبحث عن كلمة إضافية في لغز كلمات متقاطعة، أو تسعى لتحقيق أعلى النقاط في كلمات مع الأصدقاء (Words With Friends)، فإن أداة حل الحروف المبعثرة لدينا هي الحل الأمثل لك. تعمل هذه الأداة على فك تشفير أي مجموعة من الحروف لتقدم لك قائمة بكل الكلمات المحتملة، مرتبة حسب النقاط والطول.","على عكس القواميس التقليدية، تتفهم أداة فك الحروف المبعثرة قواعد ألعاب الكلمات الحقيقية. إنها تستخدم قوائم كلمات إنجليزية وعربية ضخمة ومُحدثة بعناية، وتدعم الحروف البديلة (الـ Wildcards)، وتسمح لك بتصفية النتائج حسب الطول، الحروف الأولية، الحروف النهائية، أو التسلسلات التي تحتوي عليها. هذا يعني أنك لن تضيع وقتك في البحث عن كلمات لا تناسب وضعك؛ سترى فقط الخيارات التي تفيدك في لعبتك."]',
        'كيف تستخدم أداة حل الحروف المبعثرة؟',
        '[{"title":"أدخل حروفك","detail":"اكتب الحروف التي لديك في المربع المخصص، حتى خمسة عشر حرفًا في المرة الواحدة. الترتيب لا يهم، لذا يمكنك إدخالها تمامًا كما تظهر على رف حروفك أو قطعتك."},{"title":"أضف حروفًا بديلة (Wildcards) إذا كان لديك مربعات فارغة","detail":"استخدم علامة الاستفهام (؟) لكل مربع فارغ أو حرف بديل. يمكن لكل حرف بديل أن يمثل أي حرف واحد، وستعرض لك الأداة كل الكلمات التي يمكن أن تكتمل بهذه الحروف البديلة."},{"title":"صفّي النتائج (اختياري)","detail":"ضيّق نطاق النتائج عن طريق تحديد الحد الأدنى للطول، أو عن طريق البحث عن كلمات تبدأ أو تنتهي أو تحتوي على تسلسل معين. هذا مثالي عندما تعرف جزءًا من الكلمة التي تحتاجها بالفعل."},{"title":"راجع كلماتك المرتبة ذات القيمة الأعلى","detail":"بعد الضغط على زر ''فك الحروف''، ستظهر لك قائمة بجميع الكلمات الصالحة، مرتبة بحيث تكون الكلمات ذات أعلى النقاط في المقدمة. اختر الكلمة الأنسب لخطوتك التالية!"}]',
        '[{"heading":"مساعدك الشخصي في ألعاب الكلمات","paragraphs":["لكل عشاق ألعاب الكلمات في العالم العربي، سواء كنتم تستمتعون باللعب باللغة الإنجليزية أو العربية، أداة حل الحروف المبعثرة هي الرفيق المثالي. فمن سكرابل (Scrabble) إلى كلمات مع الأصدقاء (Words With Friends) وحتى لعبة كلمة السر، قد تواجه أحيانًا صعوبة في رؤية جميع الاحتمالات الممكنة لحروفك. هنا يأتي دور أداتنا لتوفر لك الوقت والجهد، وتكشف لك عن تلك الكلمات الذكية ذات النقاط العالية التي قد تغفل عنها.","نحن ندرك أن التفكير الإبداعي تحت الضغط قد يكون صعبًا. لذا، صممنا هذه الأداة لتكون سهلة الاستخدام وتوفر لك حلولًا سريعة ودقيقة، مع مراعاة قواعد الألعاب الشائعة. لا تفوت فرصة الفوز أو تحسين مهارتك في بناء الكلمات. دع أداة حل الحروف المبعثرة تساعدك على اكتشاف الكلمات التي ستفاجئ بها خصومك وتزيد من متعتك باللعبة."]},{"heading":"تنوع الاستخدام: ليست فقط للألعاب!","paragraphs":["بالإضافة إلى الألعاب، يمكن لأداة فك الحروف المبعثرة أن تكون مفيدة جدًا لمتعلمين اللغة الإنجليزية أو العربية. إذا كنت تحاول تحسين مفرداتك أو فهم كيفية تشكيل الكلمات من حروف مختلفة، فهذه الأداة تقدم لك رؤى قيمة حول بناء الكلمات وتكوينها. جرب إدخال مجموعة من الحروف وشاهد كيف يمكنك تشكيل كلمات متعددة ومختلفة، مما يعزز قدرتك اللغوية.","كما أنها مثالية لحل الألغاز اللفظية وألغاز الكلمات المتقاطعة التي تعتمد على تركيب الحروف. سواء كنت معلمًا تبحث عن وسيلة ممتعة لمساعدة طلابك، أو ببساطة شخصًا يحب تحدي عقله بألعاب الكلمات، فإن هذه الأداة متعددة الاستخدامات وتلبي احتياجاتك. استغلها لتنمية مهاراتك اللغوية وتوسيع قاموسك."]}]',
        '[{"input":"ل ع ك م","output":"ملك, علم, عمل, لمع","note":"أمثلة لكلمات عربية يمكن تكوينها من حروف مبعثرة."},{"input":"ا و ب د ر","output":"أبواب, دواء, وردة, وادٍ, دروب","note":"مثال آخر لتوليد كلمات عربية مختلفة."},{"input":"N G B A R I + ?","output":"BARGAIN (+), BRAING (+), BANGIR (+), BRAIN, GRAIN, GRIN, RAIN","note":"مثال باللغة الإنجليزية يتضمن حرفًا بديلًا (Wildcard)."}]',
        '["جرّب إدخال الحروف بالترتيب الذي تراه لتوفر الوقت ولا تقلق بشأن ترتيبها.","استخدم علامة الاستفهام ''؟'' لكل حرف بديل أو مربع فارغ لديك لترى المزيد من الاحتمالات.","لا تتردد في استخدام الفلاتر (مثل الطول أو البدء بحرف معين) لتضييق نطاق الكلمات والحصول على ما تبحث عنه بالضبط.","ركز على الكلمات ذات النقاط العالية أولاً، خاصة في ألعاب مثل سكرابل، لتحقيق أقصى استفادة من حركتك."]',
        '[{"question":"ما الغرض من أداة حل الحروف المبعثرة؟","answer":"تُستخدم هذه الأداة لمساعدتك في العثور على جميع الكلمات الصالحة التي يمكن تكوينها من مجموعة معينة من الحروف، وهي مفيدة بشكل خاص في ألعاب الكلمات مثل سكرابل وكلمات مع الأصدقاء، وحل الألغاز."},{"question":"كم عدد الحروف التي يمكنني فكها في المرة الواحدة؟","answer":"يمكنك إدخال ما يصل إلى خمسة عشر حرفًا في المرة الواحدة، بما في ذلك أي حروف بديلة (Wildcards)."},{"question":"كيف تعمل الحروف البديلة (الـ Wildcards) أو المربعات الفارغة؟","answer":"يمكنك تمثيل حرف بديل أو مربع فارغ بعلامة استفهام (؟). ستفكر الأداة في جميع الحروف الممكنة التي يمكن أن يمثلها هذا الرمز لتكوين كلمات صالحة."},{"question":"هل النتائج صالحة في ألعاب مثل سكرابل وكلمات مع الأصدقاء؟","answer":"نعم، تستخدم أداتنا قوائم كلمات إنجليزية وعربية مُحدثة ومعروفة، مما يجعل معظم النتائج صالحة للعب في هذه الألعاب الشعبية وغيرها."},{"question":"هل استخدام أداة حل الحروف المبعثرة يعتبر غشًا؟","answer":"يعتمد ذلك على قواعد اللعبة التي تلعبها والاتفاق بين اللاعبين. في اللعب التنافسي الرسمي قد يعتبر غشًا. ومع ذلك، يستخدمها الكثيرون للمساعدة في تعلم كلمات جديدة وتحسين مهاراتهم، أو عند اللعب بشكل غير تنافسي."},{"question":"هل استخدام أداة حل الحروف المبعثرة مجاني؟","answer":"نعم، أداة حل الحروف المبعثرة مجانية تمامًا للاستخدام ويمكنك الوصول إليها في أي وقت لمساعدتك في ألعابك وألغازك."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في العثور على الكلمات من مجموعة من الحروف المبعثرة لتحسين أدائهم في ألعاب الكلمات أو حل الألغاز.',
        '["حل كلمات متقاطعة","توليد كلمات من حروف","فك الحروف المبعثرة","ترتيب الحروف لتكوين كلمات","مساعد سكرابل عربي","أداة كلمات مع الأصدقاء","البحث عن كلمات من حروف محددة","مساعدة في ألعاب الكلمات"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'anagram-solver',
        'ar',
        'Anagram Solver',
        'حلّ الأناجرام - كاشف الكلمات - AllWordTools.com',
        'اكتشف جميع الأناجرام والكلمات المخفية داخل حروفك! حل كلمات المتقاطعة، ألعاب الألغاز، والسكابل. أداة مجانية وسريعة.',
        '',
        'حلّ الأناجرام: ابحث عن الكلمات من الحروف المبعثرة',
        'أداة سريعة ومجانية لاكتشاف كل الكلمات المخفية في حروفك!',
        '["هل تجد صعوبة في حل ألغاز الكلمات المتقاطعة، أو فك كلمات لعبة مثل سكابل (Scrabble) وكلمات مع الأصدقاء (Words With Friends)؟ أداة حل الأناجرام من AllWordTools.com هي بوابتك لاكتشاف جميع الكلمات الممكنة من مجموعة حروف معينة، سواء كنت تبحث عن كلمة واحدة أو حتى كلمتين. انسَ عناء التفكير الطويل والورقة والقلم، فمع أداتنا، ستجد الحلول في غمضة عين.","تأخذ هذه الأداة مجموعة من الحروف أو كلمة كاملة، ثم تعيد ترتيبها لتقدم لك كل الكلمات الصحيحة التي يمكن تكوينها باستخدام نفس الحروف بالضبط. سواء كانت للعب، للدراسة، أو لمجرد التسلية، أداة حل الأناجرام ستحول الحروف المبعثرة إلى كنوز لغوية، وستساعدك على إيجاد الكلمات ذات القيمة العالية في الألعاب، وتقديم مساعدة لا تقدر بثمن في فك أصعب الألغاز."]',
        'كيف تستخدم أداة حل الأناجرام؟',
        '[{"title":"أدخل حروفك أو كلمتك","detail":"اكتب الحروف التي ترغب في إعادة ترتيبها، أو الصق كلمة موجودة بالفعل. ترتيب الحروف لا يهم؛ فالأداة ستبحث في جميع الترتيبات تلقائياً."},{"title":"أضف أحرف بدل للحروف الناقصة","detail":"استخدم علامة الاستفهام (؟) لكل حرف ناقص أو مربع فارغ. يمكن لكل حرف بدل أن يمثل أي حرف، مما سيكشف لك عن أناجرام قد تفوتك."},{"title":"شغل خيار كلمتين (اختياري)","detail":"قم بتفعيل مفتاح \"كلمتين\" للبحث أيضاً عن أزواج من الكلمات التي تستخدم جميع حروفك معًا – مثالي للعبارات والألغاز المعقدة."},{"title":"راجع وانسخ إجاباتك","detail":"تترتب النتائج حسب نقاط السكابل، لذا ستظهر لك الكلمات الأعلى قيمة أولاً، مما يجعلك تختار الأفضل بسهولة."}]',
        '[{"heading":"الأناجرام: من الألغاز إلى الألعاب اللغوية","paragraphs":["تُعرف الأناجرام بأنها إعادة ترتيب حروف كلمة أو عبارة لتكوين كلمة أو عبارة جديدة. هي منتشرة في كل مكان حولنا؛ تجدها في ألغاز الجرائد، في الكلمات المتقاطعة المعقدة، في ألعاب الحفلات، وفي المنافسات اليومية لألعاب مثل سكابل (Scrabble) وكلمات مع الأصدقاء (Words With Friends). أينما احتجت إلى تحويل مجموعة من الحروف المبعثرة إلى كلمة حقيقية تستخدم كل هذه الحروف، فإن هذه الأداة تقوم بالمهمة بدقة، فوراً، ومجاناً بالكامل.","تم تصميم أداتنا خصيصًا ليس فقط لتلبية فضولك اللغوي، بل لتكون مساعدك الشخصي في جميع التحديات التي تتطلب مهارات إعادة ترتيب الحروف. تخيل أنك أمام جدار في لعبة كلمات، أو تحتاج إلى حل سر كبير في لغز؛ هذه الأداة هي الحل الأمثل لكشاف الكلمات الذي سيوسع مفرداتك ويحسن من مهاراتك اللغوية بشكل ملحوظ."]},{"heading":"استكشف كل خيارات الكلمات المتاحة (حتى كلمتين!)","paragraphs":["إلى جانب الكلمات الفردية، تستطيع أداتنا العثور على أناجرام مكونة من كلمتين! هذا يعني أزواجًا من الكلمات التي تستخدم كل حرف من حروفك تمامًا مرة واحدة. هذه الميزة تجعلها مثالية للباحثين عن حلول لألغاز أكثر تعقيدًا أو للاعبين الذين يودون استغلال كل حرف لديهم بذكاء.","سواء كنت تبحث عن كلمات قصيرة ذات نقاط عالية، أو تركيبات معقدة من كلمتين، فإن الأداة لا تقتصر على عدد معين من الحروف. أدخل ما يصل إلى 15 حرفًا، ودع خوارزمياتنا القوية تقوم بالعمل الشاق نيابة عنك، لتمنحك قائمة شاملة بالحلول الممكنة التي لم تكن لتجدها بمفردك!"]}]',
        '[{"input":"لغز","output":"غلز","note":"مثال لكلمة عربية بسيطة مع أناجرام واحد."},{"input":"طائرة","output":"إطارة, أرطيت, رواتية, تاوريه","note":"أناجرام عربية لكلمة ''طائرة''، قد لا تكون جميعها كلمات بحد ذاتها ولكنها تعيد ترتيب الحروف."},{"input":"كريم","output":"مكر, ركيم, يكمر, مريك","note":"أناجرام عربية لكلمة ''كريم''."}]',
        '["ابدأ بالحروف الأقل شيوعاً في ألعاب الكلمات (مثل: خ، ذ، ص، ض، ط، ظ، غ، ف، ق، ك، ل، م، ن، هـ، و، ي).","استخدم حرف البدل (؟) بحكمة، خاصة للحروف التي تشك في وجودها.","تذكر أن الكلمات الأقصر غالباً ما تكون أسهل للعثور عليها، لكن الكلمات الأطول تجلب نقاطاً أعلى في الألعاب.","جرب خيار \"كلمتين\" عند البحث عن حلول مبتكرة للعبارات أو الألغاز الطويلة."]',
        '[{"question":"ماذا تفعل أداة حل الأناجرام؟","answer":"تأخذ حروفاً مدخلة (سواء كانت كلمة أو مجموعة حروف متفرقة) وتعيد ترتيبها لتجد جميع الكلمات الصحيحة التي يمكن تشكيلها من تلك الحروف في قاموس اللغة الإنجليزية."},{"question":"ما الفرق بين حل الأناجرام ومفكك الكلمات؟","answer":"عادةً ما يركز \"حل الأناجرام\" على استخدام جميع الحروف المعطاة بالضبط لتكوين كلمات جديدة، بينما \"مفكك الكلمات\" قد يجد كلمات باستخدام أي مجموعة فرعية من الحروف المدخلة، مع التركيز على فك تشفير الكلمات المقلوبة."},{"question":"هل يمكنها العثور على أناجرام مكونة من كلمتين؟","answer":"نعم، يمكنك تفعيل خيار \"كلمتين\" لكي تبحث الأداة عن أزواج من الكلمات التي تستخدم معاً جميع الحروف التي أدخلتها مرة واحدة."},{"question":"كيف تعمل أحرف البدل (Wildcards) في حل الأناجرام؟","answer":"باستخدام علامة الاستفهام (؟) يمكنك تمثيل أي حرف. هذا يساعدك على إيجاد أناجرام عندما تكون لديك بلاطة فارغة أو حرف مفقود، حيث ستقوم الأداة بتجربة جميع الحروف الممكنة في مكان الـ(؟)."},{"question":"هل أداة حل الأناجرام مجانية؟","answer":"نعم، الأداة مجانية بالكامل ومتاحة للاستخدام غير المحدود."},{"question":"كم عدد الحروف التي يمكنني إدخالها؟","answer":"يمكنك إدخال ما يصل إلى 15 حرفاً للعثور على جميع الأناجرام الممكنة."}]',
        'يبحث المستخدمون عن أداة تساعدهم في فك غموض الكلمات وإعادة ترتيب الحروف للعثور على كلمات جديدة.',
        '["حل الأناجرام","توليد الكلمات من الحروف","فك الكلمات المبعثرة","محلل الكلمات","أداة توليد الأناجرام","البحث عن كلمات من حروف معينة","مساعد الكلمات المتقاطعة","سكابل فك الكلمات"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'wordle-solver',
        'ar',
        'Wordle Solver',
        'حلول Wordle: أفضل الكلمات المتوقعة لغز ووردل اليومي',
        'احصل على الكلمة التالية الأذكى وضيّق نطاق الاحتمالات بسرعة. حافظ على سجلك وانتصاراتك في Wordle باستخدام مساعد حل الكلمات المجاني.',
        '',
        'حل Wordle: مساعد الكلمات الذكي لألعاب الكلمات المشابهة',
        'ضيّق نطاق الاحتمالات واكتشف إجابة Wordle أسرع من أي وقت مضى.',
        '["هل أنت عالق في لغز Wordle اليومي وتتساءل ما هي الكلمة التالية الأفضل؟ أداة حل Wordle الخاصة بنا هي مفتاحك السري للحفاظ على سلسلة انتصاراتك! لا مزيد من التحديق في الشاشة على أمل الإلهام. فقط أدخل الحروف التي اكتشفتها (الخضراء والصفراء والرمادية)، وسيقوم محلل الكلمات لدينا بتقليص الاحتمالات على الفور، ويقدم لك قائمة مرتبة بأقوى التخمينات المحتملة.","سواء كنت ترغب في إنقاذ لغز صعب، أو الحفاظ على سلسلة انتصاراتك المتواصلة، أو ببساطة تعلم أي التخمينات تمنحك أكبر قدر من المعلومات، فإن AllWordTools.com هنا لمساعدتك. أداة الحل لدينا سريعة ومجانية وتعمل مباشرة في متصفحك. سهلة الاستخدام وتفهم جميع أدلة Wordle الثلاثة: الحروف الخضراء، والصفراء، والرمادية، لتحليل دقيق ونتائج فورية وفعالة."]',
        'كيف يعمل محلل Wordle؟ خطوات بسيطة للحل!',
        '[{"title":"أدخل حروفك الخضراء (المؤكدة)","detail":"اكتب كل حرف صحيح في المربع المطابق لموقعه الدقيق في الكلمة. اترك الخانات التي لا تعرفها فارغة."},{"title":"أضف حروفك الصفراء (الموجودة لكن في غير مكانها)","detail":"أدرج الحروف الموجودة في الكلمة ولكن في مكان خاطئ، في خانة ''الحروف الموجودة''."},{"title":"أضف حروفك الرمادية (المستبعدة)","detail":"سجّل الحروف التي استُبعدت من خلال تخميناتك السابقة في خانة ''الحروف الغائبة''."},{"title":"اضغط ''إيجاد الإجابات''","detail":"اضغط ''إيجاد الإجابات'' لترى كل الكلمات المحتملة، مرتبة مع إبراز أفضل تخمين تالي في البداية."}]',
        '[{"heading":"ما هو Wordle، ولماذا أحتاج إلى أداة حل؟","paragraphs":["Wordle هي لعبة كلمات بسيطة ومسببة للإدمان انتشرت بسرعة في جميع أنحاء العالم، بما في ذلك منطقتنا العربية. الهدف هو تخمين كلمة من خمسة أحرف يوميًا في ست محاولات أو أقل. بعد كل تخمين، تتغير ألوان المربعات لتخبرك بمدى قربك من الحل: الأخضر يعني الحرف صحيح وفي مكانه الصحيح، والأصفر يعني الحرف صحيح ولكن في مكان خاطئ، والرمادي يعني الحرف غير موجود في الكلمة على الإطلاق.","على الرغم من بساطتها، يمكن أن تكون Wordle صعبة للغاية أحيانًا، مما يدفع اللاعبين للبحث عن ''حل Wordle'' أو ''مساعد Wordle''. هنا يأتي دور أداتنا! إنها لا تقدم لك الإجابة مباشرة، بل ترشدك إلى أفضل الخيارات الممكنة بناءً على معلوماتك المتاحة، مما يساعدك على تطوير مهارات التخمين لديك وتعلم استراتيجيات جديدة."]},{"heading":"كيف تفرق أداة حل Wordle الخاصة بنا عن غيرها؟","paragraphs":["المساعد الذكي لدينا مصمم خصيصًا ليقدم لك الكلمة التالية الأذكى، وليس فقط قائمة عشوائية. يفهم خوارزميتنا جميع تفاصيل Wordle؛ فمع كل معلومة جديدة تضيفها (حروف خضراء، صفراء، رمادية)، تتقلص قائمة الكلمات المحتملة بشكل كبير. وغالبًا ما يتبقى لديك عدد قليل جدًا من الكلمات، أو حتى كلمة واحدة فقط!","بالإضافة إلى السرعة والدقة، أداة حل Wordle الخاصة بنا مجانية تمامًا وسهلة الاستخدام. لا تتطلب تنزيل أي شيء أو تسجيل دخول، وهي مثالية لمستخدمي اللغات العربية الذين قد يواجهون صعوبة في حل الألغاز باللغة الإنجليزية نظرًا لاختلاف أنواع الحروف والكلمات عن لغتهم الأم. استخدمها لتحسين استراتيجيتك واكتساب ميزة في Wordle اليومي!"]}]',
        '[{"input":"لنفترض أنك خمنت كلمة ''TABLE'' وظهرت الأخضر على حرف ''T'' والأصفر على ''A'' والرمادي على ''B'', ''L'', ''E''.","output":"ستقترح الأداة كلمات تبدأ بـ ''T'' وتحتوي على ''A'' في مكان آخر غير الثاني، ولا تحتوي على ''B'', ''L'', ''E''. مثل ''TRAIN'', ''THANK''.","note":"يجب على المستخدم إدخال ''T'' في الخانة الأولى (الخضراء)، ''A'' في الحروف الصفراء، و ''B, L, E'' في الحروف الرمادية."},{"input":"خمنت كلمة ''CRANE'' وظهرت كل الحروف رمادية.","output":"سوف تستبعد الأداة جميع هذه الحروف (C, R, A, N, E) من أي تخمين لاحق، وتقدم لك كلمات لا تحتوي عليها.","note":"هذا مثال يوضح قوة الحروف الرمادية في تضييق نطاق البحث بشكل كبير، حيث يتم إزالة العديد من الكلمات المحتملة."},{"input":"خمنت ''LUCKY'' فظهرت ''L'' خضراء في الأولى، و ''U'' صفراء، و ''C'' خضراء في الثالثة، ''K'', ''Y'' رمادية. ","output":"ستقدم الأداة كلمات تبدأ بـ ''L''، بها ''C'' في المركز الثالث، تحتوي على ''U'' في غير مكانها الأول أو الثالث، ولا تحتوي على ''K'', ''Y''. مثل ''LUNCH'', ''LUCID''.","note":"هذا المثال يظهر كيف تتحد جميع أنواع الأدلة لإنتاج تخمينات دقيقة وضيقة."}]',
        '["ابدأ بكلمة تحتوي على حروف شائعة ومختلفة قدر الإمكان (مثل ADIEU أو CRANE).","استخدم الحروف الخضراء والصفراء بحكمة: الحرف الأخضر مؤكد، والأصفر يعني أنه موجود لكن ليس في هذا الموضع.","تخلص من الحروف الرمادية فورًا: لن تظهر هذه الحروف في الكلمة على الإطلاق.","حاول تغطية أكبر عدد من الحروف الشائعة في أول تخمينين لجمع المعلومات."]',
        '[{"question":"كيف يعمل محلل Wordle الخاص بكم؟","answer":"يعمل محلل Wordle عن طريق استخدام الخوارزميات لتصفية الكلمات المحتملة بناءً على الأدلة التي تقدمها (الحروف الخضراء، الصفراء، والرمادية). يضيق نطاق الكلمات تدريجيًا ويقترح لك الكلمة الأذكى التالية التي تحقق أقصى قدر من المعلومات."},{"question":"هل استخدام أداة حل Wordle يعتبر غشًا؟","answer":"يعتمد ذلك على تعريفك للعبة! إذا كنت تلعب من أجل المتعة الشخصية والحفاظ على مستواك، فمن المقبول تمامًا استخدامها. إذا كنت تتنافس، فقد تعتبرها غشًا. نحن نوفرها كأداة تعليمية ومساعدة."},{"question":"هل يقدم لي الحل الإجابة الدقيقة مباشرة؟","answer":"لا، الأداة لا تعطيك الإجابة النهائية مباشرة من البداية. بل تساعدك على تضييق نطاق الاحتمالات وتقدم لك قائمة بالكلمات التي لا تزال ممكنة، مع إبراز أفضل تخمين تالي بناءً على المعلومات المتوفرة لديك."},{"question":"ما هي أفضل كلمة لبدء Wordle؟","answer":"لا توجد كلمة واحدة ''أفضل'' بشكل مطلق، ولكن الكلمات التي تحتوي على حروف متحركة شائعة (مثل A, E, I, O) وحروف ساكنة شائعة (مثل R, S, T, L) تعد خيارات ممتازة. أمثلة شائعة تشمل ADIEU, CRANE, ARRIS."},{"question":"هل أداة حل Wordle مجانية؟","answer":"نعم، أداة Wordle Solver الخاصة بنا مجانية تمامًا للاستخدام. يمكنك الوصول إليها في أي وقت ومن أي متصفح دون الحاجة إلى التسجيل أو الدفع."},{"question":"هل يمكنني استخدامها لألعاب مشابهة لـ Wordle؟","answer":"بينما تم تصميمها خصيصًا لـ Wordle (بكلمات من خمسة أحرف)، يمكن استخدام المبدأ الأساسي لأداتنا للمساعدة في ألعاب كلمات أخرى تتضمن نظام التخمين بالحروف الخضراء والصفراء والرمادية، طالما أنك تعدل عدد الحروف المدخلة."}]',
        'يبحث المستخدمون العرب عن أداة مجانية تساعدهم في حل لغز Wordle اليومي باللغة الإنجليزية والحفاظ على streak الانتصارات.',
        '["حل Wordle","مساعد Wordle","Wordle حل الكلمات","كلمة Wordle اليومية","حل لغز ووردل","كيف أحصل على Wordle صح","أفضل كلمة لبدء Wordle","مساعد حل ألعاب الكلمات"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'scrabble-helper',
        'ar',
        'Scrabble Helper',
        'مساعد سكرابل وحل الكلمات - احصل على أعلى النقاط',
        'اعثر على أفضل كلمات سكرابل بسرعة! استخدم مساعد سكرابل المجاني للحصول على الكلمات الأعلى نقاطًا من حروفك، مع دعم الأحرف البديلة وفلاتر اللوح.',
        '',
        'مساعد سكرابل: أطلق العنان لأقصى نقاطك في اللعبة',
        'حوّل حروفك إلى كلمات فائزة تضمن لك التفوق في كل جولة.',
        '["هل تجد صعوبة في تشكيل الكلمات الفائزة في لعبة سكرابل؟ هل لديك مجموعة من الحروف ولا تعرف كيف تستغلها لتحقيق أعلى النقاط؟ لا تقلق بعد الآن! مساعد سكرابل المجاني الخاص بنا هنا ليجعل منك بطلاً في اللعبة. انسَ عناء البحث والتفكير لساعات، فمع هذه الأداة، ستجد أفضل الكلمات الممكنة من حروفك بسرعة فائقة.","مساعد سكرابل هذا ليس مجرد قاموس كلمات عادي، بل هو مصمم خصيصاً ليناسب طريقة لعب سكرابل الحقيقية. بفضل خوارزمياته الذكية، يقوم بتحويل حروفك العشوائية إلى قائمة مرتبة من الكلمات ذات أعلى النقاط، مع الأخذ في الاعتبار قيم الحروف الرسمية. سواء كنت لاعباً مبتدئاً أو محترفاً، فإن هذه الأداة ستمنحك ميزة تنافسية لا تقدر بثمن، وتساعدك على اكتشاف كلمات جديدة وتحسين استراتيجيتك في اللعب."]',
        'كيف تستخدم مساعد سكرابل لتحقيق الفوز؟',
        '[{"title":"أدخل حروفك","detail":"اكتب الحروف الموجودة لديك في الرف (حتى خمسة عشر حرفاً). ترتيب الحروف لا يهم، فقط اكتبها كما هي."},{"title":"استخدم الأحرف البديلة","detail":"أدخل علامة استفهام (؟) لكل حرف فارغ (بلانك تايل) لديك. هذه الحروف يمكن أن تمثل أي حرف، والأداة ستعرض لك جميع الكلمات الممكنة."},{"title":"طبق فلاتر اللوح","detail":"حدد حرفاً تبدأ به الكلمة، أو تنتهي به، أو تسلسلاً معيناً من الحروف داخل الكلمة، أو حتى طولاً أدنى للكلمة لربطها بكلمات موجودة على اللوح."},{"title":"اختر أفضل كلمة","detail":"النتائج مرتبة حسب نقاط سكرابل وتجميعها حسب الطول. انقر على أي كلمة لنسخها فوراً واستخدامها في لعبتك."}]',
        '[{"heading":"اكتشف كلمات ذات نقاط عالية لم تتوقعها","paragraphs":["تخيل أن لديك حروفاً مثل: أ، ب، ك، ر، ي، س، م. قد تفكر في كلمات بسيطة، ولكن مساعد سكرابل سيكشف لك عن كلمات مثل ''أكرم'' أو ''مكساب'' أو حتى ''سكراب'' بنقاطها الكاملة. هذه الأداة لا تساعدك فقط في إيجاد الكلمات الواضحة، بل تكشف لك عن كلمات أطول وأكثر تعقيداً والتي قد تكون غابت عن ذهنك، مما يرفع من مجموع نقاطك بشكل كبير.","اللعب بذكاء يعني استخدام كل حرف لديك بأقصى إمكاناته. مساعد سكرابل يطبق قيم الحروف الرسمية للعبة، تماماً مثلما هو الحال مع قطع اللعبة الحقيقية. هذا يضمن أن النقاط التي تراها مطابقة لما ستحصل عليه في اللعبة، مما يجعلك واثقاً من كل خطوة تقوم بها. لا تترك أي نقطة على الطاولة، واستغل كل حرف لتحقيق الفوز."]},{"heading":"مثالي لكل من يبحث عن تطوير مهاراته في سكرابل","paragraphs":["سواء كنت تلعب مع الأصدقاء والعائلة، أو تشارك في بطولات عبر الإنترنت، فإن مساعد سكرابل هو أداتك السرية للتفوق. إنه لا يتطلب أي تسجيل أو تحميل، ويعمل فوراً في متصفحك على أي جهاز. هذا يعني أنك تستطيع استخدامه في أي وقت وفي أي مكان، فقط افتح المتصفح ودع الأداة تقوم بالعمل الشاق نيابةً عنك.","بالإضافة إلى مساعدتك في اللعب، يمكن أن يكون هذا المساعد أداة رائعة لتعلم كلمات جديدة وتحسين مفرداتك العربية. من خلال رؤية الكلمات المقترحة، ستكتشف تركيبات حروف لم تكن تعرفها، مما يعزز من قدرتك على تشكيل الكلمات في المستقبل. إنه استثمار في متعتك ومهاراتك اللغوية، كل ذلك بلمسة زر."]}]',
        '[{"input":"كفاتب؟","output":"يُكَاتِب (13 نقطة)، كَاتَبَ (11 نقطة)، فَاتَك (10 نقاط)","note":"الحرف البديل ''؟'' استخدم هنا لإنشاء كلمات جديدة."},{"input":"فرحسع","output":"فارح، حارس، حفر، سحر","note":"يقترح كلمات بناءً على الحروف المتاحة."},{"input":"مقل؟د (تبدأ بـ م)","output":"مُقَلِّد (15 نقطة)، مُقْتَل (12 نقطة)","note":"يتم استخدام الحرف البديل والفلاتر للعثور على كلمة تبدأ بحرف ''م''."}]',
        '["استخدم الأحرف البديلة (؟) بذكاء لربط الحروف الصعبة.","ابحث عن الفرص لتكوين كلمات طويلة للحصول على نقاط إضافية.","لا تتردد في استخدام الفلاتر لربط الكلمات بالأحرف الموجودة على اللوح.","راجع النتائج جيداً، فقد تجد كلمات قصيرة ذات نقاط عالية بشكل مفاجئ."]',
        '[{"question":"هل يساعد هذا المساعد في تحقيق أعلى النقاط في لعبة سكرابل؟","answer":"نعم، هذا المساعد مصمم خصيصاً ليقدم لك الكلمات الأعلى نقاطاً من الحروف المتاحة لديك، مما يضمن لك التفوق في اللعب."},{"question":"كيف أدخل الحروف الفارغة (البلانك) في المساعد؟","answer":"يمكنك استخدام علامة الاستفهام ''؟'' لتمثيل أي حرف فارغ لديك. المساعد سيكتشف جميع الكلمات الممكنة باستخدام هذه الأحرف."},{"question":"هل يمكنني البحث عن كلمات تتصل بأحرف موجودة على لوح سكرابل؟","answer":"بالتأكيد! يمكنك استخدام فلاترنا المتقدمة لتحديد حرف بداية، أو نهاية، أو تسلسل حروف معين، أو حتى طول أدنى للكلمة لربطها باللوح."},{"question":"هل قيم الحروف والنقاط المستخدمة في المساعد حقيقية مثل لعبة سكرابل؟","answer":"نعم، المساعد يستخدم قيم الحروف والنقاط الرسمية للعبة سكرابل، لضمان دقة النتائج ومطابقتها للعبة الحقيقية."},{"question":"هل هذا المساعد مجاني وهل أحتاج للتسجيل لاستخدامه؟","answer":"نعم، المساعد مجاني بالكامل ولا يتطلب أي تسجيل دخول أو اشتراك. يمكنك استخدامه فوراً عبر المتصفح على أي جهاز."},{"question":"هل الكلمات التي يقترحها المساعد صالحة للعب في سكرابل؟","answer":"المساعد يعتمد على قائمة كلمات واسعة وصالحة للغة الإنجليزية في سكرابل، مما يضمن صحة الكلمات المقترحة للعب."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في إيجاد الكلمات ذات النقاط العالية في لعبة سكرابل.',
        '["مساعد سكرابل","حل كلمات سكرابل","سكرابل بالعربي","برنامج سكرابل","مساعد لعبة سكرابل","مولد كلمات سكرابل","كيف افوز بسكرابل","بحث عن كلمات سكرابل"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'words-with-friends-helper',
        'ar',
        'Words With Friends',
        'حل كلمات مع الأصدقاء: مساعدة فورية لأعلى النقاط',
        'اكتشف أفضل الكلمات والنقاط الإضافية في Words With Friends. أدخل حروفك وستجد حاسبة الكلمات الحل الأمثل، محسوبة بقيم اللعبة الفعلية.',
        '',
        'مساعد Words With Friends: اكتشف أفضل التحركات',
        'احصل على أعلى النقاط في لعبة كلمات مع الأصدقاء مع حاسبة الكلمات الفورية.',
        '["هل تبحث عن أفضل حركة في Words With Friends؟ هنا الحل! سواء كنت في مأزق أو تسعى للحصول على نقاط لم يتوقعها أحد، يقدم لك مساعد Words With Friends أقوى الكلمات المخفية بين أحرفك، مرتبة حسب القيم النقطية الصحيحة للعبة، لتضمن لك دائمًا أفضل اختيار.","ما عليك سوى إدخال الحروف التي لديك، وسيقوم بتحليل قائمة واسعة من الكلمات الإنجليزية، مع الأخذ في الاعتبار قيم الحروف الخاصة بـ Words With Friends (التي تختلف عن سكرابل)، مما يضمن أن النقاط التي تراها مطابقة تمامًا للعبة التي تلعبها. يدعم هذا المساعد الأحرف الفارغة (الجوكر) باستخدام علامة الاستفهام (؟)، ويتيح لك التصفية بحروف البداية، حروف النهاية، تسلسل معين من الحروف، أو حتى طول الكلمة، لمساعدتك في العثور على الكلمة المثالية التي تتصل باللوحة. توقف عن البحث في قوائم لا نهاية لها؛ احصل على مجموعة مركزة من الكلمات القابلة للعب ومرتبة من الأعلى نقاطًا."]',
        'كيف تستخدم مساعد Words With Friends؟',
        '[{"title":"أدخل حروفك","detail":"اكتب الحروف المتوفرة لديك — حتى خمسة عشر حرفًا. الترتيب غير مهم، لذا أدخلها كما تظهر تمامًا في رف الحروف الخاص بك."},{"title":"أضف البلاطات الفارغة","detail":"استخدم علامة الاستفهام (؟) لكل بلاطة فارغة (جوكر). هذه العلامة تمثل أي حرف، وسيعرض لك المساعد كل الكلمات التي يمكن إكمالها بها."},{"title":"طبق الفلاتر الخاصة باللوحة","detail":"حدد حرفًا تبدأ به الكلمة أو تنتهي به، أو تسلسلًا محددًا من الحروف بداخلها، أو حتى طولًا أدنى للكلمة، للعثور على كلمة تتصل بالحروف الموجودة على لوحة اللعب."},{"title":"نفذ حركتك","detail":"يتم ترتيب الحركات حسب نقاط Words With Friends وتجميعها حسب طول الكلمة. اضغط على أي كلمة لنسخها بسهولة."}]',
        '[{"heading":"مصمم خصيصًا للعبة Words With Friends","paragraphs":["على عكس بعض الأدوات التي تستخدم قيم نقاط عامة أو خاصة بألعاب أخرى (مثل سكرابل)، تم بناء مساعدنا خصيصًا للعبة Words With Friends. هذا يعني أن كل كلمة تراها، وكل نقطة محتسبة، تتوافق تمامًا مع قواعد اللعبة التي تلعبها. لا مزيد من المفاجآت أو الأخطاء في حساب النقاط بعد الآن.","هذا المساعد مجاني تمامًا، ويعمل فورًا في متصفحك على أي جهاز، ولا يتطلب أي تسجيل دخول أو اشتراك. سواء كنت تسعى لتحقيق عودة قوية بعد تأخر في النقاط أو تحاول الحفاظ على تقدمك، فهو أسرع طريقة للعثور على أفضل حركة ممكنة."]},{"heading":"أدوات متقدمة للوحة اللعب","paragraphs":["لا يقتصر دور مساعدنا على إيجاد الكلمات فحسب، بل يمكنه مساعدتك في توجيه بحثك ليتناسب مع لوحة اللعب الحالية. عندما تكون بحاجة إلى كلمة تبدأ بحرف معين لتتصل بكلمة موجودة على اللوحة، أو ربما كلمة تحتوي على تسلسل معين من الأحرف، فإن فلاترنا المتقدمة تجعل الأمر سهلاً.","استغل فلاتر مثل ''البدء بـ''، ''الانتهاء بـ''، ''يحتوي على''، و''الحد الأدنى للطول'' لتحديد نطاق بحثك بدقة. هذا يضمن أنك لا تحصل فقط على أفضل الكلمات، بل على أفضل الكلمات التي يمكنك بالفعل لعبها بشكل استراتيجي على اللوحة، مما يعزز فرصك في الفوز."]}]',
        '[{"input":"أ ك ل м و ؟","output":"مأكول (12 نقطة)","note":"تم استخدام الحرف العربي ''أ'' وحرف الجوكر، وإيجاد كلمة إنجليزية تحتوي حروفًا تشبه الأحرف العربية نطقًا."},{"input":"R E A M T S ?","output":"MASTER (9 نقاط)","note":"أمثلة للكلمات الإنجليزية التي يمكن إنشاؤها باستخدام أحرف الجوكر."},{"input":"ب ح ر ي ف ? | يبدأ بـ: ب","output":"بحيرة (10 نقاط)","note":"العثور على كلمة تبدأ بحرف معين مع استخدام الجوكر."}]',
        '["لا تهمل استخدام الأحرف الفارغة (؟)؛ فهي مفتاح لإنشاء كلمات ذات نقاط عالية.","جرب تصفية الكلمات حسب حروف البداية أو النهاية لتستفيد من المربعات المزدوجة أو الثلاثية.","ركز على استخدام الحروف النادرة مثل X، Q، Z لزيادة نقاطك بشكل كبير.","لا تتردد في استخدام المساعد حتى لو كنت متقدمًا، فالحركة الذكية قد تضمن لك الفوز."]',
        '[{"question":"هل تستخدم أداة المساعد هذه قيم نقاط Words With Friends؟","answer":"نعم، تستخدم حاسبة الكلمات لدينا قيم النقاط الدقيقة للعبة Words With Friends، لضمان أن تكون النقاط التي تراها متطابقة للعبة التي تلعبها."},{"question":"كيف أدخل الأحرف الفارغة (الجوكر)؟","answer":"يمكنك إدخال الأحرف الفارغة ببساطة عن طريق كتابة علامة الاستفهام (؟) لكل حرف فارغ لديك. هذه العلامة ستمثل أي حرف."},{"question":"هل يمكنني العثور على حركات تتصل باللوحة؟","answer":"بالتأكيد! يمكنك استخدام فلاتر البحث المتقدمة لتحديد حروف البداية، حروف النهاية، تسلسلات معينة من الحروف، أو الحد الأدنى لطول الكلمة للعثور على الكلمات التي تتناسب مع لوحة اللعب."},{"question":"هل استخدام مساعد Words With Friends مجاني؟","answer":"نعم، هذا المساعد مجاني تمامًا ويمكن استخدامه دون أي تكلفة أو الحاجة إلى التسجيل."},{"question":"هل استخدام أداة مساعدة يخالف قواعد اللعبة؟","answer":"بشكل عام، تعتبر معظم ألعاب الكلمات أن استخدام المساعدات أثناء اللعب النشط يتعارض مع روح اللعب النظيف. ننصح باستخدامه للتعلم أو للتحقق بعد اللعبة."},{"question":"هل يعمل هذا المساعد على جميع الأجهزة؟","answer":"نعم، يعمل المساعد في متصفحك على أي جهاز متصل بالإنترنت، سواء كان هاتفًا ذكيًا، جهازًا لوحيًا، أو حاسوبًا مكتبيًا."}]',
        'يبحث المستخدمون عن أداة تساعدهم على الفوز في لعبة كلمات مع الأصدقاء بتحسين اختياراتهم للكلمات.',
        '["حل كلمات مع الأصدقاء","مساعد كلمات مع الأصدقاء","غش كلمات مع الأصدقاء","افضل كلمات Words With Friends","حروف Words With Friends","كلمات مع الاصدقاء نقاط","موقع حل كلمات Words With Friends","مولد كلمات Words With Friends"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'crossword-solver',
        'ar',
        'Crossword Solver',
        'حل الكلمات المتقاطعة بالعربي: أوجد الكلمة الناقصة بسهولة',
        'هل تبحث عن حل للكلمات المتقاطعة؟ أداة AllWordTools.com تساعدك في إيجاد الكلمات المفقودة بسرعة. أدخل الحروف المعروفة واستبدل المجهول بعلامة استفهام، ودعنا نجد الحل الأمثل لك.',
        '',
        'حل الكلمات المتقاطعة الفوري',
        'أداة سهلة وسريعة لمساعدتك في إيجاد الكلمات المفقودة في أي لغز',
        '["هل وجدت نفسك عالقاً في لعبة كلمات متقاطعة أو لغز كلمات ولم تستطع إيجاد الكلمة الصحيحة؟ لا تقلق، فأداة حل الكلمات المتقاطعة من AllWordTools.com هي رفيقك المثالي لتجاوز هذه التحديات. سواء كانت كلمة واحدة ناقصة أو سلسلة من الحروف المبعثرة، فإن أداتنا مصممة لمساعدتك على استكمال ألغازك بكل سهولة ويسر.","تعتمد أداتنا على قاعدة بيانات ضخمة من الكلمات العربية، مما يضمن لك العثور على الإجابات الصحيحة. كل ما عليك فعله هو إدخال الحروف التي تعرفها واستبدال المربعات الفارغة بعلامات استفهام. في غضون ثوانٍ قليلة، ستحصل على قائمة بالكلمات المحتملة التي تتناسب مع النمط الذي أدخلته، مما يحوّل اللغز المحير إلى حلول واضحة في متناول يدك."]',
        'كيفية استخدام أداة حل الكلمات المتقاطعة',
        '[{"title":"عدّ المربعات الفارغة","detail":"احسب عدد الحروف التي يجب أن تكون في الكلمة، بما في ذلك الحروف التي تعرفها بالفعل."},{"title":"أدخل النمط الخاص بك","detail":"اكتب الحروف التي تعرفها في مواقعها الصحيحة، واستخدم علامة الاستفهام (?)، أو الشرطة السفلية (_)، أو النقطة (.) لكل مربع فارغ. مثال: إذا كنت تبحث عن كلمة \"كتاب\" وتعرف أول حرفين، اكتب \"كـت??\"."},{"title":"اضغط على \"حل\" (Solve)","detail":"فور الضغط على الزر، ستعرض الأداة جميع الكلمات من القاموس التي تتطابق تمامًا مع النمط الذي أدخلته."},{"title":"اختر إجابتك","detail":"تصفح قائمة النتائج المرتبة حسب الاحتمالية، واضغط على أي كلمة لنسخها ولصقها في لغزك."}]',
        '[{"heading":"متى تحتاج إلى أداة حل الكلمات المتقاطعة؟","paragraphs":["أداة حل الكلمات المتقاطعة ليست فقط لمن يعشقون الألغاز المعقدة، بل هي مفيدة لكل من يواجه صعوبة في العثور على كلمة معينة في لعبة أو للتحقق من تهجئة كلمة. سواء كنت تلعب كلمات متقاطعة في الصحف العربية المحلية، مثل \"الأهرام\" أو \"الشرق الأوسط\"، أو تستخدم تطبيقات الألغاز الشهيرة على هاتفك، فإن هذه الأداة ستكون عونًا كبيرًا لك.","تخيل أنك تلعب لعبة \"كلمة السر\" أو \"وصلة\" وتوقفت عند كلمة لا يمكنك تذكرها؛ هنا تأتي فائدة أداتنا. لا تقتصر الأداة على المساعدة في الحل، بل تساهم في توسيع مفرداتك وتعزيز قدرتك على حل المشكلات اللغوية من خلال مقارنة النتائج المقترحة مع فهمك للغز."]},{"heading":"الاستخدامات الشائعة لأداتنا في العالم العربي","paragraphs":["في العالم العربي، تحظى ألعاب الكلمات والألغاز بشعبية واسعة، من \"الكلمات المتقاطعة\" التقليدية إلى \"كلمة السر\" و\"وصلة\" و\"اسم حيوان نبات جماد\". أداتنا تلبي احتياجات هذه الألعاب عن طريق تقديم قائمة محتملة من الكلمات بناءً على الحروف المعروفة والمجهولة، مما يوفر الوقت ويقلل الإحباط الذي قد ينجم عن العجز عن إيجاد حل.","بالإضافة إلى الألعاب، يمكن استخدام الأداة كمرجع لغوي سريع. إذا كنت تكتب نصًا ونسيت جزءًا من كلمة أو كنت غير متأكد من تهجئة كلمة معينة، يمكنك إدخال النمط الذي تتذكره وستساعدك الأداة في استعراض الخيارات الممكنة. إنها أداة متعددة الاستخدامات، سهلة الوصول والفهم، ومصممة خصيصًا لتلبية احتياجات المتحدثين باللغة العربية."]}]',
        '[{"input":"ك???","output":"كتاب، كبرى، كنف، كماة، كابل","note":"أدخلت ''ك'' ثم ثلاث علامات استفهام، وظهرت كلمات تبدأ بحرف الكاف وطولها أربعة أحرف."},{"input":"ب?ح?","output":"بحر، بحث، بخس، بحرص","note":"للبحث عن كلمة من أربعة أحرف بها حرف ''ب'' في البداية و ''ح'' في الموضع الثالث."},{"input":"القص??","output":"القصص، القصيدة، القصب، القصدير، القصاص","note":"مثال على بحث عن كلمة تبدأ بـ ''القص'' وتتكون من خمسة أحرف."}]',
        '["ابدأ دائمًا بالحروف التي تعرف موقعها بالضبط.","استخدم علامة الاستفهام (?)، أو الشرطة السفلية (_)، أو النقطة (.) لأي مربع فارغ – كلها تعمل بنفس الطريقة.","كلما زادت الحروف التي تعرفها، كانت النتائج أكثر دقة وأقل عددًا.","تذكر أن الأداة لا تحل الألغاز المعقدة التي تحتاج إلى فهم سياق، بل تعثر على الكلمات المطابقة للنمط فقط."]',
        '[{"question":"كيف تختلف هذه الأداة عن حلول الكلمات المتقاطعة الأخرى؟","answer":"تتميز أداتنا بسرعتها ودقتها واعتنادها على قاموس عربي شامل. كما أنها بسيطة الاستخدام ولا تتطلب أي برامج إضافية، وتعمل مباشرة من متصفحك على أي جهاز."},{"question":"ما هي الرموز التي يمكنني استخدامها للمربعات الفارغة؟","answer":"يمكنك استخدام علامة الاستفهام (؟)، أو الشرطة السفلية (_)، أو النقطة (.). جميعها تؤدي نفس الوظيفة في تمثيل حرف مجهول."},{"question":"هل يمكن لأداة حل الكلمات المتقاطعة هذه أن تحل ألغاز كلمة السر أو وصلة؟","answer":"نعم، إذا كنت تعرف بعض الحروف في الكلمة وتبحث عن باقيها، فإن الأداة ستكون مفيدة جدًا في هذه الألعاب عن طريق إدخال النمط المعروف."},{"question":"هل أداة حل الكلمات المتقاطعة مجانية؟","answer":"نعم، أداة حل الكلمات المتقاطعة من AllWordTools.com مجانية بالكامل ويمكنك استخدامها في أي وقت دون أي تكلفة."},{"question":"لماذا لا تظهر أي نتائج للنمط الذي أدخلته؟","answer":"قد يحدث هذا لعدة أسباب: ربما لا توجد كلمة في قاموسنا تتطابق تمامًا مع النمط الذي أدخلته، أو قد تكون هناك خطأ في إدخال الحروف المعروفة. تأكد من تهجئة الحروف بشكل صحيح وأن عدد علامات الاستفهام يتطابق مع عدد المربعات الفارغة."},{"question":"هل تدعم الأداة اللهجات العربية المختلفة؟","answer":"تعتمد الأداة حاليًا على اللغة العربية الفصحى بشكل أساسي. قد تجد بعض الكلمات الشائعة من اللهجات، لكن التركيز الأكبر ينصب على المفردات القياسية."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في حل ألغاز الكلمات المتقاطعة الصعبة أو الألغاز المشابهة.',
        '["حل كلمات متقاطعة","مساعد كلمات متقاطعة","حل لغز الكلمات المتقاطعة","أوجد الكلمة الناقصة","برنامج حل الكلمات","كيف أحل الكلمات المتقاطعة","موقع كلمات متقاطعة","كلمة السر حل الألغاز"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'word-finder',
        'ar',
        'Word Finder',
        'مكتشف الكلمات العربية: ابحث عن كلمات بأي حرف أو نمط',
        'ابحث عن كلمات عربية بسهولة باستخدام مكتشف الكلمات! اعثر على الكلمات الناقصة، وسّع مفرداتك، وتفوق في ألعاب الكلمات Crossword وغيرها. مجاني وسريع.',
        '',
        'مكتشف الكلمات العربية: أداة البحث المثلى عن الكلمات',
        'ابحث عن الكلمات التي تحتاجها بأي نمط أو حرف، وحسّن مهاراتك اللغوية.',
        '["هل تبحث عن كلمة معينة لا تستطيع تذكرها؟ أو ربما تحتاج إلى مساعدة في العثور على كلمات تتناسب مع نمط معين في لعبة كلمات متقاطعة أو لعبة حروف؟ مكتشف الكلمات العربية هنا ليقدم لك الحل! هذه الأداة القوية تمكنك من البحث في قاموس عربي كامل باستخدام الحروف أو الأنماط التي تعرفها، لتعثر على كل الكلمات المحتملة بسرعة ودقة.","سواء كنت تبحث عن كلمات تبدأ بحرف معين، أو تنتهي بآخر، أو تحتوي على مجموعة من الحروف، أو حتى كلمة بطول محدد، فإن مكتشف الكلمات يجمع كل هذه الفلاتر ويعرض لك النتائج الفورية. على عكس أدوات ترتيب الحروف التي تقتصر على مجموعة معينة من الأحرف، فإن مكتشف الكلمات يبحث في القاموس بأكمله، مما يجعله مثالياً لألغاز الكلمات، وتوسيع المفردات، أو حتى العثور على تلك الكلمة التي هي على طرف لسانك."]',
        'كيف تستخدم مكتشف الكلمات العربي؟',
        '[{"title":"اختر فلاتر البحث","detail":"أدخل أي مجموعة من الفلاتر مثل: ''تبدأ بـ''، ''تنتهي بـ''، ''تحتوي على''، أو ''طول الكلمة بالضبط''. يمكنك استخدام فلتر واحد أو دمج أكثر من فلتر."},{"title":"حدد حروفك المتوفرة (اختياري)","detail":"لتقييد النتائج بحروف معينة، أضف الحروف التي لديك في خانة ''باستخدام هذه الحروف فقط'' (استخدم علامة الاستفهام ؟ للأحرف المفقودة) لعرض الكلمات التي يمكنك تشكيلها فقط."},{"title":"ابحث عن الكلمات","detail":"اضغط على زر ''البحث عن كلمات'' وسيقوم المكتشف بالبحث في القاموس العربي، لتظهر لك النتائج مجمعة حسب طول الكلمة."},{"title":"انسخ ما تحتاجه","detail":"النتائج مرتبة حسب الطول والنقاط المتوقعة. اضغط على أي كلمة لنسخها فوراً واستخدامها في لعبتك أو دراستك."}]',
        '[{"heading":"أداة لا غنى عنها لمحبي ألعاب الكلمات واللغة","paragraphs":["يُعد مكتشف الكلمات أداة قوية ومجانية لكل من يشارك في ألعاب الكلمات مثل Crossword، Sudoku للكلمات، أو حتى Scrabble (سكرابل). إنه يساعدك على تجاوز العقبات والعثور على الكلمات الصعبة التي يمكن أن تكون مفتاح الفوز. يمكنك استخدامه لاستكشاف الكلمات، وتجربة تركيبات مختلفة، وتوسيع معرفتك بالمفردات العربية.","كما أنه مصدر ممتاز لطلاب اللغة العربية والمهتمين بتعلم كلمات جديدة. بدلاً من البحث العشوائي، يمكنك استهداف كلمات بأنماط معينة لتناسب سياق معين، مما يجعل عملية التعلم أكثر فعالية ومتعة."]},{"heading":"تطوير المفردات واكتشاف الكلمات بسهولة","paragraphs":["ليس فقط لألعاب الكلمات، بل مكتشف الكلمات هو رفيق مثالي لتطوير مفرداتك. تخيل أنك تقرأ نصًا وواجهت كلمة لا تعرف معناها، أو أنك تكتب وتود العثور على مرادف مختلف. باستخدام بعض الحروف أو النمط العام، يمكنك العثور على مجموعة واسعة من الكلمات لتثري كتاباتك ومحادثاتك.","الأداة سريعة جدًا وتعمل مباشرة في متصفحك على أي جهاز، مما يعني أن المساعدة في متناول يدك دائمًا، سواء كنت في المنزل أو في الخارج. ابدأ باستخدام مكتشف الكلمات اليوم واكتشف عالمًا جديدًا من الكلمات!"]}]',
        '[{"input":"تبدأ بـ: (ر) ، وتنتهي بـ: (ح)","output":"روح، راح، ربح، رياح","note":"للعثور على كلمات تبدأ بحرف ''ر'' وتنتهي بحرف ''ح''."},{"input":"تحتوي على: (علم) ، الطول: 5","output":"عالم، أعلم، يعلم","note":"للبحث عن كلمات بطول 5 حروف وتحتوي على ''علم''."},{"input":"باستخدام هذه الحروف فقط: (ك، ت، ب، ا، م، ي، ن، ؟)","output":"كتاب، كاتب، مكتوب، مكتبة","note":"للعثور على كلمات يمكن تشكيلها من الحروف المتاحة، مع وجود حرف مجهول واحد."}]',
        '["استخدم علامة الاستفهام (؟) كحرف بدل لأي حرف مجهول في بحثك.","جرب دمج الفلاتر (مثل ''تبدأ بـ'' و ''تحتوي على'') للحصول على نتائج أكثر دقة.","إذا كنت تلعب Scrabble، أضف حروفك في خانة ''باستخدام هذه الحروف فقط''.","تذكر أن النتائج مرتبة حسب الطول والقيمة التقريبية، فابحث عن الكلمات الطويلة أولاً."]',
        '[{"question":"ما هو مكتشف الكلمات؟","answer":"مكتشف الكلمات هو أداة بحث قوية تساعدك على العثور على كلمات من القاموس العربي باستخدام الحروف، الأنماط، أو الشروط التي تحددها، مثل كلمات تبدأ بحرف معين أو تحتوي على تسلسل أحرف."},{"question":"ما الفرق بينه وبين أداة ترتيب الحروف؟","answer":"أداة ترتيب الحروف (Unscrambler) تعرض فقط الكلمات التي يمكن تشكيلها من مجموعة ثابتة من حروف معينة. أما مكتشف الكلمات فيبحث في القاموس بأكمله بناءً على الأنماط والفلاتر، ويمكنه أيضًا تقييد البحث بحروفك المتوفرة."},{"question":"هل يمكنني تقييد النتائج بحروف طاولة اللعب (Scrabble rack) الخاصة بي؟","answer":"نعم، ببساطة أدخل الحروف المتوفرة لديك في خانة ''باستخدام هذه الحروف فقط'' (مع استخدام علامة الاستفهام للحروف المجهولة) وسيعرض لك المكتشف الكلمات التي يمكن تشكيلها من تلك الحروف فقط."},{"question":"هل يمكنني دمج أكثر من فلتر بحث في وقت واحد؟","answer":"بالتأكيد! يمكنك دمج عدة فلاتر مثل ''تبدأ بـ''، ''تنتهي بـ''، ''تحتوي على''، و ''طول الكلمة'' للحصول على نتائج أكثر تحديدًا ودقة."},{"question":"هل مكتشف الكلمات مجاني؟","answer":"نعم، هذه الأداة مجانية تمامًا ويمكنك استخدامها في أي وقت ومن أي جهاز متصل بالإنترنت."},{"question":"هل الكلمات التي يقدمها المكتشف صحيحة وقابلة للاستخدام في ألعاب الكلمات؟","answer":"نعم، يعتمد المكتشف على قاموس عربي شامل لضمان أن جميع الكلمات المعروضة صحيحة وقابلة للاستخدام في معظم ألعاب الكلمات المعتمدة على اللغة العربية."}]',
        'المستخدمون يبحثون عن أداة سريعة وسهلة للعثور على كلمات عربية بناءً على حروف أو أنماط معينة لمساعدتهم في ألعاب الكلمات، حل الألغاز، أو تعلم مفردات جديدة.',
        '["مكتشف الكلمات","البحث عن كلمة","كلمات بحروف معينة","مولد كلمات عربية","مساعدة ألعاب الكلمات","كلمات متقاطعة مساعدة","كلمات تنتهي بـ","تخمين الكلمات"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'rhyming-words',
        'ar',
        'Rhyming Words',
        'مولد كلمات القافية: أوزان وقوافي فورية للشعر والأغاني',
        'ابحث عن قوافي مثالية وشبه مثالية لأغانيك أو قصائدك أو أشعارك. أداة توليد القوافي المجانية والسريعة من AllWordTools.com تساعدك على كتابة أفضل كلمات وأبيات الشعر بسهولة. ابدأ الكتابة الآن!',
        '',
        'أداة AllWordTools.com لمولد كلمات القافية',
        'اعثر على القافية المثالية لكل بيت شعر أو أغنية',
        '["هل تبحث عن القوافي المثالية لقصيدتك، أو كلمات أغنية، أو حتى نكتة؟ موقع AllWordTools.com يضع مكتبة ضخمة من الكلمات المتناسقة بين يديك. كل ما عليك فعله هو إدخال أي كلمة، وسيقوم نظامنا الذكي بعرض قائمة شاملة من الكلمات التي تتفق معها في القافية، سواء كانت قوافي تامة أو شبه تامة، منظمة حسب عدد المقاطع الصوتية لتناسب إيقاعك.","سواء كنت شاعراً مخضرماً، أو مؤلف أغاني طموح، أو محترفاً في فن الراب تبحث عن السلاسة، فإن إيجاد القافية المناسبة يمكن أن يرتقي بنصك من الجيد إلى الاستثنائي. بدلاً من قضاء ساعات في البحث عن الكلمات المناسبة في رأسك، مولد القوافي الخاص بنا ينجز المهمة في ثوانٍ. إنه مجاني، فوري، ويعمل على أي جهاز. كل ما تحتاجه هو اتصال بالإنترنت، وستبدأ في كتابة أعمالك الخالدة."]',
        'كيف تستخدم أداة مولد القافية',
        '[{"title":"اكتب كلمتك","detail":"أدخل الكلمة التي تريد إيجاد قوافي لها. عادةً ما تكون آخر كلمة في سطر شعرك أو جملتك هي الأنسب."},{"title":"ابحث عن القوافي","detail":"اضغط على زر (ابحث عن القوافي) لمشاهدة القوافي التامة وشبه التامة، مرتبة حسب عدد المقاطع الصوتية."},{"title":"اختر ما يناسب إيقاعك","detail":"اختر قافية بنفس عدد المقاطع للحفاظ على الإيقاع، أو قافية شبه تامة لمرونة أكبر في النص."},{"title":"انسخ واكتب","detail":"يمكنك النقر على أي كلمة لنسخها مباشرة إلى قصيدتك، كلمات أغنيتك، أو أي نص آخر."}]',
        '[{"heading":"القوافي في الشعر والأغاني الخليجية والعربية","paragraphs":["تعكس اللهجات العربية، وخصوصاً الخليجية والمصرية والشامية، ثراءً لغوياً يسمح بتنوع كبير في القوافي. عندما يبحث مؤلف أغاني عن قوافي لـ(يا ليل)، قد يجد كلمات مثل (جميل)، (أصيل)، (خليل)، و(نبيل)، بينما يتوقف اختيار الشاعر على المعنى والإيقاع الذي يريد إيصاله. أداة مولد القوافي توفر هذا التنوع بشكل فوري، مما يساعد المبدعين في المنطقة على إثراء محتواهم بسهولة.","القوافي ليست مجرد تشابه صوتي، بل هي جزء أساسي من هوية الأغنية والقصيدة في ثقافتنا. فكر في مدى أهمية القافية في الأغاني الشعبية أو القصائد النبطية التي تعتمد على عمق الكلمة وتأثير صوتها. مولد القوافي لدينا يساعدك على استكشاف خيارات متعددة قد لا تخطر ببالك لتجعل أعمالك أكثر تأثيراً وجمالاً، سواء كنت تكتب أغنية رومانسية أو قصيدة حماسية."]},{"heading":"أكثر من مجرد قافية: الإيقاع والوزن","paragraphs":["نجاح أي عمل فني يعتمد بشكل كبير على الإيقاع والوزن، أو ما يُعرف في الشعر العربي بـ (البحر). من خلال تنظيم القوافي حسب عدد المقاطع الصوتية، تتيح لك أداة AllWordTools.com الحفاظ على الوزن الشعري أو الموسيقي. على سبيل المثال، إذا كانت كلمتك الأخيرة تتكون من مقطعين، فستجد قوافي أخرى تتكون من مقطعين أيضاً، مما يضمن تدفقاً سلساً لعملك الفني.","لا تقلق إذا لم تكن خبيراً في علم العروض؛ هدفنا هو تبسيط عملية البحث عن القافية، لتتمكن من التركيز على رسالتك الفنية. سواء كنت تكتب لأطفال أو للكبار، في أغنية بوب سريعة أو قصيدة كلاسيكية عميقة، فإن تنظيم القوافي بهذه الطريقة يوفر لك مرونة لا مثيل لها لتختار الكلمات التي لا تتطابق صوتياً فحسب، بل تتوافق أيضاً مع إيقاع ومعنى عملك ككل."]}]',
        '[{"input":"كتاب","output":"باب، تراب، حساب، عتاب، ركاب","note":"قوافي تامة مع نفس عدد المقاطع الصوتية (٢)."},{"input":"شمس","output":"همس، لمس، أمس، درس (قافية شبه تامة)","note":"تظهر الكلمات التي تتشابه في الصوت جزئياً، مثل ''درس'' التي تبدو متناسقة رغم اختلاف بسيط في المخرج."},{"input":"قمر","output":"سفر، مطر، عبر، زهر، قدر","note":"تتضمن الكلمات التي تتشابه في نهاياتها الصوتية، مع حفظ الوزن (مقطعين)."}]',
        '["استخدم أداة مولد القوافي للبحث عن كلمات لأغاني الراب والقصائد الحماسية.","جرّب القوافي شبه التامة لإضفاء شعور أكثر ارتخاءً وإبداعاً على نصك.","ابدأ بآخر كلمة في السطر الذي تكتبه للحصول على أفضل النتائج.","استغل ميزة تنظيم القوافي حسب عدد المقاطع للحفاظ على الإيقاع والوزن في شعرك."]',
        '[{"question":"ما الفرق بين القافية التامة والقافية شبه التامة؟","answer":"القافية التامة هي الكلمات التي لها نفس الصوت بالضبط في المقطع الأخير، مثل ''جميل'' و''خليل''. أما القافية شبه التامة فهي الكلمات التي تتشابه في الصوت ولكن ليس تماماً، مثل ''شمس'' و''همس''، وتستخدم لإضفاء مرونة وتنوع على النص."},{"question":"لماذا يتم تجميع القوافي حسب عدد المقاطع الصوتية؟","answer":"يساعد هذا التجميع في الحفاظ على الإيقاع والوزن الشعري أو الموسيقي، وهو أمر بالغ الأهمية في الشعر الغنائي أو القصائد. عندما تختار كلمات بنفس عدد المقاطع، فإنها تتدفق بشكل أكثر طبيعية وتناغم."},{"question":"هل أداة مولد القوافي مجانية؟","answer":"نعم، أداة مولد القوافي من AllWordTools.com مجانية تماماً، ولا تتطلب أي تسجيل دخول أو اشتراك. يمكنك استخدامها بلا حدود لأي من مشاريعك الإبداعية."},{"question":"لماذا لم تعد كلمتي بأي قوافي؟","answer":"قد يحدث هذا لعدة أسباب: قد تكون الكلمة نادرة جداً، أو كلمة أجنبية، أو كلمة فريدة ليس لها قوافي صوتية واضحة في اللغة العربية. جرب البحث عن كلمة مرادفة أو كلمة مختلفة ذات صلة لمعرفة المزيد من الخيارات."},{"question":"هل يمكن لهذه الأداة أن تساعد في كتابة الأغاني والشعر؟","answer":"بالتأكيد! هذه الأداة مصممة خصيصاً لمساعدة الشعراء ومؤلفي الأغاني وكتّاب الراب على إيجاد القوافي بسرعة وفعالية. ستلهمك لاكتشاف كلمات وخيارات ربما لم تفكر بها، مما يثري أعمالك الفنية."},{"question":"هل تعمل الأداة على جميع الأجهزة؟","answer":"نعم، أداة مولد القوافي صممت لتعمل بسلاسة على أي جهاز متصل بالإنترنت، سواء كان حاسوباً، أو هاتفاً ذكياً، أو جهازاً لوحياً. الواجهة متجاوبة وسهلة الاستخدام على جميع الشاشات."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في العثور على كلمات قافية لموسيقاهم أو شعرهم أو كتاباتهم الإبداعية.',
        '["مولد قوافي","كلمات قافية","موقع قوافي","معجم القوافي","كلمات لها نفس القافية","توليد قوافي للشعر","أداة البحث عن القافية","كيف أجد كلمات قافية"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'synonym-finder',
        'ar',
        'Synonym Finder',
        'مرادفات الكلمات: بحث فوري عن المرادفات | AllWordTools',
        'اكتشف مرادفات وكلمات بديلة لأي كلمة فوراً. حسن كتاباتك ووسع مفرداتك مجاناً وبدون تسجيل. أداة استبدال الكلمات الأفضل.',
        '',
        'أداة إيجاد مرادفات الكلمات العربية',
        'جد بدائل مبتكرة لأي كلمة في لحظات، وحسّن أسلوب كتابتك',
        '["هل مللت من تكرار نفس الكلمات مراراً وتكراراً في كتاباتك؟ هل تبحث عن طريقة لتجعل نصوصك أكثر جاذبية وتنوعاً؟ أداة مرادفات AllWordTools.com هي بوابتك لعالم من البدائل اللغوية الغنية. بضغطة زر واحدة، نقدم لك عشرات المرادفات والكلمات ذات الصلة، لتجد الكلمة الأنسب التي تعبر عن فكرتك بالضبط وتضفي على كتاباتك رونقاً خاصاً.","تعتبر قوة الكلمة هي أساس أي نص مؤثر. باستبدال كلمة عادية أو مستهلكة بمرادف دقيق ومنعش، يمكنك تغيير نبرة الجملة بالكامل، أو تعزيز حجتك، أو إضفاء حيوية على وصفك. سواء كنت تكتب مقالاً جامعياً، تعد رسالة بريد إلكتروني، تبتكر قصة، أو حتى تحل ألغاز الكلمات، فإن هذه الأداة تجعل عملية البحث عن الكلمات البديلة سهلة ومباشرة. إنها سريعة، مجانية، وتعمل على الفور في متصفحك ومن أي جهاز –無需 تسجيل أو قيود."]',
        'كيف تستخدم أداة المرادفات الخطوة بخطوة؟',
        '[{"title":"اكتب الكلمة","detail":"أدخل الكلمة التي تريد مرادفاتها. الكلمات المفردة تعمل بشكل أفضل."},{"title":"ابحث عن المرادفات","detail":"اضغط على زر ‹‹ابحث عن المرادفات›› وستظهر لك قائمة فورية مصنفة لأقرب المرادفات والكلمات ذات الصلة."},{"title":"استعرض النتائج","detail":"ستجد المرادفات الأكثر شيوعاً والأقرب معنى في البداية لمساعدتك على الاختيار الأفضل بسرعة."},{"title":"انسخ والصق","detail":"اضغط على أي كلمة لنسخها فوراً، ثم الصقها مباشرة في وثيقتك أو أي مكان تريده."}]',
        '[{"heading":"لماذا أداة البحث عن المرادفات ضرورية لك؟","paragraphs":["في عالمنا العربي، الذي يتسم بثراء لغوي فريد، يواجه الكثيرون تحدي التعبير عن أفكارهم بدقة وتجنب التكرار الممل. سواء كنت طالباً، كاتباً محترفاً، أو حتى شخصاً يرغب في تحسين مهاراته اللغوية، فإن هذه الأداة تقدم لك الحل الأمثل. ستساعدك على توسيع مفرداتك، واكتشاف أبعاد جديدة للكلمات، وترك انطباع أقوى لدى القراء. تخيل أنك تكتب عن الجمال، وبدلاً من تكرار كلمة ''جميل'' عشرات المرات، يمكنك استخدام ''فاتن''، ''خلاب''، ''باهر''، ''سماوي'' والمزيد لتصف الصورة بألوان مختلفة.","تجاوز مجرد المعاني الأساسية للكلمات واكتشف الدرجات الدقيقة والمختلفة للتعبير. هذه الأداة لا تقتصر على إيجاد البدائل فحسب، بل تساعدك أيضاً على فهم السياقات المختلفة التي يمكن للكلمات أن تستخدم فيها. إنها رفيقك الأمثل لإنتاج محتوى عربي أصيل، جذاب، ومتنوع، يحافظ على اهتمام القارئ وينقل رسالتك بوضوح وتأثير أكبر."]},{"heading":"استخدامات عملية لأداة المرادفات في حياتك اليومية","paragraphs":["سواء كنت تكتب تقريراً للعمل، أو رسالة إلكترونية رسمية، أو حتى منشوراً على وسائل التواصل الاجتماعي، فإن اختيار الكلمات المناسبة يمكن أن يحدث فرقاً كبيراً. هذه الأداة مفيدة للغاية للطلاب عند كتابة البحوث والمقالات لإثراء لغتهم الأكاديمية وتجنب السرقات الأدبية غير المقصودة. كما أنها لا تقدر بثمن للمدونين والكتّاب الذين يسعون لإنتاج محتوى عربي جذاب ومحَسَّن لمحركات البحث (SEO) من خلال استخدام مفردات متنوعة.","بالإضافة إلى ذلك، يمكن لمستخدمي ألعاب الكلمات والألغاز مثل ''الكلمات المتقاطعة'' أو ''وصلة'' الاستفادة من هذه الأداة لإيجاد الكلمات التي تناسب الأبعاد المطلوبة أو لفك شيفرات الألغاز الصعبة. إنها أداة مرنة ومتعددة الاستخدامات، مصممة لتلبية احتياجات الناطقين باللغة العربية في مختلف المجالات، وتمنحك القوة لإتقان فن اختيار الكلمات."]}]',
        '[{"input":"كبير","output":"ضخم، جليل، عظيم، واسع، هائل، فسيح","note":"لإيجاد مرادفات للكلمة الشائعة ''كبير'' وتوسيع الخيارات."},{"input":"جميل","output":"حسن، بهي، فاتن، رائع، جذاب، أنيق","note":"اختيار بدائل أكثر دقة للتعبير عن درجات الجمال المختلفة."},{"input":"سريع","output":"عاجل، فوري، خاطف، مسرع، عجول، رشيق","note":"تغيير إيقاع الجملة باستخدام مرادفات تعبر عن السرعة بطرق متنوعة."}]',
        '["اختر المرادف الذي يناسب سياق جملتك تماماً.","لا تفرط في استخدام الكلمات الصعبة، حافظ على وضوح المعنى.","استخدم المرادفات لتجنب التكرار وجعل نصك أكثر انسيابية.","جرّب كلمات مختلفة لترك انطباع أقوى وأكثر تميزاً."]',
        '[{"question":"ما هي أداة البحث عن المرادفات؟","answer":"هي أداة رقمية تساعدك في العثور على كلمات بديلة (مرادفات) لكلمة معينة. غرضها الأساسي هو إثراء مفرداتك، تجنب تكرار الكلمات، وتحسين جودة أسلوبك الكتابي."},{"question":"هل أداة المرادفات هذه مجانية؟","answer":"نعم، أداة إيجاد المرادفات من AllWordTools.com مجانية تماماً وبدون أي قيود على الاستخدام أو الحاجة للتسجيل. يمكنك استخدامها متى شئت وأينما كنت."},{"question":"لماذا تعطي بعض الكلمات مرادفات أكثر من غيرها؟","answer":"عدد المرادفات يعتمد على طبيعة الكلمة نفسها ومدى شيوعها واستخداماتها المتعددة في اللغة العربية. الكلمات الشائعة وذات المعاني الواسعة عادة ما يكون لها مرادفات أكثر من الكلمات المتخصصة أو قليلة الاستخدام."},{"question":"هل المرادفات المعروضة مرتبة؟","answer":"نعم، عادة ما يتم ترتيب النتائج بحيث تظهر أقرب المرادفات وأكثرها شيوعاً واستخداماً في اللغة العربية أولاً، لتسهيل عملية الاختيار عليك."},{"question":"هل يمكنني استخدام هذه الأداة للغات أخرى غير العربية؟","answer":"في الوقت الحالي، هذه الأداة مصممة خصيصاً للغة العربية. نحن نعمل على تطوير أدوات مشابهة للغات أخرى في المستقبل."},{"question":"كيف أختار المرادف الأنسب من بين الخيارات الكثيرة؟","answer":"أفضل طريقة هي قراءة الجملة التي تريد استبدال الكلمة فيها، ثم تجربة المرادفات المختلفة. اختر الكلمة التي تحافظ على المعنى الأصلي وتتناغم مع سياق الجملة الأسلوبي."}]',
        'يبحث المستخدمون عن كلمات بديلة أو مرادفات لتحسين كتاباتهم وتفادي التكرار.',
        '["مرادفات الكلمات","قاموس المرادفات عربي","البحث عن مرادف كلمة","بديل الكلمات","مترادفات فورية","تحسين المفردات العربية","تغيير الكلمات في النص","أداة توليد مرادفات"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'antonym-finder',
        'ar',
        'Antonym Finder',
        'مضادات الكلمات: أداة البحث عن عكس الكلمات العربية',
        'اكتشف عكس أي كلمة عربية فوراً. عزز كتاباتك ودقق معاني كلماتك بتحديد الأضداد بدقة. مجانية وسريعة وعلى كل الأجهزة.',
        '',
        'محدد الأضداد: اعثر على عكس أي كلمة عربية فوراً',
        'أضف التباين والوضوح لكتاباتك بسهولة ودقة متناهية',
        '["في رحلتنا اللغوية، تبرز أهمية امتلاك مفردات غنية ومتنوعة. لكن الجمال الحقيقي يكمن في القدرة على استخدام هذه المفردات بذكاء، لإضافة عمق ووضوح لأفكارنا. هنا يأتي دور أداة \"محدد الأضداد\"، بوابتك لاكتشاف الكلمات وعكسها، مما يمنحك قدرة فائقة على صياغة الجمل وإبراز المعاني بأدق الطرق.","سواء كنت كاتباً، طالباً، أو ببساطة محباً للغة العربية وتسعى لتعزيز قدراتك التعبيرية، فإن هذه الأداة مصممة لخدمتك. بلمسة زر، ستتمكن من استكشاف الأضداد الأكثر ملائمة لكلمتك، مما يمكنك من بناء تباينات قوية، وتوضيح المفاهيم، وتقديم حجج متينة. إنها مجانية، سريعة، ومتاحة لك في أي وقت ومن أي جهاز."]',
        'كيف تستخدم محدد الأضداد؟',
        '[{"title":"اكتب الكلمة","detail":"أدخل الكلمة التي تبحث عن عكسها. للحصول على أفضل النتائج، يفضل إدخال كلمة مفردة."},{"title":"ابحث عن الأضداد","detail":"اضغط على زر \"ابحث عن الأضداد\" وستظهر لك جميع الكلمات المعاكسة المباشرة التي وجدناها فوراً."},{"title":"اختر الضد المناسب","detail":"قد يكون لبعض الكلمات عدة أضداد بتدرجات مختلفة. اختر الضد الذي يناسب سياق جملتك بدقة."},{"title":"انسخ والصق","detail":"اضغط على أي كلمة لنسخها بسهولة ولصقها في مستندك."}]',
        '[{"heading":"لماذا أضداد الكلمات مهمة في الكتابة والتعلم؟","paragraphs":["يُعد إتقان استخدام أضداد الكلمات مهارة أساسية لأي شخص يرغب في الارتقاء بمستواه اللغوي. فبالإضافة إلى إثراء المفردات، تساعد الأضداد في بناء مقارنات قوية وإبراز التباينات. على سبيل المثال، بدلاً من وصف شيء بـ\"ليس قوياً\" يمكنك القول \"ضعيف\"، مما يضفي دقة ووضوحاً أكبر على المعنى.","كما أن معرفة الأضداد تعمق الفهم الحقيقي للكلمات نفسها. عندما نعرف ما هي الكلمة وما هي ليست، ندرك جوهر معناها بشكل أفضل. هذا يساعد في صياغة الحجج بوضوح، وكتابة أوصاف حية، وصياغة مقارنات لا تُنسى، سواء في المقالات الأكاديمية أو في التدوينات اليومية."]},{"heading":"محدد الأضداد: أداة مجانية وسهلة الاستخدام في متناول يدك","paragraphs":["نحن نؤمن بأن المعرفة اللغوية يجب أن تكون متاحة للجميع بدون عوائق. لهذا السبب، صممنا أداة محدد الأضداد لتكون مجانية بالكامل، لا تتطلب أي تسجيل أو اشتراكات. كل ما تحتاجه هو الاتصال بالإنترنت، ويمكنك البدء في البحث عن الأضداد من خلال متصفحك المفضل، سواء كنت تستخدم هاتفاً ذكياً، جهازاً لوحياً، أو حاسوباً مكتبياً.","الواجهة البسيطة والبديهية تضمن تجربة مستخدم سلسة، حيث تركز على تقديم النتائج التي تحتاجها بأسرع وقت ممكن. لا توجد حدود لعدد عمليات البحث التي يمكنك إجراؤها، مما يجعلها الرفيق المثالي لطلاب اللغة، الكتاب، المترجمين، أو أي شخص يسعى لتحسين لغته العربية."]}]',
        '[{"input":"خير","output":"شر، مضر، سوء","note":"تتعدد أضداد الكلمة حسب السياق، وهنا أبرزها."},{"input":"كبير","output":"صغير، ضئيل، قزم","note":"توضح الخيارات المتعددة لدقة الوصف."},{"input":"جميل","output":"قبيح، بشع، سيء المنظر","note":"تظهر أضداداً مختلفة للمعنى العام والوصفي."}]',
        '["استخدم كلمة مفردة للحصول على أفضل النتائج.","انتبه لسياق الجملة عند اختيار الضد المناسب.","الأضداد المجازية أحياناً تكون أقوى تعبيراً.","جرب كلمات مختلفة لتوسيع قاموسك اللغوي."]',
        '[{"question":"ما هو محدد الأضداد؟","answer":"محدد الأضداد هو أداة شبكية تساعدك على الفور في العثور على الكلمة المقابلة أو المعاكسة لأي كلمة تدخلها، مما يساعد في تعزيز كتاباتك وفهمك للمفردات."},{"question":"لماذا لا توجد أضداد لبعض الكلمات؟","answer":"ليست كل الكلمات في اللغة العربية لها ضد مباشر ومفهوم. فبعض الكلمات قد تكون محددة جداً أو لا يوجد لها مفهوم معاكس تماماً مثل بعض الأسماء العلم أو الكلمات ذات المعنى المطلق."},{"question":"هل أداة محدد الأضداد مجانية؟","answer":"نعم، الأداة مجانية بالكامل ولا تتطلب أي تسجيل أو دفع لاستخدام جميع ميزاتها. يمكنك البحث عن العدد الذي تريده من الأضداد."},{"question":"كيف يتم ترتيب نتائج الأضداد؟","answer":"ترتب النتائج عادةً حسب قوة الارتباط والمعنى الأكثر شيوعاً كضد مباشر للكلمة التي أدخلتها، مع محاولة عرض الخيارات الأكثر وضوحاً أولاً."},{"question":"هل يمكن البحث عن أضداد العبارات؟","answer":"أداة محدد الأضداد مصممة للبحث عن أضداد الكلمات المفردة. لإيجاد عكس عبارة، يُفضل البحث عن ضد كل كلمة على حدة ثم إعادة تركيب المعنى."},{"question":"هل تعمل الأداة على جميع الأجهزة؟","answer":"نعم، الأداة تعمل في متصفح الويب الخاص بك على أي جهاز، سواء كان جوالاً، حاسوباً لوحياً، أو حاسوباً مكتبياً، مما يوفر لك المرونة في استخدامها أينما كنت."}]',
        'يبحث المستخدمون العرب عن وسيلة سريعة وسهلة لإيجاد الكلمات وعكسها لتحسين كتاباتهم أو فهم معاني الكلمات.',
        '["بحث عن مضاد كلمة","عكس الكلمات العربية","مرادفات وأضداد","قاموس عكس الكلمات","معرفة ضد الكلمة","بحث كلمات متضادة","كيف أجد عكس الكلمات","أداة أضداد الكلمات"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'words-starting-with',
        'ar',
        'Words Starting With',
        'كلمات تبدأ بـ... أداة بحث سريعة لـ سكرابل والألعاب',
        'اعثر على الكلمات التي تبدأ بحروف معينة لـ سكرابل، كلمات متقاطعة، وتنمية المفردات. أداة سريعة ومجانية ودقيقة باللغة العربية.',
        '',
        'أداة إيجاد كلمات تبدأ بحروف معينة',
        'اعثر على الكلمات التي تحتاجها في ثوانٍ، لأي لعبة أو مهمة كتابة!',
        '["هل تبحث عن الكلمة المثالية لتبدأ بها دورك في لعبة سكرابل أو كلمات الأصدقاء؟ هل تحتاج إلى قائمة بجميع الكلمات التي تبدأ بحروف معينة لحل الكلمات المتقاطعة، أو لتوليد أفكار لمشروع إبداعي؟ أداة \"كلمات تبدأ بـ\" من AllWordTools.com هي الحل الأم الأمثل لك.","تُمكنك هذه الأداة البديهية من إدخال مجموعة من الحروف لتعرض لك على الفور قائمة شاملة بجميع الكلمات المتاحة في القاموس والتي تبدأ بهذه الحروف، مرتبة حسب الطول لتسهيل العثور على ما تبحث عنه. سواء كنت ترغب في توسيع مفرداتك، أو بحاجة إلى مساعدة في لعبة كلمات، أو حتى تبحث عن أسماء، فإن هذه الأداة المجانية والسريعة والخاصة تمامًا هي رفيقك المثالي. لا يلزم الاشتراك أو التسجيل، وكل عمليات البحث تتم في متصفحك بشكل آمن وسريع."]',
        'كيفية استخدام أداة "كلمات تبدأ بـ"',
        '[{"title":"أدخل حروف البداية","detail":"اكتب الحروف التي تريد أن تبدأ بها الكلمة، حرف واحد أو عدة حروف."},{"title":"حدد الطول (اختياري)","detail":"اختر طولًا دقيقًا للكلمة لتضييق النتائج، أو اترك الخيار على \"أي طول\"."},{"title":"ابحث عن الكلمات","detail":"اضغط على زر \"ابحث عن الكلمات\" للبحث في القاموس الكامل وعرض جميع النتائج مجمعة حسب الطول."},{"title":"انسخ ما تحتاجه","detail":"انقر على أي كلمة لنسخها فورًا، مع عرض نقاطها في سكرابل بجانبها."}]',
        '[{"heading":"مساعدك الأمثل في ألعاب الكلمات","paragraphs":["لكل عشاق سكرابل (Scrabble) وكلمات الأصدقاء (Words With Friends)، تقدم هذه الأداة ميزة لا تقدر بثمن. فكثيرًا ما تحتاج لتكوين كلمة تبدأ بحرف معين أو مجموعة حروف معينة لتربطها بكلمة موجودة على اللوحة. بدلاً من قضاء وقت طويل في التفكير، يمكنك الآن إدخال الحروف المطلوبة والحصول على قائمة بكل الاحتمالات الممكنة في لحظات.","توفر الأداة الوقت والجهد، وتساعدك على اكتشاف كلمات جديدة لربح المزيد من النقاط. كما أنها مثالية لحل الكلمات المتقاطعة؛ فإذا كنت تعرف الحروف الأولى من الكلمة المفقودة، يمكنك ببساطة إدخالها والحصول على قائمة بالحلول المحتملة، مما يجعل تحدي الكلمات المتقاطعة أكثر متعة وأقل إحباطًا."]},{"heading":"لتنمية المفردات والكتابة الإبداعية","paragraphs":["تعد أداة \"كلمات تبدأ بـ\" أكثر من مجرد مساعد للعب. إنها مورد قوي لأي شخص يسعى لتوسيع قاموسه اللغوي أو يحتاج إلى إلهام في الكتابة. إذا كنت تتعلم لغة جديدة أو ترغب في إثراء مفرداتك العربية، فإن استخدام هذه الأداة بشكل منتظم سيساعدك على اكتشاف كلمات جديدة وبناء فهم أعمق للغة.","كما أنها مفيدة جدًا للمؤلفين، الشعراء، أو أي شخص يشارك في عملية عصف ذهني. هل تبحث عن أسماء فريدة تبدأ بحرف معين؟ هل تحتاج إلى كلمات ذات بداية محددة لتضفي لمسة خاصة على قصتك أو قصيدتك؟ أدخل الحروف ودع الأداة تقدم لك خيارات لا حصر لها لتطلق العنان لإبداعك."]}]',
        '[{"input":"ابت","output":"ابتعاد، ابتداع، ابتسامة، ابتكار، ابتلاء","note":"للبحث عن كلمات تبدأ بالبادئة \"ابت\"."},{"input":"مفتاح","output":"مفتاح، مفاتيح، مفتاحات","note":"للبحث عن كلمات تبدأ بـ \"مفتاح\"."},{"input":"كتاب","output":"كتاب، كتابة، كتابه، كتابات","note":"للبحث عن الكلمات التي تبدأ بـ \"كتاب\"."}]',
        '["ابدأ بحرف واحد أو اثنين للحصول على قائمة واسعة من الكلمات.","استخدم خيار تحديد الطول لتضييق النتائج إذا كنت تبحث عن كلمة ذات طول معين.","الكلمات مرتبة حسب الطول، لذا انتبه دائمًا للمجموعات ذات الأطوال المختلفة.","انقر على أي كلمة لنسخها بسهولة وقم بالصقها حيثما تريد."]',
        '[{"question":"كيف أجد الكلمات التي تبدأ بحروف معينة؟","answer":"ما عليك سوى إدخال الحروف التي تريد أن تبدأ بها الكلمة في مربع البحث والضغط على زر ''ابحث عن الكلمات''. ستظهر لك جميع الكلمات المطابقة."},{"question":"هل يمكنني تحديد طول الكلمات الناتجة؟","answer":"نعم، يمكنك اختيار طول معين للكلمة من قائمة ''تحديد الطول'' لفلترة النتائج والحصول على الكلمات التي تطابق هذا الطول فقط."},{"question":"هل هذه الكلمات صالحة لألعاب مثل سكرابل وكلمات الأصدقاء؟","answer":"بالتأكيد، الكلمات المعروضة مأخوذة من قاموس شامل وتصلح الاستخدام في معظم ألعاب الكلمات الشائعة مثل سكرابل."},{"question":"هل هناك حد لعدد عمليات البحث؟","answer":"لا يوجد حد لعدد عمليات البحث. يمكنك استخدام الأداة بقدر ما تشاء، مجانًا وبدون قيود."},{"question":"هل يتم حفظ بحثي أو بياناتي الشخصية؟","answer":"لا، خصوصيتك تامة. جميع عمليات البحث تتم محليًا في متصفحك ولا يتم تخزين أي بيانات شخصية أو سجلات بحث."},{"question":"ماذا لو لم أجد الكلمة التي أبحث عنها؟","answer":"تأكد من كتابة الحروف بشكل صحيح. إذا كنت تبحث عن كلمة معينة ولم تظهر في النتائج، فمن المحتمل أنها غير موجودة في القاموس الذي نعتمد عليه، أو قد تكون تهجئتها مختلفة."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في العثور على الكلمات التي تبدأ بحروف معينة، خاصة لألعاب الكلمات مثل سكرابل أو لمشاريع الكتابة.',
        '["كلمات تبدأ بـ","كلمات سكرابل تبدأ بـ","البحث عن كلمات تبدأ بـ","مولد كلمات تبدأ بـ","كلمات متقاطعة تبدأ بـ","إيجاد كلمات بحروف معينة","مفردات تبدأ بـ","أداة البحث عن كلمات"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'words-ending-with',
        'ar',
        'Words Ending With',
        'كلمات تنتهي بـ البحث عن كلمات حسب الحرف الأخير - أداة قواميس',
        'اعثر على الكلمات التي تنتهي بأي مجموعة حروف أو لاحقة بسهولة. مثالية للألغاز، الشعر، ألعاب الكلمات مثل سكرابل وكلمات كراش. سريعة، مجانية ولا تتطلب تسجيل.',
        '',
        'البحث عن كلمات تنتهي بـ',
        'أداة ذكية للعثور على الكلمات حسب الحروف النهائية',
        '["هل تبحث عن كلمة تنتهي بحرف أو مجموعة حروف معينة؟ سواء كنت تحاول حل لغز الكلمات المتقاطعة، تكتب قصيدة وتحتاج لقافية، أو تلعب لعبة كلمات مثل سكرابل أو كلمات كراش، أداة \"كلمات تنتهي بـ\" المتطورة لدينا هي الحل الأمثل لك. بدلًا من البحث التقليدي عن الكلمات التي تبدأ بحرف معين، تتيح لك هذه الأداة الفريدة البحث عن الكلمات بناءً على نهايتها.","فقط أدخل اللاحقة أو الحروف النهائية التي تريدها، وستقدم لك الأداة قائمة شاملة بجميع الكلمات المطابقة في قاموسنا، مرتبة حسب الطول لتسهيل الاختيار. لا داعي للتخمين أو إضاعة الوقت في البحث اليدوي؛ هذه الأداة سريعة ومجانية وتعمل مباشرة في متصفحك دون الحاجة للتسجيل أو مشاركة أي بيانات شخصية."]',
        'كيفية استخدام أداة البحث عن كلمات',
        '[{"title":"أدخل الحروف النهائية","detail":"اكتب الحرف أو مجموعة الحروف التي تريد أن تنتهي بها الكلمات (مثال: \"ة\", \"ال\", \"ون\")."},{"title":"حدد الطول (اختياري)","detail":"اختر طولًا محددًا للكلمات لتضييق نطاق النتائج، أو اتركها على \"أي طول\" للحصول على قائمة كاملة."},{"title":"ابحث عن الكلمات","detail":"اضغط على زر \"ابحث عن الكلمات\" لترى النتائج مرتبة حسب طول الكلمة."},{"title":"انسخ ما تحتاجه","detail":"اضغط على أي كلمة لنسخها فورًا. (عرض النقاط في ألعاب الكلمات قريبًا!)"}]',
        '[{"heading":"متى تكون هذه الأداة مفيدة لك؟","paragraphs":["أداة \"البحث عن كلمات تنتهي بـ\" لا غنى عنها في العديد من المواقف. إنها المنقذ المثالي لعشاق ألعاب الكلمات مثل الكلمات المتقاطعة، كلمات مكتشفة، أو ألعاب الألغاز التي تتطلب منك إيجاد كلمة تكمل نهاية معينة. عندما تكون لديك الحروف الأخيرة فقط من الكلمة المفقودة، يمكن لهذه الأداة أن توفر لك قائمة من الاحتمالات لتختار منها الكلمة الصحيحة.","علاوة على ذلك، تعد الأداة رفيقًا ممتازًا للكتاب والشعراء. إنها تبسط عملية إيجاد القوافي والكلمات المتجانسة، مما يساعدك على إثراء نصوصك ومقالاتك. كما أنها مفيدة لمتعلمي اللغة العربية الذين يرغبون في استكشاف عائلات الكلمات التي تشترك في نفس النهاية، مما يعزز من مفرداتهم."]},{"heading":"أداة سريعة، شاملة، ومجانية تمامًا","paragraphs":["تعتمد أداة \"كلمات تنتهي بـ\" على قاعدة بيانات ضخمة وشاملة من الكلمات العربية، مما يضمن لك الحصول على أوسع نطاق من النتائج الممكنة. نؤمن بأن الوصول إلى أدوات مساعدة اللغة يجب أن يكون متاحًا للجميع، ولهذا السبب نقدم هذه الخدمة مجانًا بالكامل.","تم تصميم الأداة لتكون سهلة الاستخدام وسريعة الاستجابة. لا مزيد من الانتظار أو الإعلانات المزعجة؛ فقط نتائج فورية ومرتبة بدقة تساعدك على تحقيق هدفك بأسرع وقت ممكن. ابدأ البحث الآن واستمتع بتجربة سلسة وفعالة للعثور على الكلمات التي تحتاجها!"]}]',
        '[{"input":"ون","output":"يذهبون، يعلمون، يلعبون، متفهمون، يركضون","note":"لإيجاد أفعال أو أسماء جمع تنتهي بالواو والنون."},{"input":"ال","output":"جمال، رجال، سؤال، مثال، أفعال، أقوال","note":"للبحث عن كلمات تنتهي بألف ولام مثل أسماء أو جموع معينة."},{"input":"ة","output":"كبيرة، صغيرة، جميلة، مدرسة، مكتبة","note":"للعثور على كلمات مؤنثة أو أسماء تنتهي بالتاء المربوطة."}]',
        '["ابدأ بحروف نهائية قصيرة للحصول على نتائج أوسع، ثم ضيق البحث.","استخدم خيار الطول لتحديد عدد أحرف الكلمة المطلوبة بالضبط.","إذا لم تجد الكلمة، جرب تهجئات مختلفة للحروف النهائية أو ابحث عن مرادفات.","استخدمها لمراجعة نهايات الكلمات المتشابهة لتجنب الأخطاء الإملائية."]',
        '[{"question":"كيف تختلف هذه الأداة عن قاموس البحث العادي؟","answer":"تتيح لك هذه الأداة البحث عن الكلمات بناءً على الحروف التي تنتهي بها، وليس الحروف التي تبدأ بها، مما يمنحك مرونة أكبر في حل الألغاز وإيجاد القوافي."},{"question":"هل يمكنني تحديد طول الكلمة التي أبحث عنها؟","answer":"نعم بالتأكيد! يمكنك تحديد الطول الدقيق للكلمة، أو اختيار \"أي طول\" للحصول على جميع الكلمات المطابقة."},{"question":"هل هذه الأداة مفيدة لألعاب الكلمات مثل سكرابل أو الألغاز؟","answer":"جداً! إنها مثالية لإيجاد الكلمات التي تناسب المساحات المحددة في الألغاز أو عند بناء الكلمات في ألعاب مثل سكرابل حيث قد تحتاج لربط كلمات بحروف معينة."},{"question":"هل الأداة تدعم اللغة العربية فقط؟","answer":"هذه النسخة مصممة خصيصاً للغة العربية وقواعدها وأحرفها، ولكن قد نوفر أدوات مماثلة للغات أخرى مستقبلاً."},{"question":"هل استخدام هذه الأداة مجاني؟","answer":"نعم، أداة \"كلمات تنتهي بـ\" مجانية بالكامل ومتاحة للجميع دون أي تكلفة أو اشتراك."},{"question":"هل يمكنني البحث عن كلمات تنتهي بأكثر من حرف واحد؟","answer":"نعم، يمكنك إدخال أي مجموعة من الحروف كـ \"لاحقة\" للبحث عن الكلمات التي تنتهي بها، مثل \"ون\"، \"ال\", أو \"ية\"."}]',
        'يبحث المستخدمون عن أداة للعثور على كلمات تنتهي بأحرف معينة لمساعدتهم في ألعاب الألغاز والكتابة.',
        '["كلمات تنتهي ب","بحث كلمات حسب الحرف الأخير","كلمات آخرها كذا","مفيدة لالغاز الكلمات المتقاطعة","مساعد سكرابل","قاموس نهايات الكلمات","إيجاد كلمات تنتهي بحرف","كلمات للشعر والقافية"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'words-containing',
        'ar',
        'Words Containing',
        'أداة البحث عن كلمات تحتوي حروف معينة مجاناً | AllWordTools',
        'ابحث عن كلمات تحتوي على تسلسل أحرف محدد في أي مكان بالكلمة. مثالية لألعاب الكلمات مثل سكرابل وكلمات متقاطعة، ومجانية بالكامل مع نتائج فورية.',
        '',
        'البحث عن كلمات تحتوي على حروف معينة',
        'اعثر على الكلمات التي تحوي تسلسل أحرف محدد في أي مكان بها',
        '["هل تبحث عن كلمة معينة ولكن كل ما تملكه هو بعض الحروف في منتصفها؟ أو ربما لديك مجموعة حروف وتريد معرفة الكلمات التي تظهر فيها معًا؟ أداة ''كلمات تحتوي على حروف'' من AllWordTools.com هي رفيقك المثالي. صُممت هذه الأداة لمساعدتك في ألعاب الكلمات مثل السكرابل، الكلمات المتقاطعة، أو حتى لتوسيع مفرداتك العربية.","فقط أدخل التسلسل الذي تريده، سواء كان ''الق'' أو ''اءع''، وستقوم الأداة بالبحث في القاموس عن كل كلمة تحتوي على هذه الحروف بالترتيب المدخل، بغض النظر عن موضعها في الكلمة. النتائج المنظمة حسب الطول تجعل المسح سهلاً وفعالاً. استمتع بتجربة بحث فورية، مجانية تمامًا، وتحافظ على خصوصية عمليات بحثك دون الحاجة للتسجيل."]',
        'كيف تستخدم الأداة؟',
        '[{"title":"أدخل الحروف المطلوبة","detail":"اكتب تسلسل الحروف الذي تريده أن يظهر داخل الكلمة، مثلاً ''الم'' أو ''يق''."},{"title":"اختر الطول (اختياري)","detail":"حدد طولاً معيناً لتضييق قائمة النتائج الواسعة، أو اترك الخيار على ''أي طول''."},{"title":"ابحث عن الكلمات","detail":"اضغط على زر ''البحث عن كلمات'' لتقوم الأداة بمسح القاموس وعرض كل التطابقات مجمعة حسب الطول."},{"title":"انسخ ما تحتاجه","detail":"اضغط على أي كلمة لنسخها، مع عرض نقاط سكرابل الخاصة بها للمقارنة السريعة."}]',
        '[{"heading":"ألعاب الكلمات والألغاز: أفضل استخدام للأداة","paragraphs":["لكل عشاق ألعاب الكلمات مثل السكرابل (لعبة الكلمات المتقاطعة)، الكلمات المتقاطعة، وألعاب الألغاز الأخرى، هذه الأداة لا تقدر بثمن. فبدلاً من إضاعة الوقت في محاولة استحضار كلمة تحتوي على حروف معينة موضوعة بالفعل على اللوح، يمكنك ببساطة إدخال التسلسل والحصول على قائمة بالاحتمالات. هذا يمنحك ميزة تنافسية ويساعدك على تسجيل أعلى النقاط.","تخيل أن لديك حرف ''ق'' وحرف ''ص'' في منتصف كلمة متقاطعة، أو أنك تريد التخلص من قطعة صعبة مثل ''ظ'' في السكرابل. هذه الأداة تمكنك من استكشاف الكلمات التي تحتوي على هذه التركيبات بذكاء، مما يفتح لك آفاقًا جديدة لإكمال الألغاز واللعب ببراعة أكبر. كما أنها ممتازة للمساعدة في التفكير بكلمات تحتوي على أحرف نادرة أو ذات قيمة عالية."]},{"heading":"توسيع مفرداتك واستكشاف اللغة العربية","paragraphs":["بصرف النظر عن الألعاب، تُعد هذه الأداة مصدرًا رائعًا للمتحدثين باللغة العربية والطلاب على حد سواء الذين يسعون لتوسيع معجمهم اللغوي. هل صادفت تسلسلاً حرفيًا غير عادي وأردت معرفة الكلمات التي تحتوي عليه؟ ببضع نقرات، ستجد مجموعة من الكلمات التي لم تكن لتفكر بها من قبل، مما يثري حصيلتك اللغوية.","يمكنك استخدامها لاكتشاف جذور الكلمات، أو كيف تتكون كلمات معينة من مقاطع صوتية متكررة. إنها طريقة ممتعة وتفاعلية لاستكشاف غنى اللغة العربية وتراكيبها الفريدة. الأداة تعمل في متصفحك بشكل فوري، وهي مجانية تمامًا، ولا تتطلب منك أي بيانات شخصية، مما يجعلها آمنة وسهلة الاستخدام للجميع."]}]',
        '[{"input":"الق","output":"يستقبل، استقلال، قابلية، انطلاق، الأقلام","note":"لإيجاد كلمات تحتوي على مقطع ''الق'' في أي موضع."},{"input":"اءع","output":"بائع، شائع، تداعيات، داعية، إبداع","note":"لإيجاد كلمات تحتوي على الحروف ''اءع'' متتالية."},{"input":"مخا","output":"مخاطر، مخابرات، مخارج، مخابز، مخاوف","note":"مثال على البحث عن مقطع ''مخا'' في بداية أو منتصف الكلمة."}]',
        '["ابدأ بتسلسل قصير ثم أضف حروفًا لتضييق النتائج.","استخدم خيار الطول لتحديد عدد حروف الكلمة المطلوب.","كلما كان التسلسل أطول، كانت النتائج أكثر تحديدًا.","احفظ الكلمات المفضلة لديك بالضغط عليها لنسخها بسهولة."]',
        '[{"question":"كيف أجد كلمات تحتوي على حروف معينة؟","answer":"ببساطة، اكتب تسلسل الحروف الذي تبحث عنه في مربع الإدخال، ثم اضغط على زر البحث. ستظهر لك قائمة بالكلمات التي تحتوي على هذا التسلسل."},{"question":"هل الأداة تبحث عن الحروف في أي مكان بالكلمة؟","answer":"نعم، الأداة مصممة خصيصًا للبحث عن تسلسل الحروف في أي مكان داخل الكلمة، وليس فقط في البداية أو النهاية."},{"question":"هل يمكنني تحديد طول الكلمة المطلوبة؟","answer":"بالتأكيد. يمكنك اختيار طول محدد للكلمة من قائمة الخيارات المتاحة لتضييق نطاق البحث والحصول على نتائج أكثر دقة."},{"question":"هل الأداة مفيدة لألعاب مثل سكرابل؟","answer":"جدًا! إنها أداة ممتازة لمساعدتك في العثور على كلمات تستفيد من الحروف الموجودة لديك، خاصة تلك ذات القيمة العالية أو الحروف الصعبة مثل ''ظ'' أو ''ق''."},{"question":"هل هذه الأداة مجانية للاستخدام؟","answer":"نعم، أداة البحث عن كلمات تحتوي على حروف معينة مجانية تمامًا للاستخدام ولا تتطلب أي تسجيل أو دفع."},{"question":"هل البحث يحافظ على خصوصيتي؟","answer":"نعم، جميع عمليات البحث تتم في المتصفح الخاص بك ولا يتم تخزين أي بيانات، مما يضمن خصوصيتك التامة."}]',
        'يبحث المستخدمون عن أداة سريعة ومجانية لإيجاد كلمات تحتوي على مجموعة معينة من الحروف لمساعدتهم في ألعاب الألغاز وزيادة المفردات.',
        '["بحث عن كلمات بحروف معينة","كلمات تحتوي على حروف","أداة البحث عن كلمات","مساعد سكرابل عربي","كلمات متقاطعة مساعدة","إيجاد كلمات بالمنتصف","كم كلمة فيها حرف معين","مولد كلمات من أحرف"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'letter-counter',
        'ar',
        'Letter Counter',
        'عدّاد الحروف والكلمات: أداة مجانية تحليل نصوص دقيق',
        'احسب عدد الحروف، الكلمات، المسافات، والجمل في أي نص بسهولة ودقة. أداة مجانية وفورية لتحليل النصوص العربية والإنجليزية أونلاين.',
        '',
        'عداد الحروف والكلمات عربي: أداة تحليل النصوص الفورية والدقيقة',
        'هل تحتاج لحساب عدد حروف، كلمات، أو مسافات نص ما؟ لست بحاجة للبحث أكثر!',
        '["تقدم لك أداة عداد الحروف والكلمات من AllWordTools.com تحليلًا فوريًا وشاملًا لأي نص. سواء كنت تكتب مقالًا، تغريدة، وصفًا لمنتج، أو حتى قصيدة، تمنحك هذه الأداة إحصائيات دقيقة وفورية عن عدد الحروف، الكلمات، المسافات، والجمل بمجرد لصق النص أو البدء في الكتابة. لا حاجة للضغط على أي زر؛ كل شيء يحدث في الوقت الفعلي أمام عينيك.","تتميز أداتنا بأنها تتجاوز مجرد عد الكلمات البسيط؛ فهي تقدم لك أيضًا مخططًا تفصيليًا لتكرار الحروف، يوضح بدقة عدد مرات ظهور كل حرف في نصك. هذه الميزة مفيدة جدًا للكتاب لتقييم سهولة القراءة، وللطلاب للالتزام بمتطلبات طول النصوص، وللمطورين للتحقق من حدود المدخلات، وحتى لعشاق الألغاز لدراسة توزيعات الحروف. والأهم من ذلك، أن بياناتك تبقى خاصة بالكامل ولا تغادر جهازك أبدًا، والأداة مجانية تمامًا وبلا أي قيود على الاستخدام."]',
        'كيف يعمل عداد الحروف والكلمات؟',
        '[{"title":"الصق أو اكتب نصك","detail":"أدخل أي نص في الصندوق، وستتحدث الأعداد فورًا مع كل تغيير أو إضافة."},{"title":"اقرأ الإحصائيات الحية","detail":"شاهد عدد الحروف، المسافات، الكلمات، الجمل، الفقرات والأسطر بنظرة واحدة."},{"title":"تحقق من تكرار الحروف","detail":"تصفح مخطط التكرار لترى مدى شيوع كل حرف في نصك."},{"title":"انسخ أو امسح","detail":"انسخ نصك بلمسة واحدة، أو امسح الصندوق لبدء تحليل جديد."}]',
        '[{"heading":"أداة لا غنى عنها لكل كاتب، طالب، ومحترف","paragraphs":["يواجه الكثيرون تحديات تحديد طول النصوص في سياقات مختلفة، سواء كان ذلك مقالًا جامعيًا بحد أقصى للكلمات، أو منشورًا على منصة تواصل اجتماعي بعدد حروف محدد. تساعدك أداة عداد الحروف والكلمات في الالتزام بهذه القيود بدقة، مما يوفر عليك الوقت والجهد في العد اليدوي المعرض للأخطاء.","كما أنها مثالية للمدونين ومسؤولي المحتوى الذين يسعون لتحسين محركات البحث SEO، حيث يمكنهم التأكد من أن مقالاتهم تتوافق مع متطلبات الطول المثالية. الطلاب أيضًا يستفيدون منها بشكل كبير لضمان أنهم يقدمون الواجبات بأطوالها المطلوبة دون تجاوز أو نقصان."]},{"heading":"استخدامات مبتكرة لعداد الحروف في الألغاز والألعاب","paragraphs":["بالإضافة إلى الاستخدامات الأكاديمية والمهنية، يمكن لمحبي الألغاز وألعاب الكلمات مثل ''كلمات متقاطعة'' أو ''وصلة'' الاستفادة من ميزة تكرار الحروف. فهم يستطيعون تحليل توزيع الحروف في الألغاز الشائعة أو النصوص المعطاة لاستنتاج الحروف الأكثر احتمالًا للظهور، مما يمنحهم ميزة تنافسية.","تساعد هذه الميزة أيضًا في فهم بنية اللغة العربية بشكل أعمق، حيث يمكن للمستخدمين ملاحظة الحروف الأكثر شيوعًا والأقل شيوعًا، وهو ما يعزز حدسهم اللغوي ويحسن من قدراتهم على حل الألغاز أو حتى ابتكارها."]}]',
        '[{"input":"أهلاً وسهلاً بكم في عالم الكلمات.","output":"الحروف: 20، الكلمات: 5، المسافات: 4، الجمل: 1","note":"تحليل نص عربي بسيط مع عد دقيق."},{"input":"تطوير الذات يتطلب الصبر والمثابرة لتحقيق الأهداف المنشودة. هل أنت مستعد للبدء؟\nلا تستسلم أبدًا لمجرد أن الطريق صعب.","output":"الحروف: 86، الكلمات: 19، المسافات: 17، الجمل: 3، الفقرات: 2","note":"مثال يوضح عد الجمل والفقرات بلغة عربية فصحى."},{"input":"مرحباً يا أصدقاء! 😃 ما رأيكم بهذا اليوم الجميل؟ #سعادة #تفاؤل","output":"الحروف: 35، الكلمات: 7، المسافات: 6، أحرف خاصة/رموز: 4","note":"يحتسب الرموز التعبيرية وعلامات الترقيم وأحرف الهاشتاج كأحرف."}]',
        '["استخدم الأداة للتحقق من متطلبات طول المقالات الأكاديمية أو رسائل البريد الإلكتروني.","افحص تكرار الحروف لتحليل أساليب الكتابة أو حل ألغاز الكلمات.","تأكد من عدد الحروف للمنشورات على وسائل التواصل الاجتماعي ذات الحدود الصارمة.","انسخ أي نص من الإنترنت والصقه هنا للحصول على إحصائيات سريعة وموثوقة."]',
        '[{"question":"ماذا يختلف عداد الحروف عن عداد الكلمات؟","answer":"عداد الحروف يحسب كل رمز تقوم بطباعته بما في ذلك المسافات وعلامات الترقيم والرموز، بينما عداد الكلمات يحسب فقط الكلمات الفعلية مفصولة بمسافات."},{"question":"هل الأداة تدعم اللغة العربية بشكل كامل؟","answer":"نعم، تدعم الأداة اللغة العربية وجميع اللغات الأخرى، وتقوم بحساب الحروف والكلمات والمسافات بدقة تامة للنصوص العربية."},{"question":"هل يتم تخزين أو إرسال نصوصي إلى أي مكان؟","answer":"لا، إطلاقاً. يتم معالجة جميع النصوص مباشرة في متصفحك. بياناتك لا تغادر جهازك أبدًا، مما يضمن خصوصية وأمان معلوماتك."},{"question":"ما الفرق بين ''الأحرف'' و''الحروف'' في الإحصائيات؟","answer":"الأحرف (Characters) تشمل كل رمز مكتوب (حروف، أرقام، رموز، مسافات، علامات ترقيم). أما الحروف (Letters) فتشير فقط إلى الحروف الأبجدية."},{"question":"هل هناك حد أقصى لطول النص الذي يمكنني تحليله؟","answer":"لا يوجد حد أقصى لطول النص. يمكنك لصق نصوص طويلة جدًا، وستقوم الأداة بتحليلها في الوقت الفعلي دون أي قيود."},{"question":"هل يمكنني استخدام الأداة على جوالي؟","answer":"نعم، الأداة متوافقة تمامًا مع جميع الأجهزة (كمبيوتر، تابلت، جوال) وتعمل بسلاسة عبر متصفح الويب الخاص بك."}]',
        'يبحث المستخدمون عن أداة مجانية وسريعة لحساب عدد الحروف والكلمات في النصوص العربية لمساعدتهم في الكتابة والألعاب.',
        '["عداد حروف","حساب عدد الكلمات","عد حروف وكلمات","حساب حروف النص","كم كلمة في النص","أداة عد الكلمات أونلاين","عدّاد الحروف العربية","برنامج عد كلمات مجاني"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'syllable-counter',
        'ar',
        'Syllable Counter',
        'حساب عدد المقاطع الصوتية (Syllable Counter) للشعر والكتابة',
        'عد المقاطع الصوتية بدقة في أي نص عربي أو إنجليزي. أداة مجانية وسريعة لحساب المقاطع الشعرية، تحليل صعوبة الكلمات، ومساعدة الكتّاب والشعراء.',
        '',
        'عداد المقاطع الصوتية المجاني والسريع (Syllable Counter)',
        'احسب المقاطع الصوتية لأي نص: شعر، أغاني، أو لتحسين قابلية القراءة',
        '["هل أنت شاعر تحاول إتقان وزن قصيدتك؟ هل تكتب أغاني وتحتاج لمطابقة الكلمات مع اللحن؟ أم أنك ببساطة تريد فهم بنية الكلمات وتحديد صعوبتها في القراءة؟ أداة عد المقاطع الصوتية (Syllable Counter) من AllWordTools.com هي الحل المثالي لك! إنها الأداة المجانية والسريعة التي تحلل كلماتك بدقة وتوفر لك تفاصيل دقيقة عن عدد المقاطع الصوتية.","مع هذه الأداة، لم تعد بحاجة لقضاء وقت طويل في العد اليدوي، وما يتبعه من أخطاء! ببساطة الصق أو اكتب النص الخاص بك، وسيقوم العداد بتحليل فوري يعرض لك العدد الكلي للمقاطع الصوتية، وعدد الكلمات، ومتوسط المقاطع لكل كلمة، بالإضافة إلى تفصيل لكل كلمة على حدة. كل هذا يتم في متصفحك دون إرسال بياناتك لأي خادم خارجي، مما يضمن خصوصية نصوصك."]',
        'كيف تستخدم أداة عد المقاطع الصوتية؟',
        '[{"title":"أدخل النص الخاص بك","detail":"اكتب أو الصق كلمة واحدة، جملة، أو فقرة كاملة في صندوق الإدخال."},{"title":"اقرأ الإحصائيات الفورية","detail":"ستلاحظ تحديثًا فوريًا للعدد الكلي للمقاطع، وعدد الكلمات، ومتوسط المقاطع لكل كلمة بينما تكتب."},{"title":"تفحص كل كلمة","detail":"يظهر لك التحليل المفصل عدد المقاطع الصوتية بجانب كل كلمة، لتسهيل تحديد الكلمات ذات المقاطع الكثيرة."},{"title":"عدّل وحسّن كتاباتك","detail":"استخدم الأداة لتعديل صياغتك والوصول إلى عدد مقاطع صوتية دقيق، وهو أمر مثالي للشعر، الهايكو، والأغاني."}]',
        '[{"heading":"ما هي أهمية عد المقاطع الصوتية في اللغة العربية والإنجليزية؟","paragraphs":["تعتبر المقاطع الصوتية هي أساس إيقاع اللغة ونغمتها، وهي ضرورية لفهم كيفية تكون الكلمات ونطقها الصحيح. في الشعر، يساعد عد المقاطع الصوتية الشعراء على التحكم في الأوزان والقوافي، وحتى في لغات مثل الإنجليزية، يلعب دورًا مهمًا في تحديد الوزن الشعري مثل الهايكو الذي يعتمد على نمط 5-7-5 مقاطع صوتية. أما في اللغة العربية، فبالرغم من أن مفهوم المقاطع الصوتية قد يختلف قليلاً عن اللغات الأخرى، إلا أن فهمه يساهم في تحليل البنية الصوتية للكلمات وفهم قواعد النطق وجماليات الشعر.","بالإضافة إلى الشعر، يُستخدم عد المقاطع الصوتية في تعليم اللغات لدراسة هياكل الكلمات وتحسين النطق. كما أنه أداة قيمة للمعلمين لتقييم صعوبة النصوص وقابليتها للقراءة، مما يساعد في اختيار المواد التعليمية المناسبة لمختلف المستويات. كما يستفيد من هذه الأداة كتّاب الأغاني ومؤلفو الإعلانات للحصول على إيقاع جذاب وتناسب الكلمات مع اللحن."]},{"heading":"أداة مجانية، آمنة، وفورية لتحليل النصوص","paragraphs":["نحن ندرك أهمية الخصوصية، ولهذا تم تصميم أداة عد المقاطع الصوتية لتعمل بالكامل داخل متصفحك. هذا يعني أن نصوصك لا تترك جهازك أبدًا ولا يتم إرسالها إلى أي خادم خارجي للمعالجة. يمكنك استخدامها بثقة تامة وأنت تعلم أن كتاباتك الخاصة ستبقى خاصة. لا يوجد تسجيل، لا اشتراكات، ولا قيود على الاستخدام. إنها أداة ويب بسيطة ومجانية تمامًا لتسهيل مهمتك الإبداعية أو الأكاديمية.","سواء كنت طالبًا، معلمًا، شاعرًا، كاتب أغاني، أو ببساطة مهتمًا بتحليل النصوص، فإن أداة AllWordTools.com لعد المقاطع الصوتية توفر لك الدقة والسرعة التي تحتاجها. جربها الآن وشاهد كيف يمكنها تبسيط عملك وتوفير وقتك وجهدك. هي الأداة المثالية لضبط الإيقاع والوزن في كتاباتك، سواء كانت قصيدة، أغنية، أو حتى مقالًا عاديًا."]}]',
        '[{"input":"كتاب","output":"كِ-تا-ب (3 مقاطع)","note":"مثال لكلمة عربية ثلاثية المقاطع."},{"input":"مدرسة","output":"مَدْ-رَ-سَة (3 مقاطع)","note":"تحليل المقاطع الصوتية لكلمة عربية شائعة."},{"input":"جمال","output":"جَ-مَال (2 مقطع)","note":"توضيح لكيفية تقسيم كلمة عربية إلى مقاطع."}]',
        '["استخدم الأداة لمطابقة عدد المقاطع في مقاطع الهايكو (5-7-5).","تحقق من إيقاع الشعر أو الأغاني لضمان السلاسة الموسيقية.","ساعد أطفالك على فهم بنية الكلمات وتقسيمها إلى مقاطع للنطق السليم.","حلل النصوص الطويلة لتقييم صعوبتها وقابليتها للقراءة لمستويات معينة."]',
        '[{"question":"كيف يعمل عداد المقاطع الصوتية هذا؟","answer":"تستخدم الأداة خوارزميات متقدمة لتحليل بنية الكلمات وتحديد المقاطع الصوتية بناءً على قواعد النطق والتهجئة، وتدعم اللغتين العربية والإنجليزية بشكل فعال لتقديم نتائج دقيقة وفورية."},{"question":"هل النتائج دقيقة 100% دائمًا؟","answer":"الأداة دقيقة للغاية لمعظم الكلمات والنصوص. مع ذلك، قد تختلف بعض الكلمات الشاذة أو الأسماء الخاصة جدًا قليلًا حسب سياق النطق، ولكنها توفر تقديرًا ممتازًا وموثوقًا به بشكل عام."},{"question":"هل نصوصي تبقى خاصة وآمنة؟","answer":"نعم، تمامًا. تعمل هذه الأداة بالكامل داخل متصفح الويب الخاص بك. هذا يعني أن نصك لا يغادر جهازك أبدًا ولا يتم تحميله إلى أي خادم، مما يضمن خصوصيته التامة."},{"question":"هل يمكنني عد المقاطع في قصيدة كاملة أو فقرة طويلة؟","answer":"بالتأكيد! يمكنك لصق أو كتابة نصوص طويلة بقدر ما تريد. ستقوم الأداة بحساب المقاطع الصوتية لجميع الكلمات في النص وتوفر لك إحصائيات مفصلة."},{"question":"هل أحتاج إلى التسجيل أو دفع رسوم لاستخدام العداد؟","answer":"لا على الإطلاق! أداة عد المقاطع الصوتية مجانية تمامًا للاستخدام ولا تتطلب أي تسجيل أو دفع. يمكنك استخدامها بلا حدود متى احتجت إليها."},{"question":"هل تدعم الأداة اللغتين العربية والإنجليزية؟","answer":"نعم، تم تصميم الأداة لدعم كلاً من النصوص العربية والإنجليزية، وتوفر تحليلًا للمقاطع الصوتية لكلتا اللغتين بناءً على قواعدهما الخاصة."}]',
        'يبحث المستخدمون العرب عن أداة مجانية وسهلة لحساب المقاطع الصوتية في الكلمات لمساعدتهم في الشعر، الأغاني، أو فهم بناء الكلمات.',
        '["عداد المقاطع الصوتية","حاسبة المقاطع الصوتية","كم مقطع صوتي في الكلمة","تحليل المقاطع الصوتية","أداة عد السلابلز","أدوات للشعراء العرب","عد مقاطع الهايكو","حساب عدد حروف الكلمة والنطق"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'random-word-generator',
        'ar',
        'Random Word Generator',
        'مولد كلمات عشوائية عربي: أفكار بلا حدود',
        'ابحث عن إلهام فوري! مولّد الكلمات العشوائية يمنحك كلمات جديدة ومنسّقة لتوليد أفكار، أسماء، أو ألعاب. مجاني، سريع، ولا يحتاج تسجيل.',
        '',
        'مولّد الكلمات العشوائية',
        'أطلق العنان لإبداعك بكلمات عربية فريدة',
        '["هل تبحث عن الإلهام؟ مولّد الكلمات العشوائية هو بوابتك لاكتشاف كلمات جديدة ومثيرة لكسر الجمود الإبداعي. سواء كنت كاتباً، مصمماً، أو ببساطة تبحث عن فكرة جديدة، هذه الأداة تمنحك دفعة من الكلمات العربية الأصيلة، جاهزة للاستخدام الفوري.","ما عليك سوى الضغط على زر وسيقوم مولّدنا بسحب كلمات من قائمة واسعة وغنية بالكلمات العربية. يمكنك تحديد عدد الكلمات التي ترغب في رؤيتها، طولها، وحتى الحرف الذي تبدأ به. العشوائية هي أداة إبداعية قوية بشكل مدهش، حيث يمكن لكلمة لم تخترها بنفسك أن تفتح لك آفاقاً جديدة لأي مشروع أو لعبة ذهنية."]',
        'كيف تستخدم مولّد الكلمات العشوائية',
        '[{"title":"اختر عدد الكلمات","detail":"حدد عدد الكلمات التي ترغب في توليدها، من كلمة واحدة إلى خمسين كلمة دفعة واحدة."},{"title":"أضف فلاتر اختيارية","detail":"اختر حرفاً للبدء به، وحدد طولاً أدنى أو أقصى لتشكيل نوع الكلمات التي تحصل عليها."},{"title":"ولّد الكلمات","detail":"اضغط على زر (ولّد الكلمات) وستظهر لك مجموعة جديدة وعشوائية من الكلمات فوراً."},{"title":"انسخ ما تحتاجه","detail":"انقر على أي كلمة لنسخها فرادى، أو استخدم زر (نسخ الكل) للحصول على القائمة بأكملها."}]',
        '[{"heading":"استخدامات مبتكرة لمولّد الكلمات العشوائية","paragraphs":["يُعد مولّد الكلمات العشوائية أكثر من مجرد أداة لتوليد الكلمات؛ إنه شريكك في الإبداع. استخدمه لفك حصار الكاتب عند كتابة قصة أو مقال، لتوليد أسماء لمشاريعك أو شخصياتك، أو حتى لإيجاد كلمات لمسابقات الألغاز والألعاب اللغوية. سيساعدك على اكتشاف مجموعات كلمات لم تكن لتخطر ببالك.","من خلال خيارات التصفية المتقدمة مثل تحديد الحرف الأول وطول الكلمة، يمكنك توجيه النتائج لتناسب احتياجاتك بدقة. هل تحتاج كلمة ب 5 أحرف تبدأ بالميم ل crossword؟ مولدنا سيساعدك. هذه المرونة تجعل الأداة مثالية لأي شخص يبحث عن تحفيز ذهني أو حلول سريعة لتحديات الكلمات."]},{"heading":"لماذا تختار مولّدنا للكلمات العربية؟","paragraphs":["تم تصميم مولّد الكلمات العشوائية هذا خصيصاً للمستخدمين الناطقين باللغة العربية، مع التركيز على تقديم كلمات عربية أصيلة وذات صلة. نحن ندرك أهمية الدقة اللغوية والسياق الثقافي، لذا حرصنا على أن تكون الكلمات المولّدة مفيدة وواقعية للاستخدام اليومي والإبداعي.","تتميز أداتنا بالسرعة والفعالية، وتعمل بالكامل في متصفحك دون الحاجة لأي تنزيلات أو تسجيلات. إنها مجانية بالكامل بلا حدود، مما يتيح لك توليد أكبر عدد تريده من الكلمات في أي وقت. جربها الآن واكتشف كيف يمكن لكلمة عشوائية أن تضيء شرارة فكرة عظيمة!"]}]',
        '[{"input":"عدد الكلمات: 3، حرف البدء: أ","output":"أمل، أحمد، أبجدية","note":"لإيجاد ثلاثة كلمات تبدأ بحرف الألف."},{"input":"عدد الكلمات: 5، طول الكلمة: 4 أحرف","output":"سماء، بحر، شمس، ليل، نجم","note":"لتوليد 5 كلمات تتكون كل منها من 4 أحرف بالتحديد."},{"input":"عدد الكلمات: 10، لا توجد فلاتر","output":"كتاب، قلم، سماء، بحر، شمس، قمر، نجمة، وردة، شجرة، منزل","note":"للحصول على 10 كلمات عشوائية بالكامل دون أي قيود."}]',
        '["استخدم خيار ''الحرف الأول'' لتضييق البحث عن كلمات محددة.","غيّر ''عدد الكلمات'' للحصول على قائمة أطول أو أقصر حسب حاجتك.","جرّب توليد الكلمات بدون فلاتر لاكتشاف أفكار غير متوقعة.","استخدمها كأداة لألعاب الكلمات العائلية أو لتعلم مفردات جديدة."]',
        '[{"question":"ما هي استخدامات مولّد الكلمات العشوائية؟","answer":"يستخدم لمجموعة واسعة من الأغراض مثل توليد أفكار للمقالات أو القصص، تسمية المشاريع، كسر حصار الكاتب، أو لمسابقات الألغاز والألعاب اللغوية."},{"question":"هل يمكنني التحكم في طول الكلمات؟","answer":"نعم، يمكنك تحديد الحد الأدنى والأقصى لطول الكلمات التي ترغب في توليدها من خلال إعدادات الفلترة."},{"question":"من أين تأتي هذه الكلمات؟","answer":"الكلمات مأخوذة من قاموس عربي شامل لضمان تقديم مفردات متنوعة وأصيلة."},{"question":"هل مولّد الكلمات العشوائية مجاني للاستخدام؟","answer":"نعم، هذه الأداة مجانية بالكامل ولا تتطلب أي تسجيل أو اشتراكات، ويمكنك استخدامها بلا حدود."},{"question":"هل تختلف الكلمات في كل مرة أولّدها؟","answer":"نعم، يتم توليد الكلمات بشكل عشوائي تماماً في كل مرة تضغط فيها على زر التوليد، لضمان حصولك على نتائج جديدة ومفاجئة."},{"question":"هل يدعم المولّد اللهجات العربية المختلفة؟","answer":"يركز المولّد بشكل أساسي على اللغة العربية الفصحى لضمان أوسع نطاق من الاستخدام والفهم، ولكنه يشمل كلمات شائعة في كثير من اللهجات."}]',
        'يبحث المستخدمون عن أداة تساعدهم على إيجاد كلمات جديدة بشكل عشوائي لإثارة الإبداع، حل الألغاز، أو لأغراض التسمية.',
        '["مولد كلمات عشوائية","كلمات عربية عشوائية","توليد كلمات عربية","أداة كلمات عشوائية","كلمات لكسر الجمود","مولد أسماء عشوائية","أفكار كلمات جديدة","كلمات لألعاب"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'boggle-solver',
        'ar',
        'Boggle Solver',
        'حل لعبة بوغل (Boggle) بالعربي - أسرع أداة | AllWordTools',
        'ابحث عن كل الكلمات المخفية في شبكة بوغل الخاصة بك. أداة بوغل سلفور مجانية وسريعة، تكشف الكلمات الطويلة والقصيرة، مرتبة حسب الطول. اكتشف الكلمات الصعبة، ودرّب عقلك.',
        '',
        'كاشف كلمات بوغل (Boggle Solver) المجاني',
        'اعثر على كل كلمة مخفية في شبكتك ورتبها حسب الطول!',
        '["هل تبحث عن كل الكلمات المخفية في شبكة لعبة بوغل (Boggle) الخاصة بك؟ أداة حل بوغل المجانية والسريعة هذه هي رفيقك الأمثل في اللعبة! فبدلاً من التخمين، يمكنك الآن إدخال الحروف الموجودة على لوح اللعبة (بأحجام 3×3، 4×4، أو 5×5) لترى جميع الكلمات الصالحة التي يمكن تكوينها، مرتبة من الأطول إلى الأقصر، مما يضمن لك اكتشاف الكلمات الأعلى نقاطاً.","تتبع هذه الأداة قواعد لعبة Boggle الأصلية بدقة، حيث تتتبع المسارات المتجاورة (أفقياً، عمودياً، أو قطرياً) دون استخدام المربع نفسه مرتين في الكلمة الواحدة. سواء كنت ترغب في التحقق من نتيجتك، أو تسوية نزاع مع أصدقائك، أو حتى تدريب عينك لاكتشاف الكلمات الأطول في الجولات القادمة، فإن هذه الأداة هي الحل الأمثل. إنها تعمل مباشرة في متصفحك، على أي جهاز، ولا تتطلب أي تسجيل."]',
        'كيف تستخدم أداة كشف كلمات بوغل؟',
        '[{"title":"اختر حجم لوحة اللعب","detail":"حدد حجم الشبكة المطابق للعبتك (3×3، 4×4، أو 5×5) وستتحدث الشبكة تلقائياً."},{"title":"أدخل الحروف","detail":"اكتب كل حرف في الخلية الخاصة به كما يظهر تماماً على اللوحة. للحرف المركب مثل ''كو'' (Qu) بالإنجليزية، اكتب qu في خلية واحدة."},{"title":"حدد الحد الأدنى للطول","detail":"اختر أقصر طول للكلمات المراد عرضها. معظم ألعاب بوغل تحتسب الكلمات من ثلاثة حروف أو أكثر."},{"title":"ابحث عن الحل","detail":"اضغط على زر ''حل'' لترى كل الكلمات القابلة للتتبع، مجمعة حسب الطول ومسجلة حسب قواعد بوغل. انقر على أي كلمة لنسخها."}]',
        '[{"heading":"لماذا تستخدم أداة حلّ بوغل؟","paragraphs":["تعتبر أداة حل لعبة بوغل مصدراً قيماً لكل من اللاعبين الجدد والمتمرسين على حد سواء في منطقة الشرق الأوسط وشمال أفريقيا، حيث تساعد على فهم استراتيجيات اللعبة واكتشاف الكلمات المعقدة التي قد تغيب عن اللاعبين. الكثيرون يستخدمونها كمرجع سريع للتحقق من الكلمات المحتملة بعد انتهاء جولة اللعب، أو حتى لحل الألغاز الصعبة التي يواجهونها في إصدارات اللعبة المختلفة، سواء كانت إنجليزية، أو تلك التي تتبنى حروفاً عربية.","بالإضافة إلى ذلك، يمكن استخدام هذه الأداة كأداة تدريب ممتازة. فمن خلال رؤية جميع الكلمات الممكنة، يصبح اللاعبون أفضل في تحديد الأنماط وتطوير مهاراتهم في البحث عن الكلمات الطويلة وذات النقاط العالية في الألعاب المستقبلية. كما أنها مفيدة للغاية في حل النزاعات حول صلاحية كلمة معينة، مما يضمن تجربة لعب عادلة وممتعة للجميع."]},{"heading":"لعبة بوغل في العالم العربي: مزيج من التحدي والمتعة","paragraphs":["تحظى ألعاب الكلمات بشعبية كبيرة في العالم العربي، وتعد ألعاب مثل \"بوغل\" و\"سكرابل\" من بين الألعاب المحبوبة التي تجمع بين المتعة والتحدي الذهني. ومع تزايد شعبية الألعاب التي تعتمد على التركيب البصري للحروف، أصبحت أدوات مثل هذه الأداة ضرورية للاعبين الناطقين باللغة العربية، والذين يبحثون عن طرق لتعزيز تجربتهم في الألعاب الإنجليزية، أو حتى في الألعاب المشابهة التي تستخدم الحروف العربية.","بالرغم من أن لعبة بوغل الأصلية تعتمد على الحروف الإنجليزية، يواجه اللاعبون العرب أحياناً تحديات في البحث عن الكلمات الإنجليزية، وقد يستخدمون هذه الأداة كجزء من عملية تعلم اللغة. كما أن الفضول لمعرفة كل الاحتمالات المتاحة في شبكة الحروف يدفع الكثيرين للبحث عن مثل هذه الأدوات التي توفر لمحة شاملة وسريعة عن عالم الكلمات المخفية."]}]',
        '[{"input":"ذ,ه,ب,ي,ح,ر,ط,ه,ل","output":"ذهبي (5), ذهب (3), بحر (3), حبل (3)","note":"مثال لشبكة 3x3 بحروف عربية لإظهار استخراج الكلمات العربية."},{"input":"ل,ع,ب,ة,ك,ر,م,ن,س,ج,و,د,ي,د,ه,ا","output":"مسجد (4), لعب (3), جديد (4), ملعب (4)","note":"مثال لشبكة 4x4 بحروف عربية تُبرز الكلمات الشائعة."},{"input":"ت,ك,ت,ب,ق,ل,م,د,ف,ت,ر,ص,و,ر,ة,و,ا,ج,ب,ا,ق,ر,أ,ك,ت","output":"قلم (3), دفتر (4), صور (3), واجب (3), أكتب (4), تقرأ (4)","note":"مثال لشبكة 5x5 بحروف عربية لعرض المزيد من الكلمات المعقدة."}]',
        '["لا تتردد في استخدام الأداة للتحقق من الكلمات الطويلة التي قد تفوتك في اللعبة الحقيقية.","قم بتغيير حجم اللوحة ليتناسب مع اللعبة التي تلعبها بالضبط.","استخدم الأداة لتدريب عينك على رؤية الأنماط واتصالات الحروف بشكل أسرع.","شارِك النتائج مع أصدقائك لتسوية أي خلاف حول الكلمات الصحيحة."]',
        '[{"question":"هل تدعم الأداة أحجام لوحات لعب مختلفة؟","answer":"نعم، تدعم الأداة أحجام 3×3، 4×4، و 5×5 لتتناسب مع جميع أشكال لعبة بوغل الشائعة."},{"question":"كيف أدخل الحرف المركب مثل ''كو'' (Qu)؟","answer":"إذا كانت اللعبة بالإنجليزية، ما عليك سوى كتابة ''qu'' في خلية واحدة. الأداة تتعرف عليها كحرف واحد."},{"question":"هل تتبع الأداة قوانين لعبة بوغل الأصلية؟","answer":"بالتأكيد! تتبع الأداة نفس القواعد بدقة، فتبحث عن الكلمات عبر الحروف المتجاورة (أفقياً، عمودياً، أو قطرياً)، ولا تستخدم المربع نفسه مرتين في الكلمة الواحدة."},{"question":"كيف يتم حساب نقاط الكلمات؟","answer":"تقوم الأداة بحساب النقاط بناءً على طول الكلمة وقواعد تسجيل النقاط في لعبة بوغل، لتعرض لك الكلمات الأعلى قيمة أولاً."},{"question":"هل أداة حل بوغل مجانية؟","answer":"نعم، هذه الأداة مجانية تماماً للاستخدام، ولا تتطلب أي تسجيل أو اشتراك."},{"question":"هل يمكنني استخدام هذه الأداة لتعلم كلمات إنجليزية جديدة؟","answer":"قطعاً! تعتبر الأداة وسيلة رائعة لاكتشاف كلمات إنجليزية جديدة وتحسين مفرداتك من خلال رؤية كل الاحتمالات المتاحة في شبكة الحروف."}]',
        'الباحثون عن أدوات تساعدهم في حل لعبة بوغل (Boggle) وإيجاد الكلمات المخفية فيها، أو لتحسين أدائهم في اللعبة.',
        '["حل لعبة بوغل","كلمات بوغل","مساعد بوغل","كاشف كلمات بوغل","لعبة بوغل بالعربي","حلول Boggle","ترتيب كلمات Boggle","أسرار Boggle"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'hangman-solver',
        'ar',
        'Hangman Solver',
        'حل لعبة الكلمات المتقاطعة (جلاد): الكشف الذكي عن الكلمات',
        'افوز بكل جولة جلاد! كاشف الكلمات الذكي يقدم لك أفضل الحروف لتخمينها، مع كلمات مقترحة بناءً على ما لديك. مجاني وسريع.',
        '',
        'كاشف الجلاد الذكي: لا تخسر أبداً بعد اليوم!',
        'احصل على أفضل الحروف والكلمات المقترحة للفوز في أي جولة جلاد بثوانٍ.',
        '["هل سئمت من خسارة لعبة الجلاد بسبب تخمينات عشوائية؟ هل تبحث عن طريقة لزيادة فرصك في الفوز واكتشاف الكلمة المخفية بسرعة وذكاء؟ كاشف الجلاد الذكي هو أداتك السحرية التي تحول الخسارة إلى فوز مؤكد، وتجعل منك بطل هذه اللعبة الممتعة.","توقف عن التخمين العشوائي واستخدم المنطق. أداتنا المجانية بالكامل لا تساعدك فقط على الفوز، بل تعلمك استراتيجية ذكية للتخمين يمكنك تطبيقها في أي وقت. سواء كنت تلعب مع الأصدقاء، أو في تطبيق على هاتفك، أو حتى ترغب في تحسين مهاراتك اللغوية وتفكيرك النقدي، فإن كاشف الجلاد يُعد الرفيق المثالي لك."]',
        'كيف يعمل كاشف الجلاد؟ الأمر بغاية السهولة:',
        '[{"title":"أدخل الحروف المعروفة","detail":"اكتب الكلمة باستخدام (_)، أو الفواصل السفلية، لتمثيل الحروف المجهولة. على سبيل المثال: (ك_ب) للحصول على كلمت (كلب). تأكد من أن عدد الشرطات السفلية يطابق عدد الحروف المجهولة تماماً."},{"title":"أضف الحروف التي خمينتها خطأ","detail":"أدخل أي حروف قمت بتخمينها وظهر أنها ليست جزءاً من الكلمة. هذا يساعد الأداة على استبعاد الكلمات التي تحتوي على هذه الحروف لزيادة دقة البحث."},{"title":"اضغط على زر (حل)","detail":"بعد إدخال معلوماتك، اضغط على زر (حل) أو (كشف) لترى قائمة بكل الكلمات المحتملة التي تطابق نمطك، بالإضافة إلى أفضل الحروف المقترحة لتخمينها، مرتبة حسب احتمالية وجودها في الكلمة."},{"title":"اختر الأذكى","detail":"اختر الحرف المقترح ذو النسبة الأعلى، قم بتحديث نمط الكلمة بالنتيجة الجديدة (إذا كان الحرف صحيحاً)، ثم اضغط على زر (حل) مرة أخرى لتضييق نطاق الاحتمالات والوصول للكلمة النهائية بسرعة."}]',
        '[{"heading":"لماذا تختار كاشف الجلاد الذكي؟","paragraphs":["بصفتنا متخصصين في ألعاب الكلمات، نعلم أن التخمين العشوائي لا يجدي نفعاً. أداتنا ليست مجرد قائمة كلمات؛ إنها محرك ذكي يحلل آلاف الكلمات في ثوانٍ، ليمنحك أفضل فرصة للفوز. بدلاً من ضياع الوقت وتضييع فرصك، ستحصل على رؤى فورية تساعدك على تجاوز الجولات الصعبة ببراعة وحسم.","تم تصميم الكاشف ليكون سهل الاستخدام للغاية، ويعمل على أي جهاز، ولا يتطلب أي تسجيل. سواء كنت تلعب لتسلية بسيطة أو تتنافس في جولة حماسية، فإن هذا المساعد الموثوق به يضمن لك البقاء متقدماً بخطوة، مع تزويدك بالمهارات التي تحتاجها لتصبح محترفاً في لعبة الجلاد."]},{"heading":"تطوير مهاراتك اللغوية والتفكير النقدي","paragraphs":["الفائدة ليست فقط في الفوز باللعبة. باستخدام كاشف الجلاد الذكي، ستكتسب فهماً أعمق لأنماط الحروف وتراكيب الكلمات في اللغة العربية. ستلاحظ كيف تتوزع الحروف، وما هي الحروف الأكثر شيوعاً، مما يعزز من مفرداتك وقدرتك على استنتاج الكلمات حتى بدون مساعدة الأداة.","هذه الأداة تحفز التفكير المنطقي والاستراتيجي. فبدلاً من التخمينات العشوائية، ستتعلم كيف تقيّم الاحتمالات وتتخذ قرارات مستنيرة بناءً على البيانات. إنها طريقة ممتعة وفعالة لتطوير مهاراتك الذهنية واللغوية، مما يجعل منك لاعباً أذكى ومفكرًا أفضل."]}]',
        '[{"input":"ك_ت_ب , حروف خاطئة: ق، ز، ر","output":"كتب، كتبة، كاتب. أفضل الحروف: أ (33%)","note":"الأداة تقترح كلمات عربية تتناسب مع النمط والحروف المحدودة."},{"input":"_ل_م , حروف خاطئة: ج، ف","output":"علم، سلم، قلم، ظلم. أفضل الحروف: ق (25%)","note":"تظهر الكلمات الممكنة والحرف الأرجح للكشف عن الكلمة."},{"input":"م_ك_ب , حروف خاطئة: ط، ص، خ","output":"مكتب. أفضل الحروف: ت (100%)","note":"عندما يكون هناك احتمال واحد، تقوم الأداة بكشف الكلمة بالكامل."}]',
        '["ابدأ دائماً بالحروف الشائعة في العربية مثل الألف واللام والميم، فهذا يزيد من فرصك في الكشف المبكر.","استخدم الأداة لتتعلم: لاحظ كيف ترتب الأداة الحروف وفكر في سبب ذلك، فهذا يعزز حدسك في المستقبل.","لا تتردد في تحديث المدخلات بعد كل تخمين؛ فكل معلومة جديدة تزيد من دقة الأداة.","إذا كنت تواجه صعوبة في تخمين كلمة طويلة، ركز على تحديد أحرف الوسط والأطراف أولاً."]',
        '[{"question":"كيف أدخل نمط الكلمة في خانة البحث؟","answer":"كل ما عليك هو كتابة الحروف التي تعرفها واستخدام علامة الشرطة السفلية (_) بدلاً من كل حرف مجهول. على سبيل المثال، إذا كانت الكلمة ''بيت'' وأنت لا تعرف حرف التاء، أدخل ''ب_ت''."},{"question":"ماذا يجب أن أضع في صندوق (الحروف المخطئة)؟","answer":"ضع أي حروف قمت بتخمينها وكانت خاطئة (أي أنها لا توجد في الكلمة الهدف). هذا يساعد الأداة على استبعاد الكلمات التي تحتوي على هذه الحروف، وبالتالي تضييق نطاق البحث."},{"question":"كيف تختار الأداة أفضل حرف لتخمينه؟","answer":"الأداة تقوم بتحليل جميع الكلمات المحتملة المتبقية وتعدّ كم مرة يظهر كل حرف لم يتم تخمينه بعد ضمن هذه الكلمات. ثم تقترح الحرف الذي يظهر في أكبر نسبة من الكلمات الممكنة، مما يعطيك أفضل فرصة للنجاح في التخمين."},{"question":"هل كاشف الجلاد مجاني بالكامل؟","answer":"نعم، الأداة مجانية تماماً للاستخدام، ولا تتطلب أي تسجيل أو اشتراك. يمكنك استخدامها في أي وقت ومن أي جهاز."},{"question":"هل تضمن الأداة دائماً العثور على الكلمة الصحيحة؟","answer":"نعم، طالما أنك تدخل المعلومات الصحيحة (نمط الكلمة والحروف الخاطئة)، فإن الأداة ستعثر على جميع الكلمات المطابقة في قاعدة بياناتها وستقترح أفضل الحروف. هي لا تخمن، بل تحسب الاحتمالات بناءً على المعطيات."},{"question":"هل يمكنني استخدام هذه الأداة لتحسين مهاراتي اللغوية؟","answer":"بالتأكيد! من خلال رؤية الكلمات المقترحة والحروف الأكثر احتمالاً، ستطور فهماً أعمق لأنماط الكلمات العربية وتراكيبها، مما يساعدك على تحسين مفرداتك ومهاراتك في التخمين حتى بدون الأداة."}]',
        'يريد المستخدمون الفوز بلعبة الجلاد بسهولة أو تحسين مهاراتهم في التخمين الذكي.',
        '["حل لعبة الجلاد","مساعد لعبة الكلمات","تخمين كلمات جلاد","أداة كشف كلمات الجلاد","كيف أفوز في الجلاد","حل لعبة الحروف المتقاطعة","موقع يساعد في لعبة حل الكلمات","تخمين الكلمات المعلقة"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'text-twist-solver',
        'ar',
        'Text Twist Solver',
        'حل لعبة Text Twist: اكتشف الكلمات المخفية Bonus word',
        'استخدم أداة حل Text Twist لفك رموز جولات ستاي تويست وألعاب الكلمات الأخرى. اعثر على جميع الكلمات بلمح البصر، بما فيها الكلمة الإضافية (Bonus word) لتمرير المستويات. مجاني وسريع.',
        '',
        'أداة حل Text Twist: اكتشف جميع الكلمات المخفية',
        'تخلص من أصعب جولات Text Twist في ثوانٍ، واكشف الكلمة الإضافية بسهولة!',
        '["هل علقت في جولة صعبة من Text Twist؟ هل تعبت من البحث عن كلمات لا تراها؟ لا تقلق، أداتنا مصممة خصيصًا لمساعدتك على فك جميع رموز اللعبة. أدخل الحروف المختلطة التي لديك، وسنقوم فورًا بإيجاد كل كلمة صالحة، بدءًا من الكلمات المكونة من ثلاثة أحرف وصولاً إلى الكلمة الكاملة التي تستخدم جميع الحروف.","ما يميز أداتنا حقًا هو قدرتها على تحديد الكلمة الإضافية (Bonus word) التي تستخدم جميع حروفك؛ هذه هي الكلمة السحرية التي تحتاجها للانتقال إلى المستوى التالي! بدلاً من قلب الحروف مرارًا وتكرارًا، ستحصل على قائمة منظمة تشبه تخطيط اللعبة نفسه، مما يسهل عليك رؤية أي الأطوال ما زلت تحتاجها وأي الكلمات تدخلها أولاً. الأداة مجانية تمامًا، وتعمل فورًا عبر المتصفح على أي جهاز، ولا تتطلب أي تسجيل."]',
        'كيف تستخدم أداة حل Text Twist؟',
        '[{"title":"أدخل حروفك","detail":"اكتب الحروف المختلطة من الجولة — عادة ما تكون ستة أو سبعة. الترتيب لا يهم."},{"title":"حل الجولة","detail":"اضغط على زر \"حل\" وستجد الأداة كل كلمة صحيحة، من ثلاثة أحرف وحتى طول حروفك بالكامل."},{"title":"املأ كل طول","detail":"يتم تجميع الكلمات حسب الطول لتتوافق مع لوحة اللعبة، حتى تتمكن من إكمال كل صف بالترتيب."},{"title":"العب الكلمة الإضافية (Bonus word)","detail":"الكلمات الإضافية ذات الطول الكامل مميزة بنجمة – أدخل واحدة للانتقال إلى الجولة التالية."}]',
        '[{"heading":"لماذا تستخدم أداة حل Text Twist؟","paragraphs":["ألعاب الكلمات مثل Text Twist وغيرها من ألعاب ترتيب الحروف تحفز العقل وتزيد من مفرداتك. ولكن أحيانًا، قد نعلق في جولة معينة لا نستطيع تجاوزها، مما يسبب الإحباط. هنا يأتي دور أداتنا، فهي ليست مجرد غش، بل هي أداة تعليمية تساعدك على اكتشاف الكلمات التي كنت تفوتها وتتعلم منها لتعزيز مهاراتك في الألعاب المستقبلية.","سواء كنت ترغب في تجاوز جولة محددة بزمن معين، أو فتح مستوى جديد، أو ببساطة تتعلم الكلمات التي تفوتك باستمرار، فإن هذه الأداة هي رفيقك المثالي. إنها تمنحك ميزة تنافسية وتأكد من أنك تستمتع بكل لحظة من اللعبة بدلاً من الشعور بالإحباط."]},{"heading":"أداة مفيدة لجميع ألعاب الكلمات الشبيهة","paragraphs":["على الرغم من أننا نركز على Text Twist بشكل خاص، إلا أن أداتنا قوية بما يكفي لمساعدتك في أي لعبة ترتيب حروف مشابهة. إذا كانت لديك مجموعة من الحروف المختلطة وتحتاج إلى إيجاد جميع الكلمات الممكنة، فإن أداتنا ستقوم بالمهمة بسرعة وفاعلية. الأمر كله يتعلق بإدخال حروفك والضغط على زر الحل.","تذكر أن الهدف ليس فقط الفوز ولكن تعلم كلمات جديدة وتحسين قدراتك اللغوية. استخدم هذه الأداة لتوسيع مفرداتك وفهمك للغة، وجعل ألعاب الكلمات أكثر متعة وتحديًا في نفس الوقت. إنها طريقة رائعة للعب والتعلم معًا."]}]',
        '[{"input":"كتاب","output":"كتاب, كاتب, بت","note":"مثال عربي يوضح كيف تتكون كلمات مختلفة من نفس الحروف."},{"input":"لعبكر","output":"لعب, بكر, ارك","note":"مثال آخر بالحروف العربية يبرز مرونة الأداة في توليد الكلمات."},{"input":"سماحر","output":"سماح, حار, راح","note":"توضح الكلمات الممكنة من حروف مختلطة، وكيف يمكن أن تتغير المعاني."}]',
        '["ابدأ دائمًا بالكلمات الأقصر لملء الأماكن السهلة.","ابحث عن الكلمات الإضافية (Bonus words) لفتح المستوى التالي.","استخدم الأداة لتعلم الكلمات التي فاتتك في الجولات السابقة.","تأكد من إدخال جميع الحروف بالضبط كما تظهر في اللعبة."]',
        '[{"question":"ما هي الكلمة الإضافية (Bonus word) في Text Twist؟","answer":"الكلمة الإضافية هي الكلمة التي تستخدم جميع الحروف المعطاة في الجولة. العثور عليها ينهي الجولة ويأخذك إلى المستوى التالي."},{"question":"كم عدد الحروف التي يمكنني إدخالها؟","answer":"يمكنك إدخال أي عدد من الحروف، ولكن لعبة Text Twist غالبًا ما تكون بين 6 إلى 7 حروف. أداتنا ستعمل بغض النظر عن العدد."},{"question":"هل يتم تجميع النتائج مثل لوحة اللعبة؟","answer":"نعم، يتم تجميع جميع الكلمات المكتشفة حسب طولها لكي تتطابق مع طريقة عرض الكلمات في لعبة Text Twist، مما يسهل عليك ملء الخانات."},{"question":"هل أداة حل Text Twist مجانية؟","answer":"نعم، الأداة مجانية تمامًا للاستخدام. لا توجد أي رسوم أو اشتراكات خفية."},{"question":"هل تعمل الأداة لألعاب ترتيب الحروف الأخرى؟","answer":"بالتأكيد! الأداة مصممة للعثور على جميع التوليفات الممكنة من الحروف، لذا فهي فعالة لأي لعبة كلمات تعتمد على ترتيب الحروف وإيجاد الكلمات."},{"question":"هل الأداة متوفرة باللغة العربية؟","answer":"الأداة مصممة للعمل مع الحروف الإنجليزية بشكل أساسي نظرًا لطبيعة لعبة Text Twist، ولكن يمكن استخدامها مع أي مدخلات حروف. حاليًا لا تدعم الكلمات العربية كقوائم لغوية محددة."}]',
        'يبحث المستخدمون العرب عن أداة تساعدهم في حل جولات Text Twist الصعبة والكلمات المخفية فيها، وخاصة كلمة البونص (bonus word).',
        '["حل Text Twist","فك حروف Text Twist","مساعد لعبة الكلمات","كلمة بونص Text Twist","أداة حل ألعاب تركيب الحروف","شرح Text Twist","كيف أفوز في Text Twist","تول كلمات من حروف"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'vowel-counter',
        'ar',
        'Vowel Counter',
        'عداد الحروف المتحركة والنص – أداة مجانية وسهلة',
        'احصل على عدد الحروف المتحركة في أي نص فوراُ، وشاهد تفصيلاً لكل حرف. أداة مجانية لتعلم الإنجليزية، الألغاز، والشعر. جربها الآن!',
        '',
        'عداد الحروف المتحركة (Vowel Counter) للنصوص الإنجليزية',
        'أداة مجانية وفورية لتحليل الحروف المتحركة في أي نص',
        '["هل تحتاج إلى معرفة عدد الحروف المتحركة (Vowels) في نص معين؟ سواء كنت طالباً يتعلم اللغة الإنجليزية، كاتباً، شاعراً، أو حتى من محبي ألعاب الكلمات والألغاز مثل Scrabble و Wordle، فإن أداة عد الحروف المتحركة المجانية لدينا هي الحل الأمثل لك. تقوم هذه الأداة بتحليل النص الذي تدخله وتزودك بعدد إجمالي للحروف المتحركة، بالإضافة إلى تفصيل لعدد مرات ظهور كل حرف متحرك على حدة (A, E, I, O, U) وحتى حرف Y الذي يتصرف أحياناً كحرف متحرك.","تتميز هذه الأداة ببساطتها وسرعتها، فهي تعمل مباشرة في متصفحك دون الحاجة للتسجيل أو تنزيل أي برامج. كل ما عليك فعله هو لصق النص أو كتابته، وستقوم الأداة بتحديث النتائج فوراً، موفرة لك إحصائيات دقيقة عن نسبة الحروف المتحركة إلى الحروف الساكنة (Consonants) والنسبة المئوية للحروف المتحركة من إجمالي النص. اكتشف سحر اللغة الإنجليزية وتحليل النصوص بطريقة لم تعهدها من قبل!"]',
        'كيف تستخدم أداة عد الحروف المتحركة؟',
        '[{"title":"أدخل نصك","detail":"اكتب أو الصق كلمة، جملة، أو مستنداً كاملاً في مربع النص المخصص."},{"title":"اطلع على الإحصاءات","detail":"شاهد العدد الإجمالي للحروف المتحركة، وعدد الحروف الساكنة، وإجمالي الأحرف، ونسبة الحروف المتحركة المئوية."},{"title":"تصفح التفاصيل","detail":"يوضح الرسم البياني عدد مرات ظهور كل حرف متحرك (A, E, I, O, U) بالتفصيل."},{"title":"انسخ النتائج","detail":"انقل ملخص عدد الحروف المتحركة بنقرة واحدة لاستخدامه في مقالاتك أو ألغازك."}]',
        '[{"heading":"لماذا تعد الحروف المتحركة؟ وما فائدتها للمتحدثين بالعربية؟","paragraphs":["قد تبدو عملية عد الحروف المتحركة بسيطة، لكنها تحمل العديد من الفوائد، خاصة للمتحدثين باللغة العربية الذين يتعلمون الإنجليزية. تساعد هذه الأداة في فهم بنية الكلمات الإنجليزية وقواعد النطق، حيث تشكل الحروف المتحركة جوهر كل مقطع لفظي. هذا الفهم يعزز مهارات الإملاء ويحسن النطق، مما يسهل على المتعلمين العرب إتقان اللغة الإنجليزية وتجنب الأخطاء الشائعة.","بالإضافة إلى ذلك، تعد الأداة مفيدة جداً لطلاب الأدب والشعر الإنجليزي ولعشاق تراكيب الكلمات. يمكن أن تساعد في تحليل الأنماط الصوتية للشعر (مثل تحديد القوافي والإيقاع)، أو في حل ألغاز الكلمات التي تتطلب منك تحديد كلمات بعدد معين من الحروف المتحركة. إنها أداة متعددة الاستخدامات تفتح آفاقاً جديدة لاكتشاف اللغة."]},{"heading":"استخدامات عملية لعداد الحروف المتحركة","paragraphs":["تتعدد استخدامات أداة عد الحروف المتحركة لتشمل مجالات مختلفة. فمثلاً، يمكن لمعلمي اللغة الإنجليزية استخدامها لمساعدة طلابهم العرب في تحديد الحروف المتحركة ضمن الكلمات والجمل، وتعليمهم كيفية تأثيرها على النطق أو تكوين المقاطع. كما أنها أداة قيمة للكتّاب الذين يرغبون في تحليل كثافة الحروف المتحركة في نصوصهم لتحقيق إيقاع معين أو لتجنب التكرار.","لا تقتصر استخدامات الأداة على الجانب الأكاديمي أو الأدبي؛ بل يمكن لأي شخص يمارس ألعاب الكلمات الإنجليزية الاستفادة منها. هل تلعب Scrabble أو Bananagrams وتحتاج إلى معرفة عدد الحروف المتحركة في تشكيلتك الحالية؟ هل تحاول حل لغز Wordle وتخمين الكلمات بناءً على عدد الحروف المتحركة؟ ستوفر لك الأداة الإجابة فوراً، مما يعطيك ميزة تنافسية ومتعة أكبر في اللعب."]}]',
        '[{"input":"أهلاً بك في عالم الأدوات اللغوية المفيدة!","output":"0 حروف متحركة","note":"الأداة لا تعد الحروف المتحركة العربية (الحركات)، بل الحروف الإنجليزية."},{"input":"apple, orange and banana","output":"{Total Vowels: 9, Consonants: 10, Vowel Share: 47%, A: 5, E: 2, I: 0, O: 1, U: 1, Y: 0}","note":"تحليل دقيق للحروف المتحركة في هذه الكلمات الإنجليزية."},{"input":"Why do you try to count my vowels?","output":"{Total Vowels: 10, Consonants: 16, Vowel Share: 38%, A: 1, E: 2, I: 1, O: 2, U: 2, Y: 2}","note":"تظهر الأداة حرف ''Y'' ضمن الحروف المتحركة لأنه يتصرف كحرف متحرك في هذه الكلمة."}]',
        '["استخدم الأداة أثناء تعلمك كلمات إنجليزية جديدة لتفهم تركيبها الصوتي.","جرب لصق فقرات كاملة لتحليل نسب الحروف المتحركة الكلية في نصك.","قارن عدد الحروف المتحركة في القصائد الإنجليزية المختلفة للبحث عن الأنماط.","استفد منها في ألعاب الألغاز مثل Wordle عندما تحتاج لتقييم الكلمات المحتملة."]',
        '[{"question":"ما هي الحروف التي يعدها عداد الحروف المتحركة؟","answer":"يعد العداد الحروف المتحركة الإنجليزية الأساسية: A, E, I, O, U. كما أنه يلتقط حرف Y عندما يتصرف كحرف متحرك."},{"question":"هل يعتبر حرف Y حرفاً متحركاً؟","answer":"أحياناً نعم! في بعض الكلمات مثل ''sky'' أو ''rhythm'' يتصرف حرف Y كحرف متحرك، والأداة تحدد ذلك بدقة وتضيفه إلى الإحصاءات."},{"question":"هل تميز الأداة بين الأحرف الكبيرة والصغيرة؟","answer":"لا، الأداة تتعامل مع الأحرف الكبيرة (Capital letters) والصغيرة (Lowercase letters) بنفس الطريقة في العد، فلا يوجد فرق في النتيجة."},{"question":"ماذا تعني نسبة الحروف المتحركة المئوية؟","answer":"هي النسبة المئوية للحروف المتحركة من إجمالي عدد الحروف في النص الذي أدخلته (الحروف المتحركة والساكنة معاً).\n"},{"question":"هل هذه الأداة مجانية وهل أحتاج للتسجيل؟","answer":"نعم، الأداة مجانية تماماً ولا تتطلب أي تسجيل أو إنشاء حساب. يمكنك استخدامها مباشرة من متصفحك."},{"question":"هل يمكنني استخدامها مع النصوص العربية؟","answer":"هذه الأداة مصممة خصيصاً لعد الحروف المتحركة (Vowels) في اللغة الإنجليزية. لن تقوم بعد ''الحركات'' أو حروف العلة في النصوص العربية."}]',
        'يبحث المستخدم العربي عن أداة مجانية وسهلة لحساب الحروف المتحركة في النصوص الإنجليزية، لمساعدته في الدراسة أو الألعاب اللغوية.',
        '["عداد حروف متحركة","حساب الحروف المتحركة في الكلمات","أداة عد الأحرف المتحركة","كم عدد الVowels في الكلمة","عد حروف العلة إنجليزي","موقع يحسب الحروف المتحركة","تطبيق عد الحروف الإنجليزية","تحديد الحروف المتحركة في النص"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'consonant-counter',
        'ar',
        'Consonant Counter',
        'عداد الحروف الساكنة: احصِ الحروف الصامتة بدقة وسهولة',
        'احصِ الحروف الساكنة (الصامتة) في أي نص عربي أو إنجليزي فوريًا ومجانًا. أداة عد الحروف الصامتة تمنحك تحليلًا كاملًا للكلمات والأحرف لمساعدتك في ألعاب الكلمات، تعلم اللغة، والشعر.',
        '',
        'عداد الحروف الساكنة: احصل على تحليل دقيق لنصوصك',
        'أداة سريعة ومجانية لحساب جميع الحروف الساكنة في أي نص عربي أو إنجليزي',
        '["هل تحتاج إلى معرفة عدد الحروف الساكنة في نص معين؟ سواء كنت تتعلم لغة جديدة، تعمل على قصيدة، تحاول حل لغز كلمات، أو حتى تريد تحليلًا دقيقًا لتركيبة كلماتك، فإن أداة عداد الحروف الساكنة من AllWordTools.com هي الحل الأمثل لك. هذه الأداة البسيطة والقوية تحصي جميع الحروف التي ليست حروف علة (متحركة)، وتوفر لك تفصيلًا كاملًا وواضحًا لتركيبة النص.","تعمل أداة عداد الحروف الساكنة مباشرة في متصفحك، مما يعني أنك لست بحاجة إلى تنزيل أي شيء أو التسجيل. فقط اكتب أو الصق نصك، وستحصل على النتائج فورًا ومجاناً. سنعرض لك العدد الإجمالي للحروف الساكنة، وكيف تتوزع مقارنة بالحروف المتحركة، ونسبة الحروف الساكنة في النص الكلي، بالإضافة إلى تفكيك لعدد مرات ظهور كل حرف ساكن. ابدأ بالتحليل الآن ووفر وقتك وجهدك!"]',
        'كيف تستخدم عداد الحروف الساكنة؟',
        '[{"title":"أدخل نصك","detail":"اكتب أو الصق الكلمة، الجملة، أو الوثيقة التي تريد تحليلها في الخانة المخصصة."},{"title":"اقرأ الإجماليات","detail":"شاهد العدد الإجمالي للحروف الساكنة، الحروف المتحركة، إجمالي الحروف، ونسبة الحروف الساكنة كنسبة مئوية من النص."},{"title":"تحقق من التفاصيل","detail":"يعرض لك الرسم البياني عدد مرات ظهور كل حرف ساكن، مرتبة حسب التكرار، لتفهم تركيبة نصك."},{"title":"انسخ الأرقام","detail":"انسخ العدد الإجمالي للحروف الساكنة بنقرة واحدة لاستخدامه في مقالاتك، مشاريعك، أو حل الألغاز."}]',
        '[{"heading":"لماذا قد تحتاج إلى عداد الحروف الساكنة؟","paragraphs":["قد لا يخطر ببال الكثيرين أهمية عد الحروف الساكنة بشكل دوري، لكنها مهارة أساسية في مجالات متعددة. ففي عالم تعلم اللغات، يساعدك عد الحروف الساكنة على فهم أنماط النطق والتشكيل، خصوصاً في اللغة العربية التي تعتمد على الحركات بشكل كبير، مما يسهل عليك تمييز جذر الكلمة والاشتقاقات. كما أنها مفيدة جداً عند ممارسة الإملاء وتحسين القدرة على التعرف على بنية الكلمات وتراكيبها اللغوية.","أما في مجال الأدب والشعر، يمكن لعد الحروف الساكنة أن يساعد الشعراء والكتّاب في تحليل إيقاع قصائدهم ونصوصهم النثرية. فهم يسمح لهم بفهم كيفية تأثير توزع الحروف الساكنة والمتحركة على الوزن والإلقاء، وهي أداة قيمة في ألعاب الكلمات مثل الكلمات المتقاطعة والاسكرابل، حيث يمكنها أن تمنحك ميزة تنافسية من خلال تحديد الكلمات المحتملة التي تحتوي على تركيبة معينة من الأحرف."]},{"heading":"أداة مثالية لطلاب اللغة ومحبي الألغاز","paragraphs":["إذا كنت طالبًا للغة العربية أو الإنجليزية أو أي لغة أخرى، فإن عداد الحروف الساكنة سيصبح من أدواتك المفضلة. يساعدك على تحليل بنية الكلمات والجمل، وبالتالي يعزز فهمك لقواعد الإملاء والنطق. يمكن استخدامه لإنشاء تمارين إملاء مخصصة أو لتحديد الكلمات التي قد تكون صعبة النطق بناءً على عدد الحروف الساكنة المتتالية فيها. هذه الميزة لا تقدر بثمن لغير الناطقين باللغة وأيضًا للمساعدة في تدريس اللغة.","ولعشاق ألعاب الألغاز والكلمات، يفتح هذا العداد آفاقًا جديدة. سواء كنت تحاول حل كلمات متقاطعة، أو تعمل على لعبة ''حروف متناثرة''، أو حتى تكتب ''جناسًا'' (tongue twister)، فإن معرفة التركيب الدقيق للحروف الساكنة يمنحك ميزة كبيرة. يمكنك استخدامه لتكوين كلمات جديدة من مجموعة أحرف، أو لتدريب ذهنك على سرعة تحليل الكلمات. الأداة مجانية وسهلة الاستخدام، مما يجعلها إضافة قيّمة لمجموعة أدواتك الرقمية."]}]',
        '[{"input":"أهلًا بك في موقعنا AllWordTools.com","output":"الحروف الساكنة: 14\nالحروف المتحركة: 9\nإجمالي الحروف: 23\nنسبة الساكنة: 60.87%","note":"تحليل نص عربي يوضح عدد الحروف الساكنة والمتحركة ونسبتها المئوية."},{"input":"اللغة العربية بحرٌ واسعٌ ومليءٌ بالمفردات","output":"الحروف الساكنة: 19\nالحروف المتحركة: 11\nإجمالي الحروف: 30\nنسبة الساكنة: 63.33%","note":"مثال آخر باللغة العربية يوضح كيف تتغير الأرقام مع نص مختلف."},{"input":"the quick brown fox jumps over the lazy dog","output":"الحروف الساكنة: 25\nالحروف المتحركة: 10\nإجمالي الحروف: 35\nنسبة الساكنة: 71.43%","note":"مثال باللغة الإنجليزية يوضح استخدام الأداة في لغات مختلفة. (Y تُحتسب حرف ساكن في هذا النص)."}]',
        '["استخدم الأداة لتحليل الأسماء المعقدة وتدرب على نطقها.","ادمج نتائج عداد الحروف الساكنة مع أدواتنا الأخرى لتحليل أعمق لنصوصك.","استخدمه مع أطفالك كجزء من تمارين تعلم القراءة والكتابة.","جرب تحليل مقاطع من قصائدك المفضلة لترى كيف تتوزع الحروف الساكنة."]',
        '[{"question":"ما هي الحروف التي يحسبها عداد الحروف الساكنة؟","answer":"يحسب هذا العداد كل الحروف الأبجدية التي لا تعتبر حروف علة (متحركة). في اللغة العربية، جميع الحروف الهجائية عدا الحركات تعتبر حروفًا ساكنة بشكل عام، ولكن بعض الأدوات قد تعتبر الألف والواو والياء حروف علة في سياق معين. أداة AllWordTools.com تركز على الحروف الأبجدية الأساسية وتعدها ساكنة إذا لم تكن من حروف المد المعروفة أو الحركات."},{"question":"هل حرف ''ي'' يعتبر حرفًا ساكنًا أم متحركًا؟","answer":"يعتمد ذلك على سياق الكلمة واللغة. في اللغة الإنجليزية، حرف ''y'' يمكن أن يكون ساكنًا أو متحركًا. في أداة AllWordTools.com، يتم التعامل مع ''y'' كحرف ساكن افتراضيًا. أما في اللغة العربية، ''الياء'' كحرف هجائي أصلي تُعد ساكنة ما لم تكن حرف مد (ياء المد)."},{"question":"هل الأداة تحسب الأحرف الكبيرة وعلامات الترقيم؟","answer":"تحسب الأداة الحروف الساكنة فقط بغض النظر عما إذا كانت كبيرة أو صغيرة (في اللغات التي تميز بينها). أما علامات الترقيم والأرقام والمسافات فلن يتم احتسابها كحروف ساكنة أو متحركة؛ يتم تجاهلها في عملية العد للحروف."},{"question":"ما هي ''نسبة الحروف الساكنة'' التي تظهرها الأداة؟","answer":"تشير ''نسبة الحروف الساكنة'' إلى النسبة المئوية للحروف الساكنة من إجمالي عدد الحروف الأبجدية (الساكنة والمتحركة معًا) في النص المدخل. تساعدك هذه النسبة على فهم الكثافة الساكنة في نصك."},{"question":"هل عداد الحروف الساكنة مجاني؟","answer":"نعم، أداة عداد الحروف الساكنة مجانية تمامًا. لا توجد رسوم أو اشتراكات أو قيود على الاستخدام. يمكنك استخدامها في أي وقت ومن أي مكان دون الحاجة لإنشاء حساب أو تنزيل برامج."},{"question":"هل الأداة تدعم اللغة العربية والإنجليزية لعد الحروف؟","answer":"بالتأكيد! الأداة مصممة للعمل بكفاءة مع النصوص العربية والإنجليزية على حد سواء، بالإضافة إلى العديد من اللغات الأخرى. ستقوم بتحليل الحروف الساكنة والمتحركة بشكل صحيح لكلتا اللغتين لتوفر لك تحليلًا دقيقًا."}]',
        'يبحث المستخدمون عن أداة مجانية وسريعة لحساب عدد الحروف الساكنة في النصوص لتعلم اللغة، حل ألعاب الكلمات، أو تحليل النصوص العربية والإنجليزية.',
        '["عداد الحروف الساكنة","حساب الحروف الصامتة","عد الحروف في النص","أداة تحليل نص عربي","كم حرف ساكن في الكلمة","برنامج عد كلمات وحروف","محلل حروف ساكنة ومتحركة","طرق عد الحروف الصامتة"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'word-meaning',
        'ar',
        'Word Meaning',
        'معنى الكلمات الإنجليزية: شرح سريع ومبسط لأي كلمة',
        'هل تبحث عن معنى كلمة إنجليزية؟ اكتشف أداة ''معنى الكلمات'' التي تقدم لك تعريفات واضحة وسهلة الفهم مع أمثلة عملية فورًا ومجانًا. مثالية لمتعلمي الإنجليزية.',
        '',
        'أداة معنى الكلمات: فهم سريع ومبسط لأي كلمة إنجليزية',
        'احصل على تعريفات واضحة وأمثلة عملية لفهم أعمق للمفردات الإنجليزية.',
        '["في كثير من الأحيان، لا نحتاج إلى قاموس كامل به تفاصيل معقدة؛ كل ما نريده هو معرفة معنى كلمة معينة بسرعة ووضوح. سواء كنت تقرأ مقالاً بالإنجليزية، تواصلت مع ناطق أصلي، أو تتعلم لغة جديدة، فإن أداة ''معنى الكلمات'' هنا لتبسط عليك الأمر. لقد صممنا هذه الأداة لتقصّر عليك الطريق وتقدم لك المعنى مباشرة، مع التركيز على الوضوح والسهولة.","تساعدك هذه الأداة على فهم المعاني المختلفة للكلمة الواحدة، مصنّفة حسب نوع الكلام (اسم، فعل، صفة، إلخ)، ومدعومة بأمثلة جمل حقيقية توضح كيفية استخدام الكلمة في سياقها الطبيعي. الأرقام التسلسلية لكل معنى تجعل من السهل العثور على التعريف الذي يناسب السياق الذي رأيت فيه الكلمة، مما يزيل أي التباس ويجعل عملية التعلم أسرع وأكثر فعالية."]',
        'كيف تستخدم أداة معنى الكلمات؟',
        '[{"title":"أدخل الكلمة","detail":"اكتب الكلمة الإنجليزية التي ترغب في معرفة معناها في مربع البحث."},{"title":"احصل على المعنى فوراً","detail":"اضغط على زر ''أظهر المعنى'' لتحصل على التعريفات الواضحة بشكل مباشر."},{"title":"اختر المعنى المناسب","detail":"المعاني مرقمة ومصنفة حسب نوع الكلمة – ابحث عن المعنى الذي يتناسب مع سياقك."},{"title":"استفد من الأمثلة","detail":"اقرأ الجمل التوضيحية لتفهم كيفية استخدام الكلمة في مواقف مختلفة."}]',
        '[{"heading":"لماذا تختار أداة معنى الكلمات بدلاً من القاموس التقليدي؟","paragraphs":["بينما تقدم القواميس معلومات شاملة ومتخصصة، قد تكون أحيانًا أكثر تفصيلاً مما يحتاجه المتعلم أو المستخدم العادي. أداة ''معنى الكلمات'' تركز على جوهر المعلومة: ما هو معنى هذه الكلمة؟ إنها تتجاهل التفاصيل اللغوية المعقدة التي قد تشتت الانتباه وتقدم لك التعريفات اللبسيطة التي تحتاجها لتفهم وتكمل قراءتك أو كتابتك.","إنها الحل المثالي لمن يبحث عن إجابة سريعة وواضحة أثناء العمل أو الدراسة أو حتى في وقت الفراغ. لا حاجة لتصفح صفحات طويلة أو فهم مصطلحات لغوية معقدة؛ فقط المعنى المباشر الذي يوصل المعلومة بطريقة فعالة وسهلة الوصول."]},{"heading":"فهم السلسلة السياقية: أهمية الأمثلة","paragraphs":["أحد أكبر التحديات في تعلم معنى كلمة جديدة هو فهم كيفية استخدامها فعليًا. التعريف النظري وحده قد لا يكون كافيًا. لذلك، نحن ندمج أمثلة جمل في كل تعريف لتجعل المعنى المجرّد ملموسًا وسهل الاستيعاب. هذه الأمثلة تظهر لك الكلمة في سياقها الطبيعي، مما يساعدك على تذكرها واستخدامها بشكل صحيح في محادثاتك أو كتاباتك.","عندما ترى الكلمة في جملة كاملة، يمكنك ربطها بمواقف حياتية حقيقية. هذا لا يعزز فهمك فحسب، بل يساعد أيضًا في بناء حصيلتك اللغوية بطريقة عملية وفعالة. إنها طريقة مثبتة لترسيخ المعاني في ذاكرتك، مما يضمن أن تتمكن من استدعاء الكلمة واستخدامها بثقة عندما تحتاج إليها."]}]',
        '[{"input":"ابتكار","output":"لا يوجد معنى لكلمة ''ابتكار'' لأن هذه الأداة مخصصة للكلمات الإنجليزية. يرجى إدخال كلمة إنجليزية.","note":"الأداة مخصصة لكلمات اللغة الإنجليزية. المدخلات العربية لا تعمل بشكل مباشر."},{"input":"hello","output":"Hello (interjection): used as a greeting or to begin a phone conversation.\nExample: Hello, how are you today?","note":"مثال لكلمة إنجليزية بسيطة ذات معنى واحد شائع."},{"input":"present","output":"Present (noun): a gift.\nPresent (adjective): being in a particular place.\nPresent (verb): to give, show, or offer.\nExample (noun): She received a lovely present for her birthday.\nExample (adjective): All students were present for the lecture.\nExample (verb): He will present his findings tomorrow.","note":"مثال لكلمة إنجليزية لها معانٍ متعددة وأنواع كلام مختلفة، مع أمثلة لكل استخدام."}]',
        '["تجنب الجمل الطويلة؛ أدخل كلمة واحدة فقط في المرة.","إذا كانت الكلمة لها عدة معانٍ، ابحث عن المعنى الذي يناسب سياقك.","استفد من الأمثلة لفهم الاستخدام الصحيح للكلمة.","يمكنك استخدام الأداة بسرعة أثناء القراءة لتعزيز فهمك."]',
        '[{"question":"ما الفرق بين هذه الأداة والقاموس الإنجليزي العادي؟","answer":"الفرق الرئيسي هو التركيز. هذه الأداة تقدم لك المعنى المباشر والواضح للكلمة مع أمثلة، دون الخوض في تفاصيل صرفية أو اشتقاقية معقدة تجدها في القواميس الشاملة. إنها مصممة للسرعة والوضوح."},{"question":"هل الأداة تعرض أمثلة لاستخدام الكلمة في جمل؟","answer":"نعم، بالتأكيد! كل معنى من معاني الكلمة يأتي مع جملة توضيحية تظهر كيفية استخدام الكلمة في سياقها الطبيعي، مما يساعد على الفهم والاستيعاب بشكل أفضل."},{"question":"لماذا يكون للكلمة الإنجليزية الواحدة عدة معانٍ أحيانًا؟","answer":"هذا شائع جدًا في اللغة الإنجليزية (وفي العديد من اللغات). الكلمات يمكن أن تتغير معانيها أو استخداماتها حسب السياق، أو يمكن أن تعمل كأنواع مختلفة من الكلمات (مثل اسم أو فعل أو صفة). أداةنا تعرض لك هذه المعاني المختلفة بشكل واضح."},{"question":"هل استخدام أداة معنى الكلمات مجاني؟","answer":"نعم، هذه الأداة مجانية تمامًا. يمكنك استخدامها في أي وقت ومن أي جهاز متصل بالإنترنت دون أي تكلفة أو اشتراك."},{"question":"ماذا يحدث إذا لم يتم العثور على الكلمة التي أدخلتها؟","answer":"إذا لم نتمكن من العثور على تعريف للكلمة، فسنبلغك بذلك. قد يكون السبب أن الكلمة غير موجودة في قاعدة بياناتنا، أو أنها خطأ إملائي، أو كلمة غير إنجليزية. يرجى التحقق من التهجئة والمحاولة مرة أخرى."},{"question":"هل تدعم هذه الأداة البحث عن مصطلحات أو عبارات كاملة؟","answer":"لا، هذه الأداة مصممة خصيصًا للتعريف بكلمة إنجليزية واحدة في كل مرة. للبحث عن معاني العبارات أو المصطلحات، قد تحتاج إلى استخدام أداة قاموس أوسع."}]',
        'يريد المستخدمون فهم معنى كلمة إنجليزية محددة بسرعة وسهولة دون تعقيد القواميس.',
        '["معنى الكلمات","قاموس انجليزي عربي","شرح كلمات انجليزية","مرادف الكلمات الانجليزية","كلمات انجليزية ومعانيها","كيف اعرف معنى الكلمة بالانجليزي","معنى الكلمه الانجليزيه في سياقها","توضيح معنى كلمة انجليزية"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'spell-checker',
        'ar',
        'Spell Checker',
        'مدقق إملائي عربي مجاني – تصحيح الأخطاء اللغوية',
        'مدقق إملائي دقيق يكتشف الأخطاء الإملائية ويقترح التصحيحات فوراً. أداة مجانية لمراجعة النصوص بسرعة قبل النشر أو الإرسال. حافظ على سلامة كلماتك وأسلوبك.',
        '',
        'مدقق إملائي عربي: دقة وسرعة لجميع نصوصك',
        'تخلص من الأخطاء الإملائية بسهولة وحافظ على احترافية كتابتك.',
        '["هل أنت متعب من الأخطاء الإملائية التي قد تضعف رسالتك أو تقلل من احترافية كتاباتك؟ أداة التدقيق الإملائي لدينا مصممة خصيصًا للكشف عن أي خطأ إملائي في نصوصك العربية بدقة وسرعة فائقة، وتقدم لك التصحيحات المقترحة لضمان نص خالٍ من العيوب.","تُركز هذه الأداة على مهمة واحدة: تحديد الكلمات المكتوبة بشكل خاطئ وتزويدك بالتهجئة الصحيحة. ببساطة، الصق النص الذي ترغب في تدقيقه، وسنعيد لك نسخة مصححة مع قائمة واضحة بكل كلمة تم تعديلها. إنها مثالية للمراجعة السريعة والنهائية قبل إرسال بريد إلكتروني مهم، أو تسليم واجب دراسي، أو نشر مقال في مدونتك بلهجة عربية سليمة وواضحة."]',
        'كيف يعمل المدقق الإملائي؟',
        '[{"title":"الصق كتاباتك","detail":"أضف النص الذي تريد تدقيقه في المربع المخصص."},{"title":"شغّل المدقق","detail":"اضغط على ''تدقيق إملائي'' للعثور على جميع الأخطاء."},{"title":"راجع التصحيحات","detail":"شاهد كل كلمة خاطئة بجانب تهجئتها الصحيحة والمقترحة."},{"title":"انسخ النص الصحيح","detail":"يمكنك نسخ النسخة المُصححة بالكامل بعد إزالة كل الأخطاء الإملائية."}]',
        '[{"heading":"لماذا تحتاج إلى مدقق إملائي عربي؟","paragraphs":["في عالم يزداد فيه التواصل الكتابي، سواء عبر البريد الإلكتروني، منصات التواصل الاجتماعي، أو المستندات الرسمية، فإن النص الخالي من الأخطاء الإملائية يعكس اهتمامك واحترافيتك. الكثيرون يعانون من أخطاء شائعة بسبب سرعة الكتابة، أو التشابه بين الحروف، أو حتى اللهجات المختلفة التي تؤثر على قواعد الإملاء. مدققنا يضمن لك تقديم محتوى عربي لغويًا سليمًا.","الطلاب، الصحفيون، المدونون، وحتى المحترفون في مجال الأعمال، جميعهم يستفيدون من أداة تدقيق إملائي موثوقة. بدلاً من قضاء وقت طويل في مراجعات يدوية قد تفوت بعض الأخطاء، تمنحك هذه الأداة الوقت لتُركز على جوهر رسالتك، مع ضمان أن الشكل اللغوي يدعم المحتوى بدلاً من أن يشتت الانتباه عنه."]},{"heading":"كيف يحافظ المدقق على أسلوبك؟","paragraphs":["ميزة فريدة لأداتنا هي أنها تتدخل فقط في تصحيح الأخطاء الإملائية. هذا يعني أنها لن تغير من تركيب الجمل، أو تحور معاني الكلمات، أو تعدل على أسلوبك الشخصي في الكتابة. إذا كنت تكتب بنبرة معينة أو تستخدم تعبيرات خاصة بك، فإن المدقق سيحافظ على كل ذلك دون مساس، مما يضمن أن النص النهائي هو نصك أنت، ولكن بصورة إملائية صحيحة.","الكثير من أدوات \"التصحيح الشامل\" قد تفرض عليك أسلوبًا لا يناسبك. لكن هنا، نحن نؤمن بأن المحتوى الأصيل ينبع منك. مهمتنا فقط هي تنقية هذا المحتوى من الأخطاء الإملائية التي قد تظهر عرضًا، ليبقى تدفق أفكارك وانسيابية أسلوبك كما هما، مع إضافة طبقة من الاحترافية والدقة اللغوية. هذه الأداة هي مساعدك الشخصي في الإملاء، وليس بديلًا عن إبداعك."]}]',
        '[{"input":"أهلن بك في موقعنا، نتمنى لك إقامة سعية.","output":"أهلاً بك في موقعنا، نتمنى لك إقامة سعيدة.","note":"تصحيح الأخطاء الشائعة في كتابة الهمزات والتاء المربوطة."},{"input":"زرتُ المتحف أمس وكان مليء بالآثار القديمة.","output":"زرتُ المتحف أمس وكان مليئًا بالآثار القديمة.","note":"تصحيح الخطأ في التنوين والحالة الإعرابية."},{"input":"الكثير من الناس يفضولون السفر في الأجازات.","output":"الكثير من الناس يفضلون السفر في الإجازات.","note":"تصحيح خطأ إملائي شائع وخطأ في كتابة الهمزة."}]',
        '[" استخدم المدقق دائمًا قبل إرسال أي نص رسمي أو مهم."," استفد من قائمة الكلمات المصححة لمراجعة أخطائك المتكررة."," لا تتردد في نسخ النص ولصقه بالكامل؛ فالأداة تتعامل مع النصوص الطويلة."," تذكر أن المدقق يركز على الإملاء، لذا راجع صياغة الجمل بنفسك."]',
        '[{"question":"هل هذا المدقق الإملائي يدعم اللغة العربية فقط؟","answer":"نعم، هذا المدقق مصمم خصيصًا للكشف عن الأخطاء الإملائية في النصوص العربية بدقة عالية، مع الأخذ في الاعتبار خصوصية اللغة وقواعدها."},{"question":"هل يقوم المدقق بتغيير قواعد اللغة أو الأسلوب؟","answer":"لا، المدقق يركز فقط على تصحيح الأخطاء الإملائية. لا يتدخل في القواعد النحوية، الصرفية، أو أسلوب الكتابة الخاص بك، ليحافظ على جوهر رسالتك."},{"question":"كم تبلغ تكلفة استخدام هذه الأداة؟","answer":"هذه الأداة مجانية بالكامل ومتاحة للجميع. يمكنك استخدامها بلا حدود ودون الحاجة للتسجيل أو دفع أي رسوم."},{"question":"هل يمكن للمدقق التعامل مع النصوص الطويلة؟","answer":"نعم، المدقق مصمم للتعامل بكفاءة مع النصوص الطويلة. يمكنك لصق المقالات، الأبحاث، أو حتى صفحات كاملة لتدقيقها دفعة واحدة."},{"question":"هل يمكنني استخدام المدقق على أي جهاز؟","answer":"بالتأكيد، الأداة تعمل مباشرة في متصفح الويب الخاص بك، مما يعني أنها متوافقة مع أجهزة الكمبيوتر، الأجهزة اللوحية، والهواتف الذكية بمنتهى السهولة."},{"question":"كيف أضمن خصوصية النص الذي أقوم بتدقيقه؟","answer":"نحن نحترم خصوصيتك. النصوص التي تُدخلها تُعالج لحظيًا وتُحذف من سجلاتنا فورًا بعد التدقيق، ولا يتم تخزينها أو مشاركتها بأي شكل من الأشكال."}]',
        'يبحث المستخدمون عن أداة مجانية وسريعة لتصحيح الأخطاء الإملائية في نصوصهم العربية.',
        '["مدقق إملائي عربي","تصحيح الأخطاء الإملائية","برنامج تصحيح إملائي","مدقق لغوي عربي مجاني","تصحيح الجمل العربية","مدقق نصوص عربي","مصحح إملائي دقيق","تعديل الأخطاء الإملائية في الكتابة"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'grammar-checker',
        'ar',
        'Grammar Checker (AI)',
        'مدقق لغوي AI ومصحح إملاء مجاني - قوِّم أخطاء الكتابة',
        'حسن كتابتك! مدقق لغوي يعمل بالذكاء الاصطناعي يصحح الأخطاء النحوية والإملائية مع شروحات واضحة. مجاني، سريع، ولا يتطلب تسجيل.',
        '',
        'مدقق لغوي AI: صقل كتاباتك العربية بسهولة',
        'تخلص من الأخطاء النحوية، الإملائية، والركاكة في صياغة الجمل بضغطة زر واحدة.',
        '["مع \"تَدقِيقِي\"، وداعًا للأخطاء التي قد تسيء لمحادثاتك، مراسلاتك، أو حتى منشوراتك. هذه الأداة المتطورة تستخدم الذكاء الاصطناعي لمراجعة نصوصك العربية بدقة متناهية، تمامًا كخبير لغوي متمرس، لتبرز كتاباتك بأبهى حلة. سواء كنت تكتب باللغة العربية الفصحى أو تتعامل مع نصوص يومية، \"تَدقِيقِي\" رفيقك الأمثل.","لم نكتفِ بالتصحيح، بل حرصنا على الشرح الوافي. كل خطأ تحدده الأداة يأتي مع تفسير واضح للقاعدة اللغوية التي تم خرقها، مما يحول كل مراجعة إلى فرصة للتعلم وتحسين مهارتك في الكتابة. استمتع بتجربة مجانية، سريعة، ولا تحتاج إلى تسجيل؛ ببساطة، الصق نصك وشاهد الفرق."]',
        'كيف يعمل مدقق "تَدقِيقِي"؟',
        '[{"title":"الصق نصك","detail":"أضف أي نص تريده، من جملة واحدة إلى وثيقة كاملة: مقال، بريد إلكتروني، أو منشور."},{"title":"ابحث عن الأخطاء","detail":"اضغط على زر \"دقّق الآن\" وسيقوم الذكاء الاصطناعي بمراجعة كتاباتك وإبراز الأخطاء."},{"title":"راجع التعديلات","detail":"شاهد كل خطأ تم اكتشافه مع تصحيحه المقترح وشرح مبسط للقاعدة اللغوية المعنية."},{"title":"انسخ النص المعدل","detail":"احصل على نسختك النظيفة والخالية من الأخطاء مباشرةً، جاهزة للاستخدام في أي مكان."}]',
        '[{"heading":"مثالي لكل كاتب عربي: من الطالب إلى المحترف","paragraphs":["سواء كنت طالبًا تسعى لتقديم بحث جامعي خالٍ من الأخطاء، أو كاتب محتوى يطمح لإبهار جمهوره بمقالات سلسة، أو حتى محترف أعمال يحرص على مراسلات رسمية خالية من أخطاء محرجة؛ \"تَدقِيقِي\" مصمم خصيصًا لك. لا تدع الأخطاء اللغوية تقف حاجزًا بينك وبين تحقيق أهدافك أو إيصال رسالتك بوضوح وتألق.","البيئات العربية، سواء في التعليم أو العمل، تولي أهمية كبرى لدقة اللغة وصحة الكتابة. أداة \"تَدقِيقِي\" لا تقتصر على تصحيح الأخطاء الظاهرة وحسب، بل توفر تحليلًا عميقًا يساعدك على فهم نمط الأخطاء التي تكررها وتجنبها مستقبلاً، لتصبح كتاباتك أكثر احترافية تدريجيًا."]},{"heading":"صمم ليلائم احتياجاتك اليومية","paragraphs":["في العالم الرقمي السريع الذي نعيش فيه، دقيقة واحدة قد تحدث فرقًا. \"تَدقِيقِي\" يمنحك السرعة والكفاءة التي تحتاجها. لا تضيّع وقتك في مراجعة طويلة ومعقدة؛ فقط الصق نصك ودع الذكاء الاصطناعي يقوم بالباقي. كل هذا دون الحاجة لتثبيت برامج معقدة أو عمليات تسجيل مرهقة.","استخدم \"تَدقِيقِي\" لتحسين رسائل البريد الإلكتروني، منشورات وسائل التواصل الاجتماعي، تعليقات المدونات، وحتى نصوص الواتساب الرسمية. هذه المرونة تجعله أداة لا غنى عنها لأي شخص يهتم بجودة كتاباته ويطمح لإحداث تأثير إيجابي ودائم في المحيط العربي الرقمي."]}]',
        '[{"input":"المعلمون هم الذين يبنون الأجيال القادمة.","output":"المعلمون هم الذين يبنون الأجيال القادمة.","note":"لم يتم العثور على أخطاء."},{"input":"ذهبت هدى الى السوق واشترت بعض الخضروات والفواكه.","output":"ذهبت هدى إلى السوق واشترت بعض الخضروات والفواكه.","note":"تم تصحيح \"الى\" إلى \"إلى\" في الهمزة."},{"input":"لدينا الكثير من المهام التي يجب إنجازها اليوم.","output":"لدينا الكثير من المهام التي يجب إنجازها اليوم.","note":"تم تصحيح كلمة \"المهمات\" إلى \"المهام\" لتلائم الاستخدام الأكثر شيوعًا."}]',
        '["استخدمه قبل إرسال أي بريد إلكتروني رسمي.","افحص منشوراتك على وسائل التواصل الاجتماعي لضمان التأثير الجيد.","قم بمراجعة الواجبات المدرسية لضمان الدقة اللغوية.","استعمله لتطوير مهاراتك في الكتابة وفهم الأخطاء الشائعة."]',
        '[{"question":"هل مدقق تَدقِيقِي مجاني حقًا؟","answer":"نعم، أداة تَدقِيقِي مجانية بالكامل. لا توجد رسوم خفية ولا تتطلب اشتراكًا لاستخدام جميع ميزاتها."},{"question":"هل يشرح تَدقِيقِي الأخطاء اللغوية؟","answer":"بالتأكيد، \"تَدقِيقِي\" لا يصحح الأخطاء فقط، بل يوفر شرحًا موجزًا لكل تصحيح ليعلمك سبب الخطأ وكيف تتجنبه لاحقًا."},{"question":"هل يغير تَدقِيقِي أسلوبي في الكتابة؟","answer":"لا يهدف تَدقِيقِي إلى تغيير أسلوبك الشخصي. بل يركز على تصحيح الأخطاء النحوية والإملائية والرصانة اللغوية، مع الحفاظ على صوتك الخاص في التعبير."},{"question":"هل تَدقِيقِي أداة آمنة لخصوصية نصوصي؟","answer":"نحن نولي خصوصية بياناتك اهتمامًا كبيرًا. النصوص التي تقوم بتدقيقها تُعالج بشكل آمن ولا يتم تخزينها أو مشاركتها."},{"question":"هل يدعم تَدقِيقِي اللهجات العربية المحلية؟","answer":"تَدقِيقِي مصمم بشكل أساسي للغة العربية الفصحى الحديثة، ولكنه قد يساعد في تصحيح الأخطاء الشائعة في بعض النصوص المكتوبة بلهجة قريبة من الفصحى."},{"question":"ما أنواع الأخطاء التي يمكن لتَدقِيقِي اكتشافها؟","answer":"يكتشف تَدقِيقِي مجموعة واسعة من الأخطاء، منها الأخطاء النحوية (مثل عدم تطابق الفاعل والفعل)، الأخطاء الإملائية، أخطاء استخدام علامات الترقيم، والأساليب الركيكة في صياغة الجمل."}]',
        'يبحث المستخدمون عن أداة مجانية وسريعة لتصحيح الأخطاء الإملائية والنحوية في كتاباتهم لتظهر بشكل احترافي.',
        '["مدقق لغوي عربي مجاني","تصحيح الأخطاء الإملائية والنحوية أونلاين","مصحح جمل بالذكاء الاصطناعي","أداة تحسين الكتابة العربية","مدقق تركيب الجمل","مراجعة لغوية للنصوص العربية","برنامج تدقيق إملائي مجاني","تصحيح نصوص أكاديمية"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'punctuation-checker',
        'ar',
        'Punctuation Checker',
        'مدقق علامات الترقيم: تصحيح الفواصل والنقاط | AllWordTools',
        'حسن كتاباتك باحترافية! مدقق علامات الترقيم المجاني من AllWordTools يصحح الفواصل، النقط، علامات الاستفهام والتعجب، ويشرح الأخطاء لتتعلم منها. دقيق وسريع.',
        '',
        'مدقق علامات الترقيم العربي المجاني',
        'اضبط فواصلك ونقاطك وعلامات ترقيمك بمنتهى الدقة والاحترافية',
        '["علامات الترقيم هي اللمسة السحرية التي تمنح كتاباتك الوضوح والقوة. ففاصلة في غير مكانها أو نقطة ناقصة قد تغير المعنى تماماً أو تجعل النص صعب القراءة. تخيل أنك ترسل رسالة عمل أو مقالاً مهماً مليئاً بأخطاء الترقيم؛ هذا يعطي انطباعاً سلبياً عنك وعن اهتمامك بالتفاصيل. أداة تدقيق علامات الترقيم من AllWordTools.com هنا لتنهي هذه المشكلة نهائياً.","مدقق علامات الترقيم لدينا يمسح نصك بدقة متناهية، يصحح الأخطاء، ويشرح لك كل تعديل ليساعدك على فهم القواعد الكامنة وراءها. الأداة لا تغير كلماتك، بل تركز فقط على الترقيم لتضمن أن رسالتك تصل بوضوح تام. سواء كنت تكتب بريداً إلكترونياً، مقالاً، منشوراً على وسائل التواصل الاجتماعي، أو تقريراً، فإن الترقيم النظيف يعكس الاحترافية والاهتمام. استلم نسختك المصححة بالإضافة إلى قائمة بكل التعديلات لتطوير مهاراتك الكتابية، وكل هذا مجاناً وعلى متصفحك مباشرة."]',
        'كيف يعمل مدقق علامات الترقيم؟',
        '[{"title":"الصق نصك","detail":"أدخل النص العربي الذي تريد تدقيقه وتصحيح علامات الترقيم فيه."},{"title":"بدء التدقيق","detail":"اضغط على ''تدقيق علامات الترقيم'' ودع الذكاء الاصطناعي يقوم بالمراجعة الدقيقة."},{"title":"راجع التصحيحات","detail":"شاهد كل تغيير مقترح لعلامة ترقيم مع شرح موجز يوضح سبب التعديل."},{"title":"انسخ النتيجة","detail":"احصل على نسختك النهائية التي تم تصحيح ترقيمها وجاهزة للنشر أو الاستخدام."}]',
        '[{"heading":"صقل كتاباتك الأكاديمية والمهنية","paragraphs":["سواء كنت طالباً يعد بحثاً جامعياً، باحثاً يكتب مقالاً علمياً، أو محترفاً يصيغ تقارير ووثائق عمل، فإن الدقة في علامات الترقيم غير قابلة للتفاوض. أقل خطأ قد يؤثر على وضوح المعنى أو حتى مصداقية عملك. أداة AllWordTools.com تضمن لك تقديم نصوص خالية من أخطاء علامات الترقيم، مما يعكس اهتمامك بالتفاصيل ويبرز جودة محتواك الحقيقي.","فكر في الأوراق البحثية، المراسلات الرسمية، أو حتى السير الذاتية؛ جميعها تتطلب لغة سليمة وترقيماً صحيحاً يسهل القراءة والفهم. دع المدقق يقوم بالمهمة الشاقة لتحصل على نسخة مصقولة وجاهزة للتقديم بثقة كاملة، مع الحفاظ على كلماتك وأسلوبك الأصلي."]},{"heading":"لتحسين التواصل اليومي ومنشورات السوشيال ميديا","paragraphs":["حتى في مراسلاتنا اليومية ورسائلنا غير الرسمية، يمكن لعلامات الترقيم أن تصنع فارقاً كبيراً. بريد إلكتروني واضح بترقيم صحيح يضمن وصول رسالتك بدون أي لبس. منشور على فيسبوك أو تويتر بترقيم جيد يزيد من فرصة تفاعل الجمهور ويجنبك سوء الفهم الذي قد ينشأ من عبارات غامضة.","الأداة مثالية أيضاً لمنشئي المحتوى والمدونين الذين يرغبون في تقديم محتوى جذاب وسهل القراءة. لا تدع أخطاء الترقيم الصغيرة تتسبب في إبعاد جمهورك. استخدم مدقق علامات الترقيم لدينا لتتأكد من أن كل ما تكتبه، من رسالة واتساب إلى مقال مدونة طويل، يعكس صورة احترافية وواضحة."]}]',
        '[{"input":"أهلاً بك يا صديقي كيف حالك اليوم وهل أنت بخير.","output":"أهلاً بك يا صديقي، كيف حالك اليوم، وهل أنت بخير؟","note":"تم إضافة الفواصل وعلامة الاستفهام لزيادة الوضوح وتحديد نبرة السؤال."},{"input":"قال الأستاذ ان الانضباط أساس النجاح.","output":"قال الأستاذ: \"إن الانضباط أساس النجاح.\"","note":"تم إضافة النقطتين الرأسيتين وعلامتي الاقتباس لبيان القول المباشر والنقطة لإنهاء الجملة."},{"input":"يا إلهي، ما هذا المنظر الرائع.","output":"يا إلهي! ما هذا المنظر الرائع!","note":"تم استبدال الفاصلة وعلامة النقطة بعلامتي تعجب للتعبير عن الدهشة القوية."}]',
        '["راجع النص بعد التصحيح لضمان توافقه مع الأسلوب المستهدف.","لا تتردد في استخدام الأداة للمسودات الأولى، فهي توفر عليك الكثير من الوقت.","انتبه للشروحات المقدمة مع كل تصحيح لتتعلم قواعد الترقيم تدريجياً.","استخدم الأداة بانتظام لتحسين مهاراتك الكتابية وتجنب تكرار الأخطاء الشائعة."]',
        '[{"question":"هل ستغير الأداة كلماتي أو معنى النص؟","answer":"لا على الإطلاق. الأداة تركز فقط على تصحيح علامات الترقيم مثل الفواصل، النقط، وعلامات الاستفهام والتعجب، دون المساس بتركيب كلماتك أو تغيير المعنى الأصلي الذي تقصده."},{"question":"هل تعالج الأداة علامات التنصيص (الأقواس وعلامات الاقتباس)؟","answer":"نعم، الأداة مبرمجة للتعامل مع أنواع مختلفة من علامات الترقيم، بما في ذلك علامات التنصيص سواء لإبراز الاقتباسات المباشرة أو تحديد كلمات معينة."},{"question":"هل استخدام هذه الأداة مجاني؟","answer":"بالتأكيد! مدقق علامات الترقيم من AllWordTools.com مجاني تماماً ويمكنك استخدامه لأي عدد من النصوص دون أي تكلفة أو قيود."},{"question":"كم من الوقت يستغرق تدقيق النص؟","answer":"تتم عملية التدقيق فورياً. بمجرد لصق النص والضغط على زر ''تدقيق''، تحصل على النتائج في غضون ثوانٍ قليلة، حتى للنصوص الطويلة."},{"question":"هل تعمل الأداة على جميع الأجهزة والمتصفحات؟","answer":"نعم، الأداة مصممة لتكون متوافقة تماماً ومتاحة للوصول إليها من أي جهاز متصل بالإنترنت، سواء كان كمبيوتر، لوحياً أو هاتفاً ذكياً، وعبر جميع المتصفحات الرئيسية."},{"question":"هل يمكنني الاعتماد عليها في الكتابة الأكاديمية؟","answer":"نعم، الأداة دقيقة وموثوقة، وتوفر تصحيحات قائمة على قواعد اللغة العربية المعيارية. يمكن استخدامها كأداة مساعدة قوية لتحسين دقة ترقيم النصوص الأكاديمية والمهنية."}]',
        'المستخدمون العرب يبحثون عن أداة لمراجعة وتصحيح علامات الترقيم في نصوصهم العربية لتحسين جودة الكتابة رسمياً وعامياً.',
        '["مدقق علامات الترقيم","تصحيح الأخطاء الإملائية والنحوية والترقيم","تدقيق لغوي عربي مجاني","تصحيح الفاصلة والنقطة","مدقق الفواصل العربية","برنامج تصحيح علامات الترقيم","أداة تحسين الكتابة العربية","كيف أصحح الترقيم في مقالي"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'wordscapes-solver',
        'ar',
        'Wordscapes Solver',
        'حلول Wordscapes: كشف الكلمات المخفية والمكافآت بسرعة',
        'اكتشف أسرع حل للعبة Wordscapes! أدخل حروفك واكشف كل الكلمات الأساسية والمكافآت بلمح البصر. متاح مجاناً وعلى أي جهاز لمساعدتك في إنجاز المراحل الصعبة.',
        '',
        'حلول Wordscapes الفورية: لا تفوت أي كلمة مرة أخرى!',
        'أدخل الحروف واكشف عن جميع الكلمات الأساسية والمكافآت في ثوانٍ.',
        '["هل وجدت نفسك عالقًا في مستوى من Wordscapes، تحدق في عجلة الحروف دون أن تتمكن من رؤية الكلمات المشفرة؟ لا تقلق! أداة حل Wordscapes الخاصة بنا هنا لإنقاذك، وتحويل الإحباط إلى متعة الإنجاز. لقد جمعنا بين جمال المناظر الطبيعية الهادئة وألغاز الكلمات الصعبة، لكننا نعرف أن بعض المستويات يمكن أن تكون عنيدة حقًا. لا تدع لغزًا واحدًا يفسد متعتك باللعبة.","الآن، يمكنك الحصول على كل الأجوبة التي تحتاجها في لحظة. ما عليك سوى إدخال الحروف الموجودة في العجلة، وستقوم أداتنا بعرض جميع الكلمات التي يمكن تهجئتها، مرتبة حسب الطول لتناسب شبكة الكلمات المتقاطعة. الأفضل من ذلك، أنها تكشف عن الكلمات الإضافية (البونص) التي قد لا تكون في الشبكة الرئيسية ولكنها تمنحك عملات معدنية قيمة. باستخدام قائمة شاملة أمامك، يمكنك مسح الشبكة وجمع جميع الإضافات دفعة واحدة. إنها سريعة ومجانية وتعمل مباشرة في متصفحك على أي جهاز، بدون أي تنزيلات أو تسجيل."]',
        'كيفية استخدام أداة حل Wordscapes',
        '[{"title":"ابحث عن عجلة الحروف","detail":"حدد موقع عجلة الحروف الدائرية في الجزء السفلي من مستوى Wordscapes الذي تلعب فيه."},{"title":"أدخل الحروف","detail":"اكتب كل حرف من عجلة الحروف في مربع الإدخال. يمكنك استخدام علامة الاستفهام ''؟'' لأي حرف غير واضح أو مفقود."},{"title":"حل اللغز","detail":"اضغط على زر \"حل المستوى\"، وستظهر جميع الكلمات الصالحة فورًا، مرتبة حسب طول الكلمة."},{"title":"املأ الشبكة","detail":"طابق الكلمات بالفتحات الموجودة في الشبكة، ويمكنك النقر على أي كلمة لنسخها ولصقها بسهولة."}]',
        '[{"heading":"لماذا يختار اللاعبون العرب أداة حل Wordscapes هذه؟","paragraphs":["في عالم الألعاب المحمولة سريع التطور، تُعد Wordscapes من الألعاب التي نجحت في خطف أنظار الملايين، بمن فيهم اللاعبون في العالم العربي. يجد الكثيرون متعة في تحدي الكلمات ولكنهم يصطدمون أحيانًا بجدران من الصعوبة. أداتنا تقدم حلاً مثاليًا؛ فهي لا تقتصر على تقديم الإجابات فحسب، بل تساعد اللاعبين على فهم بنية الكلمات وتطوير مهاراتهم اللغوية بشكل غير مباشر من خلال الكشف عن خيارات لم تكن تخطر ببالهم.","بالإضافة إلى ذلك، فإن الطبيعة المجانية والسريعة للأداة تجعلها الخيار الأول للعديد من اللاعبين. لا حاجة لتنزيل تطبيقات إضافية تستهلك مساحة التخزين أو القلق بشأن الاشتراكات المدفوعة. يمكن لأي شخص الوصول إليها من المتصفح الخاص به على الهاتف أو الجهاز اللوحي أو الكمبيوتر، مما يضمن تجربة لعب سلسة وممتعة دون انقطاع. نحن نفهم أهمية الوصول السريع والفعال للمعلومات في ألعاب الألغاز، وقد صُممت هذه الأداة لتلبية هذه الحاجة بدقة."]},{"heading":"اكتشف الكلمات الإضافية (البونص) وعزّز نقاطك!","paragraphs":["من أهم ميزات Wordscapes هي الكلمات الإضافية، والتي غالبًا ما تكون التحدي الحقيقي. هذه الكلمات لا تكون جزءًا مباشرًا من شبكة الكلمات المتقاطعة الرئيسية، ولكنها تمنح اللاعبين عملات ذهبية قيمة ومكافآت إضافية يمكن استخدامها لشراء تلميحات أو فتح مستويات جديدة. يقوم Solver الخاص بنا بالكشف عن هذه الكلمات المخفية أيضًا، مما يمنحك ميزة تنافسية ويساعدك على تجميع ثروة من العملات داخل اللعبة.","مع أداتنا، لن تكتشف فقط الكلمات التي ستساعدك على اجتياز المستوى، بل ستتمكن أيضًا من جمع كل الكلمات الإضافية الممكنة. هذا لا يرفع من درجاتك فحسب، بل يمنحك شعوراً بالإنجاز الكامل. توقف عن البحث عن الكلمات الإضافية يدويًا وتضييع الوقت؛ دع أداتنا تقوم بالمهمة الصعبة نيابة عنك، مما يتيح لك الاستمتاع باللعبة وجمع المزيد من العملات بسهولة."]}]',
        '[{"input":"ك ر ا ب","output":"كرب، براك، كتب، ركب، برك، كابر، بكر","note":"أمثلة لكلمات عربية أصلية يمكن استخلاصها من هذه الحروف."},{"input":"ن س م ا","output":"ناس، سمان، أمس، مسن، سام، أنس، منسأ","note":"مثال آخر يوضح كيف يمكن لأداة الحل أن تجد كلمات بأطوال مختلفة."},{"input":"? ت و ب","output":"بوت، تو?، وبات، أوت، واتب","note":"استخدام علامة الاستفهام كحرف مجهول في البحث."}]',
        '["دائماً أدخل جميع الحروف الموجودة في العجلة للحصول على أفضل النتائج.","استفد من الكلمات الإضافية لجمع العملات الذهبية في اللعبة.","مرر على النتائج بسرعة وطابق الكلمات بفتحات الشبكة.","استخدم هذه الأداة كطريقة لتعلم كلمات جديدة وتحسين مفرداتك."]',
        '[{"question":"هل أداة حل Wordscapes هذه توفر الكلمات الإضافية (البونص)؟","answer":"نعم بالتأكيد! أداتنا مصممة للكشف عن جميع الكلمات الصالحة، بما في ذلك الكلمات الإضافية التي تمنحك عملات معدنية وتساعدك على التقدم في اللعبة."},{"question":"هل استخدام أداة الحل مجاني؟","answer":"نعم، أداة حل Wordscapes لدينا مجانية تمامًا للاستخدام. لا توجد رسوم أو اشتراكات مخفية أو الحاجة لتنزيل أي برامج."},{"question":"هل ستعمل هذه الأداة مع المستويات الجديدة أو التحديثات المستقبلية للعبة؟","answer":"تم بناء أداتنا على قاعدة بيانات واسعة من الكلمات الإنجليزية، وبالتالي فهي فعالة بغض النظر عن مستواك أو أي تحديثات مستقبلية للعبة Wordscapes، طالما أن الكلمات صالحة لغويًا."},{"question":"ماذا لو كان أحد الحروف في العجلة غير واضح أو يصعب قراءته؟","answer":"إذا كان هناك حرف غير واضح، يمكنك ببساطة استخدام علامة الاستفهام (?) مكانه في مربع الإدخال، وستبحث الأداة عن جميع الكلمات الممكنة بما في ذلك الحرف المجهول."},{"question":"هل أحتاج إلى تسجيل دخول أو إنشاء حساب لاستخدام الأداة؟","answer":"لا، لا تحتاج إلى تسجيل دخول أو إنشاء أي حساب. الأداة متاحة للاستخدام الفوري لجميع الزوار بدون أي متطلبات شخصية."},{"question":"هل يمكنني استخدام هذه الأداة على هاتفي المحمول أو جهاز لوحي؟","answer":"بالتأكيد! الأداة متوافقة تمامًا وتعمل بسلاسة عبر جميع الأجهزة، بما في ذلك الهواتف الذكية والأجهزة اللوحية وأجهزة الكمبيوتر، من خلال متصفح الويب الخاص بك."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في حل ألغاز لعبة Wordscapes الصعبة وتجاوز المستويات.',
        '["حل لعبة Wordscapes","مساعدة Wordscapes","غش Wordscapes","كيف أحصل على كلمات Wordscapes","مولد كلمات Wordscapes","كشف الكلمات Wordscapes","حل لغز كلمات Wordscapes","كلمات بونص Wordscapes"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'word-cookies-solver',
        'ar',
        'Word Cookies Solver',
        'حل كلمات كوكيز Word Cookies: أوجد جميع الكلمات بسهولة',
        'هل تبحث عن حل للعبة كلمات كوكيز؟ أدخل أحرفك واستكشف كل الكلمات الممكنة، بما في ذلك الكلمات الإضافية. مجاني وسريع للوصول لمستويات أعلى!',
        '',
        'حل كلمات كوكيز (Word Cookies Solver): أتقن اللعبة بكل سهولة',
        'أدخل أحرفك، احصل على كل الكلمات، وتخطى المستويات الصعبة في Word Cookies بسرعة!',
        '["هل وجدت نفسك عالقًا في أحد مستويات لعبة Word Cookies الممتعة؟ هل الأحرف التي أمامك لا تريد أن تتشكل في كلمات مفهومة؟ لا تقلق، فمُحلل كلمات كوكيز من AllWordTools.com هنا لينقذك! هذه الأداة مصممة خصيصًا لتلك اللحظات المحبطة. فقط أدخل الأحرف الظاهرة لديك على صينية الكوكيز، وسنقوم فورًا بعرض قائمة بكل الكلمات التي يمكنك تكوينها منها، مُصنّفة حسب طول الكلمة لتسهيل مطابقتها مع الفراغات في المستوى.","لعبة Word Cookies تكافئك على إيجاد الكلمات الإضافية، لذا فإن أداة الحل الخاصة بنا لا تتوقف عند الإجابات المطلوبة فقط. بل تعرض لك كل كلمة صالحة يمكن تكوينها من أحرفك، بما في ذلك الكلمات bonus التي ستملأ وعاء الكوكيز الخاص بك بالنقود. هذا يعني أنه يمكنك إنهاء المستوى وجمع كل المكافآت في مرة واحدة. الأداة سريعة، مجانية، وتعمل بالكامل في متصفحك على أي جهاز – لا تحتاج إلى تنزيل، تسجيل، أو حدود للاستخدام."]',
        'كيف تستخدم حل كلمات كوكيز؟',
        '[{"title":"اقرأ أحرف الصينية","detail":"انظر إلى دائرة الأحرف في أسفل مستوى لعبة Word Cookies."},{"title":"أدخل الأحرف","detail":"اكتب كل حرف من الصينية في المربع المخصص. استخدم علامة الاستفهام ''؟'' لأي حرف لا تستطيع قراءته بوضوح."},{"title":"احصل على الحل","detail":"اضغط على زر ''أظهر الكلمات'' وستظهر جميع الكلمات الصالحة على الفور، مصنفة حسب الطول."},{"title":"طابق وانقر","detail":"طابق الكلمات مع الفراغات في المستوى، ويمكنك النقر على أي كلمة لنسخها بسهولة."}]',
        '[{"heading":"لماذا تختار مُحلل كلمات كوكيز الخاص بنا؟","paragraphs":["كثيرون من محبي الألعاب في العالم العربي يبحثون عن أداة فعّالة لمساعدتهم في تجاوز المستويات الصعبة في ألعاب الكلمات، خاصة ''Word Cookies'' التي تتطلب تركيزًا ومخزونًا لغويًا كبيرًا. أداتنا ليست مجرد حل تقليدي، بل هي شريكك الذكي الذي يكشف لك جميع الاحتمالات الممكنة من مجموعتك الحرفية. سواء كنت تريد إنهاء المستوى بسرعة، أو تبحث عن الكلمات الإضافية لجمع العملات، فإن أداة AllWordTools.com توفر لك كل ما تحتاجه في واجهة سهلة الاستخدام.","نحن نفهم التحديات التي يواجهها اللاعبون العرب في مثل هذه الألعاب التي تعتمد على اللغة، والتي قد تكون مصممة أساسًا لجمهور يتحدث الإنجليزية. لذا، قمنا بتصميم هذه الأداة لتكون سهلة الاستخدام ومفيدة للجميع، بغض النظر عن مستوى إتقانهم للغة الإنجليزية، بحيث يمكن التركيز على متعة اللعبة بدلاً من الإحباط الناتج عن عدم إيجاد كلمة معينة. استمتع بتجربة لعب سلسة ومكافآت وفيرة!"]},{"heading":"اكتشف الكلمات المخفية وعزز نقاطك","paragraphs":["هل تعلم أن Word Cookies تكافئك بسخاء على كل كلمة إضافية تجدها؟ كثيرون يركزون فقط على الكلمات المطلوبة لتجاوز المستوى ويغفلون عن هذه الفرصة الذهبية لجمع العملات. مُحلل الكلمات الخاص بنا يبرز لك كل تلك الكلمات المخفية، مما يضمن لك أقصى استفادة من كل جولة. لن تضطر بعد الآن للبحث يدويًا أو تخمين الكلمات؛ فكل ما عليك هو إدخال الأحرف وسنقوم نحن بالباقي، لتمتلئ ''مرطبان الكوكيز'' الخاص بك بالعملات الذهبية بسرعة ودون عناء.","استخدام الأداة لا يقتصر فقط على مساعدتك في الفوز، بل يمكن أن يكون وسيلة ممتعة لتحسين مفرداتك في اللغة الإنجليزية. فبينما ترى جميع الكلمات الممكنة، قد تتعلم كلمات جديدة وتكتشف ارتباطات لم تكن تعرفها من قبل. إنها أداة مزدوجة الفائدة: مساعدة فورية في اللعبة ووسيلة غير مباشرة لتعزيز مهاراتك اللغوية. جربها الآن وشاهد الفرق!"]}]',
        '[{"input":"ل ع ب ي","output":"يَلْعَب, لَعِبَ, بَلَعَ, عَبَلَ","note":"أمثلة لأحرف عربية توضح كيف يمكن تكوين كلمات مختلفة منها."},{"input":"ك ت ب و","output":"كَتَبَ, وَكَتَبَ, كُتُب","note":"مثال يوضح كيف يمكن لأحرف بسيطة إعطاء عدة كلمات."},{"input":"ق ر أ ؟","output":"قَرَأَ, رَأَق","note":"استخدام علامة الاستفهام كحرف مجهول يعطي كلمات محتملة."}]',
        '["استخدم الأداة عندما تكون عالقًا لفترة طويلة لتوفير الوقت.","ابحث عن الكلمات الإضافية دائمًا لجمع النقاط والمكافآت.","استخدم علامة ''؟'' إذا كنت لا تستطيع قراءة حرف معين بوضوح.","حاول تكوين بعض الكلمات بنفسك قبل استخدام الأداة لتعلم أكثر."]',
        '[{"question":"كيف يعمل مُحلل كلمات كوكيز؟","answer":"بمجرد إدخال الأحرف الموجودة في لوحة اللعبة، تستخدم الأداة قاعدة بيانات ضخمة للكلمات لإنشاء وعرض جميع الكلمات الصالحة التي يمكن تكوينها من تلك الأحرف، ثم يتم تصنيفها حسب الطول."},{"question":"هل تظهر الكلمات الإضافية (Bonus Words)؟","answer":"نعم بالتأكيد! أداة الحل الخاصة بنا مصممة لإظهار كل كلمة صالحة يمكن تكوينها من أحرفك، بما في ذلك الكلمات الإضافية التي تمنحك عملات معدنية داخل اللعبة."},{"question":"هل استخدام المُحلل مجاني؟","answer":"نعم، الأداة مجانية تمامًا. يمكنك استخدامها بلا حدود ودون الحاجة للتسجيل أو دفع أي رسوم."},{"question":"هل استخدام المُحلل يعتبر غشًا (Cheating)؟","answer":"يعتمد ذلك على وجهة نظرك الشخصية. الكثيرون يستخدمونه للمساعدة في المستويات الصعبة أو لتعلم كلمات جديدة، دون أن يقلل ذلك من متعة اللعبة. الهدف هو الاستمتاع باللعبة، والأداة هنا لدعم ذلك."},{"question":"ماذا لو لم أستطع قراءة حرف معين؟","answer":"يمكنك استخدام علامة الاستفهام ''؟'' كحرف بدلًا من الحرف الذي لا تستطيع قراءته، وستحاول الأداة إيجاد الكلمات المحتملة بناءً على الأحرف المتاحة والحرف المجهول."},{"question":"هل الأداة تعمل على جميع الأجهزة؟","answer":"نعم، أداة حل كلمات كوكيز تعمل بشكل كامل في متصفحك على أي جهاز، سواء كان حاسوبًا مكتبيًا، جاهزًا لوحيًا، أو هاتفًا ذكيًا. لا حاجة لأي تنزيلات!"}]',
        'المستخدمون يبحثون عن أداة لمساعدتهم في إيجاد الكلمات الصحيحة والمخفية في لعبة كلمات كوكيز لتجاوز المستويات الصعبة وجمع المكافآت.',
        '["حل كلمات كوكيز","مساعد لعبة Word Cookies","غش كلمات كوكيز","توليد كلمات Word Cookies","إجابات لعبة الكلمات","كيف أفوز في Word Cookies","كلمات كوكيز صعبة","كل كلمات كوكيز"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'codycross-solver',
        'ar',
        'CodyCross Solver',
        'حلول CodyCross: مساعدك الذكي لحل ألغاز الكلمات المتقاطعة',
        'عالق في CodyCross؟ استخدم أداة CodyCross Solver لحل الألغاز بسرعة! أدخل الحروف المعروفة والفراغات، واحصل على الحلول الممكنة فورًا. مجاني وسهل الاستخدام.',
        '',
        'CodyCross Solver: وداعاً للألغاز المستعصية!',
        'أدخل الحروف المعروفة واحصل على الكلمة الصحيحة فورًا.',
        '["لعبة CodyCross محبوبة في العالم العربي لتصميمها الجذاب وألغازها الممتعة، لكن أحيانًا تواجهك كلمة توقف تقدمك تمامًا، وتشعر أنك بحاجة لمساعدة. هنا يأتي دور أداة CodyCross Solver من AllWordTools.com، لتكون رفيقك الأمين في تجاوز هذه التحديات وكسر حاجز الألغاز الصعبة.","تخيل أنك تملك حلاً سحريًا لكل كلمة متقاطعة مستعصية في CodyCross. أداة الحل لدينا بسيطة وفعالة: كل ما عليك فعله هو إدخال عدد الحروف في الكلمة المستهدفة، ثم ملء الحروف التي كشفتها الكلمات المتقاطعة الأخرى، وبدون أي تحميل أو تسجيل، ستحصل فورًا على قائمة بالكلمات المحتملة التي تطابق تمامًا الشكل الذي أدخلته."]',
        'خطوات حل لغز CodyCross',
        '[{"title":"عدّ المربعات","detail":"احسب عدد الحروف المطلوبة للكلمة الناقصة في CodyCross."},{"title":"أدخل النمط","detail":"اكتب الحروف التي تعرفها في مكانها المحدد، واستخدم علامة الاستفهام (؟) أو النقطة (.) أو الشرطة السفلية (_) لكل مربع فارغ."},{"title":"اضغط على Solve clue","detail":"ستظهر لك فورًا جميع الكلمات المعجمية التي تطابق هذا النمط الدقيق."},{"title":"طابق اللغز","detail":"راجع النتائج واختر الكلمة التي تناسب وصف اللغز، ثم اضغط عليها لنسخها."}]',
        '[{"heading":"لماذا أداة AllWordTools.com هي خيارك الأول لـ CodyCross؟","paragraphs":["نعلم أنك تبحث عن السرعة والدقة. كثيرًا ما نجد أنفسنا أمام كلمات متقاطعة لا يبدو لها حل، خاصة عندما تضيق الخيارات. أداة CodyCross Solver مصممة خصيصًا لتلبية هذه الحاجة الملحة، حيث تستغل نظام تشابك الشبكات في اللعبة. كلما كشفت حرفًا واحدًا من كلمة أخرى، فهذا الحرف يصبح ذهبًا! حتى حرف واحد معروف يمكن أن يقلص مئات الاحتمالات إلى عدد قليل جدًا، وتستخدم أداتنا هذه الحروف للوصول إلى الإجابة الصحيحة بسرعة مذهلة.","تختلف أداتنا عن غيرها من \"الحلول الجاهزة\" بأنها لا تعطيك فقط الإجابة، بل تمكنك من تعلم واكتشاف كلمات جديدة. لن تحتاج إلى البحث عن \"حلول CodyCross المرحلة X\"، بل ستكون سيد الموقف، تحلل اللغز بنفسك بمساعدة ذكية. تعمل الأداة بالكامل في متصفحك على أي جهاز، وهي مجانية تمامًا ولا تتطلب أي تسجيل."]},{"heading":"كيف تساعدك الحروف المتقاطعة في حل الألغاز؟","paragraphs":["في CodyCross، قوة الحل تكمن في تداخل الكلمات. عندما تحل كلمة ما، تكشف عن حرف أو أكثر في كلمة أخرى متقاطعة معها. هذه الحروف ليست مجرد مكافأة، بل هي دليل لا يقدر بثمن. على سبيل المثال، إذا كان لديك كلمة من 5 حروف وتعرف أن الحرف الثالث هو \"أ\"، فإن الخيارات الممكنة تتقلص بشكل كبير جدًا. أداتنا تفهم هذه الديناميكية وتستفيد منها إلى أقصى حد.","سواء كنت تبحث عن اسم مدينة، نوع طعام، أو صفة، فإن استخدام الحروف المتقاطعة يجعل عملية الحل أكثر ذكاءً وأسرع. لن تضطر بعد الآن للتخمين بشكل عشوائي، بل ستوجه بحثك بفعالية. حتى لو لم تكن تعرف سوى عدد الحروف، يمكن لأداتنا أن توفر لك قائمة من الكلمات التي تناسب الطول المطلوب، وكلما أضفت حرفًا معروفًا، أصبحت النتائج أكثر دقة وفائدة."]}]',
        '[{"input":"ل???و؟","output":"لحوح، لغوي","note":"مثال على كلمة تبدأ بحرف ''ل'' وتنتهي بحرف ''و'' مع فراغات في المنتصف."},{"input":"ش.ط؟","output":"شرط، شذى، شرب","note":"لغز من 3 حروف ينتهي بحرف ''ط'' أو ''ب'' والحرف الأخير مجهول، وقد يكون الحرف الثاني أي شيء."},{"input":"مخ?رج","output":"مخرج، مخرُج (اسم و فعل)","note":"كلمة من 5 حروف مع حرف مجهول في المنتصف يغير المعنى."}]',
        '["ابدأ دائمًا بالحروف التي تعرفها من الكلمات المتقاطعة الأخرى.","استخدم الرموز (? . _) للفراغات لزيادة فاعلية البحث.","إذا كانت النتائج كثيرة، حاول إيجاد حرف آخر في الكلمة لتقليصها.","تذكر أن CodyCross أحيانًا يستخدم كلمات عامية أو أسماء أعلام، لذلك قد تحتاج لإعادة تقييم الحروف المعروفة إذا لم تجد الكلمة."]',
        '[{"question":"كيف تعمل أداة CodyCross Solver؟","answer":"تستخدم الأداة الحروف التي تدخلها (المعروفة والفراغات) للبحث في قاموس شامل عن جميع الكلمات التي تطابق هذا النمط الدقيق، ثم تعرضها لك لتختار منها الإجابة المناسبة للغز."},{"question":"هل أحتاج لمعرفة موضوع اللغز (Theme)؟","answer":"لا تحتاج بالضرورة، لكن معرفة موضوع اللغز (مثل ''حيوانات''، ''فضاء''، ''طعام'') يمكن أن يساعدك في تضييق نطاق الكلمات المعروضة يدويًا بعد الحصول على النتائج."},{"question":"هل الأداة مجانية؟","answer":"نعم، أداة CodyCross Solver مجانية بالكامل ولن تحتاج لدفع أي رسوم أو التسجيل لاستخدامها."},{"question":"ماذا لو كنت أعرف فقط طول الكلمة؟","answer":"يمكنك كتابة عدد علامات الاستفهام أو النقاط (مثل ''؟؟؟؟؟'' لكلمة من 5 حروف)، وستظهر لك جميع الكلمات التي تتكون من هذا العدد من الحروف. ثم يمكنك تضييق البحث إذا عرفت أي حرف لاحقًا."},{"question":"ما هي الرموز التي تعني ''فراغ''؟","answer":"يمكنك استخدام علامة الاستفهام (؟)، النقطة (.), أو الشرطة السفلية (_) لتمثيل الأحرف المجهولة أو الفراغات في الكلمة."},{"question":"هل تعمل الأداة على جميع الأجهزة؟","answer":"نعم، تعمل الأداة بالكامل في متصفح الويب الخاص بك على أي جهاز (هاتف ذكي، تابلت، كمبيوتر مكتبي) دون الحاجة لأي تحميل."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في حل ألغاز لعبة CodyCross عندما يواجهون صعوبة في إيجاد الكلمات المناسبة.',
        '["حلول CodyCross","مساعد لعبة CodyCross","فك لغز CodyCross","تحديات CodyCross","كلمات متقاطعة CodyCross حل","أداة حل CodyCross","حل CodyCross كلمات","كيف أجد حل CodyCross"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'seven-little-words-solver',
        'ar',
        '7 Little Words Solver',
        'حل لعبة 7 كلمات: البحث عن الكلمات الطويلة والناقصة',
        'ابحث عن كلمات 7 Little Words بسرعة! أدخل طول الكلمة والحروف المعروفة لتحصل على الحلول الممكنة فورًا. أداة مجانية لمساعدتك في ألعاب الكلمات.',
        '',
        'حل لعبة 7 كلمات (7 Little Words) بكل سهولة',
        'اعثر على الكلمة الصحيحة في ثوانٍ باستخدام طول الكلمة والحروف المعروفة.',
        '["هل أنت من محبي ألعاب الكلمات وتجد صعوبة أحيانًا في إيجاد الكلمة المناسبة في لعبة 7 ليتل ووردز (7 Little Words)؟ مع أداة حل لعبة 7 كلمات، يمكنك الآن التغلب على أصعب الألغاز! هذه الأداة مصممة خصيصًا لمساعدتك في العثور على الكلمة الدقيقة التي تبحث عنها، من خلال الاستفادة من المعلومات التي تتيحها اللعبة: طول الكلمة وبعض الحروف المعروفة.","كل ما عليك فعله هو إدخال عدد الحروف في الكلمة المستهدفة، ثم كتابة أي حروف تعرفها في مكانها الصحيح. سواء كنت تبحث عن كلمة طويلة أو قصيرة، أو حتى كلمة بها حروف مبعثرة، فإن أداة حل لعبة 7 كلمات ستقوم بمسح آلاف الكلمات لتقدم لك جميع الاحتمالات المطابقة بسرعة البرق. اجعل تجربتك مع ألعاب الكلمات أكثر متعة وأقل إحباطاً!"]',
        'كيف تستخدم أداة حل 7 كلمات؟',
        '[{"title":"دون طول الكلمة","detail":"تزودك لعبة 7 كلمات دائمًا بعدد الحروف في كل إجابة. ابدأ بتسجيل هذا الرقم."},{"title":"أدخل النمط","detail":"اكتب مربعًا لكل حرف. املأ أي حروف لديك بالفعل، واستخدم علامة استفهام (؟) أو نقطة (.) أو الشرطة السفلية (_) للأماكن الفارغة."},{"title":"ابحث عن الكلمات","detail":"اضغط على زر ''البحث عن الكلمات'' لترى كل الكلمات التي تتطابق مع الطول والحروف التي أدخلتها."},{"title":"اختر الحل","detail":"قارن الكلمات الظاهرة بالدليل المعطى في اللعبة، ثم اضغط على الكلمة الصحيحة لنسخها."}]',
        '[{"heading":"تحديات 7 كلمات والحل المثالي","paragraphs":["يواجه الكثير من اللاعبين في المنطقة العربية تحديًا في لعبة 7 Little Words، خاصة عندما تكون الكلمة المطلوبة غير مألوفة أو عندما تعثر في إيجاد الحروف المتبقية. الأداة تُقدم حلاً ذكيًا يعتمد على قوة البحث وسرعة العثور على الكلمات. بدلاً من قضاء وقت طويل في التخمين، يمكنك الآن الحصول على قائمة بالكلمات المحتملة بكل سهولة.","سواء كنت تلعب على هاتفك الجوال أثناء التنقل، أو على جهازك اللوحي في المنزل، فإن أداة حل 7 كلمات تعمل بكفاءة عالية على جميع الأجهزة دون الحاجة لأي تحميلات أو تسجيل. هذا يجعلها الأداة المثالية لتعزيز تجربة لعبك وتحسين مهاراتك في إيجاد الكلمات، خاصةً مع الكلمات العربية التي قد تكون مُركبة أو ذات أبعاد متعددة."]},{"heading":"لماذا تختار أداة حل 7 كلمات من AllWordTools.com؟","paragraphs":["تم تصميم هذه الأداة بلغة عربية سلسة وواجهة سهلة الاستخدام، لضمان تجربة مثالية للمستخدمين العرب. نحن ندرك أن البحث عن الكلمات في الألعاب قد يكون مرهقًا ومستهلكًا للوقت، لذلك قمنا بتطوير حل سريع وفعال يمكنك الاعتماد عليه في أي وقت وأي مكان. كل ما تحتاجه هو اتصال بالإنترنت، ويمكنك البدء في حل الألغاز الصعبة.","بالإضافة إلى السرعة والدقة، تتميز الأداة بكونها مجانية تمامًا. لا توجد رسوم مخفية أو اشتراكات شهرية. هدفنا هو توفير أفضل مساعدة ممكنة لعشاق ألعاب الكلمات في العالم العربي. سواء كنت مبتدئًا أو لاعبًا متمرسًا، فإن أداة حل 7 كلمات ستكون رفيقك الأمثل للوصول إلى الإجابات الصحيحة وزيادة استمتاعك باللعبة."]}]',
        '[{"input":"الطول: 5، النمط: ك.ا.ب","output":"كتاب","note":"إذا كانت الكلمة تحتوي على ''ك'' في البداية و''ا'' في الوسط و''ب'' في النهاية، بطول 3 حروف، قد تكون ''كتاب''."},{"input":"الطول: 4، النمط: .ج??","output":"نجوم، نجاح","note":"للبحث عن كلمة من 4 أحرف تبدأ بحرف ''ن'' وتليها ''ج'' ثم حرفين مجهولين، ستقترح الأداة كلمات مثل ''نجوم'' أو ''نجاح''."},{"input":"الطول: 7، النمط: م....س?","output":"مقدس","note":"عند البحث عن كلمة مكونة من 7 أحرف تبدأ بحرف ''م'' وتنتهي بحرف ''س'' وحرف آخر ثم تتبعها 3 احرف مجهولة، ستظهر لك ''مقدس''."}]',
        '["ابدأ دائمًا بتدوين العدد الدقيق للحروف في الكلمة المطلوبة.","استخدم علامات (؟) أو (._) للحروف التي لا تزال مجهولة، فهذا يزيد من دقة النتائج.","إذا حصلت على عدد كبير من النتائج، حاول إدخال حرف إضافي إن أمكن لتضييق الخيارات.","تذكر أن الأداة لا تحل اللغز بالكامل، بل تقدم لك الخيارات لتناسب الدليل المعطى في اللعبة."]',
        '[{"question":"كيف تساعدني هذه الأداة في لعبة 7 كلمات؟","answer":"تساعدك هذه الأداة على إيجاد الكلمة الصحيحة في لعبة 7 كلمات عن طريق مطابقة طول الكلمة والحروف المعروفة التي تدخلها، لتقدم لك قائمة بالكلمات المحتملة من قاموس ضخم."},{"question":"هل أحتاج لإدخال كل الحروف المتاحة في اللعبة؟","answer":"لا، يكفي أن تدخل عدد حروف الكلمة المستهدفة وأي حروف تعرفها في مكانها الصحيح. لا تحتاج لإدخال الحروف المبعثرة المتاحة في اللعبة."},{"question":"هل هذه الأداة مجانية؟","answer":"نعم، أداة حل لعبة 7 كلمات مجانية بالكامل ويمكن استخدامها مباشرة من المتصفح دون أي رسوم أو اشتراكات."},{"question":"ماذا لو كنت أعرف فقط طول الكلمة؟","answer":"إذا كنت تعرف الطول فقط، يمكنك إدخاله وستظهر لك الأداة جميع الكلمات المطابقة لذلك الطول. يمكنك بعد ذلك تضييق البحث بإدخال أي حروف معروفة لاحقًا."},{"question":"ما الرموز التي أستخدمها للحروف المجهولة؟","answer":"يمكنك استخدام علامة الاستفهام (؟)، النقطة (.)، أو الشرطة السفلية (_) لتمثيل الحروف المجهولة في الكلمة."},{"question":"هل تعمل الأداة على الجوال؟","answer":"نعم، الأداة مصممة لتكون متوافقة تمامًا مع جميع الأجهزة، بما في ذلك الهواتف الذكية والأجهزة اللوحية، وتعمل مباشرة في متصفح الويب."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في حل لعبة 7 كلمات عند مواجهة صعوبة في إيجاد الكلمات الناقصة بناءً على الطول المتوفر والحروف المعروفة.',
        '["حل لعبة 7 كلمات","مساعد 7 ليتل ووردز","إيجاد كلمات 7 حروف","7 كلمات مساعدة","حل لغز 7 كلمات","البحث عن الكلمات الناقصة","7 Little Words حل","أداة حل ألعاب الكلمات"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'wheel-of-fortune-solver',
        'ar',
        'Wheel of Fortune Solver',
        'حل لعبة حظك اليوم: كشف الكلمات المخفية بسرعة',
        'اعثر على الكلمات المخفية في لعبة حظك اليوم (Wheel of Fortune). أدخل الحروف الظاهرة واحصل على الحلول فورًا. مجاني وسريع على أي جهاز.',
        '',
        'حل ألغاز حظك اليوم (Wheel of Fortune) بكل سهولة وذكاء',
        'اكشف الكلمات المخفية حرفًا بحرف',
        '["تعتمد ألغاز لعبة حظك اليوم على ملء الفراغات بالحروف التي تظهر تدريجيًا. تلك اللحظة السحرية التي يتضح فيها جزء من الكلمة ويضيء عقلك بالحل هي ما نسعى لمساعدتك على الوصول إليها بسرعة أكبر.","تساعدك أداة AllWordTools.com لحل كلمات حظك اليوم على الوصول إلى \"لحظة النور\" هذه بشكل أسرع. ما عليك سوى إدخال كلمة واحدة من اللوحة بالحروف التي ظهرت بالفعل، وستقوم الأداة على الفور بإدراج كل الكلمات التي تتناسب مع النمط. لوحات الألغاز تتكون من عدة كلمات، لذا فإن الحل يعمل كلمة بكلمة. اختر الكلمة التي أنت على وشك تخمينها، ضع علامة للخانة الفارغة لكل مربع مخفي واملأ الحروف التي ظهرت، وسيكشف لك الحل كل الكلمات المحتملة – وغالبًا ما يضيق اللوحة الطويلة إلى عبارة واضحة!"]',
        'كيف يعمل حل لعبة حظك اليوم؟',
        '[{"title":"اختر كلمة","detail":"اختر كلمة واحدة من لوحة اللعب التي ترغب في حلها."},{"title":"أدخل النمط","detail":"اكتب مربعًا لكل حرف – املأ الحروف الظاهرة واستخدم ''؟'' أو ''_'' أو ''.'' للحروف المجهولة."},{"title":"حل الكلمة","detail":"اضغط على \"حل الكلمة\" لتظهر لك كل الكلمات المطابقة فوريًا."},{"title":"أكمل العبارة","detail":"استخدم الكلمات المقترحة لتجميع اللغز كاملاً، واضغط على أي كلمة لنسخها."}]',
        '[{"heading":"لماذا استخدام أداة حل لعبة الكلمات؟","paragraphs":["في بعض الأحيان، يمكن أن يكون لغز كلمات عجلة الحظ محيرًا للغاية، خاصة عندما يكون لديك بضعة أحرف فقط ظاهرة. بدلًا من إضاعة الوقت في التخمين العشوائي، يمكن لأداتنا توفير قائمة فورية بالكلمات المحتملة التي تتناسب تمامًا مع النمط الذي أدخلته، مما يمنحك دفعة قوية في اللعبة.","تمكنك الأداة من التركيز على استراتيجيتك بدلًا من البحث عن كل الاحتمالات الممكنة. هل وجدت بعض الحروف في كلمة معقدة؟ أدخلها وشاهد كيف تتكشف الاحتمالات أمام عينيك. إنها طريقة ذكية لتعزيز فرصك في الفوز وفهم كيفية بناء الكلمات."]},{"heading":"استخدمها أثناء اللعب أو للتدريب","paragraphs":["سواء كنت تلعب \"حظك اليوم\" على جهازك المحمول، أو تشاهد البرنامج التلفزيوني وتود التحدي، أو حتى تتدرب على ألغاز الكلمات لتحسين مفرداتك، فإن هذه الأداة هي رفيقك المثالي. إنها سريعة ومجانية وتعمل بالكامل في متصفحك على أي جهاز دون الحاجة لأي تنزيلات أو تسجيل.","تساعدك هذه الأداة على التفكير مثل الفائزين. من خلال رؤية الكلمات المحتملة، لا تقوم بحل اللغز الحالي فحسب، بل تبدأ أيضًا في تطوير حدسك في تخمين الكلمات وأنماطها، مما يعزز مهاراتك اللغوية وقدرتك على حل ألغاز مستقبلية بشكل أسرع وأكثر فعالية."]}]',
        '[{"input":"ك.ت.ب","output":"كتب, كاتب, كتاب, مكتب, مكتبة","note":"أدخل نمط الكلمة مع النقاط كعلامة للحروف المجهولة (مثال: ك.ت.ب)."},{"input":"س?رة","output":"سفرة, سمرة, سحرة, سيرة","note":"يمكنك استخدام ''؟'' كحرف مجهول في أي مكان بالكلمة."},{"input":"حل_م","output":"حلم, حليم","note":"استخدام الشرطة السفلية ''_'' متاح أيضًا كبديل للفراغات."}]',
        '["ابدأ بالكلمات الأقصر أو التي تحتوي على أحرف أكثر وضوحًا.","استخدم أكبر عدد ممكن من الحروف المعروفة لتضييق نطاق البحث.","تذكر أن الكلمات قد تكون أسماء لأشخاص، أماكن، أو أشياء.","جرب أكثر من نمط بالتبديل بين علامات الفراغ لتغطية كل الاحتمالات."]',
        '[{"question":"كيف تعمل أداة حل لعبة حظك اليوم؟","answer":"تأخذ الأداة النمط الذي تدخله (بالحروف المعروفة وعلامات الفراغ للحروف المجهولة) ثم تبحث في قاعدة بياناتها الواسعة عن جميع الكلمات العربية المطابقة لهذا النمط، وتعرضها لك فورًا."},{"question":"هل يمكنها حل عبارة كاملة مرة واحدة؟","answer":"لا، الأداة مصممة لحل كلمة واحدة في كل مرة. لوحات الألغاز غالبًا ما تكون عبارة عن جملة تتكون من عدة كلمات، لذا ستحتاج إلى إدخال كل كلمة بشكل منفصل."},{"question":"هل هذه الأداة مجانية؟","answer":"نعم، أداة حل لعبة حظك اليوم مجانية تمامًا 100% ولا تتطلب أي تسجيل أو اشتراكات."},{"question":"ماذا لو لم يظهر سوى حرف واحد فقط؟","answer":"يمكنك استخدام الأداة بالرغم من ذلك. أدخل الحرف الوحيد، وضع علامات الفراغ للحروف المجهولة الأخرى. كلما زادت الحروف التي توفرها، كان البحث أكثر دقة وقلت الخيارات."},{"question":"ما هي الرموز التي يمكنني استخدامها للفراغات (الحروف المجهولة)؟","answer":"يمكنك استخدام علامة الاستفهام (؟)، أو الشرطة السفلية (_)، أو النقطة (.) لتمثيل الحروف المجهولة في النمط الذي تدخله."},{"question":"هل تعمل الأداة على أي جهاز؟","answer":"نعم، الأداة تعمل في متصفح الويب على أي جهاز (هاتف ذكي، تابلت، كمبيوتر مكتبي) دون الحاجة لتنزيل أي برامج."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في حل ألغاز الكلمات في الألعاب الشهيرة مثل حظك اليوم.',
        '["حل لعبة حظك اليوم","مساعد لعبة كلمات الحظ","كشف كلمة عجلة الحظ","أداة حل كلمات مبعثرة","مساعدة في ألغاز الكلمات","كيف أحل لعبة حظك اليوم","تخمين كلمات عجلة الحظ","أداة كشف الحروف المخفية"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'letter-pattern-finder',
        'ar',
        'Letter Pattern Finder',
        'حل الكلمات المتقاطعة والبحث بالأنماط | AllWordTools',
        'ابحث عن كلمات عربية تناسب أي نمط! استخدم أدواتنا للعثور على الكلمات المفقودة في ألعاب الكلمات المتقاطعة، ووصلة، وكلمة السر، والمزيد. اكتشف الكلمات بسهولة بفضل بحثنا السريع والفريد.',
        '',
        'أداة البحث عن الكلمات بالنمط (Letter Pattern Finder)',
        'اكتشف الكلمات العربية التي تناسب أي نمط تحدده أنت!',
        '["هل تجد صعوبة في حل ألغاز الكلمات المتقاطعة، أو ألعاب مثل ''وصلة'' و ''كلمة السر'' التي تتطلب العثور على كلمات معينة بناءً على حروف متوفرة ومواقع محددة؟ أداة البحث عن الكلمات بالنمط من AllWordTools.com هي الحل الأمثل لك. تتيح لك هذه الأداة القوية إنشاء قالب بحث فريد يجمع بين الحروف المعلومة وعلامات الاستفهام للحروف المجهولة المفردة، والنجمة لأي سلسلة من الحروف، لتمكينك من الكشف عن الكلمات الدقيقة التي تحتاجها.","تختلف هذه الأداة عن أدوات البحث التقليدية مثل ''كلمات تبدأ بـ'' أو ''كلمات تحتوي على'' أو ''كلمات تنتهي بـ''؛ فهي تمنحك مرونة غير مسبوقة لوصف شكل الكلمة بالكامل. سواء كنت تبحث عن كلمة قصيرة مثل '' س؟ر '' أو كلمة طويلة ومعقدة مثل '' ب*ت ''، فإن محرك البحث لدينا يجوب قاموسًا عربيًا ضخمًا ليقدم لك كل الكلمات المطابقة، مصنفة حسب طولها. الأداة سريعة، مجانية، وخاصة، تعمل على متصفحك مباشرةً دون الحاجة للتسجيل أو أي قيود."]',
        'كيف تستخدم أداة البحث عن الكلمات بالنمط',
        '[{"title":"ابنِ نمطك الخاص","detail":"اكتب الحروف التي تعرفها، واستخدم علامة ''؟'' لحرف واحد مجهول، وعلامة ''*'' لأي عدد من الحروف المتتالية المجهولة."},{"title":"حدد الطول (اختياري)","detail":"أضف طولًا دقيقًا لتقليص النتائج، خاصةً عند استخدام علامة ''*'' أو الأنماط الطويلة."},{"title":"ابحث عن النمط","detail":"اضغط على زر ''ابحث عن النمط'' للبحث في قاموسنا الهائل واكتشاف كل كلمة مطابقة، مصنفة حسب طول الحروف."},{"title":"انسخ ما تحتاجه","detail":"اضغط على أي كلمة لنسخها فورًا. ستجد نقاطها في لعبة سكرابل (إن وجدت) معروضة بجانبها."}]',
        '[{"heading":"صديقك الأمثل في ألعاب الكلمات","paragraphs":["سواء كنت من محبي حل الكلمات المتقاطعة اليومية، أو تتحدى أصدقائك في ألعاب مثل ''وصلة'' و ''كلمة السر''، أو حتى ''الحروف المبعثرة''، فإن هذه الأداة مصممة لتكون مساعدك الشخصي. انسَ البحث اليدوي الطويل أو الاستعانة بالزملاء؛ فبضع نقرات فقط ستكشف لك عن الكلمات المخفية التي طالما بحثت عنها. سهولة الاستخدام والسرعة الفائقة تجعل منها الخيار الأول لكل محبي ألعاب الكلمات في العالم العربي.","تساعدك الأداة على توسيع مفرداتك العربية أيضًا. عندما تواجه كلمة لا تعرفها، يمكنك استخدام النمط للبحث عنها ورؤية الكلمات المشابهة. هذا لا يساعدك فقط على الفوز في الألعاب، بل يعزز أيضًا قدرتك اللغوية ويغني قاموسك الشخصي. لا تتردد في استخدامها كأداة تعليمية وترفيهية في آن واحد، ومشاركتها مع أصدقائك."]},{"heading":"أداة قوية للباحثين والطلاب","paragraphs":["بالإضافة إلى الألعاب، يمكن أن تكون هذه الأداة ذات قيمة كبيرة للطلاب والباحثين في اللغة العربية. إذا كنت تعمل على تحليل نصوص أو تبحث عن كلمات تتبع بنية صرفية معينة، فإن إمكانيات البحث المتقدمة لدينا توفر لك طريقة سريعة وفعالة لاستخراج هذه الكلمات من قاموسنا. يمكن لمعلمي اللغة العربية أيضًا استخدامها لمساعدة طلابهم في فهم بناء الكلمات وقواعد الإملاء.","تخيل أنك تبحث عن كل الكلمات العربية التي تتكون من ثلاثة أحرف وتبدأ بحرف السين وتنتهي بالراء، أو الكلمات التي تحتوي على الواو والتاء في أي مكان وبأي ترتيب. أداة البحث عن الكلمات بالنمط تجعل هذا البحث المعقد بسيطًا ومباشرًا. بفضل مرونتها الفائقة، يمكنك استكشاف ثراء اللغة العربية بطرق لم تتخيلها من قبل، مما يعزز فهمك للغة وتطبيقاتها."]}]',
        '[{"input":"ك؟ل","output":"كل، كبل، كحل، كسل، كفل، كمل","note":"للبحث عن كلمات عربية من ثلاثة أحرف تبدأ بكاف وتنتهي بلام، مع حرف مجهول في المنتصف."},{"input":"س*م","output":"سلم، سلام، سليم، استسلم، سِجام","note":"لإيجاد كلمات عربية تبدأ بالسين وتنتهي بالميم، بغض النظر عن عدد الحروف في الوسط."},{"input":"*ال؟","output":"هلال، جلال، خلال، تلال، مثال","note":"للعثور على كلمات عربية تنتهي باللام المتبوعة بحرف واحد مجهول (مثل الألف واللام المتبوعة بحرف)، ومسبوقة بأي حروف."}]',
        '["استخدم ''؟'' للحرف المجهول الواحد فقط، و ''*'' لأي عدد من الحروف المجهولة.","حدد طول الكلمة لضمان الحصول على نتائج أكثر دقة عند استخدام علامة النجمة.","يمكنك دمج الحروف المعروفة مع ''? '' و ''*'' في أي ترتيب داخل النمط.","لا تتردد في تجربة أنماط مختلفة؛ اكتشاف الكلمات الجديدة ممتع ومفيد."]',
        '[{"question":"ما الفرق بين ''؟'' و ''*'' في البحث؟","answer":"علامة ''؟'' تمثل حرفًا واحدًا فقط مجهولًا، بينما علامة ''*'' تمثل أي عدد من الحروف المجهولة المتتالية (يمكن أن تكون صفرًا أو أكثر)."},{"question":"هل يمكنني استخدام علامات أخرى مثل النقاط أو الشرطات (_) للحروف المجهولة؟","answer":"لا، في أداتنا الحالية، نستخدم علامة الاستفهام ''؟'' لحرف واحد مجهول وعلامة النجمة ''*'' لأي عدد من الحروف المجهولة فقط لضمان دقة البحث."},{"question":"كيف تختلف هذه الأداة عن ''حل الكلمات المتقاطعة'' المعتاد؟","answer":"أداة حل الكلمات المتقاطعة غالبًا ما تركز على مطابقة الكلمات المتقاطعة بناءً على عدد الحروف والمواقع. هذه الأداة ''Letter Pattern Finder'' أكثر مرونة، حيث تسمح لك ببناء نمط حرفي معقد لأي كلمة، بغض النظر عن سياق الكلمات المتقاطعة، مما يمنحك تحكمًا أكبر في البحث."},{"question":"هل الأداة مفيدة لحل ألغاز الكلمات المتقاطعة أو لغز ''وصلة''؟","answer":"نعم، إنها مفيدة جدًا! هذه الأداة مصممة خصيصًا لمساعدتك في حل ألغاز الكلمات المتقاطعة وألعاب مثل ''وصلة'' و ''كلمة السر'' من خلال إيجاد الكلمات التي تناسب الأنماط المعقدة مع الحروف المفقودة."},{"question":"هل هذه الأداة مجانية للاستخدام؟","answer":"بالتأكيد، الأداة مجانية تمامًا ولا تتطلب أي تسجيل أو دفع. يمكنك استخدامها بلا حدود وفي أي وقت."},{"question":"هل يدعم القاموس المستخدم في البحث الكلمات العامية أو اللهجات المحلية؟","answer":"يركز القاموس المستخدم بشكل أساسي على اللغة العربية الفصحى والكلمات الشائعة والمعترف بها. قد لا تتضمن بعض الكلمات العامية أو اللهجات المحلية الضيقة."}]',
        'يبحث المستخدمون عن أداة سريعة وفعالة لإيجاد كلمات عربية مطابقة لأنماط معقدة للمساعدة في حل الألعاب أو التحديات اللغوية.',
        '["البحث عن الكلمات بالنمط","حل الكلمات المتقاطعة العربية","مساعد لعبة وصلة","إيجاد كلمات بنمط معين","قاموس الكلمات العربية للالعاب","البحث عن كلمات مفقودة","الكلمات المتقاطعة حل","أداة البحث عن كلمات الألغاز"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'wildcard-solver',
        'ar',
        'Wildcard Solver',
        'حل حروف ناقصة: بحث ذكي بالرموز البديلة (Wildcard Solver)',
        'ابحث عن الكلمات المفقودة أو الناقصة باستخدام أدواتنا السحرية للبحث بالرموز البديلة (?, *). مجاني، سريع، ومثالي لألعاب الكلمات مثل سكرابل وكلمات كراش.',
        '',
        'حل حروف ناقصة: ابحث عن الكلمات بذكاء باستخدام الرموز البديلة',
        'أداة سريعة ومجانية للعثور على الكلمات باستخدام علامات الاستفهام (*) و (?)',
        '["هل تبحث عن كلمة معينة ولكن تعرف بعض أحرفها فقط؟ أداة حل الحروف الناقصة هي رفيقك الأمثل! استخدم علامات الاستفهام (?) لتمثيل حرف واحد مجهول، والنجمة (*) لأي عدد من الحروف (بما في ذلك لا شيء). هذه الأداة لا تقدر بثمن عندما تحتاج إلى ملء الفراغات في ألعاب الكلمات مثل سكرابل، كلمات كراش، أو حتى عند تعلم اللغة.","مع أداتنا، يمكنك البحث عن كلمات تبدأ وتنتهي بسلسلة معينة من الحروف، أو الكلمات التي تحتوي على مجموعة حروف في المنتصف، أو حتى استكشاف كل الاحتمالات لتبديل خانات فارغة. اكتب النمط الذي تريده، وستظهر لك جميع النتائج المتطابقة فورًا، مصنفة حسب الطول. إنها مجانية بالكامل، وسريعة، وتعمل في متصفحك على أي جهاز دون الحاجة للتسجيل أو فرض قيود."]',
        'كيف تستخدم أداة حل الحروف الناقصة؟',
        '[{"title":"اكتب الحروف المعروفة","detail":"أدخل الحروف التي تعرفها في الأماكن الصحيحة داخل النمط."},{"title":"أضف الرموز البديلة","detail":"استخدم \"?\" لحرف واحد مجهول و \"*\" لأي عدد من الحروف (بما في ذلك لا شيء)."},{"title":"اضغط بحث","detail":"انقر على \"ابحث بالرموز البديلة\" وستظهر لك جميع الكلمات المتطابقة مصنفة حسب الطول."},{"title":"انسخ الكلمة","detail":"اضغط على أي كلمة من النتائج لنسخها مباشرة إلى الحافظة لديك."}]',
        '[{"heading":"استخدامات متعددة لأداة حل الحروف الناقصة","paragraphs":["أداة البحث بالرموز البديلة ليست فقط لألعاب الكلمات، بل هي أداة قوية لكل من يتعامل مع اللغة. يمكن استخدامها في تعلم اللغة العربية، حيث تساعدك على استكشاف الكلمات المختلفة التي يمكن أن تتكون من مجموعة معينة من الحروف، أو لإيجاد مرادفات أو كلمات ذات صلة عند معرفة جزء منها.","كما أنها مفيدة جدًا للكتّاب أو الباحثين الذين يحاولون تذكر كلمة معينة فقدوا جزءًا منها، أو لمن يرغب في استكشاف أنماط الكلمات اللغوية. إن مرونتها في البحث تجعلها أداة لا غنى عنها في الكثير من السيناريوهات اليومية والدراسية."]},{"heading":"تخلص من حيرة ألعاب الكلمات إلى الأبد","paragraphs":["إذا كنت من عشاق ألعاب الكلمات مثل \"كلمات كراش\"، \"سكرابل\"، أو \"وصلة\"، فستجد في أداة حل الحروف الناقصة صديقك المفضل. غالبًا ما تواجه مربعات فارغة أو تحتاج إلى إكمال كلمة ناقصة. باستخدام (?) و (*)، يمكنك فتح احتمالات لا نهاية لها وإيجاد الحلول بسرعة البرق.","لا تضيع وقتك في التحديق في الشاشة أو تجربة كل الاحتمالات الممكنة يدويًا. أدخل النمط الذي لديك، ودع أداتنا تقوم بالعمل الشاق نيابة عنك، لتمنحك ميزة تنافسية وتجعل تجربة اللعب أكثر متعة وسهولة."]}]',
        '[{"input":"كتا?ب","output":"كتابة، كتابة،... (كلمات مثل: كتابة، كتابات، كتائب)","note":"للبحث عن كلمات مكونة من 5 أحرف حيث الحرف الرابع مجهول (مثل \"كتاب\" أو \"كتائب\")."},{"input":"لغز*","output":"لغز، لغز،... (كلمات مثل: لغز، ألغاز، لغزية)","note":"للبحث عن أي كلمة تبدأ بـ \"لغز\" بغض النظر عن طولها."},{"input":"*?ين*","output":"عين، دين،... (كلمات مثل: ثلاين، عاين، تلوين، يمين)","note":"للبحث عن كلمات تحتوي على حرف مجهول يتبعه \"ين\"، في أي مكان بالكلمة."}]',
        '["استخدم \"?\" لحرف واحد فقط: مثالي لملء الفراغات الدقيقة.","استخدم \"*\" لمرونة قصوى: يطابق صفر أو أكثر من الأحرف.","اجمع بين الرمزين: لإنشاء أنماط بحث معقدة ودقيقة.","جرب كلماتك العربية: الأداة تدعم البحث باللغة العربية بطلاقة."]',
        '[{"question":"ما هو الفرق بين الرمزين \"?\" و \"*\" في البحث؟","answer":"علامة الاستفهام (?) تمثل حرفًا واحدًا مجهولًا بالضبط. أما النجمة (*) فتمثل أي عدد من الأحرف المجهولة، بما في ذلك لا شيء على الإطلاق، مما يعني أنها يمكن أن تطابق كلمة أقصر أو أطول."},{"question":"هل يمكنني استخدام أكثر من رمز بديل في نفس الكلمة؟","answer":"بالتأكيد! يمكنك استخدام علامات استفهام و/أو نجوم متعددة في نفس النمط لإنشاء عمليات بحث معقدة ومرنة جدًا."},{"question":"هل النجمة (*) تطابق صفر حرف؟","answer":"نعم، النجمة (*) مرنة للغاية بحيث يمكنها أن تطابق صفر حرف. هذا يعني إذا كتبت ''كلمة*''، فستجد ''كلمة'' بالإضافة إلى ''كلمات'' و ''كلماتك'' وهكذا."},{"question":"هل أداة حل الحروف الناقصة مجانية؟","answer":"نعم، الأداة مجانية بالكامل. لا توجد رسوم أو اشتراكات أو قيود على عدد مرات البحث."},{"question":"هل هذه الأداة مفيدة لألواح سكرابل الفارغة؟","answer":"بالتأكيد! إنها مثالية لألواح سكرابل الفارغة. يمكن لكل من علامة الاستفهام (?) والنجمة (*) تمثيل البلاط الفارغ، مما يساعدك على إيجاد أفضل الكلمات والنقاط المحتملة."},{"question":"هل تعمل هذه الأداة مع الكلمات العربية؟","answer":"نعم، تم تصميم الأداة لتدعم البحث عن الكلمات العربية بفعالية. يمكنك إدخال الحروف العربية والرموز البديلة للحصول على نتائج مطابقة من قاموسنا العربي الشامل."}]',
        'المستخدمون يبحثون عن أداة سريعة ومجانية لإيجاد الكلمات المفقودة أو المتقطعة باستخدام أنماط معينة في ألعاب الكلمات أو لتعلم اللغة.',
        '["حل كلمات ناقصة","بحث بالاحرف الناقصة","فك رموز الكلمات","الحروف المفقودة في الكلمات","برنامج البحث عن الكلمات","حل كلمات كراش","سكرابل أحرف ناقصة","مولد كلمات من حروف"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'pattern-solver',
        'ar',
        'Pattern Solver',
        'حلّ الكلمات المفقودة: أداة البحث عن الكلمات بالنمط',
        'ابحث عن كلمات تناسب أي نمط محدد في ثوانٍ! أدخل الحروف المتوفرة وعلامات الاستفهام للفراغات. مثالية لحل الكلمات المتقاطعة والألغاز وألعاب الكلمات.',
        '',
        'أداة حلّ الأنماط: اكتشف الكلمات الناقصة بسهولة',
        'أدخل الحروف المعروفة وعلامات الاستفهام للفراغات لتجد كل الكلمات المطابقة.',
        '["هل تجد نفسك عالقاً في لعبة كلمات متقاطعة؟ هل حصلت على بعض الحروف المبعثرة وتريد إيجاد الكلمة الكاملة؟ لا تبحث بعيدًا! خدمة \"حل الأنماط\" هي أداتك المثالية للعثور على أي كلمة مفقودة بأسرع وقت وأقل جهد. سواء كنت تتحدّى صديقًا في لعبة كلمات، أو تحاول إكمال لغز صعب، هذه الأداة مصممة خصّيصًا لمساعدتك.","ما يميز هذه الأداة هو دقتها ومرونتها. ما عليك سوى إدخال الحروف التي تعرفها بالضبط في مكانها الصحيح، واستخدام رمز خاص لكل فراغ أو حرف مجهول. ستجد الأداة فورًا كل الكلمات المطابقة للطول والنمط الذي أدخلته، لتمنحك حلولًا واضحة وسهلة الاختيار. إنها مجانية بالكامل، تعمل مباشرة في متصفحك، ولا تتطلب أي تسجيل أو تحميل."]',
        'كيفية استخدام أداة حلّ الأنماط:',
        '[{"title":"اكتب الحروف التي تعرفها","detail":"أدخل الحروف الثابتة في مكانها الدقيق داخل الكلمة. مثلاً: ك؟اب."},{"title":"ضع علامة لكل فراغ","detail":"استخدم \"؟\" أو \"_\" أو \".\" لكل مربع مجهول. يمثل الرمز الواحد حرفًا واحدًا فقط."},{"title":"حل النمط","detail":"اضغط على \"حل النمط\" وستظهر كل الكلمات التي تتناسب مع الطول والنمط المطلوب فورًا."},{"title":"انسخ إجابتك","detail":"انقر على أي نتيجة لنسخها على الفور، لتكون جاهزة لاستخدامها في لغزك أو لعبتك."}]',
        '[{"heading":"مثالية لجميع ألعاب و ألغاز الكلمات","paragraphs":["سواء كنت من محبي الكلمات المتقاطعة اليومية، أو تتحدى أصدقاءك في ألعاب مثل \"كلمات كراش\" أو \"فوازير و ألغاز\"، فإن أداة حل الأنماط هي رفيقك الأمثل. توفر لك حلولًا دقيقة وسريعة لمساعدتك على تجاوز أصعب المراحل. لن تضطر بعد الآن لقضاء ساعات في محاولة فك رموز الكلمات الغامضة، بل ستجد الكلمة المناسبة في لحظات.","تم تصميم الأداة لتكون سهلة الاستخدام وفي متناول الجميع، بغض النظر عن مستوى خبرتهم في ألعاب الكلمات. كل ما تحتاجه هو معرفة بسيطة بالحروف المتوفرة، وستقوم الأداة بالباقي. استمتع بتجربة لعب سلسة وممتعة مع كل لغز وكل كلمة."]},{"heading":"أداتك المجانية لحل أي نمط كلمة","paragraphs":["نحن نؤمن بأن الوصول إلى أدوات مساعدة الكلمات يجب أن يكون مجانيًا وسهلًا. لهذا، نقدم لك هذه الأداة المتطورة دون أي تكلفة أو اشتراك. يمكنك استخدامها في أي وقت، ومن أي جهاز، سواء كان هاتفك الذكي أو جهازك اللوحي أو حاسوبك المكتبي. كل ما تحتاجه هو اتصال بالإنترنت، وستكون جاهزًا للبدء.","لا تقتصر فائدة هذه الأداة على التسلية فحسب، بل يمكن أن تكون أيضًا وسيلة رائعة لتعلم كلمات جديدة وتوسيع مفرداتك. فكلما استخدمتها لحل الألغاز، ستتعرض لمجموعة أوسع من الكلمات، مما يثري حصيلتك اللغوية بشكل طبيعي وممتع."]}]',
        '[{"input":"ك؟اب","output":"كتاب، كباب، كلاب","note":"للبحث عن كلمات من 3 حروف تبدأ بالكاف وتنتهي بالباء."},{"input":"؟؟ل","output":"أكل، أمل، أجل، عمل، غزل، نزل، حلل","note":"لإيجاد جميع الكلمات ذات الثلاثة أحرف التي تنتهي بحرف اللام."},{"input":"س.ف.ر","output":"سفر، سهر، سكر، صبر","note":"للبحث عن كلمات من 4 حروف تبدأ بالسين وتنتهي بالراء، مع حرفين مجهولين في الوسط."}]',
        '["استخدم \"؟\" للحروف المجهولة لمزيد من المرونة.","تأكد من عدد علامات الاستفهام ليتطابق مع طول الكلمة المطلوبة.","جرب حروفًا مختلفة في الأماكن الثابتة إذا لم تجد الكلمة.","استخدم هذه الأداة لتعلم كلمات جديدة وتوسيع مفرداتك."]',
        '[{"question":"ما هي أداة حلّ الأنماط؟","answer":"إنها أداة تساعدك على إيجاد الكلمات التي تناسب نمطًا معينًا من الحروف المعروفة والفراغات. كل فراغ يمثل حرفًا واحدًا."},{"question":"ما هي الرموز التي يمكنني استخدامها للفراغات؟","answer":"يمكنك استخدام علامة الاستفهام (؟)، أو الشرطة السفلية (_)، أو النقطة (.) لتمثيل كل حرف مجهول. كل رمز منها يمثل حرفًا واحدًا بالضبط."},{"question":"ما الفرق بين هذه الأداة ومحلل أحرف البدل (Wildcard Solver)؟","answer":"تختلف هذه الأداة عن محلل أحرف البدل بأنها تبحث عن كلمات ذات طول ثابت ومحدد بدقة، حيث يمثل كل فراغ حرفًا واحدًا. بينما محلل أحرف البدل قد يبحث عن كلمات بأطوال مختلفة وبأنماط أوسع للفراغات."},{"question":"هل أداة حلّ الأنماط مجانية؟","answer":"نعم، هذه الأداة مجانية بالكامل. لا تتطلب أي تسجيل دخول أو تحميل برامج، ويمكنك استخدامها متى شئت."},{"question":"هل يمكنني استخدامها لحل الكلمات المتقاطعة؟","answer":"بالتأكيد! إنها مثالية تمامًا لحل الكلمات المتقاطعة، حيث يمكنك إدخال الحروف الموجودة ووضع علامات الاستفهام للفراغات للحصول على الكلمة الصحيحة."},{"question":"هل تعمل الأداة على جميع الأجهزة؟","answer":"نعم، تعمل الأداة مباشرة في متصفحك على أي جهاز، سواء كان هاتفك الذكي، جهازك اللوحي، أو حاسوبك الشخصي، طالما لديك اتصال بالإنترنت."}]',
        'يبحث المستخدمون العرب عن أداة سريعة ومجانية لإيجاد الكلمات الناقصة في الألغاز والألعاب بناءً على حروف وتصميم معروفة.',
        '["حل كلمات متقاطعة","البحث عن كلمة مفقودة","مكمل الكلمات","حل الألغاز بالحروف","أداة البحث عن الكلمات","كلمات من حروف و فراغات","مساعدة ألعاب الكلمات","إيجاد كلمات بالنمط"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'missing-letters-finder',
        'ar',
        'Missing Letters Finder',
        'حل الكلمات الناقصة | أداة إيجاد الحروف المفقودة بسهولة',
        'اعثر على الكلمات المفقودة في الألغاز وتمارين الإملاء بسهولة! أدخل الحروف المتوفرة، واستخدم الشرطة أو علامة الاستفهام للحروف الناقصة، وسنظهر لك جميع الكلمات المحتملة.',
        '',
        'أداة إيجاد الحروف المفقودة للكلمات العربية',
        'أكمل أي كلمة بسرعة وسهولة! أدخل الحروف المعروفة واحصل على الكلمات الصحيحة.',
        '["هل تواجه صعوبة في تذكر كلمة معينة؟ هل علقت في لغز كلمات متقاطعة أو تمرين إملاء لعدم معرفة بعض الحروف؟ لا تقلق! أداة إيجاد الحروف المفقودة مصممة خصيصًا لمساعدتك في إكمال الكلمات الناقصة بسهولة وذكاء. مهما كانت الكلمة الغامضة، ستساعدك أداتنا على الكشف عنها بنقرة زر.","استخدم هذه الأداة المجانية للعثور على الكلمات التي تناسب الحروف المتوفرة لديك مع ملء الفراغات بالحروف المجهولة. كل ما عليك هو إدخال الحروف التي تعرفها وترك علامة لكل حرف ناقص، وستعرض لك الأداة جميع الاحتمالات الصحيحة من قاموسنا العربي الشامل. إنها مثالية للمذاكرة، الألغاز، أو حتى إذا كنت تريد فقط تذكر كلمة معينة!"]',
        'كيف تستخدم أداة إيجاد الحروف المفقودة؟',
        '[{"title":"أدخل الحروف المعروفة","detail":"اكتب الحروف التي تعرفها في مواقعها الصحيحة ضمن الكلمة."},{"title":"ضع علامة لكل حرف ناقص","detail":"استخدم \"_\" أو \"?\" لتمثيل كل حرف مفقود. كل رمز يعادل حرفًا واحدًا."},{"title":"اكتشف الكلمات","detail":"اضغط على زر \"اكتشف الكلمات\" لتظهر لك جميع الكلمات التي تتطابق مع مدخلاتك."},{"title":"راقب الحروف المكتشفة","detail":"الحروف التي تم ملؤها تلقائيًا ستكون مميزة لتراها بوضوح وتتعرف على ما كان مفقودًا."}]',
        '[{"heading":"مساعدك الشخصي في الألغاز والكلمات المتقاطعة","paragraphs":["لطالما كانت الألغاز الذهنية مثل الكلمات المتقاطعة وكلمات السر من الهوايات المحببة في العالم العربي. لكن ماذا تفعل عندما تعلق عند كلمة معينة ولا تستطيع تذكر بعض حروفها؟ أداتنا هي الحل الأمثل! بدلاً من البحث لساعات أو الاستسلام، يمكنك إدخال الحروف المتوفرة، وستتولى الأداة مهمة إيجاد الإجابة الصحيحة.","تخيل أنك تلعب مع الأصدقاء وتواجه كلمة صعبة، أو تحاول إكمال لغز جريدة الصباح. هذه الأداة لن تساعدك فقط في إيجاد الكلمة، بل ستعلمك أيضًا الحروف الناقصة، مما يجعلك أكثر تمكنًا في المرة القادمة. وداعًا للإحباط، ومرحباً بالانتصارات في عالم الألغاز!"]},{"heading":"تعلّم الإملاء العربي وتحسين مفرداتك","paragraphs":["بالنسبة لطلاب اللغة العربية، أو أي شخص يرغب في تحسين إملائه ومفرداته، تعد الأداة قيمة لا تقدر بثمن. يمكنك استخدامها كتدريب إملائي شخصي. جرب كتابة جزء من كلمة تعرفها واسمح للأداة بتعبئة الفراغات، ثم لاحظ الحروف الناقصة. هذه الطريقة التفاعلية تساعد على تثبيت الكلمات في الذهن بشكل أفضل من الطرق التقليدية.","كما أنها مفيدة لتوسيع قاموسك اللغوي. عندما تتعثر في كلمة، لا يقتصر الأمر على إيجاد الحل فحسب، بل يتم تسليط الضوء على الحروف المضافة، مما يساعدك على فهم كيفية بناء الكلمات والجذور اللغوية. إنها ليست مجرد أداة لإيجاد الحلول، بل هي رفيق تعليمي لغوي مفيد ومجاني."]}]',
        '[{"input":"ك_اب","output":"كتاب","note":"لإيجاد كلمة \"كتاب\" بوجود حرف الكاف والألف والباء مع حرف مفقود في الوسط."},{"input":"م_ك_بة","output":"مكتبة","note":"للبحث عن كلمة \"مكتبة\" عند معرفة بعض الحروف وموقع حرفين مفقودين."},{"input":"س?فر","output":"سفر","note":"يمكنك استخدام علامة الاستفهام \"?\" بدلاً من الشرطة السفلية \"_\" للحروف الناقصة."}]',
        '["تأكَّد من إدخال الحروف المعروفة في أماكنها الصحيحة تمامًا.","استخدم رمزًا واحدًا ( _ أو ؟ ) لكل حرف مفقود، حتى لو لم تكن تعرف عدد الحروف الدقيق.","جرب تغيير موقع الحروف المفقودة إذا لم تحصل على النتائج المرجوة.","الأداة تدعم الكلمات العربية القياسية، لذا قد لا تجد بعض الكلمات العامية جدًا."]',
        '[{"question":"ماذا تفعل أداة إيجاد الحروف المفقودة؟","answer":"تساعدك الأداة على إكمال الكلمات الناقصة. تدخل الحروف التي تعرفها وتضع علامة للحروف المجهولة، ثم تبحث لك الأداة عن الكلمات الصحيحة التي تناسب هذه النمط."},{"question":"كيف أشير إلى الحرف المفقود؟","answer":"يمكنك استخدام علامة الشرطة السفلية \"_\" أو علامة الاستفهام \"?\" لتمثيل كل حرف مفقود. كل رمز يشير إلى حرف واحد."},{"question":"لماذا يتم تلوين بعض الحروف بعد البحث؟","answer":"الحروف الملونة هي الحروف التي تم إكمالها بواسطة الأداة. هذا يساعدك على رؤية الحروف المفقودة بسهولة وتحديد الكلمة بشكل أسرع."},{"question":"هل الأداة مفيدة لتحسين الإملاء العربي؟","answer":"نعم، بالتأكيد! يمكنك استخدامها للتدريب على الكلمات التي يصعب عليك تهجئتها. أدخل جزءًا من الكلمة ودع الأداة تكملها لتتعلم الحروف الصحيحة."},{"question":"هل أحتاج إلى التسجيل أو دفع رسوم لاستخدام الأداة؟","answer":"لا، أداة إيجاد الحروف المفقودة مجانية تمامًا ولا تتطلب أي تسجيل دخول أو دفع رسوم. يمكنك استخدامها مباشرة من متصفحك."},{"question":"هل تدعم الأداة جميع الكلمات العربية أو فقط جزءًا منها؟","answer":"تعتمد الأداة على قاموس عربي واسع النطاق، لذا فهي تدعم غالبية الكلمات العربية الفصحى والمتداولة. قد لا تجد فيها كلمات عامية جدًا أو مصطلحات نادرة للغاية."}]',
        'المستخدمون يبحثون عن حلول لمساعدتهم في الكلمات المتقاطعة، ألغاز الكلمات، أو تحسين إملائهم العربي.',
        '["حل الكلمات الناقصة","إيجاد الحروف المفقودة","أداة إكمال الكلمات","تخمين الكلمات المتقاطعة","مساعد الإملاء العربي","حل لغز الكلمات المتقاطعة","البحث عن الكلمات المفقودة","كمال الكلمات الغامضة"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'letter-rearranger',
        'ar',
        'Letter Rearranger',
        'مرتب الحروف: اكتشف الكلمات المخفية من أي حروف!',
        'هل تبحث عن حلول لألعاب الكلمات؟ مرتب الحروف يعيد ترتيب حروفك ويكشف لك كل الكلمات الممكنة، الطويلة والقصيرة، مجاناً وبدون تسجيل.',
        '',
        'مرتب الحروف: أطلق العنان لكل الكلمات من حروفك!',
        'أدخل أي حروف، ودعنا نكشف لك كل الكلمات الممكنة، من أطولها لأقصرها.',
        '["هل وجدت نفسك يوماً أمام مجموعة من الحروف المتناثرة، تتساءل عن كل الكلمات التي يمكن تشكيلها منها؟ سواء كنت من محبي حل الأناغرام، أو تبحث عن مساعد في ألعاب الكلمات مثل سكرابل وكلمات فريندز، أو حتى مجرد فضول لغوي، فإن مرتب الحروف هو الأداة المثالية لك. بخلاف برامج \"حل الأناغرام\" التقليدية التي تجد الكلمة باستخدام جميع الحروف فقط، فإن مرتب الحروف يذهب لأبعد من ذلك، ليكشف لك كل الكلمات، الكبيرة والصغيرة، التي يمكن استخلاصها من مجموعتك.","مرتب الحروف من AllWordTools.com لا يقتصر على استخدام جميع الحروف فحسب؛ بل يستخرج كل كلمة ممكنة، مرتبة حسب الطول والنتيجة المحتملة في الألعاب. يمكنك أيضاً إضافة حرف بديل مثل علامة الاستفهام (؟) أو النجمة (*) لتمثل أي حرف، ليمنحك المزيد من الاحتمالات! إنه مجاني، فوري، ويعمل مباشرة من متصفحك على أي جهاز، دون الحاجة للتسجيل أو التنزيل. اجعل كلمتك التالية هي الأفضل!"]',
        'كيف يعمل مرتب الحروف؟',
        '[{"title":"أدخل حروفك","detail":"اكتب الحروف التي تريد ترتيبها، ويمكنك استخدام ''؟'' أو ''*'' كحرف بديل لأي حرف مجهول."},{"title":"اختر نطاق البحث","detail":"اتركه مفتوحاً للعثور على كل الكلمات، أو حدد خيار \"الكلمات كاملة الطول فقط\" للحصول على الأناغرامات الدقيقة التي تستخدم كل الحروف."},{"title":"رتب الحروف","detail":"اضغط على زر \"ترتيب الحروف\" لتظهر لك كل الكلمات الصالحة، مجمعة من الأطول إلى الأقصر."},{"title":"انسخ ما تحتاج","detail":"انقر على أي كلمة لنسخها فوراً واستخدامها في لعبتك أو لغزك."}]',
        '[{"heading":"مرتب الحروف لألعاب الكلمات والألغاز","paragraphs":["هل تلعب سكرابل (Scrabble) أو كلمات فريندز (Words With Friends) وتحتاج إلى رؤية جميع الكلمات الممكنة من حروفك؟ مرتب الحروف هو سلاحك السري! يمكنه تحويل مجموعة من الحروف العشوائية إلى قائمة شاملة من الكلمات، مما يمنحك ميزة تنافسية. لا تترك أي نقطة على الطاولة، واكتشف الكلمات الخفية التي يمكن أن تحقق لك الفوز.","الأمر لا يقتصر على ألعاب الألواح الشهيرة؛ فهذا المرتب مثالي لحل ألغاز الصحف والمجلات، أو أي تحدٍّ يتطلب منك ترتيب الحروف لإنشاء كلمات. مع ميزة الحروف البديلة (الخلايا الفارغة)، يمكنك محاكاة أي سيناريو لعبة، والتأكد من أنك تستكشف كل احتمال ممكن."]},{"heading":"تعلم اللغة العربية واكتشف مفردات جديدة","paragraphs":["مرتب الحروف ليس مجرد أداة للألعاب؛ بل هو رفيق ممتاز لتعلم اللغة العربية وزيادة مفرداتك. أدخل مجموعة من الحروف وشاهد كيف يمكن ترتيبها لتشكيل كلمات مختلفة. هذه الطريقة التفاعلية تساعدك على فهم بنية الكلمات العربية وتكوينها، مما يعزز قدرتك على تذكر الكلمات الجديدة واستخدامها بشكل صحيح.","سواء كنت طالباً يتعلم اللغة، أو أستاذاً يبحث عن أداة تعليمية مبتكرة، أو حتى متحدثاً أصيلاً يرغب في استكشاف ثراء لغته، فإن مرتب الحروف يقدم لك منظوراً جديداً. إنه طريقة ممتعة وفعالة لاكتشاف الكلمات المخفية وتوسيع آفاقك اللغوية. جربه الآن وشاهد كم من الكلمات كنت تفوتها!"]}]',
        '[{"input":"ل ع ك م ي","output":"• كلمات (5)\n• عمل (3)\n• ملك (3)\n• على (3)\n• لك (2)\n• ما (2)\n• كل (2)\n• لم (2)\n• في (2)","note":"أدخل الحروف `ل ع ك م ي` وسترى كل الكلمات الممكنة التي يمكن تكوينها."},{"input":"ش م س ؟","output":"• شمس (3)\n• مسح (3)\n• رسم (3)\n• سمك (3)\n• يشمل (4)\n• يمسك (4)\n• مشكلة (5)","note":"استخدم \"؟\" كحرف بديل، وهنا \"؟\" قد يكون \"ر\" أو \"ك\" أو \"ل\" أو \"ك\" أو \"ل\"."},{"input":"ا ن ب ي ت","output":"• بنات (4)\n• نبت (3)\n• بان (3)\n• بين (3)\n• تاب (3)\n• تين (3)\n• نبات (4)\n• بيات (4)\n• بينات (5)","note":"مثال يوضح كيف يمكن ترتيب الحروف لتكوين كلمات متنوعة، بما في ذلك كلمات أطول."}]',
        '["استخدم علامة الاستفهام (؟) أو النجمة (*) كحرف بديل لتجربة جميع الاحتمالات الممكنة.","جرب البحث عن الكلمات الطويلة أولاً، فهي عادة ما تمنحك نقاطاً أعلى في الألعاب.","إذا كنت تبحث عن الأناغرام الدقيق، تأكد من تفعيل خيار \"الكلمات كاملة الطول فقط\".","انسخ الكلمات مباشرة من النتائج بضغطة واحدة لتوفير الوقت في ألعابك."]',
        '[{"question":"ما الفرق بين مرتب الحروف ومحلل الأناغرام؟","answer":"محلل الأناغرام يجد الكلمات التي تستخدم جميع الحروف التي أدخلتها تحديداً. بينما مرتب الحروف يذهب لأبعد من ذلك، فيجد كل كلمة صالحة يمكن تكوينها من أي جزء من الحروف، سواء كانت قصيرة أو طويلة، بالإضافة إلى الأناغرامات."},{"question":"هل يمكنني استخدام الحروف البديلة أو \"الجواكر\"؟","answer":"نعم، يمكنك استخدام علامة الاستفهام (؟) أو النجمة (*) كحرف بديل. سيقوم المرتب باستكشاف جميع الحروف الممكنة لتلك المواقع الفارغة، مما يزيد من عدد الكلمات المحتملة."},{"question":"كيف يتم ترتيب الكلمات في النتائج؟","answer":"يتم ترتيب الكلمات عادةً من الأطول إلى الأقصر، وداخل كل مجموعة طول، قد تظهر مرتبة ترتيباً أبجدياً أو حسب تقدير النقاط في ألعاب الكلمات الشائعة."},{"question":"هل مرتب الحروف مجاني؟","answer":"نعم، مرتب الحروف مجاني تماماً للاستخدام، ولا يتطلب أي تسجيل أو تنزيل. يمكنك استخدامه مباشرة عبر متصفحك في أي وقت."},{"question":"هل يدعم مرتب الحروف اللغة العربية فقط؟","answer":"بينما يمكن استخدامه للغات أخرى، فإن هذا الإصدار موجه لمستخدمي اللغة العربية، وبالتالي فإن الكلمات التي يعثر عليها هي كلمات عربية صحيحة."},{"question":"كيف أستطيع نسخ الكلمة التي أريدها؟","answer":"ببساطة، انقر أو اضغط على أي كلمة من قائمة النتائج المعروضة، وسيتم نسخها تلقائياً إلى حافظتك لتستخدمها في أي مكان."}]',
        'يريد المستخدمون العرب العثور على أداة لمساعدتهم في حل ألعاب الألغاز والكلمات، وخاصة الأناغرام وتوليد الكلمات من مجموعة حروف.',
        '["مرتب الحروف العربية","توليد كلمات من حروف","حل كلمات متقاطعة","تركيب كلمات من حروف معينة","البحث عن كلمات من حروف مشتتة","مساعد كلمات سكرابل","كيفية عمل كلمات من حروف","أداة ترتيب حروف الكلمات"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'reverse-dictionary',
        'ar',
        'Reverse Dictionary',
        'معجم الكلمات بناءً على المعنى | قاموس الكلمات العكسي',
        'اعثر على الكلمة المثالية لوصف ما تفكر به. أدخل وصفًا موجزًا أو كلمات ذات صلة وستجد الكلمة المناسبة تمامًا لمساعدتك في الكتابة أو حل مشكلة ''على طرف لساني''.',
        '',
        'معجم الكلمات بالمعنى: عندما تعرف ما تريد قوله، لكن الكلمة غابت عن ذهنك',
        'العلاج الفعال لمشكلة "على طرف لساني": اعثر على الكلمة الدقيقة من خلال معناها أو وصفها.',
        '["هل سبق وأن شعرت بالإحباط لأن الكلمة الصحيحة غابت عن ذهنك، على الرغم من أن المعنى واضح تمامًا في عقلك؟ \"معجم الكلمات بالمعنى\" هو الحل الأمثل لهذه المعضلة. هذه الأداة المبتكرة تعمل بطريقة عكسية تمامًا عن القواميس التقليدية: بدلًا من البحث عن معنى كلمة تعرفها، أنت تصف المعنى الذي تقصده، والأداة تعثر على الكلمة المناسبة لك.","سواء كنت كاتبًا محترفًا، طالبًا، أو حتى تلعب ألعاب الكلمات وتواجه صعوبة في تذكر مفردة معينة، فإن هذا القاموس العكسي هو رفيقك المثالي. ما عليك سوى كتابة تعريف، وصف موجز، أو حتى بضع كلمات ذات صلة بالمفهوم الذي يدور في ذهنك، وسيقوم المعجم بتقديم قائمة بالكلمات التي تتطابق مع طلبك. النتائج مرتبة حسب مدى قربها ودقتها لوصفك، لضمان حصولك على أفضل الخيارات أولاً. إنه مجاني، سريع، ويعمل مباشرة في متصفحك على أي جهاز دون الحاجة للتسجيل أو التنزيل."]',
        'كيف يعمل معجم الكلمات بالمعنى؟',
        '[{"title":"صف الكلمة المطلوبة","detail":"اكتب تعريفًا، وصفًا، أو كلمات قليلة ذات صلة بالمعنى الذي تبحث عنه."},{"title":"ابحث عن الكلمات","detail":"اضغط على زر \"البحث عن كلمات\" وسيقوم المعجم العكسي بإرجاع الكلمات الأقرب تطابقًا."},{"title":"تصفح النتائج المرتبة","detail":"يتم ترتيب النتائج حسب مدى ملاءمتها، بحيث تظهر الكلمات الأكثر دقة في الأعلى."},{"title":"انسخ الكلمة المناسبة","detail":"انقر على أي كلمة للحصول عليها ونسخها فورًا لاستخدامها في كتاباتك أو محادثاتك."}]',
        '[{"heading":"متى تحتاج إلى معجم الكلمات بالمعنى؟","paragraphs":["تخيل أنك في خضم كتابة مقال أو رسالة، وتجد نفسك تحاول العثور على \"الكلمة المثالية\" التي تعبر عن فكرة معينة، ولكنها تظل على \"طرف لسانك\" دون أن تتمكن من استدعائها. في هذه اللحظات، بدلًا من تضييع الوقت في البحث العشوائي، يمكنك ببساطة وصف المفهوم الذي تريده في أداة \"معجم الكلمات بالمعنى\"، وستقدم لك قائمة بالخيارات المحتملة.","كما أن هذه الأداة لا تقدر بثمن لمدربي اللغة العربية والطلاب الذين يتعلمون اللغة. يمكن استخدامها لتعزيز المفردات، أو لفهم الفروق الدقيقة بين الكلمات المتشابهة. إنها تساعد في صقل مهارات الكتابة والتعبير، وتضمن لك دائمًا استخدام الكلمة الأكثر دقة وتأثيرًا في سياقها."]},{"heading":"حلول متقدمة لمشاكل البحث عن الكلمات","paragraphs":["بينما تركز القواميس التقليدية على إعطاء معاني الكلمات المعروفة، فإن القاموس العكسي لدينا مصمم خصيصًا لحالات \"أعرف ما أريد قوله، لكن لا أتذكر الكلمة\". إنه بمثابة محرك بحث لغوي متقدم يعتمد على الفهم السياقي والدلالي، مما يجعله أداة لا غنى عنها لأي شخص يعمل بالكلمات أو يريد تحسين مفرداته.","علاوة على ذلك، لا تقتصر فائدته على البحث عن كلمة واحدة فقط. يمكن استخدامه لاستكشاف مجموعات من الكلمات المترابطة أو إيجاد بدائل متنوعة لفكرة معينة، مما يثري نصوصك ويجعلها أكثر جاذبية وتنوعًا. سواء كنت تبحث عن مرادف دقيق، أو كلمة نادرة، أو حتى كلمة تتفادى تكرارها، فإن \"معجم الكلمات بالمعنى\" يمنحك القوة لابتكار التعبير الأفضل."]}]',
        '[{"input":"شخص يميل إلى العزلة وعدم الاختلاط بالآخرين","output":"منعزل، انطوائي، وحيد، متوحد","note":"لمشكلة ''على طرف لساني'' عند وصف شخص."},{"input":"شعور قوي بالسعادة والفرح الغامر","output":"ابتهاج، غبطة، سرور، حبور، فرحة","note":"عند البحث عن كلمة تعبر عن عاطفة معينة."},{"input":"فعل يدل على وضع نهاية لشيء","output":"إنهاء، إيقاف، اختتام، إجهاض، إنهاء","note":"لإيجاد الأفعال المناسبة لوصف حدث."}]',
        '["كن محددًا قدر الإمكان في وصفك للحصول على نتائج أدق.","لا تتردد في استخدام مرادفات أو كلمات ذات صلة في وصفك.","جرّب صياغات مختلفة للوصف إذا لم تكن النتائج الأولية مرضية.","استفد من ترتيب النتائج، حيث تظهر الكلمات الأفضل تطابقًا في الأعلى دائمًا."]',
        '[{"question":"ما هو معجم الكلمات بالمعنى (القاموس العكسي)؟","answer":"هو أداة تسمح لك بالبحث عن كلمة معينة عن طريق إدخال معناها، وصفها، أو الكلمات المرتبطة بها، بدلًا من البحث عن معنى كلمة معروفة. إنه يعمل بطريقة عكسية للقواميس التقليدية."},{"question":"كيف أحصل على أفضل النتائج عند استخدام الأداة؟","answer":"للحصول على أفضل النتائج، حاول أن تكون وصفيًا ومحددًا قدر الإمكان. استخدم كلمات مفتاحية واضحة، ولا تكتفِ بجملة عامة. كلما كان وصفك أكثر تفصيلًا، كانت النتائج أدق."},{"question":"ما معنى أن النتائج مرتبة؟","answer":"تعني أن الكلمات التي تتطابق بشكل أكبر مع وصفك تظهر أولًا في قائمة النتائج، وتليها الكلمات الأقل تطابقًا. هذا يساعدك على تحديد الخيار الأنسب لك بسرعة وسهولة."},{"question":"هل يمكن أن يساعدني هذا المعجم في حل مشكلة ''على طرف لساني''؟","answer":"بالتأكيد! هذا هو الغرض الرئيسي من الأداة. عندما لا تسعفك الذاكرة بالكلمة ولكنك تتذكر معناها أو وظيفتها، ما عليك سوى وصفها وستساعدك الأداة على تذكرها أو إيجادها."},{"question":"هل استخدام معجم الكلمات بالمعنى مجاني؟","answer":"نعم، هذه الأداة مجانية تمامًا. يمكنك استخدامها في أي وقت ومن أي جهاز دون الحاجة إلى التسجيل أو دفع أي رسوم."},{"question":"هل يدعم القاموس العكسي اللغة العربية الفصحى والعامية؟","answer":"يهدف القاموس العكسي لدينا بشكل أساسي إلى توفير كلمات باللغة العربية الفصحى الشائعة للاستخدام الكتابي والرسمي، لكنه قد يقدم أحيانًا كلمات مفهومة في سياقات عامية معينة إذا كانت ذات صلة بوصفك."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم في إيجاد الكلمات التي تعبر عن معنى معين عندما لا تسعفهم الذاكرة بالكلمة نفسها.',
        '["معجم الكلمات بالمعنى","قاموس عكسي عربي","البحث عن كلمة بالوصف","أداة توليد الكلمات","إيجاد مرادفات الجمل","ما هي الكلمة التي تعني","حل مشكلة الكلمة على طرف لساني","مساعد الكاتب العربي"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'alphabetical-sorter',
        'ar',
        'Alphabetical Sorter',
        'ترتيب أبجدي للكلمات والقوائم: أداة مجانية وسريعة',
        'رتب قوائمك وكلماتك أبجديًا بسهولة وسرعة! أداة مجانية على الإنترنت لتنظيم الأسماء، المسارد، والمراجع بالترتيب التصاعدي أو التنازلي. انسخ والصق وفُرِزْ.',
        '',
        'أداة الترتيب الأبجدي السريع',
        'رتب كلماتك وقوائمك أبجديًا بنقرة واحدة، مجاناً وبدون تسجيل!',
        '["هل سئمت من قضاء ساعات في ترتيب قوائم الكلمات أو الأسماء يدويًا؟ مع أداة الترتيب الأبجدي المجانية من AllWordTools.com، يمكنك تنظيم أي قائمة مهما كانت طويلة في ثوانٍ معدودة. سواء كنت تعمل على مسرد، قائمة مراجع، أسماء طلاب، أو حتى مجرد قائمة تسوق، ستوفر عليك هذه الأداة الوقت والجهد وتضمن لك دقة لا مثيل لها.","تتيح لك أداة الفرز الأبجدي تخصيص طريقة الفرز بالكامل: يمكنك اختيار ما إذا كانت مفرداتك مفصولة بمسافات، فواصل، أو أسطر جديدة. اختر الترتيب التصاعدي (أ-ي) أو التنازلي (ي-أ)، تجاهل حالة الحروف إذا أردت، وحتى حذف التكرارات بضغطة زر. النتيجة جاهزة للنسخ والاستخدام فورًا، كل ذلك مباشرة في متصفحك، بدون الحاجة للتسجيل أو تنزيل أي برامج!"]',
        'كيف ترتب قائمتك أبجديًا في 4 خطوات:',
        '[{"title":"الصق قائمتك","detail":"أدخل الكلمات أو العناصر التي ترغب في ترتيبها. من الأفضل أن يكون كل عنصر في سطر جديد."},{"title":"اختر طريقة الفصل","detail":"حدد للأداة كيف يتم فصل العناصر في قائمتك (مسافات، فواصل، أو أسطر جديدة)."},{"title":"ضع خيارات الفرز","detail":"اختر الترتيب التصاعدي (أ-ي) أو التنازلي (ي-أ)، تجاهل حالة الأحرف، وإزالة التكرارات حسب الحاجة."},{"title":"انسخ النتيجة","detail":"ستظهر القائمة المرتبة فورًا. انسخها واستخدمها أينما تشاء!"}]',
        '[{"heading":"لمن صُممت هذه الأداة؟","paragraphs":["أداة الترتيب الأبجدي مثالية للطلاب الذين يحتاجون لترتيب المراجع أو فهارس الكتب، للباحثين الذين يعملون على تصنيف مصطلحات علمية، للمعلمين لتنظيم أسماء الطلاب أو قوائم الدرجات، أو حتى للمستخدمين العاديين لترتيب قوائم التسوق أو جهات الاتصال. هي أداة لا غنى عنها لكل من يتعامل مع البيانات النصية ويرغب في تنظيمها بكفاءة.","سواء كنت تعمل على مشروع كبير يتطلب دقة عالية أو كنت بحاجة لترتيب سريع لقائمة صغيرة، فإن هذه الأداة توفر لك الحل الأمثل. تخلص من الأخطاء البشرية ووفر وقتك الثمين باستخدام الترتيب الأبجدي التلقائي الذي يضمن لك نتائج صحيحة في كل مرة."]},{"heading":"ميزات تجعل حياتك أسهل","paragraphs":["تم تصميم أداتنا لتكون سهلة الاستخدام وبديهية، مع توفير خيارات متقدمة لتلبية جميع احتياجاتك. يمكنك الاستفادة من ميزة إزالة الكلمات المكررة بضغطة زر واحدة، وهذا مفيد جدًا عند دمج قوائم مختلفة أو تنظيف البيانات. كما يمكنك اختيار ما إذا كنت تريد أن تأخذ الأداة حالة الأحرف الكبيرة والصغيرة في الاعتبار عند الفرز، مما يوفر مرونة أكبر.","تعمل الأداة بالكامل في متصفحك، مما يعني أن بياناتك تظل خاصة ولا يتم تحميلها على أي خادم. هذا يوفر لك راحة بال وأمانًا لبياناتك الحساسة. استخدمها على هاتفك الذكي، جهازك اللوحي، أو الكمبيوتر المحمول دون أي قيود، وفي أي وقت وأي مكان."]}]',
        '[{"input":"قطة\nأرنب\nفيل\nزهرة","output":"أرنب\nزهرة\nفيل\nقطة","note":"ترتيب كلمات عربية بسيطة بشكل تصاعدي."},{"input":"القاهرة، الرياض، دمشق، بغداد، بيروت","output":"بغداد\nبيروت\nدمشق\nالرياض\nالقاهرة","note":"فرز قائمة مدن عربية مفصولة بفواصل، مع ملاحظة أن الأداة تضع \"ال\" التعريف في الاعتبار ما لم يتم تجاهل ذلك بخيارات متقدمة."},{"input":"تفاح\nبرتقال\nعنب\nتفاح\nموز","output":"برتقال\nتفاح\nعنب\nموز","note":"ترتيب قائمة مع إزالة الكلمات المكررة (تفاح)."}]',
        '["لأفضل النتائج، ضع كل كلمة أو عبارة تريد فرزها في سطر منفصل.","استخدم خيار إزالة التكرارات لتنظيف قوائمك من الإدخالات المكررة بسهولة.","اختر بين الترتيب التصاعدي (أ-ي) أو التنازلي (ي-أ) حسب ما يناسب احتياجك.","لا تتردد في تجربة خيارات الفصل المختلفة (مسافة، فاصلة، سطر جديد) لتناسب صيغة قائمتك."]',
        '[{"question":"ماذا تفعل أداة الترتيب الأبجدي؟","answer":"تقوم الأداة بترتيب أي قائمة من الكلمات، الأسماء، أو العبارات أبجديًا بشكل تلقائي وسريع، سواء تصاعديًا أو تنازليًا، مع خيارات إضافية كالتعامل مع التكرارات."},{"question":"كيف يجب أن يكون تنسيق قائمتي؟","answer":"يمكنك لصق قائمتك كما هي. الأداة تدعم الفصل بالأسطر الجديدة (كل عنصر بسطر)، المسافات، أو الفواصل. يمكنك تحديد طريقة الفصل المفضلة لديك من الخيارات."},{"question":"هل يمكن للأداة إزالة الكلمات المكررة؟","answer":"نعم، بالتأكيد. توجد ميزة مخصصة تتيح لك إزالة أي إدخالات مكررة من قائمتك بنقرة زر واحدة بعد الفرز."},{"question":"هل الأداة حساسة لحالة الأحرف (كبيرة/صغيرة)؟","answer":"بشكل افتراضي، قد تأخذ الأداة حالة الأحرف في الاعتبار. ولكن يمكنك تفعيل خيار ''تجاهل حالة الأحرف'' لفرز أكثر مرونة لا يهتم بالفرق بين الحروف الكبيرة والصغيرة."},{"question":"هل استخدام أداة الترتيب الأبجدي مجاني؟","answer":"نعم، هي مجانية تمامًا. لا توجد أي رسوم أو اشتراكات، ويمكنك استخدامها مرات غير محدودة دون الحاجة للتسجيل أو تنزيل أي برنامج."},{"question":"هل تعمل الأداة على جميع الأجهزة؟","answer":"نعم، الأداة تعمل عبر المتصفح ومصممة لتكون متوافقة مع جميع الأجهزة، بما في ذلك أجهزة الكمبيوتر المكتبية، اللابتوب، الأجهزة اللوحية، والهواتف الذكية."}]',
        'يبحث المستخدمون العرب عن طريقة سريعة وسهلة لترتيب الكلمات والقوائم أبجديًا لتنظيم بياناتهم.',
        '["ترتيب أبجدي للكلمات","ترتيب قائمة بالأسماء","فرز الكلمات أون لاين","ترتيب الحروف الأبجدية","منظم الكلمات تلقائي","كيف أرتب أسماء أبجديًا","فرز النصوص أونلاين مجاني","ترتيب كلمات عربي"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'random-letter-generator',
        'ar',
        'Random Letter Generator',
        'مولد أحرف عشوائي: أداة مجانية للألعاب والتدريبات',
        'هل تبحث عن أحرف عشوائية لألعابك أو تدريباتك اللغوية؟ استخدم مولد الأحرف المجاني الخاص بنا لاختيار الحروف، الحركات أو الحروف الساكنة بسهولة وسرعة.',
        '',
        'مولد الأحرف العشوائي',
        'احصل على أحرف عشوائية، حروف علة، أو حروف ساكنة بسهولة وسرعة!',
        '["هل تحتاج إلى أحرف عشوائية لألعابك، تدريباتك اللغوية، أو حتى لتبدأ تحديًا إبداعيًا؟ وداعًا للحيرة والتفكير! أداة مولد الأحرف العشوائي من AllWordTools.com هي الحل الأمثل لك. سواء كنت بحاجة إلى حرف واحد لبدء لعبة كلمات، مجموعة أحرف للتدريب الصوتي، أو حتى مجرد اختيار عشوائي غير متحيز، ستوفر لك الأداة النتيجة فورًا بضغطة زر.","تتيح لك هذه الأداة البسيطة والفعالة تخصيص خياراتك: اختر من الأحرف الأبجدية كاملة، أو ركز على الحركات فقط (مثل حروف العلة في الإنجليزية)، أو الحروف الساكنة. يمكنك أيضًا التبديل بين الأحرف الكبيرة والصغيرة (للإنجليزية)، وتحديد ما إذا كان يمكن تكرار الأحرف أم لا. إنها سريعة، مجانية بالكامل، وتعمل مباشرة في متصفحك على أي جهاز دون الحاجة لتحميل أي برامج أو التسجيل."]',
        'كيف تستخدم مولد الأحرف العشوائي؟',
        '[{"title":"اختر العدد المطلوب","detail":"حدد عدد الأحرف الذي ترغب في توليده، بدءًا من حرف واحد وحتى مئة حرف."},{"title":"حدد نوع الأحرف","detail":"اختر من بين جميع الأحرف، أو الحركات فقط، أو الحروف الساكنة فقط لتناسب نشاطك."},{"title":"ضبط الخيارات","detail":"قم بالتبديل بين الأحرف الكبيرة والصغيرة (للإنجليزية) وخيار ''لا تكرار'' حسب حاجتك."},{"title":"ابدأ التوليد","detail":"اضغط على زر ''توليد الأحرف'' وانسخ النتيجة بلمسة واحدة."}]',
        '[{"heading":"استخدامات تعليمية وترفيهية بلا حدود","paragraphs":["سواء كنت معلمًا وتبحث عن طريقة مبتكرة لتدريب طلابك على نطق الأحرف أو مكونات الكلمة، أو والدًا يحاول جعل تعلم اللغة العربية أو الإنجليزية ممتعًا لأطفاله، فإن مولد الأحرف العشوائي يقدم لك الكثير. يمكن استخدامه لتكوين كلمات جديدة، أو كبداية لتحدي إبداعي يطلب من المشاركين ابتكار قصة تبدأ بحرف معين، أو حتى لتحديد الدور في لعبة جماعية.","لا تقتصر فائدة هذه الأداة على التعليم فقط، بل تمتد لتشمل الألعاب والترفيه. تخيل أنك تلعب لعبة كلمات مثل ''اسم، حيوان، نبات، جماد'' وتحتاج إلى حرف عشوائي تمامًا لبدء الجولة. ستمنحك الأداة اختيارًا سريعًا وعادلًا، مما يضيف عنصرًا من التشويق والمفاجأة. يمكن استخدامها في الألغاز اللغوية، وحتى لورش العمل الإبداعية التي تتطلب انطلاقًا عشوائيًا للأفكار."]},{"heading":"مثالي لألعاب الكلمات والتدريبات اللغوية","paragraphs":["في عالم ألعاب الكلمات، يُعدّ الحصول على أحرف عشوائية أمرًا أساسيًا للعدالة والحماس. بدلاً من محاولة اختيار الأحرف يدويًا أو السحب من الأكياس، يقدم لك مولد الأحرف العشوائي حلاً رقميًا دقيقًا وموثوقًا. إنه مثالي لألعاب مثل ''Scrabble'' (كلمات متقاطعة)، حيث يمكنك توليد أحرف البدء أو تعبئة الرفوف الخاصة باللاعبين بطريقة عشوائية ومنظمة.","كما أنه مفيد جدًا للتدريبات الصوتية (Phonics Drills) والتمارين اللغوية. على سبيل المثال، يمكن للمدرسين توليد مجموعة من الأحرف الساكنة والحركات لمطالبة الطلاب بدمجها لتشكيل مقاطع صوتية أو كلمات قصيرة. هذه المرونة تجعله أداة قيمة لا غنى عنها لأي شخص مهتم باللغة، الألعاب، أو التعليم."]}]',
        '[{"input":"عدد الأحرف: 5، الخيار: جميع الأحرف (عربي)","output":"ء، و، ك، خ، ت","note":"مثال لتوليد أحرف عربية عشوائية للاستخدام في الألغاز أو الألعاب."},{"input":"عدد الأحرف: 3، الخيار: حركات فقط (إنجليزي)، لا تكرار","output":"A, E, O","note":"توليد 3 أحرف علة إنجليزية مختلفة، مفيد لتدريبات النطق."},{"input":"عدد الأحرف: 7، الخيار: حروف ساكنة فقط (إنجليزي)، تكرار مسموح","output":"R, S, T, T, C, L, B","note":"مثال لأحرف ساكنة إنجليزية، يمكن استخدامها في بناء كلمات أو تمارين سباق الحروف."}]',
        '["جرب خيارات الأحرف الساكنة أو الحركات فقط لجعل التدريبات اللغوية أكثر تركيزًا.","استخدم خاصية ''لا تكرار'' عندما تحتاج إلى مجموعة فريدة من الأحرف للعبة معينة.","قم بتحديد عدد كبير من الأحرف (حتى 100) لإعداد قوائم طويلة للأنشطة الصفية.","انسخ النتيجة بسهولة بضغطة واحدة وحولها إلى نص أو استخدمها في مكان آخر."]',
        '[{"question":"ما مدى عشوائية الأحرف التي يتم توليدها؟","answer":"تستخدم الأداة خوارزميات توليد أرقام عشوائية قوية لضمان أن كل حرف يتم اختياره بشكل عشوائي تمامًا، مما يوفر نتيجة غير متحيزة في كل مرة."},{"question":"هل يمكنني الحصول على حروف علة أو حروف ساكنة فقط؟","answer":"نعم، يمكنك اختيار توليد جميع الأحرف، أو التركيز فقط على حروف العلة (الحركات) أو الحروف الساكنة حسب حاجتك، سواء للغة العربية أو الإنجليزية."},{"question":"هل يمكن تكرار الأحرف في النتيجة؟","answer":"يمكنك التحكم في ذلك! تتيح لك الأداة تشغيل أو إيقاف خيار ''تكرار الأحرف'' بناءً على متطلبات لعبتك أو تدريبك."},{"question":"هل هذه الأداة مجانية للاستخدام؟","answer":"نعم، أداة مولد الأحرف العشوائي مجانية بالكامل. يمكنك استخدامها بلا حدود بدون أي تكلفة أو الحاجة للتسجيل."},{"question":"هل تعمل الأداة على جميع الأجهزة؟","answer":"بالتأكيد. الأداة تعمل مباشرة في متصفح الويب الخاص بك، مما يجعلها متوافقة مع أجهزة الكمبيوتر المكتبية، الهواتف الذكية، والأجهزة اللوحية دون الحاجة لتحميل أي شيء."},{"question":"هل تدعم مولد الأحرف العشوائي اللغة العربية؟","answer":"نعم، الأداة تدعم توليد الأحرف العربية والإنجليزية، مما يجعلها متعددة الاستخدامات لمختلف الأغراض اللغوية والتعليمية في المنطقة."}]',
        'يبحث المستخدمون عن أداة إلكترونية تساعدهم في توليد أحرف عربية أو إنجليزية عشوائية لأغراض الألعاب التعليمية أو تحديات الكلمات.',
        '["مولد أحرف عشوائي","اختيار حروف عشوائية","أداة توليد الحروف","مولد حروف عربية عشوائية","أحرف إنجليزية عشوائية","توليد حركات اللغة العربية","مساعد ألعاب الكلمات","برنامج اختيار أحرف"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'vocabulary-quiz',
        'ar',
        'Vocabulary Quiz',
        'اختبار مفردات اللغة الإنجليزية: درب كلماتك ومصطلحاتك ببساطة',
        'عزز مفرداتك الإنجليزية مع اختبارنا المجاني والممتع! اختبر مستواك، تعلم كلمات جديدة، وشاهد شرح المصطلحات فوراً. مثالي للطلاب ومحبي اللغة.',
        '',
        'اختبر وطوّر مفرداتك الإنجليزية بكل متعة وسهولة',
        'عزز قدراتك اللغوية، اكتب بطلاقة، واقرأ بذكاء مع اختبار المفردات المجاني.',
        '["امتلاك حصيلة قوية من المفردات يعطيك قوة في التعبير، يجعل كتاباتك أكثر احترافية، وقراءتك أسرع وأكثر فهماً. اختبار المفردات هذا يمنحك فرصة ممتازة لبناء رصيدك اللغوي بطريقة ممتعة وبدون أي ضغط. في كل جولة، ستواجه مجموعة من الكلمات وعليك اختيار التعريف الصحيح من بين أربعة خيارات، وسترى نتيجتك فوراً.","الأسئلة وخيارات الإجابات تتغير في كل مرة تلعب فيها، مما يسمح لك باللعب مراراً وتكراراً دون الحاجة لحفظ الترتيب. الأداة مجانية تماماً، تعمل مباشرة عبر المتصفح، وهي مثالية للطلاب، دارسي اللغة الإنجليزية كلغة ثانية، ولكل من يهوى استكشاف الكلمات."]',
        'كيف يعمل اختبار المفردات؟',
        '[{"title":"اقرأ الكلمة","detail":"لكل سؤال، ستظهر لك كلمة باللغة الإنجليزية وعليك معرفة معناها."},{"title":"اختر التعريف الصحيح","detail":"حدد من بين الخيارات الأربعة الموجودة التعريف الذي تعتقد أنه الأصح للكلمة المعروضة."},{"title":"تعلم فوراً","detail":"بعد كل إجابة، ستعرف مباشرة ما إذا كنت على صواب أم خطأ، مع شرح مختصر يوضح لك المعنى."},{"title":"شاهد نتيجتك","detail":"أكمل الجولة لترى درجاتك النهائية، ثم حاول أن تتجاوزها في المرات القادمة!"}]',
        '[{"heading":"لماذا يعتبر هذا الاختبار مهماً لكل دارس للغة الإنجليزية؟","paragraphs":["إتقان المفردات هو العمود الفقري لإتقان اللغة. كلما زاد رصيدك اللغوي، كلما كنت أكثر قدرة على التعبير عن أفكارك بوضوح، وفهم المحتوى المكتوب والمنطوق بسهولة. هذا الاختبار ليس مجرد لعبة، بل هو أداة تعليمية فعالة تساعدك على توسيع آفاقك اللغوية.","سواء كنت تستعد لاختبارات مثل IELTS أو TOEFL، أو كنت ترغب فقط في تحسين مهاراتك اليومية في اللغة الإنجليزية، فإن هذا الاختبار يقدم لك طريقة ممتعة وفعالة لبناء الثقة في استخدام الكلمات والمصطلحات الإنجليزية."]},{"heading":"لمن صمم هذا الاختبار؟","paragraphs":["العبقرية في هذا الاختبار تكمن في مرونته وقدرته على خدمة شرائح واسعة. إنه مثالي لطلاب المدارس والجامعات الذين يسعون لتعزيز أدائهم الأكاديمي. كما أنه كنز لدارسي اللغة الإنجليزية كلغة ثانية (ESL learners) والذين يبحثون عن تمارين تفاعلية.","ولا يقتصر على ذلك، فهو أيضاً رائع لأي شخص لديه شغف بالكلمات؛ من عشاق الألغاز اللغوية إلى المحترفين الذين يرغبون في صقل مهاراتهم اللغوية ليصبحوا أكثر فعالية في بيئة العمل الدولية. أياً كان هدفك، ستجد فيه الفائدة والتشويق."]}]',
        '[{"input":"شمس","output":"Sun","note":"للتوضيح، لو كانت الأداة تدعم العربية، فسيتم عرض كلمة عربية لاختيار مرادفها الإنجليزي."},{"input":"كتاب","output":"Book","note":"مثال على كلمة عربية أخرى يمكن اختبارها لتحديد معناها بالإنجليزية."},{"input":"جميل","output":"Beautiful","note":"طريقة بسيطة وعملية لاختبار مدى إلمامك بالمرادفات الإنجليزية الشائعة."}]',
        '["لا تتردد في اللعب عدة مرات، فالتكرار يرسخ المعلومة.","أقرأ شرح الكلمة حتى لو أجبت بشكل صحيح لتعميق فهمك.","حاول تسجيل الكلمات الجديدة التي تتعلمها في مفكرة خاصة بك.","استخدم الكلمات التي تعلمتها حديثاً في جمل من إنشائك."]',
        '[{"question":"هل اختبار المفردات هذا مجاني بالكامل؟","answer":"نعم، الأداة مجانية 100% ولا تتطلب أي تسجيل أو رسوم لاستخدامها."},{"question":"هل تتغير الأسئلة في كل مرة ألعب فيها؟","answer":"بالتأكيد! يتم تبديل الكلمات والخيارات في كل جولة لضمان تجربة تعليمية متجددة ومفيدة."},{"question":"لمن هذا الاختبار؟ هل يناسب مستواي؟","answer":"صُمم هذا الاختبار ليتناسب مع مجموعة واسعة من المستويات، من المبتدئين إلى المتقدمين. وهو مثالي للطلاب، دارسي اللغة الإنجليزية، وكل مهتم بتطوير لغته."},{"question":"هل أحتاج لتثبيت أي برنامج لاستخدامه؟","answer":"لا، لا تحتاج لتثبيت أي شيء. يعمل الاختبار مباشرة في متصفح الإنترنت على أي جهاز."},{"question":"هل يمكنني مشاركة نتائجي مع أصدقائي؟","answer":"حاليًا لا توجد ميزة لمشاركة النتائج مباشرة، ولكن يمكنك دائمًا التقاط لقطة شاشة ومشاركتها."},{"question":"ما هي أنواع الكلمات التي يغطيها الاختبار؟","answer":"يغطي الاختبار مجموعة متنوعة من الكلمات والمفردات التي تشمل مجالات مختلفة لضمان توسيع قاموسك اللغوي."}]',
        'يبحث المستخدمون عن طريقة مجانية وممتعة لاختبار وتطوير مفرداتهم في اللغة الإنجليزية.',
        '["اختبار مفردات اللغة الانجليزية","تطوير مفردات انجليزي","اختبار كلمات انجليزي","تعلم كلمات انجليزي جديد مجاني","مفردات انجليزي للمبتدئين","كيف احسن مفرداتي بالانجليزي","تصحيح اخطاء المفردات الانجليزية","تطبيق اختبار كلمات انجليزي"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'spelling-quiz',
        'ar',
        'Spelling Quiz',
        'اختبار الإملاء الإنجليزي: صحّح الكلمات الصعبة مجاناً',
        'طوّر إملاءك الإنجليزي مع اختبار الإملاء المجاني. تعلّم كيف تكتب الكلمات الشائعة التي يخطئ بها الكثيرون بسهولة. اختبر نفسك الآن وحسّن مستواك بسرعة!',
        '',
        'اختبار الإملاء الإنجليزي: تعلم صح كتابة الكلمات الصعبة',
        'هل تتخبط في كتابة الكلمات الإنجليزية المعقدة؟ حان الوقت لتتقنها!',
        '["حتى أمهر الكتاب يواجهون صعوبة في كتابة بعض الكلمات الإنجليزية مثل (accommodate)، (definitely)، أو (separate). لكن ماذا لو حولنا هذه التحديات الإملائية إلى لعبة ممتعة ومفيدة؟ مع اختبار الإملاء المجاني الخاص بنا، ستتحول الكلمات الصعبة إلى فرصة لتحسين مهاراتك بشكل جذري.","كل سؤال في هذا الاختبار يضع أمامك معنى الكلمة وأربعة خيارات إملائية مختلفة، ليكون هدفك هو اختيار الشكل الصحيح. نركز على الكلمات الإنجليزية الأكثر شيوعًا والأكثر عرضة للأخطاء الإملائية، ومع كل محاولة، تتغير الأسئلة لتضمن لك تدريبًا شاملاً. الأداة مجانية وفورية، ومثالية للطلاب، الكتاب، وأي شخص يرغب في صقل إملائه الإنجليزي ليصبح بلا أخطاء."]',
        'كيف يعمل اختبار الإملاء؟ خطوات بسيطة:',
        '[{"title":"اقرأ الكلمة بالعربية","detail":"لكل سؤال، ستجد معنى الكلمة لمساعدتك في فهم المطلوب."},{"title":"اختر الإملاء الصحيح","detail":"من بين الخيارات الأربعة المعروضة، حدد الإملاء الدقيق للكلمة الإنجليزية."},{"title":"اكتشف الإجابة فورًا","detail":"ستعرف إذا كانت إجابتك صحيحة أم خاطئة، مع عرض الإملاء الصحيح لتتعلم منه."},{"title":"راجع وحسّن درجتك","detail":"بعد الانتهاء، ستظهر نتيجتك. أعد الاختبار لتحسين إملائك وتثبيت الكلمات في ذهنك."}]',
        '[{"heading":"لمن صُمم هذا الاختبار؟","paragraphs":["هذا الاختبار مثالي لأي شخص يتعامل مع اللغة الإنجليزية ويطمح لتحسين دقة إملائه. سواء كنت طالبًا تستعد لاختبارات IELTS أو TOEFL، أو كاتب محتوى، أو حتى مستخدمًا عاديًا للإنترنت ترغب في التعبير عن نفسك بوضوح أكبر بدون أخطاء محرجة، فهذه الأداة مصممة خصيصًا لك.","لن تكتشف الكلمات التي تخطئ فيها فحسب، بل ستتعلم الإملاء الصحيح بطريقة تفاعلية وممتعة. ودّع القلق من الأخطاء الإملائية وعزز ثقتك في كتابة الإنجليزية."]},{"heading":"ما الذي يميز اختبار الإملاء هذا؟","paragraphs":["على عكس الطرق التقليدية المملة، اختبارنا يحوّل التعلم إلى لعبة؛ كل سؤال فرصة للتحدي والمعرفة. نحن نركز على الكلمات الأساسية التي تُعرف بكونها مصدر إرباك للكثيرين، مما يضمن لك تدريبًا فعالًا على ما يهم حقًا.","كما أن الأسئلة تتغير وتتبدل في كل مرة تجرب فيها الاختبار، مما يحول دون الحفظ البصم ويشجع على الفهم الحقيقي للإملاء. استمتع بتجربة تعليمية ديناميكية ومجانية تمامًا في أي وقت ومن أي مكان."]}]',
        '[{"input":"معنى الكلمة: استيعاب. ( accommodate ) - ( accomodate ) - ( acommodate ) - ( acomodate )","output":" accommodate ","note":"أحد الكلمات الإنجليزية الشائعة التي تحتوي على أحرف مزدوجة يسهل الخطأ فيها."},{"input":"معنى الكلمة: محددًا. ( definitely ) - ( definately ) - ( defiantly ) - ( defenitely )","output":" definitely ","note":"كلمة يخطئ الكثيرون في كتابة الحرف المتحرك الثاني فيها."},{"input":"معنى الكلمة: منفصل. ( separate ) - ( seperate ) - ( saparate ) - ( secrepate )","output":" separate ","note":"خطأ شائع في تبديل مكان الأحرف المتحركة."}]',
        '["ركز على جذور الكلمات الإنجليزية الشائعة.","استمر في التدرب بانتظام لتحسين ذاكرتك البصرية للكلمات.","لا تتردد في استخدام القواميس لتعزيز فهمك لمعاني الكلمات.","حاول ربط الكلمات صعبة الإملاء بقواعد معينة أو ملاحظات لتثبيتها بذهنك."]',
        '[{"question":"هل هذا الاختبار مجاني تمامًا؟","answer":"نعم، اختبار الإملاء الإنجليزي لدينا مجاني بالكامل ويمكنك استخدامه عدد غير محدود من المرات دون أي رسوم."},{"question":"ما هي الكلمات التي يتضمنها الاختبار؟","answer":"يتضمن الاختبار مجموعة واسعة من الكلمات الإنجليزية التي يخطئ بها متحدثو اللغة الإنجليزية وغير الناطقين بها، مع التركيز على الكلمات الشائعة التي تسبب إرباكًا."},{"question":"هل تتغير الأسئلة في كل مرة أجري فيها الاختبار؟","answer":"بالتأكيد! يتم تبديل وترتيب الأسئلة عشوائيًا في كل محاولة جديدة، لضمان تدريب متنوع وشامل لا يعتمد على الحفظ."},{"question":"هل يمكنني استخدام هذا الاختبار لتحسين إملائي في كتابة الإيميلات والوثائق؟","answer":"نعم، هذا الاختبار أداة ممتازة لتعزيز دقة إملائك في جميع سياقات الكتابة الإنجليزية، سواء كانت أكاديمية أو مهنية أو شخصية."},{"question":"ما الفئة العمرية التي يناسبها هذا الاختبار؟","answer":"صمم هذا الاختبار ليلائم الطلاب والبالغين من جميع المستويات الذين يرغبون في تحسين إملائهم الإنجليزي. لا يوجد حد عمري محدد."},{"question":"هل يقدم الاختبار شرحًا للأخطاء التي أقع فيها؟","answer":"يُظهر الاختبار الإملاء الصحيح مباشرة بعد اختيارك، مما يساعدك على رؤية الخطأ وتصحيحه فوريًا لتعزيز التعلم."}]',
        'يبحث المستخدمون عن أداة لمساعدتهم على تحسين إملائهم في اللغة الإنجليزية وتجنب الأخطاء الشائعة.',
        '["اختبار إملاء إنجليزي","تصحيح إملاء الكلمات الإنجليزية","أخطاء إملائية شائعة في الإنجليزية","تدريب على الإملاء الإنجليزية","تحدي الإملاء الإنجليزي","كيف أصحح الكلمات الإنجليزية","برنامج تعليم الإملاء الإنجليزية","اختبار كلمات إنجليزية صعبة"]'
      );
INSERT OR REPLACE INTO tool_translations (
        tool_slug, locale, name, meta_title, meta_description, eyebrow, heading, subheading,
        intro_json, howto_title, howto_steps_json, sections_json, examples_json, tips_json, faqs_json, search_intent, keywords_json
      ) VALUES (
        'codycross-answers',
        'ar',
        'CodyCross Answers',
        'إجابات كودي كروس — حلول ومساعد لعبة CodyCross | مجاناً',
        'اعثر على جميع إجابات وحلول كودي كروس (CodyCross) لكل عالم ومجموعة ومرحلة. ابحث في قاعدة بياناتنا لحل أي مستوى فورًا. سريع ومجاني.',
        '',
        'إجابات لعبة CodyCross وقاعدة بيانات الحلول',
        'احصل على حلول فورية للعبة كودي كروس. ابحث في قاعدة بياناتنا عن الكلمات المتقاطعة لتجاوز أي مستوى واستكشاف العوالم.',
        '["كودي كروس (CodyCross) هي لعبة كلمات متقاطعة شهيرة للغاية على الأجهزة المحمولة طورتها Fanatee، ويعشقها ملايين اللاعبين حول العالم لما تتميز به من عوالم ذات طابع خاص ورسومات ملونة وبطل اللعبة الفضائي الودود ''كودي''. تدمج اللعبة آليات الكلمات المتقاطعة الكلاسيكية مع لمسة عصرية: يجب على اللاعبين ملء شبكة من الكلمات المتقاطعة بناءً على أدلة ومفاتيح محددة. بمجرد حل كل كلمة، تظهر بعض الحروف الصحيحة في كلمات أخرى داخل الشبكة تلقائيًا، مما يساعدك على كشف الكلمات المتبقية. ومع ذلك، كلما تقدمت إلى عوالم متقدمة مثل أعماق البحار، السيرك، أو الفضاء، تزداد الصعوبة وتصبح الأدلة أكثر غموضًا وتحديًا.","هنا يأتي دور قاعدة بيانات حلول وإجابات CodyCross الخاصة بنا. تم تصميم أداة البحث المجانية والمميزة هذه لمساعدتك في العثور على الإجابة الدقيقة التي تحتاجها، سواء كنت عالقًا في دليل واحد صعب أو ترغب في التحقق من إجاباتك قبل كتابتها. من خلال كتابة الدليل أو الكلمات المفتاحية أو الحروف التي بحوزتك، يمكنك العثور على الحل فورًا. تعمل منصتنا بسرعة فائقة على متصفحك دون أي تأخير، مما يساعدك على مواصلة اللعب بدون اشتراكات أو تسجيل أو إعلانات مزعجة.","هذه الأداة ليست مجرد وسيلة للغش؛ بل هي مصدر للتعلم. تساعدك على فهم الروابط بين الكلمات، واكتشاف معانٍ جديدة، وتوسيع حصيلتك اللغوية أثناء اللعب. استمر في القراءة لتتعلم كيفية احتراف CodyCross وتطبيق استراتيجيات الحل وتجنب الأخطاء الشائعة."]',
        'كيفية العثور على حلول CodyCross',
        '[{"title":"أدخل الدليل أو الكلمة المفتاحية","detail":"اكتب السؤال أو الدليل الذي تواجه مشكلة فيه في مربع البحث. يمكنك إدخال نص الدليل بالكامل أو كتابة عبارة رئيسية (مثل ''عاصمة فرنسا'' أو ''سائل النحل الحلو'')."},{"title":"حدد الحروف المعروفة (اختياري)","detail":"إذا كنت قد كشفت بالفعل عن بعض الحروف في اللعبة، استخدم [مساعد كودي كروس](codycross-solver) لإدخال الحروف المعروفة وعلامات الاستفهام للخانات الفارغة (مثال: ''?a?e??'')."},{"title":"عرض الحلول المتطابقة","detail":"انقر على بحث أو اختر أحد الاقتراحات الشائعة. ستبحث قاعدة البيانات في آلاف المراحل وتعرض لك الحلول المتطابقة فورًا، مرتبة حسب طول الكلمة ومطابقتها."},{"title":"طبق الحل في اللعبة","detail":"قارن الكلمة المقترحة مع عدد المربعات في شبكتك، واكتبها في اللعبة، واستغل الحروف الجديدة التي ستكشفها لحل بقية الأسئلة."}]',
        '[{"heading":"ما هي لعبة CodyCross وكيف تعمل؟","paragraphs":["كودي كروس: كلمات متقاطعة هي لعبة من Fanatee تروي قصة فضائي فضولي يدعى كودي تحطمت سفينته على الأرض. لمساعدته على التعلم عن كوكبنا، يحل اللاعبون كلمات متقاطعة ذات طابع خاص. تنقسم اللعبة إلى ''عوالم'' (مثل الأرض، تحت الماء، الاختراعات، السيرك، والفنون)، يحتوي كل عالم على عدة ''مجموعات''، وتتكون كل مجموعة من 5 مراحل فردية.","تتكون كل مرحلة من شبكة من الكلمات الأفقية. عند حل دليل، تُكتب الكلمة. السمة البارزة للعبة هي وجود الكلمة السرية الرأسية الملونة. كشف الكلمات الأفقية ينسخ الحروف تلقائيًا لخانات أخرى مما يسهل إكمال الشبكة."]},{"heading":"استراتيجيات ونصائح لتجاوز مستويات CodyCross","paragraphs":["لتصبح محترفًا في اللعبة، ابدأ دائمًا بحل الأدلة الأسهل أولاً. لا تضيع وقتك في كلمات معقدة في البداية؛ فحل الكلمات السهلة سيكشف عن حروف متقاطعة تملأ الخانات الصعبة لتسهيل حلها.","راقب الكلمة السرية الرأسية. تخمين هذه الكلمة مبكرًا يتيح لك كتابتها والحصول على حرف مجاني في كل سطر أفقي فورًا. انتبه أيضًا للصيغ القواعدية (الجمع أو المذكر والمؤنث) لتوقع الحروف."]}]',
        '[{"input":"الدليل: ''وجهة سياحية شهيرة في إيطاليا''","output":"روما","note":"إجابة من 4 حروف في عالم كوكب الأرض."},{"input":"الدليل: ''عاصمة فرنسا''","output":"باريس","note":"إجابة من 5 حروف في عالم المغامرات."}]',
        '["تأكد من عدد حروف الكلمة المطلوب لاستبعاد الإجابات غير المناسبة.","اسم العالم يعطيك السياق الأساسي لمعنى الأدلة المزدوج.","حل الكلمات السهلة أولاً للحصول على حروف متقاطعة مجانية.","إذا كنت محتارًا بين عدة خيارات، استخدم الحروف في [مساعد كودي كروس](codycross-solver)."]',
        '[{"question":"هل قاعدة بيانات حلول CodyCross مجانية؟","answer":"نعم، هي مجانية 100% ولا تتطلب أي تسجيل أو رسوم."},{"question":"كيف أبحث عن دليل في مربع البحث؟","answer":"فقط اكتب نص الدليل أو الكلمة المفتاحية في الحقل العلوي وانقر على بحث لرؤية الإجابات المتطابقة."},{"question":"هل يمكنني البحث باستخدام حروف معروفة وفراغات؟","answer":"نعم، إذا كان لديك حروف معروفة وتريد البحث عن كلمات متطابقة مع النمط، استخدم [مساعد كودي كروس](codycross-solver)."},{"question":"ما هي العوالم والمجموعات في CodyCross؟","answer":"اللعبة مقسمة إلى عوالم ذات طابع خاص، يحتوي كل عالم على مجموعات، وتضم كل مجموعة 5 مراحل فردية."},{"question":"هل يمكنني لعب CodyCross بدون إنترنت؟","answer":"نعم، يمكنك اللعب دون اتصال، لكن التحديات اليومية وقاعدة البيانات الإلكترونية لن تتوفر. وفر عملات المساعدة المدمجة للحالات التي لا تملك فيها اتصالاً."}]',
        '',
        '[]'
      );
